async def validate_owner(callback, owner_id: int, msg: str = "This menu belongs to another trainer.") -> bool:
    """
    Reusable ownership guard for ALL trainer-specific callback menus.

    Usage (inside any callback handler):
        if not await validate_owner(query, owner_id):
            return

    Returns True  → caller is the owner, proceed normally.
    Returns False → caller is NOT the owner; an alert has been answered and
                    the caller should return immediately.
    """
    if callback.from_user.id != owner_id:
        await callback.answer(msg, show_alert=True)
        return False
    return True

