def get_trainer_rank(trainer_exp: int) -> tuple[str, int, int]:
    """Return (rank_name, min_exp, max_exp) for the given trainer_exp total."""
    for rank_name, min_exp, max_exp in TRAINER_RANKS:
        if trainer_exp < max_exp:
            return rank_name, min_exp, max_exp
    # If beyond the last threshold, clamp to the highest rank
    top = TRAINER_RANKS[-1]
    return top[0], top[1], top[2]


def build_rank_progress_bar(current: int, min_exp: int, max_exp: int, length: int = 10) -> str:
    """Return a filled progress bar string like █████░░░░░"""
    span = max_exp - min_exp
    if span <= 0:
        filled = length
    else:
        filled = int((current - min_exp) / span * length)
        filled = max(0, min(filled, length))
    return "█" * filled + "░" * (length - filled)


def _format_reward_line(col: str, amount: int) -> str:
    """Render a single reward (column, amount) pair as display text, e.g. '30 Great Balls'."""
    if col == "nova_rupee":
        return f"{amount:,} RoRupees"
    label = _RANK_REWARD_LABELS.get(col, col)
    if amount == 1:
        return f"{amount} {label}"
    plural = _RANK_REWARD_PLURALS.get(col, f"{label}s")
    return f"{amount} {plural}"


def _build_rank_reward_lines(rank_name: str) -> list[str]:
    """Return the display lines for a rank's automatically-granted rewards."""
    return [_format_reward_line(col, amt) for col, amt in RANK_REWARDS.get(rank_name, [])]


def _grant_rank_rewards_db(user_id: int, rank_name: str) -> None:
    """Apply the currency/consumable-item rewards for a rank, via
    increment_user() (atomic in-memory increments — see increment_user's
    docstring). The double-grant guard itself lives in
    check_and_notify_rank_up's CAS check on last_rank_rewarded, not here."""
    deltas = {}
    for col, amount in RANK_REWARDS.get(rank_name, []):
        deltas[col] = deltas.get(col, 0) + amount
    if deltas:
        increment_user(user_id, **deltas)


def _grant_nova_chosen_auto_rewards_db(user_id: int) -> str:
    """Grant the portion of the Ro Chosen reward that is given automatically
    (1 Master Ball + 1 random COMMON Mega Stone, no skin). The bonus Pokémon
    is NOT granted here — it stays manual, traded by an admin.
    Returns the name of the Mega Stone that was granted.

    master_ball lives on `users` (USER_CACHE, in-memory increment). stone
    inventory lives in the separate user_stones table, which isn't part of
    USER_CACHE, so that write still goes straight to the pooled connection
    and commits on its own — it was never covered by the same transaction
    as the last_rank_rewarded claim anyway (that guard only ever needed to
    protect the `users` row)."""
    increment_user(user_id, master_ball=1)
    stone_name = random.choice(COMMON_MEGA_STONES)
    conn = get_db("ZNX.db")
    conn.execute(
        "INSERT INTO user_stones (user_id, stone_name, quantity) VALUES (?, ?, 1) "
        "ON CONFLICT(user_id, stone_name) DO UPDATE SET quantity = quantity + 1",
        (user_id, stone_name)
    )
    conn.commit()
    return stone_name


async def check_and_notify_rank_up(
    context,
    user_id: int,
    chat_id: int,
    old_exp: int,
    new_exp: int,
) -> None:
    """Grant rank-up reward(s) and DM the trainer a rank-up notification for
    every rank threshold crossed going from old_exp to new_exp.

    Rewards are granted immediately, and the reward grant + the rank "claim"
    flag (last_rank_rewarded) are updated in the same SQLite transaction, so
    even if this function fires more than once for the same crossing the
    reward is never handed out twice.

    Rank-up announcements are always sent to the trainer's private chat —
    never to a group — regardless of where the exp gain happened.
    """
    old_rank, _, _ = get_trainer_rank(old_exp)
    new_rank, _, _ = get_trainer_rank(new_exp)
    if old_rank == new_rank:
        return

    old_idx = _get_rank_index(old_rank)
    new_idx = _get_rank_index(new_rank)
    if old_idx == -1 or new_idx == -1 or new_idx <= old_idx:
        return

    # Walk every rank boundary crossed (handles multi-rank jumps in one go)
    for idx in range(old_idx + 1, new_idx + 1):
        prev_rank_name = TRAINER_RANKS[idx - 1][0]
        rank_name = TRAINER_RANKS[idx][0]

        mega_stone_name = None
        try:
            # Atomically claim this rank-up so the reward can't be granted
            # twice. The old version relied on SQLite's row-level atomicity
            # (UPDATE ... WHERE last_rank_rewarded != ? + rowcount==0) for
            # this guarantee. Now that users lives in USER_CACHE, the same
            # guarantee comes from doing the check-then-set as a single,
            # non-yielding block against the in-memory dict (no `await`
            # between the two lines below) — exactly the same reasoning
            # that makes increment_user() safe. get_user() is a no-op after
            # the first call in this loop (already cached), so this is not
            # a repeated disk hit.
            profile = get_user(user_id)
            if profile is None:
                continue  # not registered — nothing to reward
            if (profile.get("last_rank_rewarded") or "") == rank_name:
                # Already rewarded for this rank by a previous run — skip silently
                continue
            profile["last_rank_rewarded"] = rank_name
            _USER_CACHE_DIRTY.add(user_id)

            if rank_name == "Ro Chosen":
                mega_stone_name = _grant_nova_chosen_auto_rewards_db(user_id)
            else:
                _grant_rank_rewards_db(user_id, rank_name)
        except Exception as db_err:
            logger.error(f"[rank_up] Reward grant failed for user {user_id} -> {rank_name}: {db_err}")
            continue

        # ── Build the rank-up message ───────────────────────────────────────
        if rank_name == "Ro Chosen":
            text = (
                "🎉 <b><u>Rank Up!</u></b>\n\n"
                "<blockquote>Congratulations Trainer! You've reached the highest rank!</blockquote>\n\n"
                f"<b>Previous Rank:</b> {prev_rank_name}\n"
                f"<b>Current Rank:</b> {rank_name}\n"
                "<b>Rewards:</b>\n\n"
                f"• Random Mega Stone ({mega_stone_name})\n"
                "• 1 Master Ball\n"
                "• Random Common Non-Legendary Pokémon (Uncommon Skin)\n\n"
                "<i>Forward this message to an Admin. Your rewards will be delivered via trade.</i>\n\n"
                "<i>Keep training your Pokémon to become even stronger!</i>"
            )
        else:
            reward_lines = _build_rank_reward_lines(rank_name)
            rewards_block = "\n".join(f"• {line}" for line in reward_lines)
            text = (
                "🎉 <b><u>Rank Up!</u></b>\n\n"
                "<blockquote>Congratulations Trainer! You've Ranked Up!</blockquote>\n\n"
                f"<b>Previous Rank:</b> {prev_rank_name}\n"
                f"<b>Current Rank:</b> {rank_name}\n"
                f"<b>Rewards:</b>\n{rewards_block}\n\n"
                "<i>Keep training your Pokémon to reach the next rank.</i>"
            )

        # ── Send — always to the trainer's DM, never to a group chat ───────
        try:
            await context.bot.send_message(chat_id=user_id, text=text, parse_mode="HTML")
        except Exception:
            pass

