# Indian Standard Time offset (UTC+5:30) — used for daily Safari reset at 05:30 IST
IST = timezone(timedelta(hours=5, minutes=30))

def _safari_reset_date() -> str:
    """Return the current Safari 'day' string.
    A Safari day runs from 05:30 IST to 05:29:59 IST the next day.
    If the current IST time is before 05:30, the day is still the previous calendar date."""
    now_ist = datetime.now(IST)
    # If before 05:30, the reset hasn't happened yet — belong to the previous day
    if now_ist.hour < 5 or (now_ist.hour == 5 and now_ist.minute < 30):
        now_ist = now_ist - timedelta(days=1)
    return now_ist.strftime("%Y-%m-%d")


def _safari_db_check_used(user_id: int) -> bool:
    """Return True if the trainer has already used their Safari visit today
    (based on the persistent DB record, not in-memory state)."""
    today = _safari_reset_date()
    profile = get_user(user_id)
    if profile is None:
        return False
    last_cycle = profile.get("safari_last_cycle")
    daily_used = profile.get("safari_daily_used")
    return bool(daily_used) and last_cycle == today


def _safari_db_mark_used(user_id: int) -> None:
    """Persistently record that the trainer used their Safari visit today."""
    today = _safari_reset_date()
    update_user(user_id, safari_last_cycle=today, safari_daily_used=1)


def _safari_session_save(user_id: int, context) -> None:
    """
    Persist the trainer's active Safari session to the database immediately.
    Call this whenever session state changes (start, each hunt, end).
    This ensures the session survives bot restarts, crashes, and code reloads.
    """
    active     = 1 if context.user_data.get("safari_active") else 0
    region     = context.user_data.get("safari_region", "")
    balls      = context.user_data.get("safari_balls", 0)
    hunt_count = context.user_data.get("safari_hunt_count", 0)
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        """UPDATE users
           SET safari_session_active = ?,
               safari_session_region = ?,
               safari_session_balls  = ?,
               safari_session_hunt_count = ?
           WHERE user_id = ?""",
        (active, region, balls, hunt_count, user_id)
    )
    conn.commit()
    conn.close()


def _safari_session_clear_db(user_id: int) -> None:
    """
    Clear the persistent Safari session record in the database.
    Call this when the Safari session ends normally (hunt limit / balls out / /exit).
    Does NOT clear the daily-use stamp — use _clear_safari_state_full for that.
    """
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        """UPDATE users
           SET safari_session_active = 0,
               safari_session_region = '',
               safari_session_balls  = 0,
               safari_session_hunt_count = 0
           WHERE user_id = ?""",
        (user_id,)
    )
    conn.commit()
    conn.close()


def _safari_session_load_all_active() -> list[dict]:
    """
    On bot startup, return all users with an active Safari session so they
    can be restored into context.user_data when they next interact.
    Returns a list of dicts with keys: user_id, region, balls, hunt_count.
    """
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        """SELECT user_id, safari_session_region, safari_session_balls,
                  safari_session_hunt_count
           FROM users
           WHERE safari_session_active = 1"""
    )
    rows = cursor.fetchall()
    conn.close()
    return [
        {"user_id": r[0], "region": r[1], "balls": r[2], "hunt_count": r[3]}
        for r in rows
    ]


def _safari_session_restore_for_user(user_id: int) -> dict | None:
    """
    Load the persisted Safari session for a single user from the DB.
    Returns a dict with session data if the session is active, else None.
    This is called lazily when a user with a stored session first interacts.
    """
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        """SELECT safari_session_active, safari_session_region,
                  safari_session_balls, safari_session_hunt_count
           FROM users WHERE user_id = ?""",
        (user_id,)
    )
    row = cursor.fetchone()
    conn.close()
    if not row or not row[0]:
        return None
    active, region, balls, hunt_count = row
    return {"region": region, "balls": balls, "hunt_count": hunt_count}


