def _new_mega_artwork_url(sprite_slug: str, shiny: bool = False) -> str | None:
    """
    Return the official-artwork URL for a new/custom Mega form using its
    numeric PokeAPI sprite ID, or None if the slug isn't in NEW_MEGA_IDS.
    When shiny=True, returns the shiny artwork path (may 404 for custom forms
    that lack hosted shiny artwork — callers must handle None after fetch).
    """
    mega_id = NEW_MEGA_IDS.get(sprite_slug)
    if mega_id is None:
        return None
    if shiny:
        return f"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/shiny/{mega_id}.png"
    return f"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/{mega_id}.png"


def _new_mega_sprite_url(sprite_slug: str, back: bool = False, shiny: bool = False) -> str | None:
    """
    Return the sprite URL for a new/custom Mega form using its numeric
    PokeAPI sprite ID, or None if the slug isn't in NEW_MEGA_IDS.
    Supports back and shiny variants.
    """
    mega_id = NEW_MEGA_IDS.get(sprite_slug)
    if mega_id is None:
        return None
    return _nc_sprite_url(mega_id, back=back, shiny=shiny)


