def _special_form_artwork_url(sprite_slug: str, shiny: bool = False) -> str | None:
    """
    Return the official-artwork URL for a special form (Origin / Crowned /
    Rider) using its numeric PokeAPI ID, or None if not in SPECIAL_FORM_API_IDS.

    Always uses the artwork for the TRANSFORMED form — never falls back to
    the base species or another Pokémon's artwork.
    """
    form_id = SPECIAL_FORM_API_IDS.get(sprite_slug)
    if form_id is None:
        return None
    if shiny:
        return (
            f"https://raw.githubusercontent.com/PokeAPI/sprites/master/"
            f"sprites/pokemon/other/official-artwork/shiny/{form_id}.png"
        )
    return (
        f"https://raw.githubusercontent.com/PokeAPI/sprites/master/"
        f"sprites/pokemon/other/official-artwork/{form_id}.png"
    )


def _special_form_sprite_url(sprite_slug: str, back: bool = False, shiny: bool = False) -> str | None:
    """
    Return the PokeAPI sprite URL for a special form using its numeric ID,
    or None if not in SPECIAL_FORM_API_IDS.  Supports back and shiny variants.
    """
    form_id = SPECIAL_FORM_API_IDS.get(sprite_slug)
    if form_id is None:
        return None
    return _nc_sprite_url(form_id, back=back, shiny=shiny)


