def _camp_now_ts() -> int:
    return int(time.time())

def _camp_remaining(seconds: int) -> str:
    seconds = max(0, int(seconds))
    days, rem = divmod(seconds, 86400)
    hours, rem2 = divmod(rem, 3600)
    mins = rem2 // 60
    if days > 0:
        return f"{days}d {hours}h {mins}m"
    elif hours > 0:
        return f"{hours}h {mins}m"
    else:
        return f"{mins}m"

def _camp_get_pokemon_row(pokemon_id: int, user_id: int | None = None):
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    if user_id is None:
        cursor.execute(
            "SELECT id, user_id, pokemon_id, pokemon_name, level, pokemon_bond, in_camp, camp_start_time, camp_end_time "
            "FROM user_pokemon WHERE id = ?",
            (pokemon_id,),
        )
    else:
        cursor.execute(
            "SELECT id, user_id, pokemon_id, pokemon_name, level, pokemon_bond, in_camp, camp_start_time, camp_end_time "
            "FROM user_pokemon WHERE id = ? AND user_id = ?",
            (pokemon_id, user_id),
        )
    row = cursor.fetchone()
    conn.close()
    return row

def is_pokemon_in_camp(pokemon_id: int) -> bool:
    row = _camp_get_pokemon_row(pokemon_id)
    return bool(row and row[6])

def _camp_name(pokemon_id: int, name: str) -> str:
    return f"{name} [In Camp]" if is_pokemon_in_camp(pokemon_id) else name

def _camp_get_user_active(user_id: int):
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        """SELECT user_id, camp_pokemon_id, camp_start_time, camp_end_time, camp_cooldown_end,
                  camp_gift_schedule, camp_gifts_given, last_gift_time, camp_cooldown_notified
           FROM users WHERE user_id = ?""",
        (user_id,),
    )
    row = cursor.fetchone()
    conn.close()
    if not row:
        return None
    data = {
        "user_id": row[0],
        "camp_pokemon_id": row[1] or 0,
        "camp_start_time": row[2] or 0,
        "camp_end_time": row[3] or 0,
        "camp_cooldown_end": row[4] or 0,
        "camp_gift_schedule": row[5] or "[]",
        "camp_gifts_given": row[6] or 0,
        "last_gift_time": row[7] or 0,
        "camp_cooldown_notified": row[8] or 0,
    }
    try:
        data["camp_gift_schedule"] = json.loads(data["camp_gift_schedule"] or "[]")
    except Exception:
        data["camp_gift_schedule"] = []
    return data

def _camp_is_active(user_id: int) -> bool:
    data = _camp_get_user_active(user_id)
    return bool(data and data["camp_pokemon_id"] and data["camp_end_time"] > _camp_now_ts())

def _camp_in_cooldown(user_id: int) -> bool:
    data = _camp_get_user_active(user_id)
    return bool(data and data["camp_cooldown_end"] > _camp_now_ts())

def _camp_generate_schedule(start_ts: int) -> list[int]:
    total = random.randint(CAMP_GIFT_MIN, CAMP_GIFT_MAX)
    first_day = random.randint(3, 4)
    second_day = max(3, total - first_day)
    if first_day + second_day != total:
        second_day = total - first_day
    first_day = max(3, min(4, first_day))
    second_day = max(3, min(4, second_day))
    if first_day + second_day != total:
        total = first_day + second_day

    schedule = []
    windows = [
        (start_ts, start_ts + 24 * 60 * 60, first_day),
        (start_ts + 24 * 60 * 60, start_ts + 48 * 60 * 60, second_day),
    ]
    for win_start, win_end, count in windows:
        count = max(1, count)
        low = win_start + 30 * 60
        high = max(low + 60, win_end - 30 * 60)
        points = sorted(random.randint(low, high) for _ in range(count))
        schedule.extend(points)
    return sorted(schedule)

def _camp_mega_stone_for(species_name: str) -> str | None:
    """Return a compatible Mega Stone for *species_name* with a 1-in-10,000 chance.

    Returns the stone name on a lucky roll, or None otherwise.
    Pokémon without Mega Evolutions always return None immediately.
    When a Pokémon has multiple compatible stones (e.g. Charizard, Mewtwo),
    one is chosen at random on the rare occasion the roll succeeds.
    """
    stones = MEGA_STONES.get((species_name or "").lower())
    if not stones:
        return None
    # 1-in-10,000 chance (0.01 %) per camp discovery roll
    if random.randint(1, 10000) != 1:
        return None
    return random.choice(stones)

async def _camp_send_dm(bot, user_id: int, text: str):
    try:
        await bot.send_message(chat_id=user_id, text=text)
    except Exception as e:
        logger.error(f"Camp DM failed for {user_id}: {e}")

async def _camp_send_discovery_dm(bot, user_id: int, caption: str):
    """Sends the styled Camp Discovery card (image + HTML caption)."""
    try:
        await bot.send_photo(
            chat_id=user_id,
            photo=CAMP_DISCOVERY_IMAGE_URL,
            caption=caption,
            parse_mode="HTML",
        )
    except Exception as e:
        logger.error(f"Camp discovery DM failed for {user_id}: {e}")

async def _camp_distribute_due_rewards(application: Application):
    now = _camp_now_ts()
    # This bulk multi-user scan stays as a direct query — USER_CACHE has no
    # "give me every user matching X" capability (and shouldn't; it's a
    # per-user dict keyed by user_id, not an indexed table). This reads
    # camp_pokemon_id/camp_cooldown_end straight from disk to find WHICH
    # users need attention this pass.
    conn = get_db("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        """SELECT user_id, camp_pokemon_id, camp_start_time, camp_end_time, camp_cooldown_end,
                  camp_gift_schedule, camp_gifts_given, last_gift_time, camp_cooldown_notified
           FROM users
           WHERE camp_pokemon_id != 0 OR camp_cooldown_end != 0"""
    )
    scanned_rows = cursor.fetchall()

    for row in scanned_rows:
        user_id = row[0]
        # IMPORTANT: once we know WHICH user_ids are relevant from the bulk
        # scan above, re-read this user's actual working values through
        # get_user() rather than trusting the row we just scanned. If this
        # user already has an in-memory cached profile with a pending
        # (not-yet-flushed) change to any of these same camp_* fields —
        # e.g. they just started a new Camp session via /camp seconds ago,
        # in the same 60s window this loop runs on — the bulk-scanned row
        # could be one write behind. get_user() always returns the freshest
        # value (see its module docstring on read-your-own-write), so using
        # it here (instead of unpacking `row` directly) is what keeps this
        # background loop from stomping a concurrent player action.
        profile = get_user(user_id)
        if profile is None:
            continue
        camp_pokemon_id = profile.get("camp_pokemon_id") or 0
        camp_start_time = profile.get("camp_start_time") or 0
        camp_end_time = profile.get("camp_end_time") or 0
        camp_cooldown_end = profile.get("camp_cooldown_end") or 0
        schedule_json = profile.get("camp_gift_schedule")
        gifts_given = profile.get("camp_gifts_given") or 0
        last_gift_time = profile.get("last_gift_time") or 0
        cooldown_notified = profile.get("camp_cooldown_notified") or 0
        try:
            schedule = json.loads(schedule_json or "[]")
        except Exception:
            schedule = []

        if camp_pokemon_id and camp_end_time and now >= camp_end_time:
            p_row = _camp_get_pokemon_row(camp_pokemon_id, user_id)
            if p_row and p_row[6]:
                pokemon_name = p_row[3]
                bond_gain = random.randint(300, 500)
                new_bond = min(10000, (p_row[5] or 0) + bond_gain)

                # user_pokemon is a separate table, not part of USER_CACHE —
                # still goes straight to the (pooled) connection as before.
                conn2 = get_db("ZNX.db")
                conn2.execute(
                    "UPDATE user_pokemon SET in_camp = 0, camp_start_time = 0, camp_end_time = 0, pokemon_bond = ? WHERE id = ? AND user_id = ?",
                    (new_bond, camp_pokemon_id, user_id),
                )
                conn2.commit()
                update_user(
                    user_id,
                    camp_pokemon_id=0,
                    camp_start_time=0,
                    camp_end_time=0,
                    camp_gift_schedule='[]',
                    camp_gifts_given=0,
                    last_gift_time=0,
                    camp_cooldown_end=now + CAMP_COOLDOWN_SECONDS,
                    camp_cooldown_notified=0,
                )
                await _camp_send_dm(application.bot, user_id, f"Your {pokemon_name} gained {bond_gain} Bond!\n\nNow you can use Camp again after a week.")
            continue

        if camp_pokemon_id and schedule and camp_end_time and now < camp_end_time:
            due = [ts for ts in schedule if ts <= now]
            if not due:
                continue

            p_row = _camp_get_pokemon_row(camp_pokemon_id, user_id)
            if not p_row:
                continue
            pokemon_name = p_row[3]
            species_name = p_row[2]

            for ts in due:
                # ── Normal camp reward (always given) ─────────────────────────
                reward_kind = random.choice([
                    "pokeballs", "greatballs", "ultraballs", "repeatballs", "nestballs",
                    "duskballs", "candy", "berry", "vitamin", "boost", "nova_rupee"
                ])
                if reward_kind == "pokeballs":
                    amt = random.randint(5, 25)
                    reward_name = "Regular Ball"
                elif reward_kind == "greatballs":
                    amt = random.randint(3, 15)
                    reward_name = "Great Ball"
                elif reward_kind == "ultraballs":
                    amt = random.randint(1, 10)
                    reward_name = "Ultra Ball"
                elif reward_kind == "repeatballs":
                    amt = random.randint(1, 8)
                    reward_name = "Repeat Ball"
                elif reward_kind == "nestballs":
                    amt = random.randint(1, 8)
                    reward_name = "Nest Ball"
                elif reward_kind == "duskballs":
                    amt = random.randint(1, 6)
                    reward_name = "Dusk Ball"
                elif reward_kind == "candy":
                    amt = random.randint(1, 3)
                    reward_name = "Rare Candy"
                elif reward_kind == "berry":
                    amt = random.randint(1, 4)
                    reward_name = "Berry"
                elif reward_kind == "vitamin":
                    amt = random.randint(1, 2)
                    reward_name = "Vitamin"
                elif reward_kind == "boost":
                    amt = random.randint(1, 2)
                    reward_name = "Boost"
                else:
                    amt = random.randint(100, 800)
                    reward_name = "RoRupee"
                increment_user(user_id, **{reward_kind: amt})

                reward_display = f"🎁 {reward_name} ×{amt}"

                # ── Mega Stone rare bonus (0.01 % / 1-in-10,000 — independent) ─
                # Only Mega-capable Pokémon are eligible; finding a stone does NOT
                # replace the normal reward, reset cooldowns, or affect the schedule.
                mega_stone = _camp_mega_stone_for(species_name)
                if mega_stone:
                    conn3 = get_db("ZNX.db")
                    conn3.execute(
                        "INSERT INTO user_stones (user_id, stone_name, quantity) VALUES (?, ?, 1) "
                        "ON CONFLICT(user_id, stone_name) DO UPDATE SET quantity = quantity + 1",
                        (user_id, mega_stone),
                    )
                    conn3.commit()
                    reward_display += f"\n<b>Mega Stone found!</b> {mega_stone} ×1"

                remaining_schedule = [x for x in schedule if x > ts]
                # gifts_given increment must read the CURRENT cached value,
                # not the value captured before this per-ts loop started —
                # increment_user() handles that atomically in one step.
                update_user(user_id, camp_gift_schedule=json.dumps(remaining_schedule), last_gift_time=ts)
                increment_user(user_id, camp_gifts_given=1)
                schedule = remaining_schedule
                discovery_caption = (
                    f"🎉 <b><u>Discovery!</u></b>\n\n"
                    f"<blockquote>Your {pokemon_name} explored the area and found:</blockquote>{reward_display}\n\n"
                    f"<i>Added to your inventory</i>"
                )
                await _camp_send_discovery_dm(application.bot, user_id, discovery_caption)
                if not schedule:
                    break

        if camp_cooldown_end and now >= camp_cooldown_end and not cooldown_notified:
            await _camp_send_dm(application.bot, user_id, "Your Camp cooldown is over!\n\nYou can now send another Pokémon to Camp.")
            update_user(user_id, camp_cooldown_notified=1)

async def camp_background_task(application: Application):
    while True:
        try:
            await _camp_distribute_due_rewards(application)
        except Exception as e:
            logger.error(f"Camp monitor error: {e}")
        await asyncio.sleep(60)

def _camp_get_selected_rows(user_id: int, pokemon_name: str) -> list:
    return find_duplicate_pokemon(user_id, pokemon_name)

def _camp_build_selection_text(rows: list, page: int, pokemon_name: str) -> str:
    total = len(rows)
    total_pages = max(1, math.ceil(total / CAMP_SELECT_PAGE_SIZE))
    offset = (page - 1) * CAMP_SELECT_PAGE_SIZE
    page_rows = rows[offset: offset + CAMP_SELECT_PAGE_SIZE]
    lines = ["Send to Camp — which Pokémon:\n"]
    for i, row in enumerate(page_rows, start=1):
        idx = offset + i
        # row[0]=id, row[2]=pokemon_name, row[3]=nature, row[18]=shiny (find_duplicate_pokemon schema)
        camp_tag = " [In Camp]" if is_pokemon_in_camp(row[0]) else ""
        is_shiny = bool(row[18]) if len(row) > 18 else False
        display = display_name_with_shiny(row[2], is_shiny)
        lines.append(f"{idx}. {display}{camp_tag} - {row[3]}")
    lines.append(f"\nPage: {page}/{total_pages}")
    return "\n".join(lines)

def _camp_build_selection_keyboard(rows: list, page: int, pokemon_name: str) -> InlineKeyboardMarkup:
    total = len(rows)
    total_pages = max(1, math.ceil(total / CAMP_SELECT_PAGE_SIZE))
    offset = (page - 1) * CAMP_SELECT_PAGE_SIZE
    page_rows = rows[offset: offset + CAMP_SELECT_PAGE_SIZE]
    keyboard = []
    row_buttons = []
    for i, row in enumerate(page_rows, start=1):
        idx = offset + i
        row_buttons.append(InlineKeyboardButton(f"[{idx}]", callback_data=f"camp_pick:{row[0]}:{page}"))
        if len(row_buttons) == 5:
            keyboard.append(row_buttons)
            row_buttons = []
    if row_buttons:
        keyboard.append(row_buttons)
    nav = []
    if page > 1:
        nav.append(InlineKeyboardButton("Prev", callback_data=f"camp_page:{pokemon_name}:{page-1}"))
    if page < total_pages:
        nav.append(InlineKeyboardButton("Next", callback_data=f"camp_page:{pokemon_name}:{page+1}"))
    if nav:
        keyboard.append(nav)
    return InlineKeyboardMarkup(keyboard)

async def _camp_send_confirmation(reply_fn, pokemon_name: str):
    text = (
        "The instructions of camp is given below:\n\n"
        f"You have to give your {pokemon_name} to us and you cannot use the {pokemon_name} for 2 days during battle, trades, stats.\n\n"
        f"It's like losing that pokemon for 2 days.\n\n"
        "The benefits:\n\n"
        "• It will increase the bond with your Pokémon\n\n"
        "• It will decrease miss chances during battle\n\n"
        "• It will increase critical hit chances during battle\n\n"
        "• In some major cases, if your luck is good then the Pokémon will find gifts for you\n\n"
        "Now are you sure you wanna daycare your pokemon?\n\n"
        "If you want your pokemon urgent then you can just do /leavecamp"
    )
    keyboard = InlineKeyboardMarkup([[InlineKeyboardButton("Yes", callback_data="camp_yes")]])
    await reply_fn(text, reply_markup=keyboard)

async def camp_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    user = update.effective_user
    chat = update.effective_chat
    if chat.type != "private":
        _dm_kbd = InlineKeyboardMarkup([[InlineKeyboardButton("Open Bot DM", url="https://t.me/PokieNova_bot")]])
        await update.message.reply_text("❌ This command only works in private chat.", reply_markup=_dm_kbd)
        return

    if not is_registered(user.id):
        await update.message.reply_text("❌ You need to register first. Use /start")
        return

    if _camp_is_active(user.id):
        data = _camp_get_user_active(user.id)
        remaining = _camp_remaining((data["camp_end_time"] or 0) - _camp_now_ts())
        await update.message.reply_text(f"Your Pokémon is already in Camp.\nRemaining time: {remaining}")
        return

    if _camp_in_cooldown(user.id):
        data = _camp_get_user_active(user.id)
        remaining = _camp_remaining((data["camp_cooldown_end"] or 0) - _camp_now_ts())
        await update.message.reply_text(f"<i>Camp is on cooldown.</i>\n\nRemaining time:\n<b>{remaining}</b>", parse_mode="HTML")
        return

    msg = await update.message.reply_text(
        "You wanna go on a camp with your Pokemon \nSend the name of the pokemon replying this msg."
    )
    context.user_data[f"camp_prompt_msg_id_{user.id}"] = msg.message_id
    context.user_data[f"camp_prompt_chat_id_{user.id}"] = chat.id

async def camp_name_reply(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    user = update.effective_user
    if update.effective_chat.type != "private":
        return
    pending_msg_id = context.user_data.get(f"camp_prompt_msg_id_{user.id}")
    pending_chat_id = context.user_data.get(f"camp_prompt_chat_id_{user.id}")
    if not pending_msg_id or not pending_chat_id:
        return
    if not update.message.reply_to_message or update.message.reply_to_message.message_id != pending_msg_id:
        return
    if update.effective_chat.id != pending_chat_id:
        return

    if _camp_is_active(user.id):
        await update.message.reply_text("Your Pokémon is already in Camp.")
        return
    if _camp_in_cooldown(user.id):
        data = _camp_get_user_active(user.id)
        remaining = _camp_remaining((data["camp_cooldown_end"] or 0) - _camp_now_ts())
        await update.message.reply_text(f"<i>Camp is on cooldown.</i>\n\nRemaining time:\n<b>{remaining}</b>", parse_mode="HTML")
        return

    pokemon_name = update.message.text.strip()
    rows = _camp_get_selected_rows(user.id, pokemon_name)
    if not rows:
        await update.message.reply_text(f"❌ You don't own a Pokémon named {pokemon_name}.")
        return

    context.user_data[f"camp_pending_name_{user.id}"] = pokemon_name

    if len(rows) > 1:
        text = _camp_build_selection_text(rows, 1, pokemon_name.lower())
        keyboard = _camp_build_selection_keyboard(rows, 1, pokemon_name.lower())
        await update.message.reply_text(text, reply_markup=keyboard)
        return

    row = rows[0]
    context.user_data[f"camp_selected_{user.id}"] = {"pkmn_id": row[0], "pkmn_name": row[2]}
    await _camp_send_confirmation(update.message.reply_text, row[2])

async def camp_pick_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    user = query.from_user
    parts = query.data.split(":")
    if len(parts) != 3:
        await query.answer()
        return
    pkmn_db_id = int(parts[1])
    # Ownership check: the pokemon must belong to this user
    row_check = _camp_get_pokemon_row(pkmn_db_id)
    if row_check and not await validate_owner(query, row_check[1]):
        return
    await query.answer()
    row = _camp_get_pokemon_row(pkmn_db_id, user.id)
    if not row:
        await query.answer("Pokémon not found.", show_alert=True)
        return
    context.user_data[f"camp_selected_{user.id}"] = {"pkmn_id": pkmn_db_id, "pkmn_name": row[3]}
    await query.edit_message_text(
        f"Selected {row[3]}.\n\n"
        "The instructions of camp is given below:\n\n"
        f"You have to give your {row[3]} to us and you cannot use the {row[3]} for 2 days during battle, trades, stats.\n\n"
        f"It's like losing that pokemon for 2 days.\n\n"
        "The benefits:\n\n"
        "• It will increase the bond with your Pokémon\n\n"
        "• It will decrease miss chances during battle\n\n"
        "• It will increase critical hit chances during battle\n\n"
        "• In some major cases, if your luck is good then the Pokémon will find gifts for you\n\n"
        "Now are you sure you wanna daycare your pokemon?\n\n"
        "If you want your pokemon urgent then you can just do /leavecamp",
        reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("Yes", callback_data="camp_yes")]])
    )

async def camp_page_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    user = query.from_user
    parts = query.data.split(":")
    if len(parts) != 3:
        await query.answer()
        return
    pokemon_name = parts[1]
    page = int(parts[2])
    # Ownership: only the trainer who owns pokemon with this name may paginate
    rows = _camp_get_selected_rows(user.id, pokemon_name)
    if not rows:
        await query.answer("No Pokémon found.", show_alert=True)
        return
    await query.answer()
    total_pages = max(1, math.ceil(len(rows) / CAMP_SELECT_PAGE_SIZE))
    if page < 1 or page > total_pages:
        await query.answer("Invalid page.", show_alert=True)
        return
    text = _camp_build_selection_text(rows, page, pokemon_name)
    keyboard = _camp_build_selection_keyboard(rows, page, pokemon_name)
    await query.edit_message_text(text, reply_markup=keyboard)

async def camp_yes_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query = update.callback_query
    user = query.from_user
    await query.answer()
    selected = context.user_data.get(f"camp_selected_{user.id}")
    if not selected:
        # If session belongs to someone else it simply won't exist under this user's key
        await query.answer("Camp selection expired.", show_alert=True)
        return
    pkmn_id = selected["pkmn_id"]
    row = _camp_get_pokemon_row(pkmn_id, user.id)
    if not row:
        await query.answer("Pokémon not found.", show_alert=True)
        return
    if row[6]:
        await query.answer("This Pokémon is already in the Camp.", show_alert=True)
        return
    if _camp_is_active(user.id):
        await query.answer("You already have an active Camp.", show_alert=True)
        return
    if _camp_in_cooldown(user.id):
        data = _camp_get_user_active(user.id)
        remaining = _camp_remaining((data["camp_cooldown_end"] or 0) - _camp_now_ts())
        await query.answer(f"Camp is on cooldown. Remaining: {remaining}", show_alert=True)
        return

    start_ts = _camp_now_ts()
    end_ts = start_ts + CAMP_DURATION_SECONDS
    schedule = _camp_generate_schedule(start_ts)

    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        """UPDATE users
           SET camp_pokemon_id = ?, camp_start_time = ?, camp_end_time = ?,
               camp_gift_schedule = ?, camp_gifts_given = 0, last_gift_time = 0,
               camp_cooldown_notified = 0
           WHERE user_id = ?""",
        (pkmn_id, start_ts, end_ts, json.dumps(schedule), user.id),
    )
    cursor.execute(
        "UPDATE user_pokemon SET in_camp = 1, camp_start_time = ?, camp_end_time = ?, pokemon_bond = COALESCE(pokemon_bond, 0) WHERE id = ? AND user_id = ?",
        (start_ts, end_ts, pkmn_id, user.id),
    )
    conn.commit()
    conn.close()

    # Camp Pokémon cannot remain inside battle squads — pull it out of every squad now.
    remove_pokemon_from_all_squads(user.id, pkmn_id)

    await context.bot.send_photo(
        chat_id=user.id,
        photo="https://files.catbox.moe/pjsc5d.jpg",
        caption=(
            f"You Dropped Your {row[3]} For The Camp For 2 Days!\n\n"
            "Now you can begin your journey once again.\n\n"
            f"Now the {row[3]} will find some gifts for you.\n\n"
            "Your bond increases by sending Pokémon to camp."
        )
    )
    context.user_data.pop(f"camp_selected_{user.id}", None)
    context.user_data.pop(f"camp_pending_name_{user.id}", None)
    context.user_data.pop(f"camp_prompt_msg_id_{user.id}", None)
    context.user_data.pop(f"camp_prompt_chat_id_{user.id}", None)

async def leavecamp(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    user = update.effective_user
    if update.effective_chat.type != "private":
        _dm_kbd = InlineKeyboardMarkup([[InlineKeyboardButton("Open Bot DM", url="https://t.me/PokieNova_bot")]])
        await update.message.reply_text("❌ This command only works in private chat.", reply_markup=_dm_kbd)
        return
    data = _camp_get_user_active(user.id)
    if not data or not data["camp_pokemon_id"]:
        await update.message.reply_text("You don't have any Pokémon in Camp.")
        return

    p_row = _camp_get_pokemon_row(data["camp_pokemon_id"], user.id)
    pokemon_name = p_row[3] if p_row else "your Pokémon"

    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute("UPDATE user_pokemon SET in_camp = 0, camp_start_time = 0, camp_end_time = 0 WHERE id = ? AND user_id = ?", (data["camp_pokemon_id"], user.id))
    cursor.execute(
        """UPDATE users
           SET camp_pokemon_id = 0, camp_start_time = 0, camp_end_time = 0,
               camp_gift_schedule = '[]', camp_gifts_given = 0, last_gift_time = 0,
               camp_cooldown_end = ?, camp_cooldown_notified = 0
           WHERE user_id = ?""",
        (_camp_now_ts() + CAMP_COOLDOWN_SECONDS, user.id),
    )
    conn.commit()
    conn.close()

    context.user_data.pop(f"camp_selected_{user.id}", None)
    await update.message.reply_text(f"You took {pokemon_name} back from Camp.")

