# ══════════════════════════════════════════════════════════════════════════════
# ══════════════════════════════ DYNAMAX SYSTEM ═════════════════════════════════
# ══════════════════════════════════════════════════════════════════════════════
# Requires the Dynamax Band (has_dynamax_band). Works in /hunt, PvP (RoClash),
# and RandomClash. One Dynamax per team per battle; lasts DYNAMAX_TURNS turns.
#
# Effects while Dynamaxed:
#   • Max HP roughly doubles (current HP scales proportionally, so a Pokémon
#     doesn't get healed to full just by Dynamaxing, matching how the real
#     games handle the HP-bar rescale).
#   • Attack / Sp. Atk / Sp. Def / Speed / Defense all get a moderate boost.
#   • Every damaging move it knows is temporarily replaced by its type's
#     "Max Move" (e.g. a Fire move becomes Max Flare), with power based on
#     the move's official Max Move power tier. Status moves become Max
#     Guard (a generic protect-style placeholder — full status-move-specific
#     Max effects aren't modeled here).

DYNAMAX_TURNS = 5
DYNAMAX_HP_MULTIPLIER = 2.0
DYNAMAX_STAT_MULTIPLIER = 1.3  # applied to attack/defense/sp_atk/sp_def/speed

# Type → Max Move display name (matches the mainline games)
MAX_MOVE_BY_TYPE = {
    "normal":   "Max Strike",
    "fire":     "Max Flare",
    "water":    "Max Geyser",
    "electric": "Max Lightning",
    "grass":    "Max Overgrowth",
    "ice":      "Max Hailstorm",
    "fighting": "Max Knuckle",
    "poison":   "Max Ooze",
    "ground":   "Max Quake",
    "flying":   "Max Airstream",
    "psychic":  "Max Mindstorm",
    "bug":      "Max Flutterby",
    "rock":     "Max Rockfall",
    "ghost":    "Max Phantasm",
    "dragon":   "Max Wyrmwind",
    "dark":     "Max Darkness",
    "steel":    "Max Steelspike",
    "fairy":    "Max Starfall",
}

# Official Max Move power tiers, keyed by the base move's power. Max Moves
# don't scale 1:1 with base power — they use fixed tiers. This mirrors the
# mainline games' physical/special Max Move power table.
def _max_move_power(base_power: int) -> int:
    if base_power is None or base_power <= 0:
        return 100  # status/0-power moves that still get a Max Move (rare) default to 100
    if base_power <= 40:
        return 90
    if base_power <= 50:
        return 100
    if base_power <= 60:
        return 110
    if base_power <= 70:
        return 120
    if base_power <= 100:
        return 130
    if base_power <= 140:
        return 140
    return 150


def get_max_move(move: dict) -> dict:
    """Given a normal move dict (name/power/accuracy/type/damage_class),
    returns its Dynamaxed ("Max Move") version. Max Moves always hit
    (accuracy=None), keep the same type/damage_class as the base move, and
    use the official power-tier table above. Status moves become a generic
    Max Guard placeholder rather than modeling every unique Max Move status
    effect.
    """
    move_type = move.get("type", "normal")
    if move.get("damage_class") == "status" or not move.get("power"):
        return {
            "name": "max-guard",
            "display_name": "Max Guard",
            "power": 0,
            "accuracy": None,
            "type": move_type,
            "damage_class": "status",
            "is_max_move": True,
        }
    max_name = MAX_MOVE_BY_TYPE.get(move_type, "Max Strike")
    return {
        "name": max_name.lower().replace(" ", "-"),
        "display_name": max_name,
        "power": _max_move_power(move.get("power", 0)),
        "accuracy": None,  # Max Moves never miss
        "type": move_type,
        "damage_class": move.get("damage_class", "physical"),
        "is_max_move": True,
        "base_move_name": move.get("name"),  # so we can revert when Dynamax ends
    }


def apply_dynamax(pkmn_info: dict, current_hp: int) -> tuple[dict, int]:
    """Mutates a battle-side pkmn_info dict into its Dynamaxed state and
    returns (updated_info, updated_current_hp). Stores the pre-Dynamax
    stats/moves under '_pre_dynamax' so revert_dynamax() can restore them
    exactly when the duration ends.

    current_hp is passed/returned separately (rather than read from
    pkmn_info) because different battle systems (/hunt, RoClash,
    RandomClash) store current HP in different places (state dict vs.
    inside pkmn_info) — the caller is responsible for wiring this back into
    wherever it normally lives.
    """
    if pkmn_info.get("is_dynamaxed"):
        return pkmn_info, current_hp  # already Dynamaxed, no-op safety guard

    old_max_hp = pkmn_info.get("max_hp", 1)
    pre_dynamax = {
        "max_hp": old_max_hp,
        "attack": pkmn_info.get("attack"),
        "defense": pkmn_info.get("defense"),
        "sp_atk": pkmn_info.get("sp_atk"),
        "sp_def": pkmn_info.get("sp_def"),
        "speed": pkmn_info.get("speed"),
        "moves": pkmn_info.get("moves"),
    }

    new_max_hp = max(1, int(old_max_hp * DYNAMAX_HP_MULTIPLIER))
    # Scale current HP proportionally so Dynamaxing never fully heals —
    # e.g. at 50% HP before, still 50% HP (of the new, larger max) after.
    hp_fraction = (current_hp / old_max_hp) if old_max_hp > 0 else 1.0
    new_current_hp = max(1, int(new_max_hp * hp_fraction)) if current_hp > 0 else 0

    pkmn_info["_pre_dynamax"] = pre_dynamax
    pkmn_info["max_hp"] = new_max_hp
    pkmn_info["attack"]  = int(pkmn_info.get("attack", 0) * DYNAMAX_STAT_MULTIPLIER)
    pkmn_info["defense"] = int(pkmn_info.get("defense", 0) * DYNAMAX_STAT_MULTIPLIER)
    pkmn_info["sp_atk"]  = int(pkmn_info.get("sp_atk", 0) * DYNAMAX_STAT_MULTIPLIER)
    pkmn_info["sp_def"]  = int(pkmn_info.get("sp_def", 0) * DYNAMAX_STAT_MULTIPLIER)
    pkmn_info["speed"]   = int(pkmn_info.get("speed", 0) * DYNAMAX_STAT_MULTIPLIER)
    pkmn_info["moves"]   = [get_max_move(m) for m in pkmn_info.get("moves", [])]
    pkmn_info["is_dynamaxed"] = True
    pkmn_info["dynamax_turns_left"] = DYNAMAX_TURNS

    return pkmn_info, new_current_hp


def revert_dynamax(pkmn_info: dict, current_hp: int) -> tuple[dict, int]:
    """Reverts a Dynamaxed pkmn_info back to its pre-Dynamax stats/moves when
    the duration ends. Current HP is scaled back down proportionally (so a
    Pokémon at 60% Dynamax HP returns to 60% of its normal max HP, not full
    or empty), same rule as apply_dynamax but in reverse.
    """
    pre = pkmn_info.get("_pre_dynamax")
    if not pre:
        return pkmn_info, current_hp  # was never Dynamaxed, nothing to revert

    old_max_hp = pkmn_info.get("max_hp", 1)
    hp_fraction = (current_hp / old_max_hp) if old_max_hp > 0 else 1.0

    pkmn_info["max_hp"] = pre["max_hp"]
    pkmn_info["attack"]  = pre["attack"]
    pkmn_info["defense"] = pre["defense"]
    pkmn_info["sp_atk"]  = pre["sp_atk"]
    pkmn_info["sp_def"]  = pre["sp_def"]
    pkmn_info["speed"]   = pre["speed"]
    pkmn_info["moves"]   = pre["moves"]
    pkmn_info["is_dynamaxed"] = False
    pkmn_info.pop("dynamax_turns_left", None)
    pkmn_info.pop("_pre_dynamax", None)

    new_current_hp = max(1, int(pre["max_hp"] * hp_fraction)) if current_hp > 0 else 0
    return pkmn_info, new_current_hp


def tick_dynamax(pkmn_info: dict, current_hp: int) -> tuple[dict, int, bool]:
    """Call once per turn for a Dynamaxed Pokémon. Decrements the turn
    counter and auto-reverts when it hits zero. Returns
    (updated_info, updated_hp, just_ended) — just_ended is True only on the
    turn the revert actually happens, so callers can show a "X is no longer
    Dynamaxed!" message exactly once.
    """
    if not pkmn_info.get("is_dynamaxed"):
        return pkmn_info, current_hp, False
    turns_left = pkmn_info.get("dynamax_turns_left", 0) - 1
    if turns_left <= 0:
        pkmn_info, current_hp = revert_dynamax(pkmn_info, current_hp)
        return pkmn_info, current_hp, True
    pkmn_info["dynamax_turns_left"] = turns_left
    return pkmn_info, current_hp, False


async def _user_has_dynamax_band(user_id: int) -> bool:
    """Checks whether the trainer owns a Dynamax Band."""
    profile = get_user(user_id)
    if profile is None:
        return False
    return bool(profile.get("has_dynamax_band"))



