def _get_pkmn_iv_ev_row(pkmn_id: int, user_id: int):
    """
    Fetches a pokemon's full IV/EV/boosted_stats row.
    Returns (pkmn_id, pk_name, level, ivs_dict, evs_dict, boosted_stats_list) or None.
    """
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        """SELECT id, pokemon_name, level,
           iv_hp, iv_atk, iv_def, iv_spa, iv_spd, iv_spe,
           ev_hp, ev_atk, ev_def, ev_spa, ev_spd, ev_spe,
           boosted_stats
           FROM user_pokemon WHERE id = ? AND user_id = ?""",
        (pkmn_id, user_id)
    )
    row = cursor.fetchone()
    conn.close()
    if not row:
        return None
    ivs = {"iv_hp": row[3] or 0, "iv_atk": row[4] or 0, "iv_def": row[5] or 0,
           "iv_spa": row[6] or 0, "iv_spd": row[7] or 0, "iv_spe": row[8] or 0}
    evs = {"ev_hp": row[9] or 0, "ev_atk": row[10] or 0, "ev_def": row[11] or 0,
           "ev_spa": row[12] or 0, "ev_spd": row[13] or 0, "ev_spe": row[14] or 0}
    try:
        boosted = json.loads(row[15]) if row[15] else []
    except Exception:
        boosted = []
    return row[0], row[1], row[2], ivs, evs, boosted


# ════════════════════════════════════════════════════════════════════════════════
# ═════════════ UNIVERSAL COMMAND EXECUTE HELPERS ════════════════════════════════
# ════════════════════════════════════════════════════════════════════════════════
# These are called both by the direct command (single match) and by the
# universal_pokemon_select_callback (after trainer picks from selection UI).
# All accept a query/update object, context, user_id, and resolved pkmn_db_id.
# ════════════════════════════════════════════════════════════════════════════════

async def _execute_boost(query_or_msg, context, user_id: int, pkmn_db_id: int) -> None:
    """Core boost logic after a pokemon has been resolved."""
    is_callback = hasattr(query_or_msg, "edit_message_text")
    send_text = query_or_msg.edit_message_text if is_callback else query_or_msg.message.reply_text

    profile = get_user(user_id)
    boost_count = (profile.get("boost") or 0) if profile else 0
    if boost_count <= 0:
        await send_text("❌ You don't have any Boosts.")
        return
    data = _get_pkmn_iv_ev_row(pkmn_db_id, user_id)
    if not data:
        await send_text("❌ Could not load Pokémon data.")
        return

    _, pk_name, _, ivs, evs, boosted_stats = data

    all_done = all(
        (_iv_col_to_key(col) in boosted_stats or ivs.get(col, 0) >= 31)
        for col, _ in [("iv_hp", "HP"), ("iv_atk", "Atk"), ("iv_def", "Def"),
                       ("iv_spa", "SpA"), ("iv_spd", "SpD"), ("iv_spe", "Spe")]
    )
    if all_done:
        await send_text(f"❌ All of {pk_name}'s IVs are already maxed or boosted.")
        return

    text, keyboard = _build_boost_ui(pk_name, ivs, boost_count, boosted_stats)
    context.user_data[f"boost_pkmn_{user_id}"] = pkmn_db_id
    await send_text(text, reply_markup=InlineKeyboardMarkup(keyboard) if keyboard else None)


async def _execute_vitamin(query_or_msg, context, user_id: int, pkmn_db_id: int) -> None:
    """Core vitamin logic after a pokemon has been resolved."""
    is_callback = hasattr(query_or_msg, "edit_message_text")
    send_text = query_or_msg.edit_message_text if is_callback else query_or_msg.message.reply_text

    profile = get_user(user_id)
    vitamin_count = (profile.get("vitamin") or 0) if profile else 0
    if vitamin_count <= 0:
        await send_text("❌ You don't have any Vitamins.")
        return
    data = _get_pkmn_iv_ev_row(pkmn_db_id, user_id)
    if not data:
        await send_text("❌ Could not load Pokémon data.")
        return

    _, pk_name, _, ivs, evs, _ = data
    total = get_total_evs(evs)

    if total >= 510 and all(evs.get(c, 0) >= 252 for c, _ in EV_STAT_COLS):
        await send_text(f"❌ {pk_name}'s EVs are all maxed out.")
        return

    text, keyboard = _build_vitamin_ui(pk_name, evs, vitamin_count)
    context.user_data[f"vit_pkmn_{user_id}"] = pkmn_db_id
    await send_text(text, reply_markup=InlineKeyboardMarkup(keyboard) if keyboard else None)


async def _execute_berry(query_or_msg, context, user_id: int, pkmn_db_id: int) -> None:
    """Core berry logic after a pokemon has been resolved."""
    is_callback = hasattr(query_or_msg, "edit_message_text")
    send_text = query_or_msg.edit_message_text if is_callback else query_or_msg.message.reply_text

    profile = get_user(user_id)
    berry_count = (profile.get("berry") or 0) if profile else 0
    if berry_count <= 0:
        await send_text("❌ You don't have any Berries.")
        return
    data = _get_pkmn_iv_ev_row(pkmn_db_id, user_id)
    if not data:
        await send_text("❌ Could not load Pokémon data.")
        return

    _, pk_name, _, ivs, evs, _ = data

    if all(evs.get(c, 0) <= 0 for c, _ in EV_STAT_COLS):
        await send_text(f"❌ {pk_name} has no EVs to reduce.")
        return

    text, keyboard = _build_berry_ui(pk_name, evs, berry_count)
    context.user_data[f"berry_pkmn_{user_id}"] = pkmn_db_id
    await send_text(text, reply_markup=InlineKeyboardMarkup(keyboard) if keyboard else None)


async def _execute_candy(query_or_msg, context, user_id: int, pkmn_db_id: int) -> None:
    """Core candy logic after a pokemon has been resolved."""
    is_callback = hasattr(query_or_msg, "edit_message_text")
    send_text = query_or_msg.edit_message_text if is_callback else query_or_msg.message.reply_text

    profile = get_user(user_id)
    candy_count = (profile.get("candy") or 0) if profile else 0
    conn = get_db("ZNX.db")
    cursor = conn.cursor()
    cursor.execute("SELECT pokemon_name, level FROM user_pokemon WHERE id = ? AND user_id = ?", (pkmn_db_id, user_id))
    p_row = cursor.fetchone()

    if candy_count <= 0:
        await send_text("❌ You don't have any Rare Candies.")
        return
    if not p_row:
        await send_text("❌ Pokémon not found.")
        return

    pk_name, lvl = p_row
    if lvl >= MAX_POKEMON_LEVEL:
        await send_text("❌ This Pokémon is already max level.")
        return

    candies_owned = candy_count
    text = (
        f"{pk_name} -> Lv. {lvl}\n\n"
        f"Total Rare Candy 🍬: {candies_owned}\n\n"
        f"🌟 How many candy(s) do you want to use?"
    )
    buttons = [InlineKeyboardButton("[+1]", callback_data=f"candy_use_{pkmn_db_id}_1")]
    if candies_owned >= 5:
        buttons.append(InlineKeyboardButton("[+5]", callback_data=f"candy_use_{pkmn_db_id}_5"))
    if candies_owned >= 10:
        buttons.append(InlineKeyboardButton("[+10]", callback_data=f"candy_use_{pkmn_db_id}_10"))
    await send_text(text, reply_markup=InlineKeyboardMarkup([buttons]))


async def _apply_evolution(
    query_or_msg, context, is_callback: bool, send_text,
    pkmn_db_id: int, pkmn_name: str, is_shiny: bool,
    new_api_id: str, dex_number,
) -> None:
    """Persists an evolution to `user_pokemon` and sends the evolved-into
    announcement. Shared by the normal single-outcome evolve path and the
    Kubfu-style form-choice callback so both go through the same DB write /
    message logic.

    `new_api_id` must already be the correct, directly-fetchable PokéAPI
    slug for the evolved Pokémon (e.g. "urshifu-single-strike", NOT a bare
    multi-variety species name like "urshifu") — see
    _resolve_default_variety_slug / EVOLUTION_FORM_CHOICES. Storing anything
    else here reproduces the /stats-can't-find-it bug this exists to fix."""
    new_display_name = new_api_id.replace("-", " ").title()

    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute("UPDATE user_pokemon SET pokemon_id = ?, pokemon_name = ? WHERE id = ?",
                   (new_api_id, new_display_name, pkmn_db_id))
    conn.commit()
    conn.close()

    if dex_number:
        if is_shiny:
            sprite_url = shiny_sprite_url(dex_number)
        else:
            sprite_url = f"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/{dex_number}.png"
    else:
        sprite_url = f"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/{new_api_id}.png"

    old_display = display_name_with_shiny(pkmn_name, is_shiny)
    new_display = display_name_with_shiny(new_display_name, is_shiny)

    if is_callback:
        await query_or_msg.message.delete()
        await context.bot.send_photo(
            chat_id=query_or_msg.message.chat_id,
            photo=sprite_url,
            caption=f"💫 {old_display} evolved into {new_display}!"
        )
    else:
        await query_or_msg.message.reply_photo(
            photo=sprite_url,
            caption=f"💫 {old_display} evolved into {new_display}!"
        )


async def _execute_evolve(query_or_msg, context, user_id: int, pkmn_db_id: int) -> None:
    """Core evolve logic after a pokemon has been resolved."""
    is_callback = hasattr(query_or_msg, "edit_message_text")
    send_text = query_or_msg.edit_message_text if is_callback else query_or_msg.message.reply_text

    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute("SELECT id, pokemon_id, pokemon_name, level, COALESCE(shiny, 0) FROM user_pokemon WHERE id = ? AND user_id = ?",
                   (pkmn_db_id, user_id))
    row = cursor.fetchone()
    conn.close()

    if not row:
        await send_text("❌ Pokémon not found.")
        return

    pkmn_db_id, pkmn_api_id, pkmn_name, current_lvl, is_shiny_int = row
    is_shiny = bool(is_shiny_int)
    api_lookup_id = normalize_pokemon_name(pkmn_api_id)

    # Use the same evolution resolution logic as evolve() but dispatch from here
    try:
        # All PokéAPI lookups below go through the centralized, persistent
        # cache (`_cached_pokeapi_get`) — never fetched twice, ever.
        species_url = f"https://pokeapi.co/api/v2/pokemon-species/{api_lookup_id}"
        species_data = await _cached_pokeapi_get(species_url)
        if not species_data:
            p_data = await _cached_pokeapi_get(f"https://pokeapi.co/api/v2/pokemon/{api_lookup_id}")
            if not p_data:
                await send_text("❌ Failed to fetch evolution data.")
                return
            species_url = p_data["species"]["url"]
            species_data = await _cached_pokeapi_get(species_url)
            if not species_data:
                await send_text("❌ Failed to fetch evolution data.")
                return

        if not species_data or "evolution_chain" not in species_data:
            await send_text("❌ This Pokémon cannot evolve.")
            return

        evo_chain_url = species_data["evolution_chain"]["url"]
        evo_data = await _cached_pokeapi_get(evo_chain_url)
        if not evo_data:
            await send_text("❌ Failed to fetch evolution chain.")
            return

        chain = evo_data.get("chain")
        if not chain:
            await send_text("❌ This Pokémon cannot evolve.")
            return

        def find_node(node, target):
            node_name = node["species"]["name"].lower().replace("-", "").replace(" ", "")
            target_clean = target.lower().replace("-", "").replace(" ", "")
            if node_name == target_clean:
                return node
            for child in node.get("evolves_to", []):
                res = find_node(child, target)
                if res:
                    return res
            return None

        current_node = find_node(chain, api_lookup_id)
        if not current_node:
            current_node = find_node(chain, pkmn_name)
        if not current_node:
            await send_text("❌ This Pokémon cannot evolve.")
            return

        if not current_node.get("evolves_to"):
            await send_text(f"❌ {pkmn_name} is already at its final evolution stage.")
            return

        next_evo = current_node["evolves_to"][0]
        next_name = next_evo["species"]["name"]
        min_level = None
        evo_details = next_evo.get("evolution_details", [])
        if evo_details:
            min_level = evo_details[0].get("min_level")

        if min_level and current_lvl < min_level:
            await send_text(f"❌ {pkmn_name} needs to reach Lv. {min_level} to evolve.")
            return

        species_url_parts = next_evo["species"]["url"].rstrip("/").split("/")
        try:
            dex_number = int(species_url_parts[-1])
        except (ValueError, IndexError):
            dex_number = None

        # ── Form-choice species (e.g. Kubfu → Urshifu Single/Rapid Strike) ──
        # Genuine in-game player decision between named varieties, not a
        # single PokeAPI "default" the bot should silently pick. Show a
        # button prompt; the actual DB write happens in
        # evolve_form_choice_callback once the trainer picks one.
        species_key = next_name.lower().replace(" ", "-")
        form_choices = EVOLUTION_FORM_CHOICES.get(species_key)
        if form_choices:
            buttons = [
                [InlineKeyboardButton(label, callback_data=f"evoform_{pkmn_db_id}_{variety_slug}")]
                for label, variety_slug in form_choices
            ]
            await send_text(
                f"🌟 {pkmn_name} is ready to evolve! Choose its path:",
                reply_markup=InlineKeyboardMarkup(buttons),
            )
            return

        # ── Normal single-outcome evolution ──────────────────────────────────
        # Resolve the bare species name to its actual fetchable default-variety
        # slug (a no-op for the overwhelming majority of species, where the
        # default variety's name equals the species name) before persisting
        # it as pokemon_id, so later lookups (/stats, sprites, battle stats)
        # key off a slug that genuinely resolves on PokeAPI.
        new_api_id = await _resolve_default_variety_slug(next_name)

        await _apply_evolution(
            query_or_msg, context, is_callback, send_text,
            pkmn_db_id, pkmn_name, is_shiny, new_api_id, dex_number,
        )
    except Exception as e:
        logger.error(f"Evolution error (_execute_evolve): {e}")
        try:
            await send_text("❌ Failed to process evolution.")
        except Exception:
            pass


async def evolve_form_choice_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles a tap on one of the Kubfu-style evolution-form-choice buttons
    (callback_data format: evoform_{pkmn_db_id}_{variety_slug}).

    Re-checks ownership/camp status haven't changed since the prompt was
    shown (mirrors the safety checks _execute_evolve already does) before
    applying the evolution via _apply_evolution, so a stale button tap can't
    silently corrupt state."""
    query = update.callback_query
    user = query.from_user
    parts = (query.data or "").split("_", 2)
    if len(parts) != 3:
        await query.answer("Invalid selection.", show_alert=True)
        return
    try:
        pkmn_db_id = int(parts[1])
    except ValueError:
        await query.answer("Invalid selection.", show_alert=True)
        return
    variety_slug = parts[2]

    await query.answer()

    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        "SELECT id, pokemon_id, pokemon_name, level, COALESCE(shiny, 0) FROM user_pokemon WHERE id = ? AND user_id = ?",
        (pkmn_db_id, user.id),
    )
    row = cursor.fetchone()
    conn.close()

    if not row:
        await query.edit_message_text("❌ Pokémon not found.")
        return
    if is_pokemon_in_camp(pkmn_db_id):
        await query.edit_message_text("❌ This Pokémon is in The Camp.")
        return

    pkmn_db_id, pkmn_api_id, pkmn_name, current_lvl, is_shiny_int = row
    is_shiny = bool(is_shiny_int)

    try:
        # Fetch the chosen variety's own /pokemon/{slug} resource just to
        # read its species dex id, so the sprite matches the species
        # artwork regardless of which variety was picked (Urshifu's two
        # forms share species id 892).
        variety_data = await _cached_pokeapi_get(f"https://pokeapi.co/api/v2/pokemon/{variety_slug}")
        dex_number = None
        if variety_data:
            species_url = variety_data.get("species", {}).get("url", "")
            species_url_parts = species_url.rstrip("/").split("/")
            try:
                dex_number = int(species_url_parts[-1])
            except (ValueError, IndexError):
                dex_number = None

        await _apply_evolution(
            query, context, True, query.edit_message_text,
            pkmn_db_id, pkmn_name, is_shiny, variety_slug, dex_number,
        )
    except Exception as e:
        logger.error(f"Evolution error (evolve_form_choice_callback): {e}")
        try:
            await query.edit_message_text("❌ Failed to process evolution.")
        except Exception:
            pass


async def _execute_release_ask(query_or_msg, context, user_id: int, pkmn_db_id: int) -> None:
    """Shows the release confirmation UI after pokemon is resolved.
    Works from callbacks (stats buttons) and plain messages (groups/DMs)."""
    is_callback = hasattr(query_or_msg, "edit_message_text")

    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute("SELECT pokemon_name, COALESCE(special_tag, '') FROM user_pokemon WHERE id = ? AND user_id = ?", (pkmn_db_id, user_id))
    row = cursor.fetchone()
    conn.close()

    async def _send(text, **kwargs):
        if is_callback:
            try:
                await query_or_msg.edit_message_text(text, **kwargs)
            except Exception:
                await query_or_msg.message.reply_text(text, **kwargs)
        else:
            # query_or_msg is the Update object for group/DM commands
            await query_or_msg.message.reply_text(text, **kwargs)

    if not row:
        await _send("❌ Pokémon not found.")
        return

    pkmn_name   = row[0]
    special_tag = row[1]
    pkmn_display = append_special_tag(pkmn_name, special_tag)

    if is_pokemon_in_camp(pkmn_db_id):
        await _send(f"❌ {pkmn_display} is currently in Camp and cannot be released.\nUse /leavecamp first.")
        return

    text = f"⚠️ Are you sure you want to release your {pkmn_display}?\nThis action <b>cannot</b> be undone."
    kbd = [[
        InlineKeyboardButton("Yes", callback_data=f"release_confirm_{pkmn_db_id}"),
        InlineKeyboardButton("No",  callback_data=f"release_cancel_{pkmn_db_id}")
    ]]
    await _send(text, reply_markup=InlineKeyboardMarkup(kbd), parse_mode="HTML")


async def _execute_squad_add(query_or_msg, context, user_id: int, pkmn_db_id: int, squad_id: int) -> None:
    """Adds the resolved pokemon to the given squad."""
    is_callback = hasattr(query_or_msg, "edit_message_text")
    send_text = query_or_msg.edit_message_text if is_callback else query_or_msg.message.reply_text

    squad = get_squad_by_id(squad_id, user_id)
    if not squad:
        await send_text("❌ Squad not found.")
        return

    sid, team_name, pokemon_ids_json, is_active = squad
    pokemon_ids = json.loads(pokemon_ids_json or "[]")

    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute("SELECT pokemon_name FROM user_pokemon WHERE id = ? AND user_id = ?", (pkmn_db_id, user_id))
    row = cursor.fetchone()
    conn.close()

    if not row:
        await send_text("❌ Pokémon not found.")
        return
    if is_pokemon_in_camp(pkmn_db_id):
        if is_callback:
            await query_or_msg.answer("This Pokémon is in camp can't battle with it.", show_alert=True)
        else:
            await send_text("❌ This Pokémon is in camp can't battle with it.")
        return
    if len(pokemon_ids) >= 6:
        await send_text("❌ Squad is full (max 6)!")
        return
    if pkmn_db_id in pokemon_ids:
        await send_text("❌ That Pokémon is already in this squad!")
        return

    pokemon_ids.append(pkmn_db_id)
    save_squad_pokemon_ids(squad_id, pokemon_ids)

    context.user_data.pop(f"squad_add_pending_{user_id}", None)

    text_ui, _ = await build_squad_ui(user_id, squad_id=squad_id)
    keyboard = _squad_main_keyboard(squad_id)
    await send_text(
        f"✅ {row[0]} added to {team_name}!\n\n{text_ui}",
        reply_markup=InlineKeyboardMarkup(keyboard),
        parse_mode="HTML"
    )


