async def use_boost(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Manual boost selection: /boost <pokemon_name>"""
    if update.effective_chat.type != "private":
        _dm_kbd = InlineKeyboardMarkup([[InlineKeyboardButton("Open Bot DM", url="https://t.me/PokieNova_bot")]])
        await update.message.reply_text("❌ This command only works in private chat.", reply_markup=_dm_kbd)
        return
    user = update.effective_user
    if not context.args:
        await update.message.reply_text("Usage: /boost <pokemon_name>")
        return

    # Check item availability first (fast-fail before showing selection UI)
    profile = get_user(user.id)
    boost_count_check = (profile.get("boost") or 0) if profile else 0
    if boost_count_check <= 0:
        await update.message.reply_text("❌ You don't have any Boosts.")
        return

    pokemon_name = " ".join(context.args).lower()
    rows, pkmn_key = find_pokemon_by_species_or_nickname(user.id, pokemon_name)

    if not rows:
        await update.message.reply_text(f"❌ You don't own a Pokémon named {pokemon_name.capitalize()}.")
        return

    if len(rows) == 1:
        pkmn_db_id = rows[0][0]
        if is_pokemon_in_camp(pkmn_db_id):
            await update.message.reply_text("❌ This Pokémon is currently in Camp.")
            return
        await _execute_boost(update, context, user.id, pkmn_db_id)
    else:
        await show_universal_selection_ui(update.message.reply_text, user.id, rows, pkmn_key, "boost")


async def boost_stat_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles inline button press for boost stat selection."""
    query = update.callback_query
    user = query.from_user

    # Ownership: boost_pkmn_ is keyed per user, so only the original user has it.
    # Additionally, verify the stored pkmn belongs to this user below.
    pkmn_id = context.user_data.get(f"boost_pkmn_{user.id}")
    if not pkmn_id:
        # Could be another user clicking — show ownership alert
        await query.answer("This menu belongs to another trainer.", show_alert=True)
        return

    await query.answer()

    parts = query.data.split(":")
    if len(parts) != 2:
        return
    stat_col = parts[1]  # e.g. iv_hp

    # Security: verify ownership in DB
    conn = get_db("ZNX.db")
    cursor = conn.cursor()
    cursor.execute("SELECT id FROM user_pokemon WHERE id = ? AND user_id = ?", (pkmn_id, user.id))
    if not cursor.fetchone():
        await query.answer("❌ You don't own that Pokémon.", show_alert=True)
        return
    profile = get_user(user.id)
    item_boost = (profile.get("boost") or 0) if profile else 0

    if item_boost <= 0:
        await query.edit_message_text("❌ You don't have any Boosts left.")
        context.user_data.pop(f"boost_pkmn_{user.id}", None)
        return

    boost_count = item_boost

    data = _get_pkmn_iv_ev_row(pkmn_id, user.id)
    if not data:
        await query.edit_message_text("❌ Could not load Pokémon data.")
        return

    _, pk_name, _, ivs, evs, boosted_stats = data
    stat_key = _iv_col_to_key(stat_col)

    # Security checks
    if stat_key in boosted_stats:
        await query.answer("❌ This stat has already been boosted.", show_alert=True)
        return
    if ivs.get(stat_col, 0) >= 31:
        await query.answer("❌ This stat's IV is already at maximum (31).", show_alert=True)
        return

    current_val = ivs.get(stat_col, 0)
    new_val, new_boosted, success, err_msg = apply_boost(pkmn_id, stat_col, current_val, boosted_stats, user.id)

    if not success:
        await query.answer(f"❌ {err_msg}", show_alert=True)
        return

    # Reload fresh data for updated UI
    new_data = _get_pkmn_iv_ev_row(pkmn_id, user.id)
    if not new_data:
        await query.edit_message_text("❌ Could not reload Pokémon data.")
        return

    _, pk_name, _, new_ivs, _, new_boosted_stats = new_data
    new_boost_count = boost_count - 1

    # Build updated UI
    all_done = all(
        (_iv_col_to_key(col) in new_boosted_stats or new_ivs.get(col, 0) >= 31)
        for col, _ in [("iv_hp", "HP"), ("iv_atk", "Atk"), ("iv_def", "Def"),
                       ("iv_spa", "SpA"), ("iv_spd", "SpD"), ("iv_spe", "Spe")]
    )

    stat_display_map = {
        "iv_hp": "HP", "iv_atk": "Attack", "iv_def": "Defense",
        "iv_spa": "Sp. Atk", "iv_spd": "Sp. Def", "iv_spe": "Speed"
    }
    stat_label = stat_display_map.get(stat_col, stat_col)

    if all_done or new_boost_count <= 0:
        done_text = (
            f"{pk_name}'s IVs:\n\n"
            f"Stat          IV\n"
            f"──────────────────\n"
            f"HP            {new_ivs.get('iv_hp', 0)}\n"
            f"Attack        {new_ivs.get('iv_atk', 0)}\n"
            f"Defense       {new_ivs.get('iv_def', 0)}\n"
            f"Sp. Atk       {new_ivs.get('iv_spa', 0)}\n"
            f"Sp. Def       {new_ivs.get('iv_spd', 0)}\n"
            f"Speed         {new_ivs.get('iv_spe', 0)}\n\n"
            f"✅ {stat_label} IV boosted from {current_val} → {new_val}!\n"
            f"💉 Boosts remaining: {new_boost_count}"
        )
        await query.edit_message_text(done_text)
        context.user_data.pop(f"boost_pkmn_{user.id}", None)
    else:
        text, keyboard = _build_boost_ui(pk_name, new_ivs, new_boost_count, new_boosted_stats)
        header = f"✅ {stat_label} IV boosted: {current_val} → {new_val}!\n\n"
        try:
            await query.edit_message_text(
                header + text,
                reply_markup=InlineKeyboardMarkup(keyboard) if keyboard else None
            )
        except Exception:
            pass


