async def vitamin_stat_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles inline button press for vitamin stat selection."""
    query = update.callback_query
    user = query.from_user

    pkmn_id = context.user_data.get(f"vit_pkmn_{user.id}")
    if not pkmn_id:
        await query.answer("This menu belongs to another trainer.", show_alert=True)
        return

    await query.answer()

    parts = query.data.split(":")
    if len(parts) != 2:
        return
    stat_col = parts[1]  # e.g. ev_hp

    conn = get_db("ZNX.db")
    cursor = conn.cursor()
    cursor.execute("SELECT id FROM user_pokemon WHERE id = ? AND user_id = ?", (pkmn_id, user.id))
    if not cursor.fetchone():
        await query.answer("❌ You don't own that Pokémon.", show_alert=True)
        return
    profile = get_user(user.id)
    item_vitamin = (profile.get("vitamin") or 0) if profile else 0

    if item_vitamin <= 0:
        await query.edit_message_text("❌ You don't have any Vitamins left.")
        context.user_data.pop(f"vit_pkmn_{user.id}", None)
        return

    vitamin_count = item_vitamin

    data = _get_pkmn_iv_ev_row(pkmn_id, user.id)
    if not data:
        await query.edit_message_text("❌ Could not load Pokémon data.")
        return

    _, pk_name, _, ivs, evs, _ = data
    current_val = evs.get(stat_col, 0)
    total = get_total_evs(evs)

    if total >= 510:
        await query.answer("❌ Total EVs are already at maximum (510).", show_alert=True)
        return
    if current_val >= 252:
        await query.answer("❌ This stat's EVs are already at maximum (252).", show_alert=True)
        return

    actual_increase, new_val, success, err_msg = apply_vitamin(pkmn_id, stat_col, current_val, evs, user.id)
    if not success:
        await query.answer(f"❌ {err_msg}", show_alert=True)
        return

    new_data = _get_pkmn_iv_ev_row(pkmn_id, user.id)
    if not new_data:
        await query.edit_message_text("❌ Could not reload Pokémon data.")
        return

    _, pk_name, _, _, new_evs, _ = new_data
    new_vitamin_count = vitamin_count - 1
    new_total = get_total_evs(new_evs)

    vit_name_map = {
        "ev_hp": "HP Up", "ev_atk": "Protein", "ev_def": "Iron",
        "ev_spa": "Calcium", "ev_spd": "Zinc", "ev_spe": "Carbos"
    }
    stat_label_map = {
        "ev_hp": "HP", "ev_atk": "Attack", "ev_def": "Defense",
        "ev_spa": "Sp. Atk", "ev_spd": "Sp. Def", "ev_spe": "Speed"
    }
    vit_name = vit_name_map.get(stat_col, stat_col)
    stat_label = stat_label_map.get(stat_col, stat_col)

    all_done = new_total >= 510 or all(
        new_evs.get(c, 0) >= 252 for c, _ in EV_STAT_COLS
    )

    if all_done or new_vitamin_count <= 0:
        done_text = (
            f"{pk_name}'s EV Spreads:\n\n"
            f"Stat            EV\n"
            f"──────────────────────\n"
            f"HP              {new_evs.get('ev_hp', 0)}\n"
            f"Attack         {new_evs.get('ev_atk', 0)}\n"
            f"Defense         {new_evs.get('ev_def', 0)}\n"
            f"Sp. Atk        {new_evs.get('ev_spa', 0)}\n"
            f"Sp. Def         {new_evs.get('ev_spd', 0)}\n"
            f"Speed           {new_evs.get('ev_spe', 0)}\n"
            f"──────────────────────\n"
            f"Total          {new_total} / 510\n\n"
            f"✅ {vit_name} used! {stat_label} EV: {current_val} → {new_val} (+{actual_increase})\n"
            f"💊 Vitamins remaining: {new_vitamin_count}"
        )
        await query.edit_message_text(done_text)
        context.user_data.pop(f"vit_pkmn_{user.id}", None)
    else:
        text, keyboard = _build_vitamin_ui(pk_name, new_evs, new_vitamin_count)
        header = f"✅ {vit_name} used! {stat_label} EV: {current_val} → {new_val} (+{actual_increase})\n\n"
        try:
            await query.edit_message_text(
                header + text,
                reply_markup=InlineKeyboardMarkup(keyboard) if keyboard else None
            )
        except Exception:
            pass


