async def use_berry(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Manual berry selection: /berry <pokemon_name>"""
    if update.effective_chat.type != "private":
        _dm_kbd = InlineKeyboardMarkup([[InlineKeyboardButton("Open Bot DM", url="https://t.me/PokieNova_bot")]])
        await update.message.reply_text("❌ This command only works in private chat.", reply_markup=_dm_kbd)
        return
    user = update.effective_user
    if not context.args:
        await update.message.reply_text("Usage: /berry <pokemon_name>")
        return

    profile = get_user(user.id)
    berry_count_check = (profile.get("berry") or 0) if profile else 0
    if berry_count_check <= 0:
        await update.message.reply_text("❌ You don't have any Berries.")
        return

    pokemon_name = " ".join(context.args).lower()
    rows, pkmn_key = find_pokemon_by_species_or_nickname(user.id, pokemon_name)

    if not rows:
        await update.message.reply_text(f"❌ You don't own a Pokémon named {pokemon_name.capitalize()}.")
        return

    if len(rows) == 1:
        pkmn_db_id = rows[0][0]
        if is_pokemon_in_camp(pkmn_db_id):
            await update.message.reply_text("❌ This Pokémon is currently in Camp.")
            return
        await _execute_berry(update, context, user.id, pkmn_db_id)
    else:
        await show_universal_selection_ui(update.message.reply_text, user.id, rows, pkmn_key, "berry")


async def berry_stat_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles inline button press for berry stat selection."""
    query = update.callback_query
    user = query.from_user

    pkmn_id = context.user_data.get(f"berry_pkmn_{user.id}")
    if not pkmn_id:
        await query.answer("This menu belongs to another trainer.", show_alert=True)
        return

    await query.answer()

    parts = query.data.split(":")
    if len(parts) != 2:
        return
    stat_col = parts[1]  # e.g. ev_hp

    conn = get_db("ZNX.db")
    cursor = conn.cursor()
    cursor.execute("SELECT id FROM user_pokemon WHERE id = ? AND user_id = ?", (pkmn_id, user.id))
    if not cursor.fetchone():
        await query.answer("❌ You don't own that Pokémon.", show_alert=True)
        return
    profile = get_user(user.id)
    item_berry = (profile.get("berry") or 0) if profile else 0

    if item_berry <= 0:
        await query.edit_message_text("❌ You don't have any Berries left.")
        context.user_data.pop(f"berry_pkmn_{user.id}", None)
        return

    berry_count = item_berry

    data = _get_pkmn_iv_ev_row(pkmn_id, user.id)
    if not data:
        await query.edit_message_text("❌ Could not load Pokémon data.")
        return

    _, pk_name, _, ivs, evs, _ = data
    current_val = evs.get(stat_col, 0)

    if current_val <= 0:
        await query.answer("❌ This stat's EVs are already at 0.", show_alert=True)
        return

    actual_reduction, new_val, success, err_msg = apply_berry(pkmn_id, stat_col, current_val, user.id)
    if not success:
        await query.answer(f"❌ {err_msg}", show_alert=True)
        return

    new_data = _get_pkmn_iv_ev_row(pkmn_id, user.id)
    if not new_data:
        await query.edit_message_text("❌ Could not reload Pokémon data.")
        return

    _, pk_name, _, _, new_evs, _ = new_data
    new_berry_count = berry_count - 1
    new_total = get_total_evs(new_evs)

    berry_name_map = {
        "ev_hp": "Pomeg Berry", "ev_atk": "Kelpsy Berry", "ev_def": "Qualot Berry",
        "ev_spa": "Hondew Berry", "ev_spd": "Grepa Berry", "ev_spe": "Tamato Berry"
    }
    stat_label_map = {
        "ev_hp": "HP", "ev_atk": "Attack", "ev_def": "Defense",
        "ev_spa": "Sp. Atk", "ev_spd": "Sp. Def", "ev_spe": "Speed"
    }
    berry_name = berry_name_map.get(stat_col, stat_col)
    stat_label = stat_label_map.get(stat_col, stat_col)

    all_done = all(new_evs.get(c, 0) <= 0 for c, _ in EV_STAT_COLS)

    if all_done or new_berry_count <= 0:
        done_text = (
            f"{pk_name}'s EV Spreads:\n\n"
            f"Stat            EV\n"
            f"──────────────────────\n"
            f"HP              {new_evs.get('ev_hp', 0)}\n"
            f"Attack         {new_evs.get('ev_atk', 0)}\n"
            f"Defense         {new_evs.get('ev_def', 0)}\n"
            f"Sp. Atk        {new_evs.get('ev_spa', 0)}\n"
            f"Sp. Def         {new_evs.get('ev_spd', 0)}\n"
            f"Speed           {new_evs.get('ev_spe', 0)}\n"
            f"──────────────────────\n"
            f"Total          {new_total} / 510\n\n"
            f"✅ {berry_name} used! {stat_label} EV: {current_val} → {new_val} (-{actual_reduction})\n"
            f"🍇 Berries remaining: {new_berry_count}"
        )
        await query.edit_message_text(done_text)
        context.user_data.pop(f"berry_pkmn_{user.id}", None)
    else:
        text, keyboard = _build_berry_ui(pk_name, new_evs, new_berry_count)
        header = f"✅ {berry_name} used! {stat_label} EV: {current_val} → {new_val} (-{actual_reduction})\n\n"
        try:
            await query.edit_message_text(
                header + text,
                reply_markup=InlineKeyboardMarkup(keyboard) if keyboard else None
            )
        except Exception:
            pass

