async def candy_use_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles the interactive candy usage buttons."""
    query = update.callback_query
    user = query.from_user
    
    parts = query.data.split("_")
    pkmn_id = parts[2]
    amount_requested = int(parts[3])
    
    conn = get_db("ZNX.db")
    cursor = conn.cursor()
    
    # Ownership guard: verify this Pokémon belongs to the clicker
    cursor.execute("SELECT pokemon_name, level, pokemon_id, moves, exp FROM user_pokemon WHERE id = ? AND user_id = ?", (pkmn_id, user.id))
    p_row = cursor.fetchone()
    
    if not p_row:
        # Could be stolen click — show ownership alert
        await query.answer("This menu belongs to another trainer.", show_alert=True)
        return
        
    pk_name, lvl, p_api_id, moves_json, exp = p_row
    
    if lvl >= MAX_POKEMON_LEVEL:
        await query.answer("❌ This Pokémon is already max level.", show_alert=True)
        return
        
    profile = get_user(user.id)
    candies_owned = (profile.get("candy") or 0) if profile else 0
    
    if candies_owned < amount_requested:
        await query.answer("❌ You don't have enough Rare Candies.", show_alert=True)
        return
        
    # Cap the amount if it exceeds the Lv.100 ceiling
    actual_amount = min(amount_requested, MAX_POKEMON_LEVEL - lvl)
    if actual_amount <= 0:
        await query.answer("❌ This Pokémon is already max level.", show_alert=True)
        return
        
    new_lvl = lvl + actual_amount
    new_candies = candies_owned - actual_amount
    
    if new_lvl >= MAX_POKEMON_LEVEL:
        new_lvl = MAX_POKEMON_LEVEL
        cursor.execute("UPDATE user_pokemon SET level = ?, exp = ? WHERE id = ?", (new_lvl, MAX_POKEMON_EXP, pkmn_id))
    else:
        cursor.execute("UPDATE user_pokemon SET level = ? WHERE id = ?", (new_lvl, pkmn_id))
    conn.commit()
    update_user(user.id, candy=new_candies)
    
    success_text = (
        f"🍭 Rare Candy Used!\n\n"
        f"⬆️ {pk_name} grew from Lv. {lvl} → Lv. {new_lvl}!\n\n"
        f"🍬 Candies Remaining: {new_candies}"
    )
    
    keyboard = []
    if new_lvl < MAX_POKEMON_LEVEL and new_candies > 0:
        buttons = [InlineKeyboardButton("[+1]", callback_data=f"candy_use_{pkmn_id}_1")]
        if new_candies >= 5:
            buttons.append(InlineKeyboardButton("[+5]", callback_data=f"candy_use_{pkmn_id}_5"))
        if new_candies >= 10:
            buttons.append(InlineKeyboardButton("[+10]", callback_data=f"candy_use_{pkmn_id}_10"))
        keyboard.append(buttons)
        
    reply_markup = InlineKeyboardMarkup(keyboard) if keyboard else None
    
    await query.edit_message_text(success_text, reply_markup=reply_markup)
    
    # Process level up triggers
    await check_evolution_eligibility(pk_name, p_api_id, new_lvl, context, query.message.chat_id)
    await check_new_moves(user.id, pkmn_id, pk_name, p_api_id, lvl, new_lvl, moves_json, context, query.message.chat_id)

# ════════════════════════════════════ SQUAD SYSTEM ════════════════════════════════════

# ── Helper Functions ─────────────────────────────────────────────────────────────────

def get_user_squads(user_id):
    """Returns all squads (rows) for a user."""
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute("SELECT id, team_name, pokemon_ids, is_active FROM user_squads WHERE user_id = ? ORDER BY id ASC", (user_id,))
    rows = cursor.fetchall()
    conn.close()
    return rows  # [(id, team_name, pokemon_ids_json, is_active), ...]

def get_active_squad(user_id):
    """Returns the active squad row or None."""
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute("SELECT id, team_name, pokemon_ids, is_active FROM user_squads WHERE user_id = ? AND is_active = 1 LIMIT 1", (user_id,))
    row = cursor.fetchone()
    conn.close()
    return row

def save_squad_pokemon_ids(squad_id, pokemon_ids: list):
    """Saves the pokemon_ids list for a squad."""
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute("UPDATE user_squads SET pokemon_ids = ? WHERE id = ?", (json.dumps(pokemon_ids), squad_id))
    conn.commit()
    conn.close()

def remove_pokemon_from_all_squads(user_id, pkmn_db_id) -> None:
    """Removes a Pokémon from every squad/team belonging to this user.

    Camp Pokémon cannot remain inside battle squads — this is called the
    moment a Pokémon is sent to Camp so it's automatically pulled out of
    any squad it was a member of.
    """
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute("SELECT id, pokemon_ids FROM user_squads WHERE user_id = ?", (user_id,))
    rows = cursor.fetchall()
    for squad_id, pokemon_ids_json in rows:
        try:
            pokemon_ids = json.loads(pokemon_ids_json or "[]")
        except Exception:
            continue
        if pkmn_db_id in pokemon_ids:
            new_ids = [pid for pid in pokemon_ids if pid != pkmn_db_id]
            cursor.execute(
                "UPDATE user_squads SET pokemon_ids = ? WHERE id = ?",
                (json.dumps(new_ids), squad_id)
            )
    conn.commit()
    conn.close()

def set_active_team_db(user_id, squad_id):
    """Sets one squad as active, deactivating all others for that user."""
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute("UPDATE user_squads SET is_active = 0 WHERE user_id = ?", (user_id,))
    cursor.execute("UPDATE user_squads SET is_active = 1 WHERE id = ? AND user_id = ?", (squad_id, user_id))
    conn.commit()
    conn.close()

def create_squad(user_id, team_name):
    """Creates a new squad and returns its id."""
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute("INSERT INTO user_squads (user_id, team_name, pokemon_ids, is_active) VALUES (?, ?, '[]', 0)", (user_id, team_name))
    squad_id = cursor.lastrowid
    conn.commit()
    conn.close()
    return squad_id

def get_squad_by_id(squad_id, user_id):
    """Returns a single squad row by id, verifying ownership."""
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute("SELECT id, team_name, pokemon_ids, is_active FROM user_squads WHERE id = ? AND user_id = ?", (squad_id, user_id))
    row = cursor.fetchone()
    conn.close()
    return row

def get_usable_squad_pokemon(user_id, fainted_ids=None):
    """
    Returns list of (db_id, name, level, nature) for pokemon in the active squad,
    excluding any in fainted_ids.
    """
    if fainted_ids is None:
        fainted_ids = []
    squad = get_active_squad(user_id)
    if not squad:
        return []
    pokemon_ids = json.loads(squad[2] or "[]")
    if not pokemon_ids:
        return []
    usable = []
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    for pid in pokemon_ids:
        if pid in fainted_ids:
            continue
        cursor.execute("SELECT id, pokemon_name, level, nature FROM user_pokemon WHERE id = ? AND user_id = ?", (pid, user_id))
        row = cursor.fetchone()
        if row and not is_pokemon_in_camp(row[0]):
            usable.append(row)
    conn.close()
    return usable

async def build_squad_ui(user_id, squad_id=None):
    """
    Builds the main /mysquad UI text for the given squad (or the first squad).
    Returns (text, squad_row) or (None, None) if no squads.
    """
    squads = get_user_squads(user_id)
    if not squads:
        return None, None

    # Find the squad to display
    target_squad = None
    if squad_id is not None:
        for s in squads:
            if s[0] == squad_id:
                target_squad = s
                break
    if not target_squad:
        # Show active squad, or first
        for s in squads:
            if s[3] == 1:
                target_squad = s
                break
        if not target_squad:
            target_squad = squads[0]

    sid, team_name, pokemon_ids_json, is_active = target_squad
    pokemon_ids = json.loads(pokemon_ids_json or "[]")
    active_tag = " [★ Active]" if is_active else ""

    lines = [f"{team_name}{active_tag}\n", "━━━━━━━━━━━━━━━━━━\n"]

    if pokemon_ids:
        conn = sqlite3.connect("ZNX.db")
        cursor = conn.cursor()
        for i, pid in enumerate(pokemon_ids, 1):
            cursor.execute(
                "SELECT pokemon_name, nature, COALESCE(shiny, 0), COALESCE(is_favorite, 0), COALESCE(nickname,''), COALESCE(special_tag,'') FROM user_pokemon WHERE id = ? AND user_id = ?",
                (pid, user_id)
            )
            row = cursor.fetchone()
            if row:
                base_name   = row[4] if row[4] else row[0]
                special_tag = row[5] if row[5] else ""
                display     = display_name_with_shiny(_camp_name(pid, base_name), bool(row[2]))
                display     = append_special_tag(display, special_tag)
                if row[3]:
                    display = "🌟 " + display
                lines.append(f"{i}. {display} - {row[1]}\n")
            else:
                lines.append(f"{i}. [Unknown]\n")
        conn.close()
    else:
        lines.append("(No Pokémon in this team)\n")

    lines.append(f"\n━━━━━━━━━━━━━━━━━━\n")
    lines.append(f"Pokémon: [{len(pokemon_ids)}/6]\n")
    lines.append(f"Sort: Level ▼ | Display: Nature")

    text = "".join(lines)
    return text, target_squad

# ── /mysquad Command ──────────────────────────────────────────────────────────────────

async def mysquad(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Main command for managing battle squads."""
    user = update.effective_user
    squads = get_user_squads(user.id)

    # Auto-create Team 1 if none exist
    if not squads:
        squad_id = create_squad(user.id, "Team 1")
        set_active_team_db(user.id, squad_id)
        squads = get_user_squads(user.id)

    text, target_squad = await build_squad_ui(user.id)
    sid = target_squad[0]

    keyboard = _squad_main_keyboard(sid)
    await update.message.reply_text(text, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode="HTML")

def _squad_main_keyboard(squad_id):
    return [
        [InlineKeyboardButton("Add Poke", callback_data=f"sq_add_{squad_id}"),
         InlineKeyboardButton("Remove Poke", callback_data=f"sq_rem_{squad_id}")],
        [InlineKeyboardButton("Swap Order", callback_data=f"sq_swap_{squad_id}_pick"),
         InlineKeyboardButton("Set Active", callback_data=f"sq_setactive_{squad_id}")],
        [InlineKeyboardButton("Teams", callback_data=f"sq_teams_{squad_id}"),
         InlineKeyboardButton("New Team", callback_data=f"sq_newteam_{squad_id}")],
    ]

# ── Squad Callbacks ───────────────────────────────────────────────────────────────────

async def squad_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Master callback router for all sq_ prefixed callbacks."""
    query = update.callback_query
    user = query.from_user

    data = query.data  # e.g. sq_add_5, sq_rem_5, sq_swap_5_pick, sq_swap_5_1_3, etc.
    parts = data.split("_")
    action = parts[1]  # add / rem / swap / setactive / teams / newteam / viewteam / confirm_newteam

    # ── Ownership guard: extract squad_id and verify it belongs to this user ──
    # viewteam, setdo, and swapdo also carry squad_id in parts[2]
    try:
        cand_squad_id = int(parts[2])
        # get_squad_by_id already checks user_id; if it returns None → not theirs
        cand_squad = get_squad_by_id(cand_squad_id, user.id)
        if cand_squad is None:
            # Squad doesn't belong to this user
            if not await validate_owner(query, -1):  # -1 never matches, always rejects
                return
    except (IndexError, ValueError):
        pass  # No squad_id in parts (shouldn't happen); let later validation handle it

    await query.answer()

    # ── VIEW A SPECIFIC TEAM ──
    if action == "viewteam":
        squad_id = int(parts[2])
        squad = get_squad_by_id(squad_id, user.id)
        if not squad:
            await query.answer("Squad not found.", show_alert=True)
            return
        text, target = await build_squad_ui(user.id, squad_id=squad_id)
        keyboard = _squad_main_keyboard(squad_id)
        await query.edit_message_text(text, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode="HTML")
        return

    # Extract squad_id from parts[2] for most actions
    try:
        squad_id = int(parts[2])
    except (IndexError, ValueError):
        await query.answer("Invalid action.", show_alert=True)
        return

    squad = get_squad_by_id(squad_id, user.id)
    if not squad:
        await query.answer("Squad not found.", show_alert=True)
        return

    sid, team_name, pokemon_ids_json, is_active = squad
    pokemon_ids = json.loads(pokemon_ids_json or "[]")

    # ── ADD POKEMON ──
    if action == "add":
        if len(pokemon_ids) >= 6:
            await query.answer("Squad is full (max 6)!", show_alert=True)
            return

        page = 1
        if len(parts) >= 4:
            try:
                page = int(parts[3])
            except ValueError:
                page = 1

        # Fetch all owned pokemon using the standard find_duplicate_pokemon schema
        conn = sqlite3.connect("ZNX.db")
        cursor = conn.cursor()
        cursor.execute(
            """SELECT id, pokemon_id, pokemon_name, level, nature,
                   iv_hp, iv_atk, iv_def, iv_spa, iv_spd, iv_spe,
                   ev_hp, ev_atk, ev_def, ev_spa, ev_spd, ev_spe,
                   caught_at, COALESCE(shiny, 0), COALESCE(is_favorite, 0),
                   COALESCE(nickname, ''), COALESCE(special_tag, '')
               FROM user_pokemon WHERE user_id = ?""",
            (user.id,)
        )
        all_owned = cursor.fetchall()
        conn.close()

        # Filter out pokemon already in squad
        available = [r for r in all_owned if r[0] not in pokemon_ids]

        if not available:
            await query.edit_message_text(
                f"All your Pokémon are already in {team_name}!",
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("Back", callback_data=f"sq_viewteam_{squad_id}")]])
            )
            return

        settings = get_user_settings(user.id)
        sorted_rows = sort_pokemon_results(available, settings)
        total = len(sorted_rows)
        total_pages = max(1, math.ceil(total / STATS_SELECT_PAGE_SIZE))
        page = max(1, min(page, total_pages))
        offset = (page - 1) * STATS_SELECT_PAGE_SIZE
        page_rows = sorted_rows[offset: offset + STATS_SELECT_PAGE_SIZE]

        display_mode = settings["display_mode"]
        sort_mode = settings["sort_mode"]
        sort_order = settings["sort_order"]
        sort_label = SORT_MODE_LABELS.get(sort_mode, sort_mode.title())
        sort_arrow = "▼" if sort_order == "desc" else "▲"
        display_label = DISPLAY_MODE_LABELS.get(display_mode, display_mode.title())

        lines = [f"➕ Add Pokémon to {team_name}\n"]
        for i, row in enumerate(page_rows, start=1):
            global_idx  = offset + i
            val         = format_display_value(row, display_mode)
            is_shiny    = bool(row[18]) if len(row) > 18 else False
            nickname    = row[20] if len(row) > 20 and row[20] else ""
            special_tag = row[21] if len(row) > 21 and row[21] else ""
            # Show nickname as primary name; fall back to species name
            base_name   = nickname if nickname else row[2]
            poke_display = display_name_with_shiny(_camp_name(row[0], base_name), is_shiny)
            poke_display = append_special_tag(poke_display, special_tag)
            entry = f"{global_idx}. {poke_display}"
            if display_mode != "none" and val:
                entry += f" - {val}"
            lines.append(entry)
        lines.append(f"\nPage: {page}/{total_pages}")
        lines.append(f"Sort: {sort_label} {sort_arrow} | Display: {display_label}")
        text = "\n".join(lines)

        # Number buttons → sq_addpick_{squad_id}_{db_id}
        kbd = []
        btn_row = []
        for i, row in enumerate(page_rows):
            global_idx = offset + i + 1
            btn_row.append(InlineKeyboardButton(str(global_idx), callback_data=f"sq_addpick_{squad_id}_{row[0]}"))
            if len(btn_row) == 5:
                kbd.append(btn_row)
                btn_row = []
        if btn_row:
            kbd.append(btn_row)

        nav_row = []
        if page > 1:
            if page > 5:
                nav_row.append(InlineKeyboardButton("-5", callback_data=f"sq_add_{squad_id}_{max(1, page - 5)}"))
            nav_row.append(InlineKeyboardButton("Prev", callback_data=f"sq_add_{squad_id}_{page - 1}"))
        if page < total_pages:
            nav_row.append(InlineKeyboardButton("Next", callback_data=f"sq_add_{squad_id}_{page + 1}"))
            if page + 5 <= total_pages:
                nav_row.append(InlineKeyboardButton("+5", callback_data=f"sq_add_{squad_id}_{min(total_pages, page + 5)}"))
        if nav_row:
            kbd.append(nav_row)
        kbd.append([InlineKeyboardButton("Back", callback_data=f"sq_viewteam_{squad_id}")])

        await query.edit_message_text(text, reply_markup=InlineKeyboardMarkup(kbd), parse_mode="HTML")
        return

    # ── ADD POKEMON — PICK ──
    if action == "addpick":
        pkmn_db_id = int(parts[3])
        squad = get_squad_by_id(squad_id, user.id)
        sid, team_name, pokemon_ids_json, is_active = squad
        pokemon_ids = json.loads(pokemon_ids_json or "[]")

        # Verify ownership
        conn = sqlite3.connect("ZNX.db")
        cursor = conn.cursor()
        cursor.execute("SELECT pokemon_name FROM user_pokemon WHERE id = ? AND user_id = ?", (pkmn_db_id, user.id))
        row = cursor.fetchone()
        conn.close()

        if not row:
            await query.answer("Pokémon not found.", show_alert=True)
            return
        if is_pokemon_in_camp(pkmn_db_id):
            await query.answer("This Pokémon is in camp can't battle with it.", show_alert=True)
            return
        if len(pokemon_ids) >= 6:
            await query.answer("Squad is full!", show_alert=True)
            return
        if pkmn_db_id in pokemon_ids:
            await query.answer("Already in this squad!", show_alert=True)
            return

        pokemon_ids.append(pkmn_db_id)
        save_squad_pokemon_ids(squad_id, pokemon_ids)

        text, target = await build_squad_ui(user.id, squad_id=squad_id)
        keyboard = _squad_main_keyboard(squad_id)
        await query.edit_message_text(
            f"✅ {row[0]} added to {team_name}!\n\n{text}",
            reply_markup=InlineKeyboardMarkup(keyboard),
            parse_mode="HTML"
        )
        return

    # ── REMOVE POKEMON ──
    if action == "rem":
        if not pokemon_ids:
            await query.answer("Squad is already empty!", show_alert=True)
            return

        text = f"➖ Remove Pokémon from {team_name}\n\nSelect Pokémon to remove:\n"
        keyboard = []
        conn = sqlite3.connect("ZNX.db")
        cursor = conn.cursor()
        for i, pid in enumerate(pokemon_ids, 1):
            cursor.execute("SELECT pokemon_name, level, COALESCE(shiny, 0), COALESCE(special_tag, '') FROM user_pokemon WHERE id = ? AND user_id = ?", (pid, user.id))
            row = cursor.fetchone()
            if row:
                display = display_name_with_shiny(row[0], bool(row[2]))
                display = append_special_tag(display, row[3])
                label = f"{i}. {display} Lv.{row[1]}"
            else:
                label = f"Slot {i}"
            keyboard.append([InlineKeyboardButton(label, callback_data=f"sq_rempick_{squad_id}_{pid}")])
        conn.close()
        keyboard.append([InlineKeyboardButton("Back", callback_data=f"sq_viewteam_{squad_id}")])
        await query.edit_message_text(text, reply_markup=InlineKeyboardMarkup(keyboard))
        return

    # ── REMOVE POKEMON — PICK ──
    if action == "rempick":
        pkmn_db_id = int(parts[3])
        squad = get_squad_by_id(squad_id, user.id)
        sid, team_name, pokemon_ids_json, is_active = squad
        pokemon_ids = json.loads(pokemon_ids_json or "[]")

        conn = sqlite3.connect("ZNX.db")
        cursor = conn.cursor()
        cursor.execute("SELECT pokemon_name FROM user_pokemon WHERE id = ? AND user_id = ?", (pkmn_db_id, user.id))
        row = cursor.fetchone()
        conn.close()

        if pkmn_db_id not in pokemon_ids:
            await query.answer("Pokémon not in squad.", show_alert=True)
            return

        pokemon_ids.remove(pkmn_db_id)
        save_squad_pokemon_ids(squad_id, pokemon_ids)

        pkmn_name = row[0] if row else "Unknown"
        text, target = await build_squad_ui(user.id, squad_id=squad_id)
        keyboard = _squad_main_keyboard(squad_id)
        await query.edit_message_text(
            f"❌ {pkmn_name} removed from {team_name}!\n\n{text}",
            reply_markup=InlineKeyboardMarkup(keyboard),
            parse_mode="HTML"
        )
        return

    # ── SWAP ORDER ──
    if action == "swap":
        # parts: sq_swap_{squad_id}_pick  OR  sq_swap_{squad_id}_{slot_from}_{slot_to}
        if len(parts) < 4:
            await query.answer("Invalid swap data.", show_alert=True)
            return

        sub = parts[3]

        if sub == "pick":
            # Step 1: pick source slot
            if not pokemon_ids:
                await query.answer("Squad is empty.", show_alert=True)
                return
            text = f"🔄 Swap Order — {team_name}\n\nSelect Pokémon to move:\n"
            conn = sqlite3.connect("ZNX.db")
            cursor = conn.cursor()
            keyboard = []
            row_btns = []
            for i, pid in enumerate(pokemon_ids):
                cursor.execute("SELECT pokemon_name, COALESCE(shiny, 0) FROM user_pokemon WHERE id = ?", (pid,))
                r = cursor.fetchone()
                if r:
                    label = f"{i+1}. {display_name_with_shiny(r[0], bool(r[1]))}"
                else:
                    label = f"Slot {i+1}"
                row_btns.append(InlineKeyboardButton(str(i+1), callback_data=f"sq_swap_{squad_id}_{i}_dst"))
                if len(row_btns) == 3:
                    keyboard.append(row_btns)
                    row_btns = []
            if row_btns:
                keyboard.append(row_btns)
            conn.close()
            keyboard.append([InlineKeyboardButton("Back", callback_data=f"sq_viewteam_{squad_id}")])
            await query.edit_message_text(text, reply_markup=InlineKeyboardMarkup(keyboard))
            return

        elif sub.isdigit() and len(parts) == 5 and parts[4] == "dst":
            # Step 2: pick destination slot
            src = int(sub)
            squad = get_squad_by_id(squad_id, user.id)
            sid, team_name, pokemon_ids_json, is_active = squad
            pokemon_ids = json.loads(pokemon_ids_json or "[]")

            conn = sqlite3.connect("ZNX.db")
            cursor = conn.cursor()
            src_name = "?"
            cursor.execute("SELECT pokemon_name FROM user_pokemon WHERE id = ?", (pokemon_ids[src],))
            r = cursor.fetchone()
            if r:
                src_name = r[0]
            conn.close()

            text = f"🔄 Moving: {src_name} (Slot {src+1})\n\nSelect destination slot:\n"
            keyboard = []
            row_btns = []
            for i in range(len(pokemon_ids)):
                if i == src:
                    row_btns.append(InlineKeyboardButton(f"[{i+1}]", callback_data=f"sq_noop"))
                else:
                    row_btns.append(InlineKeyboardButton(str(i+1), callback_data=f"sq_swapdo_{squad_id}_{src}_{i}"))
                if len(row_btns) == 3:
                    keyboard.append(row_btns)
                    row_btns = []
            if row_btns:
                keyboard.append(row_btns)
            keyboard.append([InlineKeyboardButton("Back", callback_data=f"sq_swap_{squad_id}_pick")])
            await query.edit_message_text(text, reply_markup=InlineKeyboardMarkup(keyboard))
            return

    # ── SWAP DO ──
    if action == "swapdo":
        src = int(parts[3])
        dst = int(parts[4])
        squad = get_squad_by_id(squad_id, user.id)
        sid, team_name, pokemon_ids_json, is_active = squad
        pokemon_ids = json.loads(pokemon_ids_json or "[]")

        if src >= len(pokemon_ids) or dst >= len(pokemon_ids):
            await query.answer("Invalid slot.", show_alert=True)
            return

        # Swap
        pokemon_ids[src], pokemon_ids[dst] = pokemon_ids[dst], pokemon_ids[src]
        save_squad_pokemon_ids(squad_id, pokemon_ids)

        # Get moved pokemon name
        conn = sqlite3.connect("ZNX.db")
        cursor = conn.cursor()
        cursor.execute("SELECT pokemon_name FROM user_pokemon WHERE id = ?", (pokemon_ids[dst],))
        r = cursor.fetchone()
        conn.close()
        moved_name = r[0] if r else "Pokémon"

        text, target = await build_squad_ui(user.id, squad_id=squad_id)
        keyboard = _squad_main_keyboard(squad_id)
        await query.edit_message_text(
            f"✅ {moved_name} moved to Slot {dst+1}!\n\n{text}",
            reply_markup=InlineKeyboardMarkup(keyboard),
            parse_mode="HTML"
        )
        return

    # ── NO-OP (already selected slot) ──
    if action == "noop":
        await query.answer("That's the current slot!", show_alert=True)
        return

    # ── SET ACTIVE ──
    if action == "setactive":
        squads = get_user_squads(user.id)
        text = "🌟 Choose Active Team:\n\n"
        keyboard = []
        for s in squads:
            s_id, s_name, _, s_active = s
            label = f"{'★ ' if s_active else ''}{s_name}"
            keyboard.append([InlineKeyboardButton(label, callback_data=f"sq_setdo_{s_id}")])
        keyboard.append([InlineKeyboardButton("Back", callback_data=f"sq_viewteam_{squad_id}")])
        await query.edit_message_text(text, reply_markup=InlineKeyboardMarkup(keyboard))
        return

    # ── SET ACTIVE — DO ──
    if action == "setdo":
        set_active_team_db(user.id, squad_id)
        squad = get_squad_by_id(squad_id, user.id)
        team_name = squad[1] if squad else "Team"
        text, target = await build_squad_ui(user.id, squad_id=squad_id)
        keyboard = _squad_main_keyboard(squad_id)
        await query.edit_message_text(
            f"✅ {team_name} is now active!\n\n{text}",
            reply_markup=InlineKeyboardMarkup(keyboard),
            parse_mode="HTML"
        )
        return

    # ── TEAMS LIST ──
    if action == "teams":
        squads = get_user_squads(user.id)
        text = "📋 Your Teams:\n\n"
        keyboard = []
        for s in squads:
            s_id, s_name, pids_json, s_active = s
            pids = json.loads(pids_json or "[]")
            label = f"{'★ ' if s_active else ''}{s_name} [{len(pids)}/6]"
            keyboard.append([InlineKeyboardButton(label, callback_data=f"sq_viewteam_{s_id}")])
        keyboard.append([InlineKeyboardButton("New Team", callback_data=f"sq_newteam_{squad_id}")])
        keyboard.append([InlineKeyboardButton("Back", callback_data=f"sq_viewteam_{squad_id}")])
        await query.edit_message_text(text, reply_markup=InlineKeyboardMarkup(keyboard))
        return

    # ── NEW TEAM ──
    if action == "newteam":
        existing = get_user_squads(user.id)
        if len(existing) >= 5:
            await query.answer("Max 5 teams allowed!", show_alert=True)
            return
        new_name = f"Team {len(existing) + 1}"
        new_id = create_squad(user.id, new_name)
        text, target = await build_squad_ui(user.id, squad_id=new_id)
        keyboard = _squad_main_keyboard(new_id)
        await query.edit_message_text(
            f"✅ {new_name} created!\n\n{text}",
            reply_markup=InlineKeyboardMarkup(keyboard),
            parse_mode="HTML"
        )
        return

    # Fallback: go back to main squad view
    text, target = await build_squad_ui(user.id, squad_id=squad_id)
    if text:
        keyboard = _squad_main_keyboard(squad_id)
        await query.edit_message_text(text, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode="HTML")

# ═══════════════════════════════════════════════════════════════════════════════════════
# ════════════════════════════════════ SHOP COMMANDS ════════════════════════════════════

ROMART_PHOTO_URL = "https://files.catbox.moe/vbu8eh.jpg"


def build_romart_home_caption(rupees: int) -> str:
    """The single source of truth for the RoMart home caption text.

    Every entry point into RoMart's main menu — the initial /romart
    command AND every "Back" button from any RoMart sub-section (TMs
    Store, etc.) — must render this exact caption via this function, so
    the home page never drifts out of sync or gets stuck showing a
    sub-section's UI.
    """
    return (
        f'<b><u>RᴏMᴀʀᴛ</u></b> 🛒\n'
        f'Your RᴏRᴜᴩᴇᴇꜱ: {rupees:,} 💵\n\n'
        '<b><u>Pokéballs</u></b>:\n'
        '<blockquote>Regular Ball — 10 💶      \n'
        'Great Ball — 20 💶      \n'
        'Ultra Ball — 25 💶      \n'
        'Repeat Ball — 25 💶      \n'
        'Nest Ball — 15 💶      \n'
        'Dusk Ball — 35 💶</blockquote>\n\n'
        '<b><u>Special Balls</u></b>:\n'
        '<blockquote>Quick Ball — 60 💶      \n'
        'Net Ball — 60 💶      \n'
        'Level Ball — 60 💶      \n'
        'Fast Ball — 60 💶      \n'
        'Heavy Ball — 60 💶      \n'
        'Moon Ball — 60 💶      \n'
        'Love Ball — 60 💶      \n'
        'Beast Ball — 400 💶      \n'
        'Master Ball — 25,000 💶</blockquote>\n\n'
        '<b><u>Items</u></b>:  <blockquote>🍭 Rare Candy — 50 💶      \n'
        '🫐 Berry — 25 💶      \n'
        '🧬 Vitamin — 25 💶      \n'
        '💉 Boost — 250 💶</blockquote>\n\n'
        '<b><u>Key Items</u></b>:      \n'
        '<blockquote>Dynamax Band — 5,000 💶      \n'
        'Key Stone — 5,000 💶</blockquote>\n\n'
        '<b><u>How to Buy</u></b>:'
        ' <blockquote>/buy [item] [quantity]</blockquote>\n\n'
        '<b><u>How to Sell</u></b>:   <blockquote>/sell [item] [quantity]</blockquote>\n\n'
        '<b><u>Example</u></b>:   <blockquote>/buy Ultra 2  ·  /sell candy 3      \n'
        '/buy Keystone  ·  /buy Dynamax Band</blockquote>'
    )


def _get_romart_home_rupees(user_id: int) -> int | None:
    """Fresh RoRupee balance for the RoMart home caption, or None if
    the trainer isn't registered."""
    profile = get_user(user_id)
    if profile is None:
        return None
    return profile.get("nova_rupee") or 0


async def render_romart_home(query, user_id: int) -> None:
    """Centralized RoMart home renderer. Rebuilds the ORIGINAL caption and
    keyboard from scratch (fresh rupee balance included) and edits the
    current message to show it.

    Every "Back" button anywhere in RoMart — regardless of which
    sub-section it's backing out of — must call this function instead of
    only touching the reply markup, so the message can never get stuck
    showing a sub-section's caption (e.g. the TM Store) while displaying
    home-menu buttons.
    """
    rupees = _get_romart_home_rupees(user_id)
    if rupees is None:
        await query.edit_message_caption(caption="You haven't registered yet! Type /start to begin your journey.")
        return
    caption = build_romart_home_caption(rupees)
    try:
        await query.edit_message_caption(
            caption=caption,
            reply_markup=romart_tm_button(user_id),
            parse_mode="HTML",
        )
    except Exception:
        pass


async def romart_store(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Displays the RoMart shop UI as a Telegram photo message.

    Sends the RoMart artwork as a normal photo and the shop text as its
    caption.  No web-preview tricks (<a href>), link_preview_options, or
    invisible URLs are used -- just reply_photo() with parse_mode HTML.
    """
    user = update.effective_user

    # ── Battle restriction: block store access during any active battle ──────
    if _is_in_battle(user.id) or context.user_data.get('safari_active'):
        await update.message.reply_text(
            "❌ You cannot access the Ro Market while battling!\n\n"
            "Finish your battle first."
        )
        return
    # ─────────────────────────────────────────────────────────────────────────

    rupees = _get_romart_home_rupees(user.id)

    if rupees is None:
        await update.message.reply_text("You haven't registered yet! Type /start to begin your journey.")
        return

    # Caption carries all the HTML-formatted shop UI — same builder used by
    # every RoMart "Back" button, so home always renders identically.
    caption = build_romart_home_caption(rupees)

    # Send as a normal Telegram photo -- artwork on top, formatted UI as caption.
    # A single inline button is added below the existing shop UI, opening the
    # weekly TMs Store (see the TM Store & TM Learning System section below).
    await update.message.reply_photo(
        photo=ROMART_PHOTO_URL,
        caption=caption,
        parse_mode="HTML",
        reply_markup=romart_tm_button(user.id),
    )


async def buy_item(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Buys items from the romart_store."""
    user = update.effective_user

    # ── Battle restriction: block purchases during any active battle ─────────
    if _is_in_battle(user.id) or context.user_data.get('safari_active'):
        await update.message.reply_text(
            "❌ You cannot access the Ro Market while battling!\n\n"
            "Finish your battle first."
        )
        return
    # ─────────────────────────────────────────────────────────────────────────

    if len(context.args) < 1:
        await update.message.reply_text("❌ Invalid format. Use /buy [item] [quantity]")
        return

    # Join all args to support "dynamax band", "key stone" multi-word input
    raw_input = " ".join(context.args).lower().strip()

    # ── Key Item alias resolution ─────────────────────────────────────────────
    KEY_ITEM_ALIASES = {
        "keystone": "keystone",
        "key stone": "keystone",
        "key_stone": "keystone",
        "dynamax_band": "dynamax_band",
        "dynamax band": "dynamax_band",
        "dynamaxband": "dynamax_band",
    }
    # Check for key item aliases first (may contain spaces)
    resolved_key_item = KEY_ITEM_ALIASES.get(raw_input)

    if resolved_key_item:
        item_name = resolved_key_item
        quantity = 1
    else:
        # Standard item: first arg is item name, second is quantity
        item_name = context.args[0].lower()
        if len(context.args) < 2:
            await update.message.reply_text("❌ Invalid format. Use /buy [item] [quantity]")
            return
        try:
            quantity = int(context.args[1])
            if quantity <= 0:
                raise ValueError
        except ValueError:
            await update.message.reply_text("❌ Invalid quantity.")
            return

    if item_name not in ITEM_PRICES:
        await update.message.reply_text("❌ Invalid item.")
        return

    # ── Key Items: one-time purchase only ─────────────────────────────────────
    KEY_ITEMS = {"keystone", "dynamax_band"}
    is_key_item = item_name in KEY_ITEMS

    cost = ITEM_PRICES[item_name] * quantity
    db_col = ITEM_DB_COLS[item_name]
    ui_name = ITEM_UI_NAMES[item_name]

    profile = get_user(user.id)
    if profile is None:
        await update.message.reply_text("You haven't registered yet! Type /start to begin your journey.")
        return

    rupees, current_owned = profile.get("nova_rupee") or 0, profile.get(db_col) or 0

    # One-time purchase guard for key items
    if is_key_item and current_owned:
        await update.message.reply_text(f"❌ You already own the <b>{ui_name}</b>.", parse_mode="HTML")
        return

    if rupees < cost:
        await update.message.reply_text("❌ You don't have enough Ro Rupees.")
        return

    if is_key_item:
        increment_user(user.id, nova_rupee=-cost, **{db_col: 1})
    else:
        increment_user(user.id, nova_rupee=-cost, **{db_col: quantity})

    # Re-read from cache — reflects the increment_user() call above
    # immediately, since USER_CACHE is read-through/write-through in memory
    # (see get_user's module docstring); no disk round-trip needed here.
    new_bal = get_user(user.id)["nova_rupee"]

    ui = (
        "✅ Purchase Successful!\n\n"
        f"🛒 Bought: {ui_name}" + (f" x{quantity}" if not is_key_item else "") + "\n"
        f"💸 Cost: {cost:,} 💶\n"
        f"💰 Remaining Balance: {new_bal:,} 💶"
    )
    await update.message.reply_text(ui)

async def sell_item(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Sells items back to the romart_store for half price."""
    user = update.effective_user
    if len(context.args) < 2:
        await update.message.reply_text("❌ Invalid format. Use /sell [item] [quantity]")
        return
        
    item_name = context.args[0].lower()
    try:
        quantity = int(context.args[1])
        if quantity <= 0:
            raise ValueError
    except ValueError:
        await update.message.reply_text("❌ Invalid quantity.")
        return
        
    if item_name not in ITEM_PRICES:
        await update.message.reply_text("❌ Invalid item.")
        return
        
    earn = (ITEM_PRICES[item_name] // 2) * quantity
    db_col = ITEM_DB_COLS[item_name]
    ui_name = ITEM_UI_NAMES[item_name]
    
    profile = get_user(user.id)
    if profile is None:
        await update.message.reply_text("You haven't registered yet! Type /start to begin your journey.")
        return
        
    current_amount = profile.get(db_col) or 0
    
    if current_amount < quantity:
        await update.message.reply_text("❌ You don't have enough of this item to sell.")
        return
        
    increment_user(user.id, nova_rupee=earn, **{db_col: -quantity})
    new_bal = get_user(user.id)["nova_rupee"]
    
    ui = (
        "💸 Sold Successfully!\n\n"
        f"📦 Sold: {ui_name} x{quantity}\n"
        f"💰 Earned: {earn} 💴\n"
        f"💳 New Balance: {new_bal} 💴"
    )
    await update.message.reply_text(ui)

async def start(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    """Starts the conversation — sends Page 1 of the 3-page intro flow."""
    if update.effective_chat.type != "private":
        keyboard = [[InlineKeyboardButton("Open Bot DM", url="https://t.me/PokieNova_bot?start=cmd_start")]]
        reply_markup = InlineKeyboardMarkup(keyboard)
        await update.message.reply_text("❌ This command only works in private chat.", reply_markup=reply_markup)
        return ConversationHandler.END

    user = update.effective_user

    # ── Capture referral code from deep-link (/start RO7XK2) ───────────────
    args = context.args or []
    referral_arg = args[0] if args else ""
    if referral_arg.startswith("RO") and len(referral_arg) >= 8:
        context.user_data["pending_referral_code"] = referral_arg

    # Check if user is already fully registered
    if is_registered(user.id):
        row = is_registered(user.id)
        if row and row[0]:
            await update.message.reply_text(
                "Professor Orion: You've already received your starter! Your journey is underway. Type /stats to see your Pokemon's stats."
            )
            return ConversationHandler.END
        # Registered in DB but trainer_name is still NULL
        await update.message.reply_text(
            "⚠️ Please send your Trainer Name first to continue your registration."
        )
        return ASK_NAME

    # If intro was already shown (user is mid-flow and hit /start again)
    if context.user_data.get("intro_shown"):
        await update.message.reply_text(
            "⚠️ Please send your Trainer Name first to continue your registration."
        )
        return ASK_NAME

    # ── Page 1: Welcome ──────────────────────────────────────────────────────
    keyboard = [
        [InlineKeyboardButton("Next", callback_data="intro_next")],
        [InlineKeyboardButton("💬 Official Group", url="https://t.me/daxxy_oooo")],
        [InlineKeyboardButton("📢 Updates Channel", url="https://t.me/+l2CnMik5hbM4MmY9")],
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)

    await update.message.reply_photo(
        photo="https://files.catbox.moe/k90aur.jpg",
        caption=(
            "🌟 <b><u>Welcome, Trainer!</u></b> 🌟\n\n"
            "This is the incredible world of Pokémon — a land filled with adventure, discovery, and powerful bonds between trainers and Pokémon.\n\n"
            "Across every region, humans and Pokémon live together, exploring, battling, and growing stronger side by side.\n\n"
            "Your journey is about to begin...\n\n"
            "⬇️ <b>Tap the button below to continue.</b>"
        ),
        parse_mode="HTML",
        reply_markup=reply_markup
    )
