def remove_pokemon_from_system(user_id, pkmn_id):
    """Helper to cleanly delete a pokemon and remove it from squads and active status."""
    conn = get_db("ZNX.db")
    cursor = conn.cursor()
    
    # 1. Remove from squads
    cursor.execute("SELECT id, pokemon_ids FROM user_squads WHERE user_id = ?", (user_id,))
    squads = cursor.fetchall()
    for sq_id, pids_json in squads:
        pids = json.loads(pids_json or "[]")
        if pkmn_id in pids:
            pids.remove(pkmn_id)
            cursor.execute("UPDATE user_squads SET pokemon_ids = ? WHERE id = ?", (json.dumps(pids), sq_id))
    
    # 2. Check if active pokemon
    profile = get_user(user_id)
    if profile and profile.get("active_pokemon_id") == pkmn_id:
        # Reassign active to the first available pokemon
        cursor.execute("SELECT id FROM user_pokemon WHERE user_id = ? AND id != ? LIMIT 1", (user_id, pkmn_id))
        fallback = cursor.fetchone()
        new_active = fallback[0] if fallback else 0
        update_user(user_id, active_pokemon_id=new_active)
    
    # 3. Delete from DB
    cursor.execute("DELETE FROM user_pokemon WHERE id = ? AND user_id = ?", (pkmn_id, user_id))
    
    conn.commit()

async def release_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles the interactive release confirmation system.
    Works from stats photo messages AND plain text messages."""
    query = update.callback_query
    user  = query.from_user
    await query.answer()

    parts   = query.data.split("_")
    action  = parts[1]          # ask | confirm | cancel
    pkmn_id = int(parts[2])

    # Helper: edit caption if photo message, else edit text
    async def _edit(text, reply_markup=None, parse_mode="HTML"):
        kwargs = {"parse_mode": parse_mode}
        if reply_markup:
            kwargs["reply_markup"] = reply_markup
        try:
            if query.message.photo:
                await query.edit_message_caption(caption=text, **kwargs)
            else:
                await query.edit_message_text(text, **kwargs)
        except Exception:
            await query.message.reply_text(text, **kwargs)

    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute("SELECT pokemon_name, COALESCE(special_tag, '') FROM user_pokemon WHERE id = ? AND user_id = ?", (pkmn_id, user.id))
    row = cursor.fetchone()
    conn.close()

    if action == "cancel":
        if not row:
            await query.message.reply_text("✅ You chose to keep your Pokémon.")
            return
        pkmn_name = row[0]
        # Restore the stats page
        p_data = await fetch_pokemon_stats_data(pkmn_id, user.id)
        if p_data:
            kbd = _build_stats_kbd("info", pkmn_id, user.id)
            try:
                if query.message.photo:
                    await query.edit_message_caption(
                        caption=format_stats_info(p_data),
                        reply_markup=kbd,
                        parse_mode="HTML",
                    )
                else:
                    await query.edit_message_text(
                        format_stats_info(p_data),
                        reply_markup=kbd,
                        parse_mode="HTML",
                    )
            except Exception:
                await context.bot.send_photo(
                    chat_id=query.message.chat_id,
                    photo=p_data["sprite"],
                    caption=format_stats_info(p_data),
                    reply_markup=kbd,
                    parse_mode="HTML",
                )
        else:
            await query.message.reply_text(f"✅ Kept {pkmn_name}.")
        return

    if not row:
        await query.answer("This menu belongs to another trainer.", show_alert=True)
        return

    pkmn_name    = row[0]
    special_tag  = row[1]
    pkmn_display = append_special_tag(pkmn_name, special_tag)

    if action == "ask":
        text = f"⚠️ Are you sure you want to release your <b>{pkmn_display}</b>?\nThis action <b>cannot</b> be undone."
        kbd = [[
            InlineKeyboardButton("Yes", callback_data=f"release_confirm_{pkmn_id}"),
            InlineKeyboardButton("No",  callback_data=f"release_cancel_{pkmn_id}"),
        ]]
        await _edit(text, reply_markup=InlineKeyboardMarkup(kbd))

    elif action == "confirm":
        remove_pokemon_from_system(user.id, pkmn_id)
        await _edit(f"✅ {pkmn_display} has been released.")

async def release_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Trainer command to release a Pokémon from inventory. Works in private, groups, and supergroups."""
    user = update.effective_user

    if not context.args:
        await update.message.reply_text("Usage: /release <pokemon_name or nickname>")
        return

    pokemon_name = " ".join(context.args).lower()
    rows, pkmn_key = find_pokemon_by_species_or_nickname(user.id, pokemon_name)

    if not rows:
        await update.message.reply_text(f"❌ You don't own a Pokémon named or nicknamed '{pokemon_name.capitalize()}'.")
        return

    if len(rows) == 1:
        pkmn_db_id = rows[0][0]
        # Release shows [In Camp] Pokémon in the list but blocks action after selection
        await _execute_release_ask(update, context, user.id, pkmn_db_id)
    else:
        await show_universal_selection_ui(update.message.reply_text, user.id, rows, pkmn_key, "release")

# ════════════════════════════════════ /STATS COMMAND SYSTEM ════════════════════════════════════

async def fetch_pokemon_stats_data(pkmn_id, user_id):
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute("""
        SELECT pokemon_id, pokemon_name, level, exp, nature, 
        iv_hp, iv_atk, iv_def, iv_spa, iv_spd, iv_spe,
        ev_hp, ev_atk, ev_def, ev_spa, ev_spd, ev_spe, moves, pokemon_bond, in_camp, shiny,
        COALESCE(is_favorite, 0), COALESCE(nickname, ''),
        COALESCE(custom_image_file_id, ''), COALESCE(special_tag, '')
        FROM user_pokemon WHERE id = ? AND user_id = ?
    """, (pkmn_id, user_id))
    row = cursor.fetchone()
    conn.close()
    
    if not row: return None
    
    is_shiny = bool(row[20]) if row[20] else False
    p_data = {
        "id": pkmn_id,
        "pokemon_id": row[0],
        "name": row[1],
        "level": row[2],
        "exp": row[3],
        "nature": row[4],
        "ivs": {"hp": row[5], "attack": row[6], "defense": row[7], "special-attack": row[8], "special-defense": row[9], "speed": row[10]},
        "evs": {"hp": row[11], "attack": row[12], "defense": row[13], "special-attack": row[14], "special-defense": row[15], "speed": row[16]},
        "moves_json": row[17],
        "pokemon_bond": row[18] or 0,
        "in_camp": row[19] or 0,
        "shiny": is_shiny,
        "is_favorite": bool(row[21]),
        "nickname": row[22] or "",
        "custom_image_file_id": row[23] or "",
        "special_tag": row[24] or "",
    }
    
    stored_moves_list = json.loads(p_data["moves_json"]) if p_data["moves_json"] else None
    
    # Calculate real stats
    info = await get_pokemon_battle_info(p_data["pokemon_id"], p_data["level"], ivs=p_data["ivs"], evs=p_data["evs"], nature=p_data["nature"], stored_moves=stored_moves_list)
    if info:
        p_data.update(info)
        # If shiny, override the sprite with the official shiny artwork
        if is_shiny and info.get("id"):
            p_data["sprite"] = shiny_sprite_url(info["id"])
        p_data["shiny"] = is_shiny  # update() may have clobbered it if wild_info has no shiny key
        # custom_image_file_id takes priority over any sprite from the API
        if p_data.get("custom_image_file_id"):
            p_data["sprite"] = p_data["custom_image_file_id"]
    
    return p_data

# ── /stats duplicate helpers ──────────────────────────────────────────────────

STATS_SELECT_PAGE_SIZE = 10


def find_duplicate_pokemon(user_id: int, pokemon_name: str) -> list:
    """Returns all user_pokemon rows matching pokemon_name (species, case-insensitive)."""
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        """SELECT id, pokemon_id, pokemon_name, level, nature,
               iv_hp, iv_atk, iv_def, iv_spa, iv_spd, iv_spe,
               ev_hp, ev_atk, ev_def, ev_spa, ev_spd, ev_spe,
               caught_at, COALESCE(shiny, 0), COALESCE(is_favorite, 0),
               COALESCE(nickname, ''), COALESCE(special_tag, '')
           FROM user_pokemon
           WHERE user_id = ? AND LOWER(pokemon_name) = ?""",
        (user_id, pokemon_name.lower()),
    )
    rows = cursor.fetchall()
    conn.close()
    return rows


def find_pokemon_by_nickname(user_id: int, nickname: str) -> list:
    """Returns all user_pokemon rows matching nickname (case-insensitive)."""
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        """SELECT id, pokemon_id, pokemon_name, level, nature,
               iv_hp, iv_atk, iv_def, iv_spa, iv_spd, iv_spe,
               ev_hp, ev_atk, ev_def, ev_spa, ev_spd, ev_spe,
               caught_at, COALESCE(shiny, 0), COALESCE(is_favorite, 0),
               COALESCE(nickname, ''), COALESCE(special_tag, '')
           FROM user_pokemon
           WHERE user_id = ? AND LOWER(COALESCE(nickname, '')) = ? AND nickname != ''""",
        (user_id, nickname.lower()),
    )
    rows = cursor.fetchall()
    conn.close()
    return rows


# Prefix used in callback_data to distinguish nickname searches from species searches
_NICKNAME_KEY_PREFIX = "nn:"

def find_pokemon_by_species_or_nickname(user_id: int, search_term: str) -> tuple:
    """
    Search by species name first; if nothing found, search by nickname.
    Returns (rows, key) where key is the string to embed in callback_data.
    Nickname keys are prefixed with 'nn:' so callbacks can re-run the right query.
    """
    rows = find_duplicate_pokemon(user_id, search_term)
    if rows:
        return rows, search_term
    rows = find_pokemon_by_nickname(user_id, search_term)
    key = f"{_NICKNAME_KEY_PREFIX}{search_term}" if rows else search_term
    return rows, key


def resolve_pkmn_key(user_id: int, pkmn_name_key: str) -> list:
    """Resolve a possibly-prefixed callback key back to DB rows."""
    if pkmn_name_key.startswith(_NICKNAME_KEY_PREFIX):
        return find_pokemon_by_nickname(user_id, pkmn_name_key[len(_NICKNAME_KEY_PREFIX):])
    return find_duplicate_pokemon(user_id, pkmn_name_key)


def _get_sort_name(r: tuple) -> str:
    """Return the effective display name for sorting by Name, stripped of all formatting.

    Priority:
      1. Nickname (r[20]) — if the Pokémon has one
      2. Species name + special tag  (e.g. "Venusaur [Tidal]") — if a tag exists
      3. Plain species name (r[2])

    Formatting stripped before comparison:
      ✨  🌟  ⭐  (shiny / favourite emoji prefixes)
      Any HTML tags  (<b>, </b>, <i>, </i> …)
      Square-bracket tags left as plain text so "Venusaur [Tidal]" still sorts
      under V, not T.
    """
    import re as _re
    nickname    = r[20] if len(r) > 20 and r[20] else ""
    species     = r[2]  or ""
    special_tag = r[21] if len(r) > 21 and r[21] else ""

    if nickname:
        name = nickname
    elif special_tag:
        name = f"{species} [{special_tag}]"
    else:
        name = species

    # Strip emoji decoration that is added at display time
    name = _re.sub(r"[✨🌟⭐]+\s*", "", name)
    # Strip any HTML markup  (<b>, </b>, <i>, </i>, etc.)
    name = _re.sub(r"<[^>]+>", "", name)
    return name.strip().lower()


def sort_pokemon_results(rows: list, settings: dict) -> list:
    """Sorts a list of user_pokemon rows using the trainer's active sort settings."""
    sort_mode = settings["sort_mode"]
    sort_order = settings["sort_order"]  # 'asc' or 'desc'
    reverse = sort_order == "desc"

    # Map sort_mode to row-tuple index
    # row: (id[0], pokemon_id[1], pokemon_name[2], level[3], nature[4],
    #       iv_hp[5], iv_atk[6], iv_def[7], iv_spa[8], iv_spd[9], iv_spe[10],
    #       ev_hp[11], ev_atk[12], ev_def[13], ev_spa[14], ev_spd[15], ev_spe[16],
    #       caught_at[17], shiny[18], is_favorite[19], nickname[20], special_tag[21])
    sort_key_map = {
        "name":        lambda r: (_get_sort_name(r), r[3] or 0),
        "caught_at":   lambda r: r[17] or 0,
        "level":       lambda r: r[3] or 0,
        "nature":      lambda r: (r[4] or "").lower(),
        "types":       lambda r: (r[1] or "").lower(),
        "total_ivs":   lambda r: (r[5] or 0) + (r[6] or 0) + (r[7] or 0) + (r[8] or 0) + (r[9] or 0) + (r[10] or 0),
        "total_evs":   lambda r: (r[11] or 0) + (r[12] or 0) + (r[13] or 0) + (r[14] or 0) + (r[15] or 0) + (r[16] or 0),
        "id":          lambda r: r[0],
        "iv_hp":       lambda r: r[5] or 0,
        "iv_atk":      lambda r: r[6] or 0,
        "iv_def":      lambda r: r[7] or 0,
        "iv_spa":      lambda r: r[8] or 0,
        "iv_spd":      lambda r: r[9] or 0,
        "iv_spe":      lambda r: r[10] or 0,
        "ev_hp":       lambda r: r[11] or 0,
        "ev_atk":      lambda r: r[12] or 0,
        "ev_def":      lambda r: r[13] or 0,
        "ev_spa":      lambda r: r[14] or 0,
        "ev_spd":      lambda r: r[15] or 0,
        "ev_spe":      lambda r: r[16] or 0,
    }
    key_fn = sort_key_map.get(sort_mode, lambda r: r[3] or 0)
    try:
        return sorted(rows, key=key_fn, reverse=reverse)
    except Exception:
        return rows


def format_display_value(row: tuple, display_mode: str) -> str:
    """Returns the display string for a single pokemon row given the display mode.
    Delegates to the existing get_display_value function."""
    return get_display_value(row, display_mode)


def _camp_suffix_for_row(pokemon_id: int) -> str:
    return " [In Camp]" if is_pokemon_in_camp(pokemon_id) else ""


def _camp_name(pokemon_id: int, name: str) -> str:
    return f"{name}{_camp_suffix_for_row(pokemon_id)}"


def build_stats_selection_text(rows: list, settings: dict, page: int, pkmn_name: str) -> str:
    """Builds the duplicate-selection message text."""
    display_mode = settings["display_mode"]
    sort_mode = settings["sort_mode"]
    sort_order = settings["sort_order"]
    total = len(rows)
    total_pages = max(1, math.ceil(total / STATS_SELECT_PAGE_SIZE))

    sort_label = SORT_MODE_LABELS.get(sort_mode, sort_mode.title())
    sort_arrow = "▼" if sort_order == "desc" else "▲"
    display_label = DISPLAY_MODE_LABELS.get(display_mode, display_mode.title())

    offset = (page - 1) * STATS_SELECT_PAGE_SIZE
    page_rows = rows[offset: offset + STATS_SELECT_PAGE_SIZE]

    lines = [f"Check stats of which Pokémon:\n"]
    for i, row in enumerate(page_rows, start=1):
        global_idx = offset + i
        val      = format_display_value(row, display_mode)
        is_shiny    = bool(row[18]) if len(row) > 18 else False
        is_fav      = bool(row[19]) if len(row) > 19 else False
        nickname    = row[20] if len(row) > 20 and row[20] else ""
        special_tag = row[21] if len(row) > 21 and row[21] else ""
        # Show nickname as primary name; species is not shown in this list
        base_name = nickname if nickname else row[2]
        display   = display_name_with_shiny(_camp_name(row[0], base_name), is_shiny)
        display = append_special_tag(display, special_tag)
        if is_fav:
            display = "🌟 " + display
        if display_mode == "none" or not val:
            lines.append(f"{global_idx}. {display}")
        else:
            lines.append(f"{global_idx}. {display} - {val}")

    lines.append(f"\nPage: {page}/{total_pages}")
    lines.append(f"Sort: {sort_label} {sort_arrow} | Display: {display_label}")
    return "\n".join(lines)


def build_stats_selection_keyboard(rows: list, page: int, pkmn_name_key: str) -> InlineKeyboardMarkup:
    """Builds numbered inline keyboard for duplicate-pokemon selection with pagination."""
    total = len(rows)
    total_pages = max(1, math.ceil(total / STATS_SELECT_PAGE_SIZE))
    offset = (page - 1) * STATS_SELECT_PAGE_SIZE
    page_rows = rows[offset: offset + STATS_SELECT_PAGE_SIZE]

    keyboard = []
    btn_row = []
    for i, row in enumerate(page_rows):
        global_idx = offset + i + 1
        pkmn_db_id = row[0]
        btn_row.append(
            InlineKeyboardButton(
                str(global_idx),
                callback_data=f"stats_select:{pkmn_name_key}:{pkmn_db_id}:{page}"
            )
        )
        if len(btn_row) == 5:
            keyboard.append(btn_row)
            btn_row = []
    if btn_row:
        keyboard.append(btn_row)

    # Pagination row
    nav_row = []
    if page > 1:
        nav_row.append(InlineKeyboardButton("Prev", callback_data=f"stats_selectpage:{pkmn_name_key}:{page - 1}"))
    if page < total_pages:
        nav_row.append(InlineKeyboardButton("Next", callback_data=f"stats_selectpage:{pkmn_name_key}:{page + 1}"))
    if nav_row:
        keyboard.append(nav_row)

    return InlineKeyboardMarkup(keyboard)


async def show_stats_selection_ui(send_fn, user_id: int, rows: list, settings: dict, pkmn_name_key: str, page: int = 1):
    """Sends or edits the duplicate-selection UI.  send_fn should be reply_text or edit_message_text."""
    sorted_rows = sort_pokemon_results(rows, settings)
    text = build_stats_selection_text(sorted_rows, settings, page, pkmn_name_key)
    keyboard = build_stats_selection_keyboard(sorted_rows, page, pkmn_name_key)
    await send_fn(text, reply_markup=keyboard, parse_mode="HTML")


# ════════════════════════════════════════════════════════════════════════════════
# ═══════════════ UNIVERSAL POKEMON SELECTION SYSTEM ════════════════════════════
# ════════════════════════════════════════════════════════════════════════════════
#
# Used by: /boost, /vitamin, /berry, /candy, /evolve, /release, /mysquad add
# Callback prefix: "pkmn_sel"
# Callback format:
#   pkmn_sel:{cmd}:{pkmn_name_key}:{pkmn_db_id}:{page}   — trainer picked a pokemon
#   pkmn_selpage:{cmd}:{pkmn_name_key}:{page}             — page navigation
#
# When a trainer picks, the appropriate command's _execute_* helper is called
# with the resolved pkmn_db_id.
# ════════════════════════════════════════════════════════════════════════════════

def build_universal_selection_text(rows: list, settings: dict, page: int, pkmn_name: str, cmd: str) -> str:
    """Builds the selection message text for universal pokemon picking (reuses stats UI style)."""
    display_mode = settings["display_mode"]
    sort_mode = settings["sort_mode"]
    sort_order = settings["sort_order"]
    total = len(rows)
    total_pages = max(1, math.ceil(total / STATS_SELECT_PAGE_SIZE))

    sort_label = SORT_MODE_LABELS.get(sort_mode, sort_mode.title())
    sort_arrow = "▼" if sort_order == "desc" else "▲"
    display_label = DISPLAY_MODE_LABELS.get(display_mode, display_mode.title())

    offset = (page - 1) * STATS_SELECT_PAGE_SIZE
    page_rows = rows[offset: offset + STATS_SELECT_PAGE_SIZE]

    CMD_VERBS = {
        "boost":   "Use Boost on",
        "vitamin": "Use Vitamin on",
        "berry":   "Use Berry on",
        "candy":   "Use Candy on",
        "evolve":  "Evolve",
        "release": "Release",
        "squad_add": "Add to squad",
    }
    verb = CMD_VERBS.get(cmd, "Select")

    lines = [f"{verb} which Pokémon:\n"]
    for i, row in enumerate(page_rows, start=1):
        global_idx  = offset + i
        val         = format_display_value(row, display_mode)
        is_shiny    = bool(row[18]) if len(row) > 18 else False
        nickname    = row[20] if len(row) > 20 and row[20] else ""
        special_tag = row[21] if len(row) > 21 and row[21] else ""
        base_name   = nickname if nickname else row[2]
        display     = display_name_with_shiny(_camp_name(row[0], base_name), is_shiny)
        display     = append_special_tag(display, special_tag)
        if display_mode == "none" or not val:
            lines.append(f"{global_idx}. {display}")
        else:
            lines.append(f"{global_idx}. {display} - {val}")

    lines.append(f"\nPage: {page}/{total_pages}")
    lines.append(f"Sort: {sort_label} {sort_arrow} | Display: {display_label}")
    return "\n".join(lines)


def build_universal_selection_keyboard(rows: list, page: int, pkmn_name_key: str, cmd: str) -> InlineKeyboardMarkup:
    """Builds numbered inline keyboard for universal pokemon selection with pagination."""
    total = len(rows)
    total_pages = max(1, math.ceil(total / STATS_SELECT_PAGE_SIZE))
    offset = (page - 1) * STATS_SELECT_PAGE_SIZE
    page_rows = rows[offset: offset + STATS_SELECT_PAGE_SIZE]

    keyboard = []
    btn_row = []
    for i, row in enumerate(page_rows):
        global_idx = offset + i + 1
        pkmn_db_id = row[0]
        btn_row.append(
            InlineKeyboardButton(
                str(global_idx),
                callback_data=f"pkmn_sel:{cmd}:{pkmn_name_key}:{pkmn_db_id}:{page}"
            )
        )
        if len(btn_row) == 5:
            keyboard.append(btn_row)
            btn_row = []
    if btn_row:
        keyboard.append(btn_row)

    nav_row = []
    if page > 1:
        nav_row.append(InlineKeyboardButton("Prev", callback_data=f"pkmn_selpage:{cmd}:{pkmn_name_key}:{page - 1}"))
    if page < total_pages:
        nav_row.append(InlineKeyboardButton("Next", callback_data=f"pkmn_selpage:{cmd}:{pkmn_name_key}:{page + 1}"))
    if nav_row:
        keyboard.append(nav_row)

    return InlineKeyboardMarkup(keyboard)


async def show_universal_selection_ui(send_fn, user_id: int, rows: list, pkmn_name_key: str, cmd: str, page: int = 1):
    """Sends the universal duplicate-pokemon selection UI for a given command."""
    settings = get_user_settings(user_id)
    sorted_rows = sort_pokemon_results(rows, settings)
    text = build_universal_selection_text(sorted_rows, settings, page, pkmn_name_key, cmd)
    keyboard = build_universal_selection_keyboard(sorted_rows, page, pkmn_name_key, cmd)
    await send_fn(text, reply_markup=keyboard, parse_mode="HTML")


async def universal_pokemon_select_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Unified callback for universal pokemon selection UI (pkmn_sel: and pkmn_selpage: prefixes)."""
    query = update.callback_query
    await query.answer()
    user = query.from_user
    data = query.data

    # ── Page navigation ────────────────────────────────────────────────────────
    if data.startswith("pkmn_selpage:"):
        # pkmn_selpage:{cmd}:{pkmn_name_key}:{page}
        parts = data.split(":", 3)
        if len(parts) != 4:
            await query.answer("Invalid action.", show_alert=True)
            return
        cmd = parts[1]
        pkmn_name_key = parts[2]
        try:
            page = int(parts[3])
        except ValueError:
            await query.answer("Invalid page.", show_alert=True)
            return

        rows = resolve_pkmn_key(user.id, pkmn_name_key)
        if not rows:
            await query.edit_message_text("Pokémon not found in your inventory.")
            return

        settings = get_user_settings(user.id)
        sorted_rows = sort_pokemon_results(rows, settings)
        total_pages = max(1, math.ceil(len(sorted_rows) / STATS_SELECT_PAGE_SIZE))
        page = max(1, min(page, total_pages))

        text = build_universal_selection_text(sorted_rows, settings, page, pkmn_name_key, cmd)
        keyboard = build_universal_selection_keyboard(sorted_rows, page, pkmn_name_key, cmd)
        try:
            await query.edit_message_text(text, reply_markup=keyboard, parse_mode="HTML")
        except Exception:
            pass
        return

    # ── Pokemon selected ───────────────────────────────────────────────────────
    if data.startswith("pkmn_sel:"):
        # pkmn_sel:{cmd}:{pkmn_name_key}:{pkmn_db_id}:{page}
        parts = data.split(":")
        if len(parts) != 5:
            await query.answer("Invalid action.", show_alert=True)
            return
        cmd = parts[1]
        pkmn_name_key = parts[2]
        try:
            pkmn_db_id = int(parts[3])
        except ValueError:
            await query.answer("Invalid Pokémon.", show_alert=True)
            return

        # Security: verify ownership
        conn = sqlite3.connect("ZNX.db")
        cursor = conn.cursor()
        cursor.execute("SELECT id FROM user_pokemon WHERE id = ? AND user_id = ?", (pkmn_db_id, user.id))
        owned_row = cursor.fetchone()
        conn.close()
        if not owned_row:
            await query.answer("You don't own that Pokémon.", show_alert=True)
            return

        # Camp restriction check for commands that cannot act on camped Pokémon
        CAMP_RESTRICTED_CMDS = {"boost", "vitamin", "berry", "candy", "evolve", "squad_add"}
        if cmd in CAMP_RESTRICTED_CMDS and is_pokemon_in_camp(pkmn_db_id):
            if cmd == "squad_add":
                await query.answer("This Pokémon is in camp can't battle with it.", show_alert=True)
            else:
                await query.edit_message_text("❌ This Pokémon is currently in Camp.")
            return

        # Dispatch to the right execute helper
        if cmd == "boost":
            await _execute_boost(query, context, user.id, pkmn_db_id)
        elif cmd == "vitamin":
            await _execute_vitamin(query, context, user.id, pkmn_db_id)
        elif cmd == "berry":
            await _execute_berry(query, context, user.id, pkmn_db_id)
        elif cmd == "candy":
            await _execute_candy(query, context, user.id, pkmn_db_id)
        elif cmd == "evolve":
            await _execute_evolve(query, context, user.id, pkmn_db_id)
        elif cmd == "release":
            await _execute_release_ask(query, context, user.id, pkmn_db_id)
        elif cmd == "squad_add":
            # squad_add stores squad_id in context.user_data
            squad_id = context.user_data.get(f"squad_add_pending_{user.id}")
            if not squad_id:
                await query.edit_message_text("❌ Squad selection expired. Please try again.")
                return
            await _execute_squad_add(query, context, user.id, pkmn_db_id, squad_id)
        else:
            await query.answer("Unknown command.", show_alert=True)


async def _resolve_or_show_selection(update_or_query, context, user_id: int, args: list, cmd: str,
                                     execute_fn, is_callback: bool = False):
    """
    Helper: resolves a pokemon name from args. If one match, calls execute_fn(pkmn_db_id).
    If multiple, shows the universal selection UI. If none, reports error.
    execute_fn signature: async fn(update_or_query, context, user_id, pkmn_db_id)
    """
    if not args:
        return False  # caller handles usage message

    pokemon_name = " ".join(args).lower()
    rows = find_duplicate_pokemon(user_id, pokemon_name)

    if not rows:
        return False  # not found — caller handles

    if len(rows) == 1:
        pkmn_db_id = rows[0][0]
        await execute_fn(update_or_query, context, user_id, pkmn_db_id)
        return True

    # Multiple — show selection UI
    if is_callback:
        send_fn = update_or_query.edit_message_text
    else:
        send_fn = update_or_query.message.reply_text
    await show_universal_selection_ui(send_fn, user_id, rows, pokemon_name, cmd)
    return True



# ── Pending nickname/favorite in-memory state ─────────────────────────────────
PENDING_NICKNAME: dict[int, dict] = {}   # user_id -> {pkmn_id, msg_id, chat_id}

# ── Stats keyboard builder ────────────────────────────────────────────────────
def _build_stats_kbd(page: str, pkmn_id, owner_id: int) -> InlineKeyboardMarkup:
    """Builds the 4-page stats keyboard with SetFav / Release / Nickname / Relearner buttons."""
    pid = pkmn_id
    oid = owner_id
    nav_map = {
        "info":  [("Stats",  f"stats_stats_{pid}_{oid}"), ("IV/EV", f"stats_ivs_{pid}_{oid}"),  ("MoveSet", f"stats_moves_{pid}_{oid}")],
        "ivs":   [("Stats",  f"stats_stats_{pid}_{oid}"), ("Info",  f"stats_info_{pid}_{oid}"),  ("MoveSet", f"stats_moves_{pid}_{oid}")],
        "stats": [("Info",   f"stats_info_{pid}_{oid}"),  ("IV/EV", f"stats_ivs_{pid}_{oid}"),   ("MoveSet", f"stats_moves_{pid}_{oid}")],
        "moves": [("Stats",  f"stats_stats_{pid}_{oid}"), ("IV/EV", f"stats_ivs_{pid}_{oid}"),  ("Info",   f"stats_info_{pid}_{oid}")],
    }
    nav = nav_map.get(page, nav_map["info"])
    row1 = [InlineKeyboardButton(label, callback_data=cb) for label, cb in nav]
    row2 = [
        InlineKeyboardButton("SetFav",   callback_data=f"stats_setfav_{pid}_{oid}"),
        InlineKeyboardButton("Release",  callback_data=f"release_ask_{pid}"),
        InlineKeyboardButton("Nickname", callback_data=f"stats_nickname_{pid}_{oid}"),
    ]
    row3 = [InlineKeyboardButton("Relearner", callback_data=f"rl_open_{pid}_{oid}")]
    return InlineKeyboardMarkup([row1, row2, row3])

async def _send_stats_photo(send_photo_fn, pkmn_id: int, user_id: int):
    """Fetches pokemon stats data and sends the stats photo. Returns True on success."""
    p_data = await fetch_pokemon_stats_data(pkmn_id, user_id)
    if not p_data:
        return False
    caption = format_stats_info(p_data)
    kbd = _build_stats_kbd("info", pkmn_id, user_id)
    await send_photo_fn(photo=p_data["sprite"], caption=caption, reply_markup=kbd, parse_mode="HTML")
    return True


async def stats_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    user = update.effective_user
    ensure_active_pokemon(user.id)

    if not context.args:
        await update.message.reply_text("Usage: /stats <pokemon_name>")
        return

    pokemon_name = " ".join(context.args).lower()

    # ── Species-name lookup first ──────────────────────────────────────────
    exact_rows, pkmn_key = find_pokemon_by_species_or_nickname(user.id, pokemon_name)

    if exact_rows:
        if len(exact_rows) == 1:
            # Only one — go straight to stats
            pkmn_id = exact_rows[0][0]
            ok = await _send_stats_photo(update.message.reply_photo, pkmn_id, user.id)
            if not ok:
                await update.message.reply_text("Error fetching Pokémon data.")
        else:
            # Multiple — show selection UI
            settings = get_user_settings(user.id)
            await show_stats_selection_ui(
                update.message.reply_text,
                user.id,
                exact_rows,
                settings,
                pkmn_key,
                page=1,
            )
        return

    # ── Fuzzy search fallback ──────────────────────────────────────────────
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute("SELECT DISTINCT pokemon_name, pokemon_id FROM user_pokemon WHERE user_id = ?", (user.id,))
    owned = cursor.fetchall()
    conn.close()

    owned_dict = {r[0].lower(): (r[0], r[1]) for r in owned}
    matches = difflib.get_close_matches(pokemon_name, list(owned_dict.keys()), n=5, cutoff=0.3)

    if matches:
        msg = f"Search Results for '{pokemon_name}':\nPage: 1/1\nDid you mean one of these Pokémon?\n\n"
        keyboard = []
        for idx, match in enumerate(matches, start=1):
            original_name, match_id = owned_dict[match]
            emoji_str = ""
            try:
                d = await _cached_pokeapi_get(f"https://pokeapi.co/api/v2/pokemon/{match_id}")
                if d:
                    t_names = [t["type"]["name"] for t in d["types"]]
                    emoji_str = "".join([TYPE_EMOJIS.get(t, "") for t in t_names])
            except Exception as e:
                logger.error(f"Error fetching type for search result: {e}")

            emoji_display = f" ({emoji_str})" if emoji_str else ""
            msg += f"{idx}. {original_name}{emoji_display}\n"
            keyboard.append([InlineKeyboardButton(f"{idx}. {original_name}", callback_data=f"sstats_{original_name.lower()}")])

        await update.message.reply_text(msg, reply_markup=InlineKeyboardMarkup(keyboard))
    else:
        await update.message.reply_text(
            f"Search Results for '{pokemon_name}':\nPage: 1/1\nNo matching Pokémon found in your inventory."
        )


async def sstats_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles the fuzzy-search result inline buttons to open a Pokemon's stats.
    Also handles stats_select: and stats_selectpage: callbacks for duplicate selection."""
    query = update.callback_query
    await query.answer()
    user = query.from_user
    data = query.data

    # ── Duplicate selection — page navigation ─────────────────────────────
    if data.startswith("stats_selectpage:"):
        # stats_selectpage:{pkmn_name_key}:{page}
        parts = data.split(":", 2)
        if len(parts) != 3:
            await query.answer("Invalid action.", show_alert=True)
            return
        pkmn_name_key = parts[1]
        try:
            page = int(parts[2])
        except ValueError:
            await query.answer("Invalid page.", show_alert=True)
            return

        # __nickname__ prefix uses species-name suffix after "__nickname__"
        if pkmn_name_key.startswith("__nickname__"):
            species_key = pkmn_name_key[len("__nickname__"):]
            exact_rows = resolve_pkmn_key(user.id, species_key)
        else:
            exact_rows = resolve_pkmn_key(user.id, pkmn_name_key)
        if not exact_rows:
            await query.edit_message_text("Pokémon not found in your inventory.")
            return

        settings = get_user_settings(user.id)
        sorted_rows = sort_pokemon_results(exact_rows, settings)
        total_pages = max(1, math.ceil(len(sorted_rows) / STATS_SELECT_PAGE_SIZE))
        page = max(1, min(page, total_pages))

        text = build_stats_selection_text(sorted_rows, settings, page, pkmn_name_key)
        keyboard = build_stats_selection_keyboard(sorted_rows, page, pkmn_name_key)
        try:
            await query.edit_message_text(text, reply_markup=keyboard, parse_mode="HTML")
        except Exception:
            pass
        return

    # ── Duplicate selection — trainer chose a specific pokemon ────────────
    if data.startswith("stats_select:"):
        # stats_select:{pkmn_name_key}:{pkmn_db_id}:{page}
        parts = data.split(":")
        if len(parts) != 4:
            await query.answer("Invalid action.", show_alert=True)
            return
        pkmn_name_key = parts[1]
        try:
            pkmn_db_id = int(parts[2])
        except ValueError:
            await query.answer("Invalid Pokémon.", show_alert=True)
            return

        # Security: verify ownership
        conn = sqlite3.connect("ZNX.db")
        cursor = conn.cursor()
        cursor.execute(
            "SELECT id, pokemon_name FROM user_pokemon WHERE id = ? AND user_id = ?",
            (pkmn_db_id, user.id),
        )
        owned_row = cursor.fetchone()
        conn.close()

        if not owned_row:
            await query.answer("You don't own that Pokémon.", show_alert=True)
            return

        # ── Nickname flow: skip /stats, go straight to nickname prompt ──────
        if pkmn_name_key.startswith("__nickname__"):
            pkmn_name = owned_row[1]
            await query.answer()
            try:
                await query.message.delete()
            except Exception:
                pass
            await _start_nickname_prompt(context.bot, user.id, query.message.chat_id, pkmn_db_id, pkmn_name)
            return

        p_data = await fetch_pokemon_stats_data(pkmn_db_id, user.id)
        if not p_data:
            await query.edit_message_text("Error fetching Pokémon data.")
            return

        caption = format_stats_info(p_data)
        kbd = _build_stats_kbd("info", pkmn_db_id, user.id)
        await query.message.delete()
        await context.bot.send_photo(
            chat_id=query.message.chat_id,
            photo=p_data["sprite"],
            caption=caption,
            reply_markup=kbd,
            parse_mode="HTML",
        )
        return

    # ── Fuzzy-search result button (sstats_<name>) ────────────────────────
    pokemon_name = data.split("_", 1)[1]

    exact_rows = find_duplicate_pokemon(user.id, pokemon_name)

    if not exact_rows:
        await query.edit_message_text("Pokémon not found in your inventory.")
        return

    if len(exact_rows) == 1:
        pkmn_id = exact_rows[0][0]
        p_data = await fetch_pokemon_stats_data(pkmn_id, user.id)
        if not p_data:
            await query.edit_message_text("Error fetching Pokémon data.")
            return

        caption = format_stats_info(p_data)
        kbd = _build_stats_kbd("info", pkmn_id, user.id)
        await query.message.delete()
        await context.bot.send_photo(
            chat_id=query.message.chat_id,
            photo=p_data["sprite"],
            caption=caption,
            reply_markup=kbd,
            parse_mode="HTML",
        )
    else:
        # Multiple duplicates found via fuzzy path — show selection UI
        settings = get_user_settings(user.id)
        sorted_rows = sort_pokemon_results(exact_rows, settings)
        text = build_stats_selection_text(sorted_rows, settings, 1, pokemon_name)
        keyboard = build_stats_selection_keyboard(sorted_rows, 1, pokemon_name)
        await query.edit_message_text(text, reply_markup=keyboard, parse_mode="HTML")

async def stats_view_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles opening the complete stats UI directly from catch success (fixes text/photo mismatch)."""
    query = update.callback_query
    await query.answer()
    pkmn_id = query.data.split("_")[2]
    user_id = query.from_user.id
    
    p_data = await fetch_pokemon_stats_data(pkmn_id, user_id)
    if not p_data:
        await query.answer("This menu belongs to another trainer.", show_alert=True)
        return
        
    caption = format_stats_info(p_data)
    kbd = _build_stats_kbd("info", pkmn_id, user_id)
    
    # Send the stats photo embed without deleting the original catch message
    await context.bot.send_photo(
        chat_id=query.message.chat_id,
        photo=p_data["sprite"],
        caption=caption,
        reply_markup=kbd,
        parse_mode="HTML",
    )

def format_stats_info(p_data):
    """INFO PAGE — page 1 of the 4-page /stats UI."""
    type_parts = [f"<b>{t.capitalize()} {TYPE_EMOJIS.get(t, '')}</b>" for t in p_data["types"]]
    types_str = " / ".join(type_parts)

    # Never display a level above the cap, even if older/unmigrated data slips through.
    display_level = min(p_data["level"], MAX_POKEMON_LEVEL)
    bar_length = 10

    if display_level >= MAX_POKEMON_LEVEL:
        # Lv.100 is always shown fully maxed — locked Exp, 0 To Next Lv, full bar.
        curr_exp = MAX_POKEMON_EXP
        to_next = 0
        bar = "█" * bar_length
    else:
        req_exp = get_required_exp(display_level)
        curr_exp = p_data["exp"]
        to_next = max(0, req_exp - curr_exp)
        ratio = min(1.0, curr_exp / req_exp) if req_exp > 0 else 1.0
        filled = int(ratio * bar_length)
        bar = "█" * filled + "░" * (bar_length - filled)

    is_shiny  = p_data.get("shiny", False)
    shiny_tag = "✨ " if is_shiny else ""
    nickname  = p_data.get("nickname", "")
    fav_tag   = "🌟 " if p_data.get("is_favorite") else ""
    special_tag = p_data.get("special_tag", "")
    tag_str   = f" <b>[{special_tag}]</b>" if special_tag else ""
    species_name = p_data['name'].capitalize()
    if nickname:
        display_name = f"{fav_tag}{shiny_tag}<b>{species_name} ({nickname})</b>{tag_str}"
    else:
        display_name = f"{fav_tag}{shiny_tag}<b>{species_name}</b>{tag_str}"

    return (
        f"Poke - {display_name}\n"
        f"Lv. <b>{display_level}</b> | Nature: <b>{p_data['nature']}</b>\n"
        f"Types: [{types_str}]\n"
        f"<b>RoBond</b> - {p_data.get('pokemon_bond', 0):,}/10,000\n"
        f"Exp: <b>{curr_exp:,}</b>\n"
        f"To Next Lv: <b>{to_next:,}</b>\n"
        f"{bar}"
    )

def format_stats_ivsevs(p_data):
    """IV/EV PAGE — page 4 of the 4-page /stats UI."""
    ivs = p_data["ivs"]
    evs = p_data["evs"]
    tot_iv = sum(ivs.values())
    tot_ev = sum(evs.values())
    divider = "—" * 24

    def row(label, iv, ev):
        return f"{label:<13}{iv:>3} |{ev:>4}"

    body = "\n".join([
        row("Points", "IV", "EV"),
        divider,
        row("HP", ivs['hp'], evs['hp']),
        row("Attack", ivs['attack'], evs['attack']),
        row("Defense", ivs['defense'], evs['defense']),
        row("Sp. Atk", ivs['special-attack'], evs['special-attack']),
        row("Sp. Def", ivs['special-defense'], evs['special-defense']),
        row("Speed", ivs['speed'], evs['speed']),
        divider,
        row("Total", tot_iv, tot_ev),
    ])
    return f"<code>{body}</code>"
def format_stats_stats(p_data):
    """STATS PAGE — page 3 of the 4-page /stats UI."""
    n = NATURES.get(p_data["nature"], {"boost": "none", "nerf": "none"})
    def mod_sym(stat):
        if n["boost"] == stat: return " <b>(+)</b>"
        if n["nerf"] == stat: return " <b>(-)</b>"
        return ""

    ivs        = p_data["ivs"]
    evs        = p_data.get("evs", {"hp": 0, "attack": 0, "defense": 0, "special-attack": 0, "special-defense": 0, "speed": 0})
    level      = p_data.get("level", 50)
    base_stats = p_data.get("base_stats", {"hp": 50, "attack": 50, "defense": 50, "special-attack": 50, "special-defense": 50, "speed": 50})
    nature     = p_data.get("nature", "Hardy")

    calc_hp  = p_data.get("max_hp")  or calculate_stat(base_stats["hp"],             ivs["hp"],             evs["hp"],             level, 1.0, is_hp=True)
    calc_atk = p_data.get("attack")  or calculate_stat(base_stats["attack"],          ivs["attack"],         evs["attack"],         level, get_nature_modifier(nature, "attack"))
    calc_def = p_data.get("defense") or calculate_stat(base_stats["defense"],         ivs["defense"],        evs["defense"],        level, get_nature_modifier(nature, "defense"))
    calc_spa = p_data.get("sp_atk")  or calculate_stat(base_stats["special-attack"],  ivs["special-attack"], evs["special-attack"], level, get_nature_modifier(nature, "special-attack"))
    calc_spd = p_data.get("sp_def")  or calculate_stat(base_stats["special-defense"], ivs["special-defense"],evs["special-defense"],level, get_nature_modifier(nature, "special-defense"))
    calc_spe = p_data.get("speed")   or calculate_stat(base_stats["speed"],           ivs["speed"],          evs["speed"],          level, get_nature_modifier(nature, "speed"))

    total = calc_hp + calc_atk + calc_def + calc_spa + calc_spd + calc_spe
    nat_on_total = mod_sym(n.get("boost", "none"))

    return (
        f"<b><u>Stats</u></b>\n"
        f"───────────────────\n"
        f"HP: <b>{calc_hp}</b>\n"
        f"Attack: <b>{calc_atk}</b>{mod_sym('attack')}\n"
        f"Defense: <b>{calc_def}</b>{mod_sym('defense')}\n"
        f"Special Attack: <b>{calc_spa}</b>{mod_sym('special-attack')}\n"
        f"Special Defense: <b>{calc_spd}</b>{mod_sym('special-defense')}\n"
        f"Speed: <b>{calc_spe}</b>{mod_sym('speed')}\n"
        f"───────────────────\n"
        f"<b>Total</b> {total}"
    )

def format_stats_moves(p_data):
    """MOVESET PAGE — page 2 of the 4-page /stats UI."""
    text = ""
    for m in p_data.get("moves", []):
        emoji   = TYPE_EMOJIS.get(m["type"], "")
        name    = m["name"].replace("-", " ").title()
        power   = m["power"]   if m["power"]   is not None else "—"
        acc     = _display_accuracy(m.get("accuracy"))
        cat     = m["damage_class"].capitalize()
        mtype   = m["type"].capitalize()
        text += (
            f"╭─「 <b><u>{name}</u></b> 」\n"
            f"├─ Type: <b>{mtype} ({emoji})</b>\n"
            f"├─ <b>Power:</b> {power} | <b>Accuracy:</b> {acc}\n"
            f"└─ Category: <b>{cat}</b>\n\n"
        )
    return text.strip() if text else "No moves available."

async def stats_pagination_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles navigation between the 4 /stats pages: info / ivs / stats / moves.
    Callback format: stats_{page}_{pkmn_id}_{owner_id}"""
    query = update.callback_query
    user  = query.from_user
    parts = query.data.split("_")
    # parts[0]="stats", parts[1]=page, parts[2]=pkmn_id, parts[3]=owner_id
    page    = parts[1]
    pkmn_id = parts[2]
    # Ownership guard
    try:
        owner_id = int(parts[3]) if len(parts) > 3 else user.id
    except (ValueError, IndexError):
        owner_id = user.id
    if not await validate_owner(query, owner_id):
        return

    p_data = await fetch_pokemon_stats_data(pkmn_id, user.id)
    if not p_data:
        await query.answer("This menu belongs to another trainer.", show_alert=True)
        return

    await query.answer()

    if page == "info":
        caption = format_stats_info(p_data)
    elif page == "ivs":
        caption = format_stats_ivsevs(p_data)
    elif page == "stats":
        caption = format_stats_stats(p_data)
    elif page == "moves":
        caption = format_stats_moves(p_data)
    else:
        caption = format_stats_info(p_data)
        page    = "info"

    kbd = _build_stats_kbd(page, pkmn_id, owner_id)
    try:
        await query.edit_message_caption(caption=caption, reply_markup=kbd, parse_mode="HTML")
    except Exception:
        pass  # Ignore if message is exactly the same


