async def stats_setfav_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Asks trainer to confirm setting a Pokémon as favourite. Max 6 favourites."""
    query = update.callback_query
    user  = query.from_user
    parts = query.data.split("_")          # stats_setfav_{pkmn_id}_{owner_id}
    pkmn_id  = int(parts[2])
    try:
        owner_id = int(parts[3])
    except (ValueError, IndexError):
        owner_id = user.id

    if not await validate_owner(query, owner_id):
        return

    # Check the Pokémon belongs to this user
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        "SELECT pokemon_name, COALESCE(nickname,''), COALESCE(is_favorite,0), COALESCE(special_tag,'') FROM user_pokemon WHERE id = ? AND user_id = ?",
        (pkmn_id, user.id)
    )
    row = cursor.fetchone()
    conn.close()
    if not row:
        await query.answer("That Pokémon doesn't belong to you.", show_alert=True)
        return

    pkmn_name, nickname, already_fav, special_tag = row
    base = nickname if nickname else pkmn_name
    display_plain = append_special_tag(base, special_tag, html=False)
    display_html  = append_special_tag(base, special_tag, html=True)

    if already_fav:
        # Toggle off
        conn = sqlite3.connect("ZNX.db")
        cursor = conn.cursor()
        cursor.execute("UPDATE user_pokemon SET is_favorite = 0 WHERE id = ? AND user_id = ?", (pkmn_id, user.id))
        conn.commit()
        conn.close()
        await query.answer(f"💔 {display_plain} removed from favourites.", show_alert=True)
        # Refresh the caption in place
        p_data = await fetch_pokemon_stats_data(pkmn_id, user.id)
        if p_data:
            try:
                await query.edit_message_caption(
                    caption=format_stats_info(p_data),
                    reply_markup=_build_stats_kbd("info", pkmn_id, owner_id),
                    parse_mode="HTML",
                )
            except Exception:
                pass
        return

    # Count existing favourites
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute("SELECT COUNT(*) FROM user_pokemon WHERE user_id = ? AND is_favorite = 1", (user.id,))
    fav_count = cursor.fetchone()[0]
    conn.close()

    if fav_count >= 6:
        await query.answer("⚠️ You already have 6 favourite Pokémon! Remove one first.", show_alert=True)
        return

    await query.answer()
    kbd = InlineKeyboardMarkup([
        [
            InlineKeyboardButton("Yes", callback_data=f"fav_confirm_{pkmn_id}_{owner_id}"),
            InlineKeyboardButton("No",  callback_data=f"fav_cancel_{pkmn_id}_{owner_id}"),
        ]
    ])
    try:
        await query.edit_message_caption(
            caption=f"Are you sure you wanna set your <b>{display_html}</b> to your favourite?",
            reply_markup=kbd,
            parse_mode="HTML",
        )
    except Exception:
        pass


