async def _start_nickname_prompt(bot, user_id: int, chat_id: int, pkmn_id: int, pkmn_name: str):
    """Sends the nickname prompt message and stores pending state."""
    # Fetch official artwork
    pkmn_data_row = None
    try:
        conn = sqlite3.connect("ZNX.db")
        cursor = conn.cursor()
        cursor.execute("SELECT pokemon_id, COALESCE(shiny,0) FROM user_pokemon WHERE id = ?", (pkmn_id,))
        pkmn_data_row = cursor.fetchone()
        conn.close()
    except Exception:
        pass

    sprite_url = None
    if pkmn_data_row:
        pid_str, is_shiny = pkmn_data_row
        # Fetch the Pokémon data from PokeAPI to get the numeric dex ID (needed
        # for official-artwork sprite URLs, which only accept numeric IDs, not slugs).
        try:
            d = await _cached_pokeapi_get(f"https://pokeapi.co/api/v2/pokemon/{pid_str}")
            if d:
                dex_id = d.get("id")
                if is_shiny and dex_id:
                    sprite_url = shiny_sprite_url(dex_id)
                elif not is_shiny:
                    sprite_url = d.get("sprites", {}).get("other", {}).get("official-artwork", {}).get("front_default")
        except Exception:
            # If PokeAPI is unreachable, fall back gracefully (sprite_url stays None)
            pass

    # Build the display name — show ✨ prefix for shiny Pokémon so the prompt
    # and the confirmation message both reflect the correct appearance.
    _nick_is_shiny = bool(pkmn_data_row[1]) if pkmn_data_row else False
    _nick_display_name = display_name_with_shiny(pkmn_name, _nick_is_shiny)
    caption = (
        f"<b>What nickname do you want to give to your {_nick_display_name}?</b>\n\n"
        f"Send your nickname by replying to this message.\n"
        f"<i>Send . to remove the nickname.</i>"
    )
    # Try photo first; if the sprite URL is broken or Telegram rejects it,
    # fall back to a plain text message so the nickname flow always starts.
    sent = None
    if sprite_url:
        try:
            sent = await bot.send_photo(chat_id=chat_id, photo=sprite_url, caption=caption, parse_mode="HTML")
        except Exception as e:
            logger.warning(f"Nickname prompt photo failed ({e}), falling back to text.")
    if sent is None:
        try:
            sent = await bot.send_message(chat_id=chat_id, text=caption, parse_mode="HTML")
        except Exception as e:
            logger.error(f"Nickname prompt error: {e}")
            return

    if sent:
        PENDING_NICKNAME[user_id] = {
            "pkmn_id": pkmn_id,
            "pkmn_name": _nick_display_name,   # includes ✨ prefix if shiny
            "msg_id": sent.message_id,
            "chat_id": chat_id,
        }


async def nickname_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """/nickname <pokemon_name> — starts the nickname workflow."""
    user = update.effective_user
    if not context.args:
        await update.message.reply_text("Usage: /nickname <pokemon_name>")
        return

    import re as _re_nick
    pkmn_name_q = " ".join(context.args)
    # Strip shiny/favourite emoji prefixes (✨ 🌟 ⭐) before searching so trainers
    # can use "/nickname ✨ Xerneas" or "/nickname Xerneas" interchangeably.
    pkmn_name_q = _re_nick.sub(r"[✨🌟⭐]+\s*", "", pkmn_name_q).strip().lower()
    rows, pkmn_key = find_pokemon_by_species_or_nickname(user.id, pkmn_name_q)
    if not rows:
        await update.message.reply_text(f"❌ You don't own a Pokémon named {pkmn_name_q.capitalize()}.")
        return

    if len(rows) == 1:
        pkmn_id   = rows[0][0]
        pkmn_name = rows[0][2]
        await _start_nickname_prompt(context.bot, user.id, update.effective_chat.id, pkmn_id, pkmn_name)
    else:
        # Use the existing selection UI
        settings = get_user_settings(user.id)
        await show_stats_selection_ui(
            update.message.reply_text,
            user.id, rows, settings, f"__nickname__{pkmn_key}", page=1
        )


async def nickname_reply_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles text replies that are responses to the nickname prompt message.
    Works in private chat, groups, and supergroups."""
    user = update.effective_user
    msg  = update.message

    pending = PENDING_NICKNAME.get(user.id)
    if not pending:
        return  # Not in a nickname session

    # Accept replies to the prompt message OR any plain text in the same chat
    # (group chats may not support forced replies)
    if msg.reply_to_message and msg.reply_to_message.message_id != pending["msg_id"]:
        return
    if not msg.reply_to_message and msg.chat_id != pending["chat_id"]:
        return

    nickname = (msg.text or "").strip()
    if not nickname or nickname.startswith("/"):
        return  # Ignore commands sent while pending

    pkmn_id   = pending["pkmn_id"]
    pkmn_name = pending["pkmn_name"]

    # ── Special case: "." removes the nickname ───────────────────────────────
    if nickname == ".":
        conn = sqlite3.connect("ZNX.db")
        cursor = conn.cursor()
        cursor.execute(
            "UPDATE user_pokemon SET nickname = '' WHERE id = ? AND user_id = ?",
            (pkmn_id, user.id)
        )
        conn.commit()
        conn.close()
        del PENDING_NICKNAME[user.id]
        await msg.reply_text(
            f"✅ Nickname removed from <b>{pkmn_name}</b>.",
            parse_mode="HTML"
        )
        return

    if len(nickname) < 1 or len(nickname) > 20:
        await msg.reply_text("❌ Nickname must be between 1 and 20 characters. Try again.")
        return

    # Block emoji and special unicode (only allow letters, numbers, spaces)
    import unicodedata as _ud
    def _has_emoji_or_special(s: str) -> bool:
        for ch in s:
            if ch == ' ':
                continue
            cat = _ud.category(ch)
            # Allow letters (L*), numbers (N*) — block everything else
            if not (cat.startswith('L') or cat.startswith('N')):
                return True
        return False
    if _has_emoji_or_special(nickname):
        await msg.reply_text("❌ Nickname can only contain letters, numbers, and spaces. Emoji and special symbols are not allowed.")
        return

    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute("UPDATE user_pokemon SET nickname = ? WHERE id = ? AND user_id = ?", (nickname, pkmn_id, user.id))
    conn.commit()
    conn.close()

    del PENDING_NICKNAME[user.id]
    await msg.reply_text(f"✅ <b>{pkmn_name}</b> has been nicknamed <b>{nickname}</b>!", parse_mode="HTML")



# ════════════ RENAME TRAINER NAME SYSTEM ════════════

PENDING_RENAME: dict[int, bool] = {}  # user_id -> True when awaiting new name input
PENDING_RENAME_APPROVAL: dict[str, dict] = {}  # "user_id:new_name" -> {user_id, username, old_name, new_name}
RENAME_ADMIN_GC = _env_id("RENAME_ADMIN_GC", default=(OWNER_IDS[0] if OWNER_IDS else None))


async def rename_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Show the trainer their current name and ask for a new one."""
    user = update.effective_user
    if not user:
        return
    reg = is_registered(user.id)
    if not reg:
        await update.message.reply_text("❌ You are not registered yet. Use /start to begin.")
        return
    current_name = reg[0] or str(user.id)
    PENDING_RENAME[user.id] = True
    await update.message.reply_text(
        f"Your current trainer name:\n\n<b>{current_name}</b>\n\nSend your new trainer name.\n\n"
        f"Requirements: 1–20 characters (letters, numbers, spaces only).",
        parse_mode="HTML"
    )


async def rename_reply_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Capture the new name input, validate it, and send approval request to admin GC."""
    user = update.effective_user
    msg = update.message
    if not user or not msg or user.id not in PENDING_RENAME:
        return

    new_name = (msg.text or "").strip()
    if not new_name or new_name.startswith("/"):
        return

    # Validate length
    if len(new_name) < 1 or len(new_name) > 20:
        await msg.reply_text("❌ Name must be between 1 and 20 characters. Try again.")
        return

    # Block emoji and special unicode
    import unicodedata as _ud2
    for ch in new_name:
        if ch == ' ':
            continue
        cat = _ud2.category(ch)
        if not (cat.startswith('L') or cat.startswith('N')):
            await msg.reply_text("❌ Name can only contain letters, numbers, and spaces.")
            return

    reg = is_registered(user.id)
    old_name = reg[0] if reg else str(user.id)
    uname = f"@{user.username}" if user.username else "N/A"

    del PENDING_RENAME[user.id]

    # Store pending approval keyed by "{user_id}"
    PENDING_RENAME_APPROVAL[str(user.id)] = {
        "user_id": user.id,
        "username": uname,
        "old_name": old_name,
        "new_name": new_name,
    }

    kb = InlineKeyboardMarkup([
        [
            InlineKeyboardButton("Approve", callback_data=f"rename_approve_{user.id}"),
            InlineKeyboardButton("Reject",  callback_data=f"rename_reject_{user.id}"),
        ]
    ])
    await context.bot.send_message(
        chat_id=RENAME_ADMIN_GC,
        text=(
            f"🔄 Name Change Request\n\n"
            f"User:\n{old_name}\n\n"
            f"Username:\n{uname}\n\n"
            f"User ID:\n{user.id}\n\n"
            f"Requested Name:\n{new_name}"
        ),
        reply_markup=kb,
    )
    await msg.reply_text("✅ Your name change request has been submitted! We'll update your name once approved.")


async def rename_approval_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle Approve / Reject for trainer rename requests (fired in the admin GC)."""
    query = update.callback_query
    # Only owner / admins / head admins may approve or reject a rename.
    actor_id = query.from_user.id if query.from_user else 0
    if (actor_id not in OWNER_IDS and actor_id not in ADMIN_IDS
            and actor_id not in HEAD_ADMIN_IDS):
        await query.answer("Only admins can approve name changes.", show_alert=True)
        return
    await query.answer()
    data = query.data  # rename_approve_<user_id> or rename_reject_<user_id>

    if data.startswith("rename_approve_"):
        target_id = int(data.split("_", 2)[2])
        pending = PENDING_RENAME_APPROVAL.pop(str(target_id), None)
        if not pending:
            await query.edit_message_text("⚠️ Approval already processed or expired.")
            return
        new_name = pending["new_name"]
        # Apply the rename
        update_user(target_id, trainer_name=new_name)
        await query.edit_message_text(
            f"✅ Name change approved!\n{pending['old_name']} → {new_name}"
        )
        try:
            await context.bot.send_message(
                chat_id=target_id,
                text=f"✅ Your trainer name has been updated to <b>{new_name}</b>!",
                parse_mode="HTML",
            )
        except Exception:
            pass

    elif data.startswith("rename_reject_"):
        target_id = int(data.split("_", 2)[2])
        pending = PENDING_RENAME_APPROVAL.pop(str(target_id), None)
        if not pending:
            await query.edit_message_text("⚠️ Already processed or expired.")
            return
        await query.edit_message_text(f"❌ Name change rejected for {pending['old_name']}.")
        try:
            await context.bot.send_message(
                chat_id=target_id,
                text="❌ Your trainer name change request was rejected.",
            )
        except Exception:
            pass


# ════════════ MOVE RELEARNER SYSTEM ════════════

RELEARNER_COST = 500
RELEARNER_PAGE_SIZE = 5


def _relearner_emoji(move_type: str) -> str:
    return TYPE_EMOJIS.get(move_type, "")


def build_relearner_list_text(moves: list, page: int = 1) -> str:
    """Builds the Relearner list UI text for the given page (RELEARNER_PAGE_SIZE
    moves per page). The move numbers are global so page 2 starts at 6, etc."""
    if not moves:
        return "❌ This Pokémon has no relearnable attack moves available."

    total_pages = max(1, math.ceil(len(moves) / RELEARNER_PAGE_SIZE))
    page        = max(1, min(page, total_pages))
    offset      = (page - 1) * RELEARNER_PAGE_SIZE
    page_moves  = moves[offset: offset + RELEARNER_PAGE_SIZE]

    text = "<b><u>What move do you wanna relearn?</u></b>\n\n"
    for idx, mi in enumerate(page_moves, start=offset + 1):
        name     = mi["name"].replace("-", " ").title()
        emoji    = _relearner_emoji(mi["type"])
        category = mi["damage_class"].capitalize()
        power    = mi["power"] if mi["power"] is not None else "—"
        acc      = _display_accuracy(mi.get("accuracy"))
        text += (
            f"{idx}. <b>{name} [{emoji}]</b> [{category}]\n\n"
            f"<blockquote>Power: {power}        Accuracy: {acc}</blockquote>"
        )
    text += (
        "<b><u>Note:</u></b>\n\n"
        f"<blockquote>Relearning a move costs {RELEARNER_COST} RoRupees</blockquote>"
    )
    return text


def build_relearner_list_keyboard(moves: list, pkmn_id, owner_id: int, page: int = 1) -> InlineKeyboardMarkup:
    """Move-number buttons for the current page (up to RELEARNER_PAGE_SIZE per
    page), a navigation row when there are multiple pages, and a Back button.

    Button row:   [1] [2] [3] [4] [5]   (global numbers, one row)
    Nav row:      [⬅️ Prev] [X/Y] [Next ➡️]   (Prev hidden on p.1, Next on last)
    Bottom row:   [🔙 Back]
    """
    total_pages = max(1, math.ceil(len(moves) / RELEARNER_PAGE_SIZE))
    page        = max(1, min(page, total_pages))
    offset      = (page - 1) * RELEARNER_PAGE_SIZE
    page_moves  = moves[offset: offset + RELEARNER_PAGE_SIZE]

    keyboard = []

    # ── Move buttons (one row, up to 5) ────────────────────────────────────
    move_row = []
    for idx, mi in enumerate(page_moves, start=offset + 1):
        move_row.append(
            InlineKeyboardButton(str(idx), callback_data=f"rl_pick_{pkmn_id}_{owner_id}_{mi['name']}")
        )
    if move_row:
        keyboard.append(move_row)

    # ── Navigation row (only when there is more than one page) ─────────────
    if total_pages > 1:
        nav = []
        if page > 1:
            nav.append(InlineKeyboardButton(
                "⬅️ Prev", callback_data=f"rl_page_{pkmn_id}_{owner_id}_{page - 1}"
            ))
        # Non-functional page indicator in the centre
        nav.append(InlineKeyboardButton(f"{page}/{total_pages}", callback_data="rl_noop"))
        if page < total_pages:
            nav.append(InlineKeyboardButton(
                "Next ➡️", callback_data=f"rl_page_{pkmn_id}_{owner_id}_{page + 1}"
            ))
        keyboard.append(nav)

    # ── Back button ─────────────────────────────────────────────────────────
    keyboard.append([InlineKeyboardButton("Back", callback_data=f"stats_info_{pkmn_id}_{owner_id}")])
    return InlineKeyboardMarkup(keyboard)


async def build_relearner_replacement_text(new_move: dict, current_moves: list, session: aiohttp.ClientSession) -> str:
    """Builds the 'choose which move to forget' UI for a chosen relearn move."""
    name     = new_move["name"].replace("-", " ").title()
    emoji    = _relearner_emoji(new_move["type"])
    category = new_move["damage_class"].capitalize()
    power    = new_move["power"] if new_move["power"] is not None else "—"
    acc      = _display_accuracy(new_move.get("accuracy"))

    text = (
        f"<b><u>Move: {name}</u></b>\n\n"
        f"<b>Type: {new_move['type'].capitalize()} {emoji}</b> [{category}]\n\n"
        f"<blockquote>Power: {power} | Accuracy: {acc}</blockquote>"
        f"<b>Choose which move you want to forget for this move:</b>\n\n"
    )

    for m_name in current_moves:
        mi = await fetch_move_info(session, f"https://pokeapi.co/api/v2/move/{m_name}/")
        if mi:
            text += (
                f"╭─「 {mi['name'].replace('-', ' ').title()} 」\n"
                f"├─ Type: {mi['type'].capitalize()} ({TYPE_EMOJIS.get(mi['type'], '')})\n"
                f"├─ Power: {mi['power']} | Accuracy: {_display_accuracy(mi.get('accuracy'))}\n"
                f"└─ Category: {mi['damage_class'].capitalize()}\n\n"
            )
    return text


def build_relearner_replacement_keyboard(current_moves: list, pkmn_id, owner_id: int, move_name: str) -> InlineKeyboardMarkup:
    """Buttons (4 per row) — one per currently-known move slot — so the
    trainer can pick which move to forget, plus a Back button. These must
    always appear whenever the Pokémon has at least one known move; an empty
    `current_moves` here would mean its moveset was never persisted to the
    DB in the first place (see compute_initial_moveset() / relearner_callback)."""
    keyboard = []
    row = []
    for idx in range(len(current_moves)):
        row.append(InlineKeyboardButton(str(idx + 1), callback_data=f"rl_slot_{pkmn_id}_{owner_id}_{move_name}_{idx}"))
        if len(row) == 4:
            keyboard.append(row)
            row = []
    if row:
        keyboard.append(row)
    keyboard.append([InlineKeyboardButton("Back", callback_data=f"rl_open_{pkmn_id}_{owner_id}")])
    return InlineKeyboardMarkup(keyboard)


def build_relearner_confirm_text(forget_name: str, learn_name: str) -> str:
    forget_disp = forget_name.replace("-", " ").title()
    learn_disp = learn_name.replace("-", " ").title()

    return (
        f"Forget <b>{forget_disp}</b> and learn <b>{learn_disp}</b>?\n\n"
        f"<blockquote>Relearning a move costs {RELEARNER_COST} RoRupees</blockquote>"
    )

def build_relearner_confirm_keyboard(pkmn_id, owner_id: int, move_name: str, slot_idx: int) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [
            InlineKeyboardButton("Yes", callback_data=f"rl_confirm_{pkmn_id}_{owner_id}_{move_name}_{slot_idx}"),
            InlineKeyboardButton("Back", callback_data=f"rl_pick_{pkmn_id}_{owner_id}_{move_name}"),
        ],
    ])


def build_relearner_success_text(pkmn_name: str, learn_name: str) -> str:
    return f"<b>{pkmn_name}</b> relearned <b>{learn_name.replace('-', ' ').title()}</b>!"


def build_relearner_success_keyboard(pkmn_id, owner_id: int) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([[InlineKeyboardButton("Back to Relearner", callback_data=f"rl_open_{pkmn_id}_{owner_id}")]])


def _build_relearner_replacement_keyboard_v2(
    current_moves: list, pkmn_id, owner_id: int, move_name: str
) -> InlineKeyboardMarkup:
    """Replacement keyboard for the 'choose which move to forget' screen.

    Uses the new callback format  rl_slot_{pid}_{oid}_{slot_idx}_{move_name}
    where the numeric slot index is at a FIXED position (parts[4]) so the
    callback parser never mis-splits move names that contain hyphens.

    Always generates one numbered button per move slot so shiny, custom, and
    regional-form Pokemon all see all four buttons, not just the Back button.
    Falls back to a single '1' button if current_moves is somehow empty after
    the safety-net backfill in relearner_callback.
    """
    keyboard = []
    row      = []
    for idx in range(max(len(current_moves), 1)):
        cb = f"rl_slot_{pkmn_id}_{owner_id}_{idx}_{move_name}"
        row.append(InlineKeyboardButton(str(idx + 1), callback_data=cb))
        if len(row) == 4:
            keyboard.append(row)
            row = []
    if row:
        keyboard.append(row)
    keyboard.append([InlineKeyboardButton("Back", callback_data=f"rl_open_{pkmn_id}_{owner_id}")])
    return InlineKeyboardMarkup(keyboard)


def _build_relearner_confirm_keyboard_v2(
    pkmn_id, owner_id: int, move_name: str, slot_idx: int
) -> InlineKeyboardMarkup:
    """Confirm keyboard using the new  rl_confirm_{pid}_{oid}_{slot_idx}_{move_name}
    format (slot index at fixed position parts[4], move name joined from parts[5:]).
    The Back button returns to the pick screen using the same new slot-first format
    for the rl_pick callback (which remains unchanged at parts[4])."""
    return InlineKeyboardMarkup([
        [
            InlineKeyboardButton(
                "Yes",
                callback_data=f"rl_confirm_{pkmn_id}_{owner_id}_{slot_idx}_{move_name}",
            ),
            InlineKeyboardButton(
                "🔙 Back",
                callback_data=f"rl_pick_{pkmn_id}_{owner_id}_{move_name}",
            ),
        ],
    ])


async def relearner_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles the full Move Relearner flow:
    open list -> pick move -> choose slot to forget -> confirm -> success.

    Callback data formats (all keyed on numeric DB id, never display names):
        rl_open_{pid}_{oid}
        rl_pick_{pid}_{oid}_{move_name}
        rl_slot_{pid}_{oid}_{slot_idx}_{move_name}   <- slot before move to survive hyphens
        rl_confirm_{pid}_{oid}_{slot_idx}_{move_name}

    Every step re-reads the Pokemon's species/level/moveset fresh from the
    database so nothing relies on stale in-memory state.  The Pokedex id
    (pid) is always the integer primary key of the user_pokemon row -- never
    a display name, shiny prefix, or custom tag -- so renames and decorations
    can never break the callback chain.
    """
    query = update.callback_query
    user  = query.from_user
    data  = query.data       # full callback string
    # Parse action from fixed prefix positions.
    # Format: rl_{action}_{pid}_{oid}[_{...}]
    parts = data.split("_")
    action = parts[1]        # open | pick | slot | confirm

    try:
        pkmn_id  = int(parts[2])
        owner_id = int(parts[3])
    except (ValueError, IndexError):
        await query.answer("Invalid request.", show_alert=True)
        return

    if not await validate_owner(query, owner_id):
        return

    # ── Load the Pokemon record by primary key ──────────────────────────────
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        """SELECT pokemon_id, pokemon_name, level, moves,
                  COALESCE(shiny, 0), COALESCE(nickname, ''), COALESCE(special_tag, '')
           FROM user_pokemon WHERE id = ? AND user_id = ?""",
        (pkmn_id, user.id),
    )
    row = cursor.fetchone()
    conn.close()

    if not row:
        await query.answer("You don't own that Pokemon.", show_alert=True)
        return

    species_id, species_name, level, moves_json, is_shiny_int, nickname, special_tag = row
    current_moves = json.loads(moves_json) if moves_json else []

    # ── Safety net: backfill moveset if the DB column is empty ─────────────
    # Any Pokemon created before moveset persistence was added (custom, admin-
    # granted, old Safari catches) will have an empty moves column.  Without
    # real moves the "choose which move to forget" keyboard has nothing to
    # build buttons from and shows only the Back button.  Backfill exactly
    # once here so every Pokemon the Relearner touches is self-healing.
    #
    # Also scrub any status / 0-power moves that slipped into storage (e.g.
    # from pre-migration data) so the Relearner never displays invalid moves.
    needs_save = False
    if current_moves:
        cleaned_moves = [
            m for m in current_moves
            if str(m).strip().lower() not in _KNOWN_INVALID_MOVE_SLUGS
        ]
        if len(cleaned_moves) != len(current_moves):
            current_moves = cleaned_moves
            needs_save    = True

    if not current_moves:
        # Always resolve to the clean PokeAPI slug before computing moveset.
        resolved_for_moveset = normalize_species_lookup_name(species_id)
        current_moves = await compute_initial_moveset(resolved_for_moveset, level)
        if not current_moves:
            # Absolute last resort -- at least give tackle so buttons appear.
            current_moves = ["tackle"]
        needs_save = True

    if needs_save:
        fix_conn = sqlite3.connect("ZNX.db")
        fix_conn.execute(
            "UPDATE user_pokemon SET moves = ? WHERE id = ? AND user_id = ?",
            (json.dumps(current_moves), pkmn_id, user.id),
        )
        fix_conn.commit()
        fix_conn.close()

    # ── Resolve the canonical PokeAPI species slug for learnset lookups ─────
    # Always use species_id (the pokemon_id DB column) which stores the raw
    # API slug or numeric id -- never a nickname, shiny-decorated display
    # string, or custom-tag display name.  normalize_species_lookup_name
    # strips any residual decoration (✨, [Tag], Mega/Primal/etc. prefixes)
    # and lower-cases + hyphenates so the result is a valid /pokemon/<slug>.
    resolved_species = normalize_species_lookup_name(species_id)

    # ── Build the human-readable display name (success message only) ────────
    display_base = nickname if nickname else species_name
    display_name = display_name_with_shiny(
        append_special_tag(display_base, special_tag, html=False), bool(is_shiny_int)
    )

    # ════════════════════════════════════════════════════════════════════════
    # ACTION: open  --  show the filtered move list
    # ════════════════════════════════════════════════════════════════════════
    if action == "open":
        candidates = await fetch_relearnable_moves(resolved_species, level, current_moves)

        # Requirement 7: if no moves remain after filtering, show an inline
        # message rather than a popup alert so the screen content changes.
        if not candidates:
            await query.answer()
            no_moves_text = "<b>No relearnable moves are available.</b>"
            kbd = InlineKeyboardMarkup([[
                InlineKeyboardButton("Back", callback_data=f"stats_info_{pkmn_id}_{owner_id}")
            ]])
            try:
                await query.edit_message_caption(
                    caption=no_moves_text, reply_markup=kbd, parse_mode="HTML"
                )
            except Exception:
                pass
            return

        await query.answer()
        text = build_relearner_list_text(candidates, page=1)
        kbd  = build_relearner_list_keyboard(candidates, pkmn_id, owner_id, page=1)
        try:
            await query.edit_message_caption(caption=text, reply_markup=kbd, parse_mode="HTML")
        except Exception:
            pass
        return

    # ════════════════════════════════════════════════════════════════════════
    # ACTION: page  --  navigate between move list pages
    # Callback: rl_page_{pid}_{oid}_{page_num}
    # page_num is at parts[4].
    # ════════════════════════════════════════════════════════════════════════
    if action == "page":
        try:
            page = int(parts[4])
        except (ValueError, IndexError):
            await query.answer("Invalid page.", show_alert=True)
            return

        candidates = await fetch_relearnable_moves(resolved_species, level, current_moves)
        if not candidates:
            await query.answer()
            no_moves_text = "<b>No relearnable moves are available.</b>"
            kbd = InlineKeyboardMarkup([[
                InlineKeyboardButton("Back", callback_data=f"stats_info_{pkmn_id}_{owner_id}")
            ]])
            try:
                await query.edit_message_caption(
                    caption=no_moves_text, reply_markup=kbd, parse_mode="HTML"
                )
            except Exception:
                pass
            return

        await query.answer()
        text = build_relearner_list_text(candidates, page=page)
        kbd  = build_relearner_list_keyboard(candidates, pkmn_id, owner_id, page=page)
        try:
            await query.edit_message_caption(caption=text, reply_markup=kbd, parse_mode="HTML")
        except Exception:
            pass
        return

    # ════════════════════════════════════════════════════════════════════════
    # ACTION: noop  --  non-functional page indicator button
    # ════════════════════════════════════════════════════════════════════════
    if action == "noop":
        await query.answer()
        return

    # ════════════════════════════════════════════════════════════════════════
    # ACTION: pick  --  trainer tapped a numbered move button
    # Callback: rl_pick_{pid}_{oid}_{move_name}
    # move_name is at parts[4]; PokeAPI slugs use hyphens not underscores so
    # split("_") always lands move_name at index 4.
    # ════════════════════════════════════════════════════════════════════════
    if action == "pick":
        move_name = parts[4]

        # Requirement 6: case-insensitive "already known" guard.
        known_lower = {m.strip().lower().replace(" ", "-") for m in current_moves}
        if move_name.lower() in known_lower:
            await query.answer("That Pokemon already knows that move.", show_alert=True)
            return

        # ── FEWER THAN 4 MOVES: skip the "choose a move to forget" screen ────
        if len(current_moves) < 4:
            # There is a free move slot — go straight to a simple confirmation.
            move_display = move_name.replace("-", " ").title()
            await query.answer()
            text = (
                f"Learn <b>{move_display}</b>?\n\n"
                f"This Pokémon has an empty move slot.\n\n"
                f"Relearning this move will cost <b>{RELEARNER_COST} RoRupees</b>."
            )
            kbd = InlineKeyboardMarkup([
                [InlineKeyboardButton(
                    "Yes",
                    callback_data=f"rl_dyes_{pkmn_id}_{owner_id}_{move_name}"
                )],
                [InlineKeyboardButton(
                    "🔙 Back",
                    callback_data=f"rl_open_{pkmn_id}_{owner_id}"
                )],
            ])
            try:
                await query.edit_message_caption(caption=text, reply_markup=kbd, parse_mode="HTML")
            except Exception:
                pass
            return

        # ── 4 MOVES: existing behaviour — ask which move to forget ───────────
        async with aiohttp.ClientSession() as session:
            mi = await fetch_move_info(session, f"https://pokeapi.co/api/v2/move/{move_name}/")
            if not mi:
                await query.answer("Could not load that move.", show_alert=True)
                return
            await query.answer()
            text = await build_relearner_replacement_text(mi, current_moves, session)

        # Requirement 8: keyboard always has one button per current move slot.
        # Use the new rl_slot_{pid}_{oid}_{slot_idx}_{move_name} format so the
        # numeric slot index is parsed from a fixed position (parts[4]) and the
        # move name is everything after (joined from parts[5:] with "_").
        kbd = _build_relearner_replacement_keyboard_v2(current_moves, pkmn_id, owner_id, move_name)
        try:
            await query.edit_message_caption(caption=text, reply_markup=kbd, parse_mode="HTML")
        except Exception:
            pass
        return

    # ════════════════════════════════════════════════════════════════════════
    # ACTION: slot  --  trainer chose which move to forget
    # Callback: rl_slot_{pid}_{oid}_{slot_idx}_{move_name}
    # slot_idx at parts[4]; move_name = "_".join(parts[5:])
    # ════════════════════════════════════════════════════════════════════════
    if action == "slot":
        try:
            slot_idx = int(parts[4])
        except (ValueError, IndexError):
            await query.answer("Invalid move slot.", show_alert=True)
            return
        move_name = "_".join(parts[5:])
        if not move_name:
            await query.answer("Invalid move name.", show_alert=True)
            return
        if slot_idx >= len(current_moves):
            await query.answer("Invalid move slot.", show_alert=True)
            return

        await query.answer()
        text = build_relearner_confirm_text(current_moves[slot_idx], move_name)
        kbd  = _build_relearner_confirm_keyboard_v2(pkmn_id, owner_id, move_name, slot_idx)
        try:
            await query.edit_message_caption(caption=text, reply_markup=kbd, parse_mode="HTML")
        except Exception:
            pass
        return

    # ════════════════════════════════════════════════════════════════════════
    # ACTION: confirm  --  deduct cost, replace move, persist
    # Callback: rl_confirm_{pid}_{oid}_{slot_idx}_{move_name}
    # slot_idx at parts[4]; move_name = "_".join(parts[5:])
    # ════════════════════════════════════════════════════════════════════════
    if action == "confirm":
        try:
            slot_idx = int(parts[4])
        except (ValueError, IndexError):
            await query.answer("Invalid move slot.", show_alert=True)
            return
        move_name = "_".join(parts[5:])
        if not move_name:
            await query.answer("Invalid move name.", show_alert=True)
            return
        if slot_idx >= len(current_moves):
            await query.answer("Invalid move slot.", show_alert=True)
            return

        profile = get_user(user.id)
        rupees = (profile.get("nova_rupee") or 0) if profile else 0

        if rupees < RELEARNER_COST:
            await query.answer(
                f"You need {RELEARNER_COST} RoRupees to relearn a move.", show_alert=True
            )
            return

        current_moves[slot_idx] = move_name
        increment_user(user.id, nova_rupee=-RELEARNER_COST)
        conn = get_db("ZNX.db")
        cursor = conn.cursor()
        cursor.execute(
            "UPDATE user_pokemon SET moves = ? WHERE id = ? AND user_id = ?",
            (json.dumps(current_moves), pkmn_id, user.id),
        )
        conn.commit()

        await query.answer("Move relearned!")
        text = build_relearner_success_text(display_name, move_name)
        kbd  = build_relearner_success_keyboard(pkmn_id, owner_id)
        try:
            await query.edit_message_caption(caption=text, reply_markup=kbd, parse_mode="HTML")
        except Exception:
            pass
        return

    # ════════════════════════════════════════════════════════════════════════
    # ACTION: dyes  --  direct confirm for Pokémon with < 4 moves
    # Callback: rl_dyes_{pid}_{oid}_{move_name}
    # move_name is at parts[4]; same parsing as pick.
    # ════════════════════════════════════════════════════════════════════════
    if action == "dyes":
        move_name = parts[4]
        if not move_name:
            await query.answer("Invalid move name.", show_alert=True)
            return

        # Safety: if the Pokémon somehow now has 4 moves, redirect to normal flow
        if len(current_moves) >= 4:
            await query.answer("Move slots are full. Please choose a move to forget.", show_alert=True)
            return

        profile = get_user(user.id)
        rupees = (profile.get("nova_rupee") or 0) if profile else 0

        if rupees < RELEARNER_COST:
            await query.answer(
                f"You need {RELEARNER_COST} RoRupees to relearn a move.", show_alert=True
            )
            return

        # Append move to the first free slot
        current_moves.append(move_name)
        increment_user(user.id, nova_rupee=-RELEARNER_COST)
        conn = get_db("ZNX.db")
        cursor = conn.cursor()
        cursor.execute(
            "UPDATE user_pokemon SET moves = ? WHERE id = ? AND user_id = ?",
            (json.dumps(current_moves), pkmn_id, user.id),
        )
        conn.commit()
        conn.close()

        await query.answer("Move relearned!")
        text = build_relearner_success_text(display_name, move_name)
        kbd  = build_relearner_success_keyboard(pkmn_id, owner_id)
        try:
            await query.edit_message_caption(caption=text, reply_markup=kbd, parse_mode="HTML")
        except Exception:
            pass
        return

    await query.answer("Unknown action.", show_alert=True)


# ════════════ /VIEWNAMES ════════════

VIEWNAMES_PAGE_SIZE = 20

async def viewnames_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """/viewnames — shows all nicknamed Pokémon (hidden command)."""
    user = update.effective_user
    await _send_viewnames(update.message.reply_text, user.id, page=1)


async def _send_viewnames(send_fn, user_id: int, page: int):
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        """SELECT pokemon_name, nickname, nature, COALESCE(special_tag, '') FROM user_pokemon
           WHERE user_id = ? AND nickname != '' AND nickname IS NOT NULL
           ORDER BY pokemon_name ASC""",
        (user_id,)
    )
    rows = cursor.fetchall()
    conn.close()

    if not rows:
        await send_fn("You haven't nicknamed any Pokémon yet.")
        return

    total = len(rows)
    total_pages = max(1, math.ceil(total / VIEWNAMES_PAGE_SIZE))
    page = max(1, min(page, total_pages))
    offset = (page - 1) * VIEWNAMES_PAGE_SIZE
    page_rows = rows[offset: offset + VIEWNAMES_PAGE_SIZE]

    lines = ["<b>Your Nicknamed Pokémon:</b>\n"]
    for i, (poke_name, nickname, nature, special_tag) in enumerate(page_rows, start=offset + 1):
        base_display = append_special_tag(poke_name, special_tag)
        lines.append(f"{i}. {nickname} ({base_display}) - {nature}")
    lines.append(f"\nPage: {page}/{total_pages}")
    text = "\n".join(lines)

    nav_row = []
    if page > 1:
        nav_row.append(InlineKeyboardButton("Prev", callback_data=f"viewnames:{user_id}:{page-1}"))
    nav_row.append(InlineKeyboardButton(f"{page}/{total_pages}", callback_data="viewnames_noop"))
    if page < total_pages:
        nav_row.append(InlineKeyboardButton("Next", callback_data=f"viewnames:{user_id}:{page+1}"))
    kbd = InlineKeyboardMarkup([nav_row]) if nav_row else None
    await send_fn(text, parse_mode="HTML", reply_markup=kbd)


