def _build_inventory_main_text(user_id: int) -> str:
    """Build the main inventory page HTML text."""
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        "SELECT trainer_name, nova_rupee, COALESCE(trainer_exp, 0), "
        "COALESCE(has_keystone, 0), COALESCE(has_dynamax_band, 0), "
        "COALESCE(referral_badge, 0), COALESCE(rank_drop_prev, '') "
        "FROM users WHERE user_id = ?", (user_id,)
    )
    row = cursor.fetchone()

    # Pokédex: count distinct species owned
    cursor.execute(
        "SELECT COUNT(DISTINCT pokemon_id) FROM user_pokemon WHERE user_id = ?", (user_id,)
    )
    dex_row = cursor.fetchone()
    conn.close()

    if not row:
        return "You haven't registered yet! Type /start to begin your journey."

    trainer_name, nova_rupee, trainer_exp, has_keystone, has_dynamax_band, referral_badge, rank_drop_prev = row
    nova_rupee = nova_rupee or 0
    dex_count  = dex_row[0] if dex_row else 0

    rank_name, rank_min, rank_max = get_trainer_rank(trainer_exp)
    # Find next rank
    next_rank = None
    for r_name, r_min, r_max in TRAINER_RANKS:
        if r_min == rank_max:
            next_rank = r_name
            break
    if next_rank is None:
        next_rank = rank_name  # Already at top

    bar = build_rank_progress_bar(trainer_exp, rank_min, rank_max, length=10)

    # Build rank drop line if a seasonal drop happened
    if rank_drop_prev and rank_drop_prev != rank_name:
        rank_drop_line = f"├ <b>Rank Drop</b>: <s>{rank_drop_prev}</s> > {rank_name}\n"
    elif rank_drop_prev and rank_drop_prev == rank_name:
        rank_drop_line = f"├ <b>Rank Drop</b>: <s>{rank_drop_prev}</s> > {rank_name} (floor)\n"
    else:
        rank_drop_line = ""

    text = (
        "<b><u>Your Inventory</u></b>\n\n"
        "💎 <b><u>Currency</u></b>\n"
        f"├ <b>RoRupee</b>: {nova_rupee:,} 💶\n"
        f"└ <b>Experience</b>: {trainer_exp:,} 💫\n\n"
        "🔑 <b><u>Special Items</u></b>\n"
        f"├ <b>Key Stone</b>: {'Owned' if has_keystone else 'Not Owned'}\n"
        f"└ <b>Dynamax Band</b>: {'Owned' if has_dynamax_band else 'Not Owned'}\n\n"
        "📚 <b><u>Progress</u></b>\n"
        f"├ 📖 <b>Pokédex</b>: [{dex_count}/1025]\n"
        f"└ 💠 <b>Referral Badge</b>: {'Owned' if referral_badge else 'Not Owned'}\n\n"
        "❖ <b><u>Rank</u></b>\n"
        f"{rank_drop_line}"
        f"├ <b>Current</b>: {rank_name}\n"
        f"├ <b>Next</b>: {next_rank}\n"
        f"├ <b>To Next Rank</b>: {trainer_exp:,}/{rank_max:,}\n"
        f"└ {bar}"
    )
    return text


def _build_inventory_keyboard(uid: int, active: str | None = None) -> InlineKeyboardMarkup:
    """
    Build the inventory inline keyboard.
    `active` is the currently open category (e.g. 'pokeballs'), whose button
    is replaced with a [Main] button per the spec.
    """
    labels = {
        "pokeballs":  "PokeBalls",
        "megastones": "Mega Stones",
        "items":      "Items",
        "tms":        "TMs",
    }

    def _btn(key: str) -> InlineKeyboardButton:
        if key == active:
            return InlineKeyboardButton("Main", callback_data=f"inv_main_{uid}")
        return InlineKeyboardButton(labels[key], callback_data=f"inv_{key}_{uid}")

    keyboard = [
        [_btn("pokeballs"), _btn("megastones")],
        [_btn("items"),     _btn("tms")],
    ]
    return InlineKeyboardMarkup(keyboard)


async def inventory(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Displays the user's current inventory."""
    user = update.effective_user
    text = _build_inventory_main_text(user.id)
    if "haven't registered" in text:
        await update.message.reply_text(text)
        return
    reply_markup = _build_inventory_keyboard(user.id, active=None)
    await update.message.reply_text(text, reply_markup=reply_markup, parse_mode="HTML")

async def inventory_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles the inline button clicks for the inventory menu."""
    query = update.callback_query
    user  = query.from_user

    # ── Ownership guard: callback_data format is inv_{category}_{owner_id} ──
    raw_parts = query.data.split("_")
    # Minimum: ["inv", category, owner_id]  — owner_id is the last segment
    if len(raw_parts) >= 3:
        try:
            owner_id = int(raw_parts[-1])
            if not await validate_owner(query, owner_id):
                return
        except ValueError:
            await query.answer("This menu belongs to another trainer.", show_alert=True)
            return
    else:
        await query.answer("This menu belongs to another trainer.", show_alert=True)
        return

    await query.answer()

    uid      = user.id
    # category is the second segment (inv_{category}_{uid})
    category = raw_parts[1]

    # ── Main page ─────────────────────────────────────────────────────────────
    if category == "main":
        text         = _build_inventory_main_text(uid)
        reply_markup = _build_inventory_keyboard(uid, active=None)
        try:
            await query.edit_message_text(text, reply_markup=reply_markup, parse_mode="HTML")
        except Exception:
            pass
        return

    # ── Fetch all inventory data needed for sub-pages ─────────────────────────
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        "SELECT trainer_name, nova_rupee, exp, candy, vitamin, boost, berry, pokeballs, greatballs, "
        "ultraballs, repeatballs, nestballs, duskballs, master_ball, "
        "quickballs, netballs, levelballs, fastballs, beastballs, heavyballs, moonballs, loveballs, "
        "COALESCE(has_keystone, 0), COALESCE(has_dynamax_band, 0) FROM users WHERE user_id = ?",
        (uid,)
    )
    result = cursor.fetchone()
    conn.close()

    if not result:
        await query.edit_message_text("You haven't registered yet! Type /start to begin your journey.")
        return

    (trainer_name, nova_rupee, exp, candy, vitamin, boost, berry,
     pokeballs, greatballs, ultraballs, repeatballs, nestballs, duskballs, master_ball_count,
     quickballs, netballs, levelballs, fastballs, beastballs, heavyballs, moonballs, loveballs,
     has_keystone, has_dynamax_band) = result

    nova_rupee      = nova_rupee      or 0; exp         = exp         or 0
    candy           = candy           or 0; vitamin     = vitamin     or 0
    boost           = boost           or 0; berry       = berry       or 0
    pokeballs       = pokeballs       or 0; greatballs  = greatballs  or 0
    ultraballs      = ultraballs      or 0; repeatballs = repeatballs or 0
    nestballs       = nestballs       or 0; duskballs   = duskballs   or 0
    master_ball_count = master_ball_count or 0
    quickballs  = quickballs  or 0; netballs   = netballs   or 0
    levelballs  = levelballs  or 0; fastballs  = fastballs  or 0
    beastballs  = beastballs  or 0; heavyballs = heavyballs or 0
    moonballs   = moonballs   or 0; loveballs  = loveballs  or 0

    if category == "pokeballs":
        ball_entries = [
            ("Regular Ball",  pokeballs),
            ("Great Ball",    greatballs),
            ("Ultra Ball",    ultraballs),
            ("Repeat Ball",   repeatballs),
            ("Nest Ball",     nestballs),
            ("Dusk Ball",     duskballs),
            ("Master Ball",   master_ball_count),
            ("Beast Ball",    beastballs),
            ("Quick Ball",    quickballs),
            ("Net Ball",      netballs),
            ("Level Ball",    levelballs),
            ("Fast Ball",     fastballs),
            ("Heavy Ball",    heavyballs),
            ("Moon Ball",     moonballs),
            ("Love Ball",     loveballs),
        ]
        ball_lines = [f"<b>{name}</b>: {qty}" for name, qty in ball_entries if qty > 0]
        if context.user_data.get("safari_active"):
            safari_balls_count = context.user_data.get("safari_balls", 0)
            if safari_balls_count > 0:
                ball_lines.append(f"<b>Safari Ball</b>: {safari_balls_count}")
        content    = ("<b><u>Poké Balls</u></b>\n\n" + "\n".join(ball_lines)) if ball_lines else "<b><u>Poké Balls</u></b>\n\nNone"
        parse_mode = "HTML"

    elif category == "megastones":
        conn_s = sqlite3.connect("ZNX.db")
        cursor_s = conn_s.cursor()
        cursor_s.execute(
            "SELECT stone_name, quantity FROM user_stones WHERE user_id = ? AND quantity > 0 ORDER BY stone_name",
            (uid,)
        )
        stone_rows = cursor_s.fetchall()
        conn_s.close()
        if stone_rows:
            individual_lines = []
            for stone_name, qty in stone_rows:
                for _ in range(qty):
                    individual_lines.append(stone_name)
            content = "<b><u>Mega Stones</u></b>\n\n" + "\n".join(individual_lines)
        else:
            content = "<b><u>Mega Stones</u></b>\n\nNone"
        parse_mode = "HTML"

    elif category == "tms":
        conn_t = sqlite3.connect("ZNX.db")
        cursor_t = conn_t.cursor()
        cursor_t.execute(
            "SELECT tm_number, move_name, quantity FROM user_tms WHERE user_id = ? AND quantity > 0 ORDER BY tm_number",
            (uid,)
        )
        tm_rows = cursor_t.fetchall()
        conn_t.close()
        if tm_rows:
            tm_lines = [
                f"• /TM{num} <b>[{move}]</b>: {qty}"
                for num, move, qty in tm_rows
            ]
            content = "📀 <b><u>TMs</u></b>\n\n" + "\n".join(tm_lines)
        else:
            content = "📀 <b><u>TMs</u></b>\n\nNone"
        parse_mode = "HTML"

    elif category == "items":
        item_lines = []
        if candy   > 0: item_lines.append(f"🍬 <b>Candy</b>: {candy:,}")
        if vitamin > 0: item_lines.append(f"💊 <b>Vitamin</b>: {vitamin:,}")
        if boost   > 0: item_lines.append(f"💉 <b>Boost</b>: {boost:,}")
        if berry   > 0: item_lines.append(f"🍇 <b>Berry</b>: {berry:,}")
        content    = ("<b><u>Items</u></b>\n\n" + "\n".join(item_lines)) if item_lines else "<b><u>Items</u></b>\n\nNone"
        parse_mode = "HTML"

    else:
        content    = "<b><u>Items</u></b>\n\nNone"
        parse_mode = "HTML"

    reply_markup = _build_inventory_keyboard(uid, active=category)
    try:
        await query.edit_message_text(content, reply_markup=reply_markup, parse_mode=parse_mode)
    except Exception:
        pass

async def dbreset(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Admin command to reset all database data."""
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        await update.message.reply_text("Unauthorized.")
        return

    try:
        # Reset t17273728287283373738.db
        conn = sqlite3.connect("t17273728287283373738.db")
        cursor = conn.cursor()
        cursor.execute("DELETE FROM users")
        cursor.execute("DELETE FROM user_pokemon")
        conn.commit()
        conn.close()

        # Reset trainers.db
        conn_trainers = sqlite3.connect("ZNX.db")
        cursor_trainers = conn_trainers.cursor()
        cursor_trainers.execute("DELETE FROM users")
        cursor_trainers.execute("DELETE FROM user_pokemon")
        conn_trainers.commit()
        conn_trainers.close()

        await update.message.reply_text("Database has been fully reset. All user data is cleared.")
    except Exception as e:
        logger.error(f"Error resetting database: {e}")
        await update.message.reply_text("An error occurred while resetting the database.")


async def rebuildcache_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Admin-only /rebuildcache — manage the persistent PokéAPI cache.

    Usage:
      /rebuildcache                 → show cache stats and repair any corrupted rows
      /rebuildcache <name or id>    → force-refresh cached entries matching that
                                       name/id, or download it fresh if it was
                                       never cached
      /rebuildcache wipe confirm    → erase the ENTIRE cache (only with the
                                       literal "confirm" — never erases on a
                                       bare "wipe")

    This never touches gameplay data (trainers.db) — only the PokéAPI
    response cache (pokeapi_cache.db). Existing cached entries are never
    erased unless "wipe confirm" is explicitly given.
    """
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        await update.message.reply_text("❌ You are not authorized to use this command.")
        return

    args = context.args or []

    # ── Full wipe — requires explicit "confirm", never triggered by accident ──
    if args and args[0].lower() == "wipe":
        if len(args) < 2 or args[1].lower() != "confirm":
            await update.message.reply_text(
                "⚠️ This will erase the ENTIRE PokéAPI cache — every Pokémon, "
                "move, species, and evolution entry will need to be "
                "re-downloaded from PokéAPI the next time it's needed.\n\n"
                "To confirm, send exactly: /rebuildcache wipe confirm"
            )
            return
        try:
            conn = sqlite3.connect(POKEAPI_CACHE_DB_PATH)
            conn.execute("DELETE FROM pokeapi_cache")
            conn.commit()
            conn.close()
            _POKEAPI_CACHE.clear()
            _MOVE_CACHE.clear()
            await update.message.reply_text(
                "🗑️ PokéAPI cache fully wiped. It will rebuild automatically, "
                "one PokéAPI request at a time, as features are used again."
            )
        except Exception as e:
            logger.error(f"[rebuildcache] wipe failed: {e}")
            await update.message.reply_text("❌ Failed to wipe the cache.")
        return

    # ── Refresh (or newly download) entries matching a specific name/id ──────
    if args:
        raw_query = " ".join(args).strip()
        slug = raw_query.lower().replace(" ", "-")
        urls = _pokeapi_cache_find_urls(slug)

        if urls:
            refreshed = 0
            for url in urls:
                _pokeapi_cache_delete(url)
                data = await _cached_pokeapi_get(url)
                if data:
                    refreshed += 1
            plural = "y" if len(urls) == 1 else "ies"
            await update.message.reply_text(
                f"🔄 Refreshed {refreshed}/{len(urls)} cached entr{plural} matching '{raw_query}'."
            )
            return

        # Nothing cached yet under that name — try downloading it fresh as
        # either a Pokémon or a move, so admins can pre-warm new entries.
        fetched = []
        for probe_url in (
            f"https://pokeapi.co/api/v2/pokemon/{slug}",
            f"https://pokeapi.co/api/v2/move/{slug}/",
        ):
            data = await _cached_pokeapi_get(probe_url)
            if data:
                fetched.append(probe_url)
        if fetched:
            plural = "y" if len(fetched) == 1 else "ies"
            await update.message.reply_text(
                f"✅ Downloaded and cached {len(fetched)} new entr{plural} for '{raw_query}'."
            )
        else:
            await update.message.reply_text(
                f"No cached entries found matching '{raw_query}', and PokéAPI "
                f"has nothing under that name/slug either."
            )
        return

    # ── No args: show stats, and repair any corrupted rows found on disk ─────
    corrupted: list = []
    try:
        conn = sqlite3.connect(POKEAPI_CACHE_DB_PATH)
        cur = conn.cursor()
        for url, data in cur.execute("SELECT url, data FROM pokeapi_cache"):
            try:
                json.loads(data)
            except (TypeError, ValueError):
                corrupted.append(url)
        for url in corrupted:
            cur.execute("DELETE FROM pokeapi_cache WHERE url = ?", (url,))
            _POKEAPI_CACHE.pop(url, None)
        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"[rebuildcache] repair scan failed: {e}")

    stats = pokeapi_cache_stats()
    lines = [
        "📦 <b>PokéAPI Cache</b>",
        f"Total cached entries: <b>{stats['total']}</b>",
    ]
    if stats["by_category"]:
        lines.append("")
        for cat, count in stats["by_category"].items():
            lines.append(f"• {cat}: {count}")
    if corrupted:
        plural = "y" if len(corrupted) == 1 else "ies"
        lines.append("")
        lines.append(f"🔧 Repaired {len(corrupted)} corrupted entr{plural} — will re-download automatically on next use.")
    lines.append("")
    lines.append(
        "Usage: <code>/rebuildcache &lt;name or id&gt;</code> to refresh one entry, "
        "or <code>/rebuildcache wipe confirm</code> to erase everything."
    )
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")


async def add_nova_rupee(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Admin command to add Ro Rupees to a user."""
    user = update.effective_user
    
    if user.id not in ADMIN_IDS:
        await update.message.reply_text("❌ You are not authorized to use this command.")
        return
        
    if not update.message.reply_to_message:
        await update.message.reply_text("❌ Reply to a user's message.")
        return
        
    if not context.args:
        await update.message.reply_text("❌ Invalid amount.")
        return
        
    try:
        amount = int(context.args[0])
        if amount <= 0:
            raise ValueError
    except ValueError:
        await update.message.reply_text("❌ Invalid amount.")
        return
        
    target_user = update.message.reply_to_message.from_user
    
    # Check if target user is registered
    profile = get_user(target_user.id)
    if profile is None:
        await update.message.reply_text("❌ Target user is not registered.")
        return
        
    trainer_name = profile.get("trainer_name")
    new_balance = increment_user(target_user.id, nova_rupee=amount)["nova_rupee"]
    
    ui = (
        "✅ RoRupees 💶 Added!\n\n"
        f"👤 Trainer: {trainer_name}\n 💰 Added: {amount} 💴\n 🏦 New Balance: {new_balance} 💴"
    )
    await update.message.reply_text(ui)

async def give_rupee(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Command to transfer RoRupee to another user."""
    if not update.message.reply_to_message:
        await update.message.reply_text("❌ You must reply to a user to give them RoRupees.")
        return

    if not context.args:
        await update.message.reply_text("❌ Usage: /give <amount>")
        return

    try:
        amount = int(context.args[0])
        if amount <= 0:
            raise ValueError
    except ValueError:
        await update.message.reply_text("❌ Invalid amount. Please enter a positive number.")
        return

    sender = update.effective_user
    receiver = update.message.reply_to_message.from_user

    if sender.id == receiver.id:
        await update.message.reply_text("❌ You cannot give RoRupees to yourself.")
        return

    # Check Sender
    sender_profile = get_user(sender.id)
    if sender_profile is None:
        await update.message.reply_text("❌ You are not registered. Type /start to begin.")
        return

    sender_bal = sender_profile.get("nova_rupee") or 0

    if sender_bal < amount:
        await update.message.reply_text("❌ You don't have enough RoRupees.")
        return

    # Check Receiver
    receiver_profile = get_user(receiver.id)
    if receiver_profile is None:
        await update.message.reply_text("❌ Target user is not registered.")
        return

    # Perform Transaction — both increments are non-yielding (no await between
    # them), so this is atomic against any other concurrent command touching
    # either account, same reasoning as increment_user()'s own docstring.
    increment_user(sender.id, nova_rupee=-amount)
    increment_user(receiver.id, nova_rupee=amount)

    await update.message.reply_text(f"{sender.first_name} gave {amount} RoRupee 💶 to {receiver.first_name}")

