async def aid_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """/aid — hidden admin utility (owner/admin only, not in the menu).

    Usage:
      /aid give <user_id> <amount>            → RoRupees
      /aid item <user_id> <item> <amount>     → items (candy, pokeballs, ...)
      /aid poke <user_id> <name> [level]      → grant a Pokémon (random IVs/nature)
      /aid shiny <user_id> <poke_db_id>       → make one of their Pokémon shiny
      /aid level <user_id> <poke_db_id> <lv>  → set a Pokémon's level
      /aid help                               → this help
    """
    user = update.effective_user
    if user.id not in ADMIN_IDS:
        return  # silent ignore for non-admins (command is meant to be invisible)

    args = context.args or []
    if not args or args[0].lower() in ("help", "?"):
        await update.message.reply_text(
            "<b>🧰 /aid</b> (hidden admin tool)\n\n"
            "<code>/aid give &lt;uid&gt; &lt;amt&gt;</code> — RoRupees\n"
            "<code>/aid item &lt;uid&gt; &lt;item&gt; &lt;amt&gt;</code> — items\n"
            "<code>/aid poke &lt;uid&gt; &lt;name&gt; [lvl]</code> — give Pokémon\n"
            "<code>/aid shiny &lt;uid&gt; &lt;poke_id&gt;</code> — shiny a Pokémon\n"
            "<code>/aid level &lt;uid&gt; &lt;poke_id&gt; &lt;lv&gt;</code> — set level",
            parse_mode="HTML")
        return

    sub = args[0].lower()

    def _uid(x: str) -> int:
        return int(x)

    try:
        # ── give RoRupees ─────────────────────────────────────────────────
        if sub == "give":
            if len(args) < 3:
                raise ValueError("usage: /aid give <uid> <amount>")
            tid, amt = _uid(args[1]), int(args[2])
            if amt <= 0:
                raise ValueError("amount must be > 0")
            if get_user(tid) is None:
                await update.message.reply_text(f"❌ {tid} is not registered.")
                return
            increment_user(tid, nova_rupee=amt)
            _ap_log(user.id, user.first_name or str(user.id), f"/aid give {amt} RoRupees", tid, str(tid))
            await update.message.reply_text(f"✅ Gave <b>{amt:,}</b> RoRupees to {tid}.", parse_mode="HTML")
            try:
                await context.bot.send_message(chat_id=tid, text=f"💶 You received {amt:,} RoRupees from an Admin!")
            except Exception:
                pass
            return

        # ── give item ─────────────────────────────────────────────────────
        if sub == "item":
            if len(args) < 4:
                raise ValueError("usage: /aid item <uid> <item> <amount>")
            tid, key, amt = _uid(args[1]), args[2].lower(), int(args[3])
            col = _AID_ITEMS.get(key)
            if not col:
                raise ValueError(f"unknown item '{args[2]}' — try: {', '.join(sorted(set(_AID_ITEMS.values())))}")
            if amt <= 0:
                raise ValueError("amount must be > 0")
            if get_user(tid) is None:
                await update.message.reply_text(f"❌ {tid} is not registered.")
                return
            increment_user(tid, **{col: amt})
            _ap_log(user.id, user.first_name or str(user.id), f"/aid give {amt} {col}", tid, str(tid))
            await update.message.reply_text(f"✅ Gave <b>{amt:,}</b> {col} to {tid}.", parse_mode="HTML")
            try:
                await context.bot.send_message(chat_id=tid, text=f"🎁 You received {amt:,} {col} from an Admin!")
            except Exception:
                pass
            return

        # ── give Pokémon ──────────────────────────────────────────────────
        if sub == "poke":
            if len(args) < 3:
                raise ValueError("usage: /aid poke <uid> <name> [lvl]")
            tid = _uid(args[1])
            raw = " ".join(args[2:]).strip()
            lvl = 5
            # trailing number = level
            parts = raw.rsplit(" ", 1)
            if len(parts) == 2 and parts[1].isdigit():
                lvl = max(1, min(100, int(parts[1])))
                raw = parts[0]
            poke_api = raw.lower().replace(" ", "-")
            poke_disp = raw.title()
            if get_user(tid) is None:
                await update.message.reply_text(f"❌ {tid} is not registered.")
                return
            ivs = generate_random_ivs()
            nature = random.choice(list(NATURES.keys()))
            moves_json = json.dumps(await compute_initial_moveset(poke_api, lvl))
            conn = _ap_db()
            cur = conn.cursor()
            cur.execute("""
                INSERT INTO user_pokemon
                (user_id, pokemon_id, pokemon_name, level, nature, iv_hp, iv_atk, iv_def, iv_spa, iv_spd, iv_spe, is_active, shiny, moves)
                VALUES (?,?,?,?,?,?,?,?,?,?,?,0,0,?)
            """, (tid, poke_api, poke_disp, lvl, nature,
                  ivs.get("hp", 0), ivs.get("attack", 0), ivs.get("defense", 0),
                  ivs.get("special-attack", 0), ivs.get("special-defense", 0), ivs.get("speed", 0),
                  moves_json))
            new_id = cur.lastrowid
            conn.commit()
            conn.close()
            _ap_log(user.id, user.first_name or str(user.id), f"/aid gave {poke_disp} Lv{lvl}", tid, str(tid))
            await update.message.reply_text(f"✅ Gave <b>{poke_disp}</b> Lv{lvl} to {tid} (db id {new_id}).", parse_mode="HTML")
            try:
                await context.bot.send_message(chat_id=tid, text=f"🎁 You received {poke_disp} Lv{lvl} from an Admin!")
            except Exception:
                pass
            return

        # ── shiny a Pokémon ───────────────────────────────────────────────
        if sub == "shiny":
            if len(args) < 3:
                raise ValueError("usage: /aid shiny <uid> <poke_db_id>")
            tid, pid = _uid(args[1]), int(args[2])
            conn = _ap_db()
            cur = conn.cursor()
            cur.execute("UPDATE user_pokemon SET shiny=1 WHERE id=? AND user_id=?", (pid, tid))
            ok = cur.rowcount
            conn.commit()
            conn.close()
            if not ok:
                await update.message.reply_text(f"❌ Pokémon {pid} not found for {tid}.")
                return
            _ap_log(user.id, user.first_name or str(user.id), f"/aid shiny poke {pid}", tid, str(tid))
            await update.message.reply_text(f"✅ Pokémon {pid} is now ✨ shiny.")
            return

        # ── set level ─────────────────────────────────────────────────────
        if sub == "level":
            if len(args) < 4:
                raise ValueError("usage: /aid level <uid> <poke_db_id> <lv>")
            tid, pid, lv = _uid(args[1]), int(args[2]), int(args[3])
            lv = max(1, min(100, lv))
            conn = _ap_db()
            cur = conn.cursor()
            if lv >= 100:
                cur.execute("UPDATE user_pokemon SET level=?, exp=? WHERE id=? AND user_id=?",
                            (lv, 1000000, pid, tid))
            else:
                cur.execute("UPDATE user_pokemon SET level=? WHERE id=? AND user_id=?", (lv, pid, tid))
            ok = cur.rowcount
            conn.commit()
            conn.close()
            if not ok:
                await update.message.reply_text(f"❌ Pokémon {pid} not found for {tid}.")
                return
            _ap_log(user.id, user.first_name or str(user.id), f"/aid set level {lv} on {pid}", tid, str(tid))
            await update.message.reply_text(f"✅ Pokémon {pid} set to Lv{lv}.")
            return

        raise ValueError(f"unknown subcommand '{args[0]}' — try /aid help")

    except ValueError as e:
        await update.message.reply_text(f"❌ {e}")
    except Exception as e:
        await update.message.reply_text(f"❌ Error: {e}")


async def promote(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Head admin command to add a new admin."""
    user = update.effective_user
    # Only the Head Admin ID is permitted to use this command
    if user.id not in OWNER_IDS and user.id not in HEAD_ADMIN_IDS:
        await update.message.reply_text("Unauthorized. Only the Head Admin can use this command.")
        return

    if not update.message.reply_to_message:
        await update.message.reply_text("Please reply to a user's message to promote them.")
        return

    target_user = update.message.reply_to_message.from_user

    if target_user.id in ADMIN_IDS:
        await update.message.reply_text(f"{target_user.first_name} is already an admin.")
        return

    ADMIN_IDS.append(target_user.id)

    conn1 = sqlite3.connect("t17273728287283373738.db")
    cursor1 = conn1.cursor()
    cursor1.execute("INSERT OR IGNORE INTO admins (user_id) VALUES (?)", (target_user.id,))
    conn1.commit()
    conn1.close()

    conn2 = sqlite3.connect("ZNX.db")
    cursor2 = conn2.cursor()
    cursor2.execute("INSERT OR IGNORE INTO admins (user_id) VALUES (?)", (target_user.id,))
    conn2.commit()
    conn2.close()

    await update.message.reply_text(f"Successfully promoted {target_user.first_name} to admin!")

async def demote(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Head admin command to remove an admin."""
    user = update.effective_user
    if user.id not in OWNER_IDS and user.id not in HEAD_ADMIN_IDS:
        await update.message.reply_text("Unauthorized. Only the Head Admin can use this command.")
        return

    if not update.message.reply_to_message:
        await update.message.reply_text("Please reply to a user's message to demote them.")
        return

    target_user = update.message.reply_to_message.from_user

    if target_user.id in OWNER_IDS:
        await update.message.reply_text("You cannot demote the Head Admin.")
        return

    if target_user.id not in ADMIN_IDS:
        await update.message.reply_text(f"{target_user.first_name} is not an admin.")
        return

    ADMIN_IDS.remove(target_user.id)

    conn1 = sqlite3.connect("t17273728287283373738.db")
    cursor1 = conn1.cursor()
    cursor1.execute("DELETE FROM admins WHERE user_id = ?", (target_user.id,))
    conn1.commit()
    conn1.close()

    conn2 = sqlite3.connect("ZNX.db")
    cursor2 = conn2.cursor()
    cursor2.execute("DELETE FROM admins WHERE user_id = ?", (target_user.id,))
    conn2.commit()
    conn2.close()

    await update.message.reply_text(f"Successfully demoted {target_user.first_name} from admin.")

async def rmadmins(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Head admin command to remove all promoted admins."""
    user = update.effective_user
    if user.id not in OWNER_IDS and user.id not in HEAD_ADMIN_IDS:
        await update.message.reply_text("Unauthorized. Only the Head Admin can use this command.")
        return

    _keep = list(dict.fromkeys(list(OWNER_IDS) + list(HEAD_ADMIN_IDS)))
    ADMIN_IDS[:] = _keep

    conn1 = sqlite3.connect("t17273728287283373738.db")
    cursor1 = conn1.cursor()
    cursor1.execute("DELETE FROM admins")
    for _k in _keep:
        cursor1.execute("INSERT OR IGNORE INTO admins (user_id) VALUES (?)", (_k,))
    conn1.commit()
    conn1.close()

    conn2 = sqlite3.connect("ZNX.db")
    cursor2 = conn2.cursor()
    cursor2.execute("DELETE FROM admins")
    for _k in _keep:
        cursor2.execute("INSERT OR IGNORE INTO admins (user_id) VALUES (?)", (_k,))
    conn2.commit()
    conn2.close()

    await update.message.reply_text("Successfully removed all promoted admins.")


# ════════════════════════════════════ RESET LIMIT COMMAND ════════════════════════════════════

async def resetlimit(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """
    Head Admin command: /resetlimit {tg_id}  OR  reply to a user's message with /resetlimit
    Resets ALL cooldowns, limits, and temporary restriction data for the target trainer.
    Does NOT touch Pokémon, inventory, RoRupees, squads, stats, bonds, or catches.
    """
    admin = update.effective_user

    # ── Access control: Head Admins only ──────────────────────────────────────
    if admin.id not in HEAD_ADMIN_IDS:
        await update.message.reply_text("❌ You are not authorized to use this command.")
        return

    # ── Resolve the target trainer ID ─────────────────────────────────────────
    target_id   = None
    target_name = None
    used_reply  = False

    # Method 1: argument provided  →  /resetlimit 123456789
    if context.args:
        try:
            target_id = int(context.args[0])
        except ValueError:
            await update.message.reply_text(
                "Usage:\n\n/resetlimit {tg_id}\n\nor reply to a user's message with:\n\n/resetlimit"
            )
            return

    # Method 2: replying to a message  →  /resetlimit (no args)
    elif update.message.reply_to_message:
        target_id  = update.message.reply_to_message.from_user.id
        used_reply = True

    else:
        await update.message.reply_text(
            "Usage:\n\n/resetlimit {tg_id}\n\nor reply to a user's message with:\n\n/resetlimit"
        )
        return

    # ── Verify the trainer exists in the DB ───────────────────────────────────
    profile = get_user(target_id)
    if profile is None:
        await update.message.reply_text("❌ Trainer not found.")
        return

    target_name = profile.get("trainer_name") or str(target_id)

    # ── Step 1: Reset all user-level cooldowns / limits in `users` table ──────
    update_user(
        target_id,
        safari_last_cycle='',
        safari_daily_used=0,
        camp_pokemon_id=0,
        camp_start_time=0,
        camp_end_time=0,
        camp_cooldown_end=0,
        camp_gift_schedule='[]',
        camp_gifts_given=0,
        last_gift_time=0,
        camp_cooldown_notified=0,
        active_battle=0,
    )

    # ── Step 2: If the trainer had a Pokémon in camp, restore it ──────────────
    # Find any pokemon still flagged in_camp = 1 for this trainer and clear it.
    # user_pokemon is a separate table, not part of USER_CACHE — stays as a
    # direct (pooled) query, same as before.
    conn = get_db("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        """
        UPDATE user_pokemon
        SET in_camp         = 0,
            camp_start_time = 0,
            camp_end_time   = 0
        WHERE user_id = ? AND in_camp = 1
        """,
        (target_id,),
    )
    conn.commit()

    # ── Step 3: Build & send the success reply ────────────────────────────────
    now_ts   = datetime.now(timezone.utc)
    now_str  = now_ts.strftime("%Y-%m-%d %H:%M:%S UTC")

    if used_reply:
        success_msg = (
            "✅ Limits reset successfully.\n\n"
            f"Trainer:\n{target_name}\n\n"
            "Reset:\n"
            "• Safari\n"
            "• Camp\n"
            "• Cooldowns\n"
            "• Daily Limits"
        )
    else:
        success_msg = (
            "✅ Limits reset successfully.\n\n"
            f"Trainer ID: {target_id}\n\n"
            "Reset:\n"
            "• Safari\n"
            "• Camp\n"
            "• Cooldowns\n"
            "• Daily Limits"
        )

    await update.message.reply_text(success_msg)

    # ── Step 4: Log the action ────────────────────────────────────────────────
    logger.info(
        "HEAD_ADMIN_RESETLIMIT | Head Admin: %s | Reset limits for: %s | Time: %s",
        admin.id,
        target_id,
        now_str,
    )

# ════════════════════════════════════ END RESET LIMIT COMMAND ════════════════════════════════════


