# ══════════════════════════════════════════════════════════════════════════════
# STARTUP MIGRATION — rename old/typo stone names in trainer inventories
# ══════════════════════════════════════════════════════════════════════════════
# Applied once on every bot start. Only renames; no trainer loses ownership.
STONE_NAME_MIGRATIONS = {
    # (old_lower) → new canonical name
    "blastoisite":     "Blastoisinite",
    "skarmoryite":     "Skarmorite",
    "darkrainite":     "Darkranite",
    "baxcaliburite":   "Baxcalibrite",
    "scraftite":       "Scraftinite",
    "drampaite":       "Drampanite",
    "eelektrossite":   "Elektrossite",
    "glimmorite":      "Glimmoranite",
    "chimechoite":     "Chimechite",
    "crabominablite":  "Crabominite",
    "hawluchite":      "Hawluchanite",
    "dragon ascent":   "Jade Orb",
    "dragon_ascent":   "Jade Orb",
}


def _migrate_stone_names() -> None:
    """
    Rename typo/old stone names to correct canonical names in:
      • user_stones (inventory)
      • mega_stone_images (stored image URLs)
      • redeem_codes rewards JSON (pending rewards)
    No trainer loses ownership — only renames.
    """
    conn = sqlite3.connect("ZNX.db")
    cur  = conn.cursor()

    for old_name_lower, new_name in STONE_NAME_MIGRATIONS.items():
        # ── 1. user_stones ───────────────────────────────────────────────────
        # Fetch all rows with the old name (case-insensitive)
        cur.execute(
            "SELECT user_id, stone_name, quantity FROM user_stones "
            "WHERE LOWER(stone_name) = ?",
            (old_name_lower,)
        )
        rows = cur.fetchall()
        for user_id, old_name, qty in rows:
            if old_name == new_name:
                continue  # already correct
            # Check if correct-name row already exists for this user
            cur.execute(
                "SELECT quantity FROM user_stones WHERE user_id=? AND stone_name=?",
                (user_id, new_name)
            )
            existing = cur.fetchone()
            if existing:
                # Merge: add quantities, delete old row
                cur.execute(
                    "UPDATE user_stones SET quantity=? WHERE user_id=? AND stone_name=?",
                    (existing[0] + qty, user_id, new_name)
                )
                cur.execute(
                    "DELETE FROM user_stones WHERE user_id=? AND stone_name=?",
                    (user_id, old_name)
                )
            else:
                # Rename in place
                cur.execute(
                    "UPDATE user_stones SET stone_name=? WHERE user_id=? AND stone_name=?",
                    (new_name, user_id, old_name)
                )
            logger.info(f"[MIGRATION] user_stones: {old_name!r} → {new_name!r} (user {user_id})")

        # ── 2. mega_stone_images ─────────────────────────────────────────────
        cur.execute(
            "SELECT stone_name FROM mega_stone_images WHERE LOWER(stone_name)=?",
            (old_name_lower,)
        )
        img_rows = cur.fetchall()
        for (img_name,) in img_rows:
            if img_name == new_name:
                continue
            # Check if correct-name image already exists
            cur.execute(
                "SELECT 1 FROM mega_stone_images WHERE stone_name=?", (new_name,)
            )
            if cur.fetchone():
                cur.execute(
                    "DELETE FROM mega_stone_images WHERE stone_name=?", (img_name,)
                )
            else:
                cur.execute(
                    "UPDATE mega_stone_images SET stone_name=? WHERE stone_name=?",
                    (new_name, img_name)
                )
            logger.info(f"[MIGRATION] mega_stone_images: {img_name!r} → {new_name!r}")

        # ── 3. redeem_codes rewards JSON ─────────────────────────────────────
        cur.execute("SELECT code, rewards FROM redeem_codes")
        code_rows = cur.fetchall()
        for code, rewards_json in code_rows:
            try:
                rewards = json.loads(rewards_json or "{}")
            except Exception:
                continue
            stones = rewards.get("stones", [])
            changed = False
            new_stones = []
            for s in stones:
                if isinstance(s, str) and s.lower() == old_name_lower:
                    new_stones.append(new_name)
                    changed = True
                    logger.info(f"[MIGRATION] redeem_codes code={code}: {s!r} → {new_name!r}")
                else:
                    new_stones.append(s)
            if changed:
                rewards["stones"] = new_stones
                cur.execute(
                    "UPDATE redeem_codes SET rewards=? WHERE code=?",
                    (json.dumps(rewards), code)
                )

    conn.commit()
    conn.close()
    logger.info("[MIGRATION] Stone name migration complete.")


