def _parse_ban_duration(text: str) -> int | None:
    """
    Parse a duration string like '1h', '12h', '1d', '7d', '30m' into seconds.
    Returns None if parsing fails.
    """
    if not text:
        return None
    text = text.strip().lower()
    multipliers = {"m": 60, "h": 3600, "d": 86400}
    if text[-1] in multipliers:
        try:
            val = int(text[:-1])
            if val <= 0:
                return None
            return val * multipliers[text[-1]]
        except ValueError:
            return None
    return None


def generate_random_code() -> str:
    """Generates a random 7-char uppercase alphanumeric code."""
    chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
    return "".join(random.choices(chars, k=7))


def _normalize_stone_input(raw: str) -> str:
    """
    Normalises a raw item string for lookup in STONE_NAME_MAP.

    Handles:
    - Leading/trailing whitespace
    - Plural "stones" → "stone"
    - "X" / "Y" suffix reordering so both
        "charizard y stone" AND "charizard stone y" resolve correctly
    - Collapsed internal whitespace
    """
    import re
    s = raw.strip().lower()
    # Collapse multiple spaces
    s = re.sub(r"\s+", " ", s)
    # "X stones" / "Y stones" → strip trailing plural 's'
    # e.g. "sceptile stones" → "sceptile stone"
    s = re.sub(r"\bstones\b", "stone", s)
    # Handle "charizard stone y" → "charizard y stone"  (variant ordering)
    m = re.match(r"^(.+?)\s+stone\s+([xy])$", s)
    if m:
        s = f"{m.group(1)} {m.group(2)} stone"
    return s


# ══════════════════════════════════════════════════════════════════════════
# /gencode "Random Reward" expansion
#
# The admin only picks a reward TYPE at code-creation time (Random / Random
# Stone / Random Pokemon / Random Legendary / Random NR). The actual reward
# CONTENT is deliberately left unresolved until each individual trainer
# redeems the code — see _gencode_resolve_random_rewards() and redeem_code().
# Two trainers redeeming the same code can get completely different rewards.
# ══════════════════════════════════════════════════════════════════════════

# Real, well-documented "pseudo-legendary" final-stage families (three-stage
# lines, ~600 BST, no further evolutions). Not an official PokéAPI flag, so
# it's tracked explicitly here for the "Random Pokemon" level table below.
PSEUDO_LEGENDARY_FINALS = {
    "dragonite", "tyranitar", "salamence", "metagross", "garchomp",
    "hydreigon", "goodra", "kommo-o", "dragapult", "baxcalibur",
}

# Ultra Beasts — a corrected/complete dex-ID set used only by this gencode
# feature (kept separate from the pre-existing ULTRA_BEAST_IDS used by the
# Beast Ball catch-rate bonus elsewhere, so that behavior is left untouched).
GENCODE_ULTRA_BEAST_IDS = {793, 794, 795, 796, 797, 798, 799, 803, 804, 805, 806}

# Generation IX Paradox Pokémon (national dex numbers). REGION_DEX has no
# Paldea/Gen-9 entry yet, so this pool is defined explicitly here.
GENCODE_PARADOX_IDS = {
    984, 985, 986, 987, 988, 989, 990, 991, 992, 993, 994, 995,  # Scarlet/Violet base game
    1005, 1006, 1007, 1008, 1009, 1010,                          # incl. Koraidon/Miraidon
    1020, 1021, 1022, 1023,                                      # The Indigo Disk DLC
}

# The expansion spec gives only illustrative NR examples (5,000 / 10,000 /
# 3,250) rather than fixed bounds. This range is a reasonable assumption —
# adjust freely if a different spread is wanted.
GENCODE_NR_MIN = 1000
GENCODE_NR_MAX = 15000


def _gencode_all_stone_names() -> list[str]:
    """All known Mega Stone and special transformation item display names
    (everything MEGA_STONE_COMMANDS + SPECIAL_TRANSFORMATION_ITEMS can grant),
    deduplicated. Used by the 'Random Stone' gencode reward."""
    names: set[str] = {v[0] for v in MEGA_STONE_COMMANDS.values()}
    names.update(SPECIAL_TRANSFORMATION_ITEMS.keys())
    return sorted(names)


def _gencode_common_pokemon_pool() -> list[int]:
    """Every non-legendary, non-mythical dex ID known to this bot (flattened
    across all regions in REGION_DEX). Used by the 'Random Pokemon' reward."""
    ids: set[int] = set()
    for region_data in REGION_DEX.values():
        ids.update(region_data.get("common", []))
    return sorted(ids)


_GENCODE_LEGENDARY_POOL_CACHE: list[int] | None = None


def _gencode_legendary_pool() -> list[int]:
    """Every Legendary, Mythical, Ultra Beast, and Paradox dex ID known to
    this bot. Used by the 'Random Legendary' gencode reward, and by /hunt's
    rare-spawn roll (1-in-10,000 chance, every single hunt still calls this).

    REGION_DEX, GENCODE_ULTRA_BEAST_IDS, and GENCODE_PARADOX_IDS are all
    static for the life of the process, so the resulting pool never changes
    once computed — it's built once (set union + sort) and memoized instead
    of being rebuilt from scratch on every call. Both call sites only ever
    read from the returned list (random.choice), so sharing the same cached
    list object across calls is safe."""
    global _GENCODE_LEGENDARY_POOL_CACHE
    if _GENCODE_LEGENDARY_POOL_CACHE is None:
        ids: set[int] = set()
        for region_data in REGION_DEX.values():
            ids.update(region_data.get("legendary", []))
            ids.update(region_data.get("mythical", []))
        ids.update(GENCODE_ULTRA_BEAST_IDS)
        ids.update(GENCODE_PARADOX_IDS)
        _GENCODE_LEGENDARY_POOL_CACHE = sorted(ids)
    return _GENCODE_LEGENDARY_POOL_CACHE


async def _gencode_random_pokemon_level(session: aiohttp.ClientSession, dex_id: int, pokemon_name: str) -> int:
    """
    Rolls a level appropriate to a Pokémon's evolutionary stage, per the
    expansion spec's level table:
        Baby Pokémon                → 1-10
        First-stage (further evos)  → 1-20
        Middle evolutions           → 15-45
        Final evolutions            → 30-60
        Pseudo-legendary finals     → 40-65
    Falls back to a safe 1-50 range if a PokéAPI lookup fails.
    """
    try:
        species_url = f"https://pokeapi.co/api/v2/pokemon-species/{dex_id}/"
        species_data = await _cached_pokeapi_get(species_url)
        if not species_data:
            return random.randint(1, 50)

        if species_data.get("is_baby"):
            return random.randint(1, 10)

        evo_chain_url = species_data["evolution_chain"]["url"]
        evo_data = await _cached_pokeapi_get(evo_chain_url)
        if not evo_data:
            return random.randint(1, 50)
        chain = evo_data["chain"]

        def find_node(node, target, depth=0):
            if node["species"]["name"].lower() == target.lower():
                return depth, len(node["evolves_to"]) > 0
            for nxt in node["evolves_to"]:
                res = find_node(nxt, target, depth + 1)
                if res:
                    return res
            return None

        result = find_node(chain, pokemon_name)
        if not result:
            return random.randint(1, 50)
        depth, has_evos = result

        if depth == 0:
            stage = "base" if has_evos else "single"
        else:
            stage = "middle" if has_evos else "final"

        if stage == "base":
            return random.randint(1, 20)
        elif stage == "middle":
            return random.randint(15, 45)
        elif stage in ("final", "single"):
            if pokemon_name.lower() in PSEUDO_LEGENDARY_FINALS:
                return random.randint(40, 65)
            return random.randint(30, 60)

        return random.randint(1, 50)
    except Exception as e:
        logger.error(f"[GENCODE] level calc failed for {pokemon_name}: {e}")
        return random.randint(1, 50)


async def _gencode_roll_random_pokemon() -> dict | None:
    """Builds one battle-ready, non-legendary wild Pokémon with rarity-appropriate
    random IVs/nature (get_pokemon_battle_info -> generate_random_ivs(), the bot's
    existing IV system) and an evolution-stage-appropriate random level."""
    pool = _gencode_common_pokemon_pool()
    if not pool:
        return None
    dex_id = random.choice(pool)
    try:
        data = await _cached_pokeapi_get(f"https://pokeapi.co/api/v2/pokemon/{dex_id}")
        if not data:
            return None
        name = data["name"]
        level = await _gencode_random_pokemon_level(None, dex_id, name)
        info = await get_pokemon_battle_info(dex_id, level)
        if info:
            info["level"] = level
        return info
    except Exception as e:
        logger.error(f"[GENCODE] random pokemon roll failed: {e}")
        return None


async def _gencode_roll_random_legendary() -> dict | None:
    """Builds one Legendary / Mythical / Ultra Beast / Paradox Pokémon using the
    bot's existing rarity rules (calculate_level + generate_random_ivs — the same
    system already used for wild Legendary spawns)."""
    pool = _gencode_legendary_pool()
    if not pool:
        return None
    dex_id = random.choice(pool)
    try:
        name = str(dex_id)
        data = await _cached_pokeapi_get(f"https://pokeapi.co/api/v2/pokemon/{dex_id}")
        if data:
            name = data["name"]
        species_url = f"https://pokeapi.co/api/v2/pokemon-species/{dex_id}/"
        stage = await get_evolution_stage(None, species_url, name)
        rarity = "mythical" if stage == "mythical" else "legendary"
        level = calculate_level(stage, rarity)
        info = await get_pokemon_battle_info(dex_id, level)
        if info:
            info["level"] = level
        return info
    except Exception as e:
        logger.error(f"[GENCODE] random legendary roll failed: {e}")
        return None


def _gencode_roll_random_nr() -> int:
    """Rolls a random RoRupee amount — see GENCODE_NR_MIN/MAX above."""
    return random.randint(GENCODE_NR_MIN, GENCODE_NR_MAX)


async def _gencode_resolve_random_rewards(random_spec: dict, user_id: int, cursor) -> list[str]:
    """
    Resolves every deferred 'Random ...' reward for ONE redeeming trainer,
    writes the result directly to the DB via the given cursor (caller still
    commits/closes the connection), and returns human-readable HTML lines
    describing what was granted, for the trainer's redeem-success message.

    random_spec example: {"stone": 1, "pokemon": 2, "nr": 1, "full": 1}
    """
    lines: list[str] = []

    def grant_stone() -> str | None:
        names = _gencode_all_stone_names()
        if not names:
            return None
        stone_name = random.choice(names)
        cursor.execute(
            """
            INSERT INTO user_stones (user_id, stone_name, quantity)
            VALUES (?, ?, 1)
            ON CONFLICT(user_id, stone_name) DO UPDATE SET quantity = quantity + 1
            """,
            (user_id, stone_name)
        )
        return f"🪨 +1 {stone_name} <i>(Random Stone)</i>"

    async def grant_pokemon(legendary: bool) -> str | None:
        mon = await (_gencode_roll_random_legendary() if legendary else _gencode_roll_random_pokemon())
        if not mon:
            return None
        ivs = mon["ivs"]
        moves_json = json.dumps([m["name"] for m in mon["moves"]])
        cursor.execute(
            """
            INSERT INTO user_pokemon
                (user_id, pokemon_id, pokemon_name, level, nature,
                 iv_hp, iv_atk, iv_def, iv_spa, iv_spd, iv_spe, moves, shiny)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
            """,
            (
                user_id, str(mon["id"]), mon["name"], mon["level"], mon["nature"],
                ivs["hp"], ivs["attack"], ivs["defense"],
                ivs["special-attack"], ivs["special-defense"], ivs["speed"],
                moves_json,
            )
        )
        tag = "Random Legendary" if legendary else "Random Pokemon"
        return f"{mon['name']} (Lv. {mon['level']}) <i>({tag})</i>"

    def grant_nr() -> str:
        amount = _gencode_roll_random_nr()
        increment_user(user_id, nova_rupee=amount)
        return f"💰 +{amount:,} RoRupees <i>(Random NR)</i>"

    for _ in range(random_spec.get("stone", 0)):
        line = grant_stone()
        if line:
            lines.append(line)

    for _ in range(random_spec.get("pokemon", 0)):
        line = await grant_pokemon(False)
        if line:
            lines.append(line)

    for _ in range(random_spec.get("legendary", 0)):
        line = await grant_pokemon(True)
        if line:
            lines.append(line)

    for _ in range(random_spec.get("nr", 0)):
        lines.append(grant_nr())

    for _ in range(random_spec.get("full", 0)):
        choice = random.choice(["stone", "pokemon", "legendary", "nr"])
        if choice == "stone":
            line = grant_stone()
        elif choice == "pokemon":
            line = await grant_pokemon(False)
        elif choice == "legendary":
            line = await grant_pokemon(True)
        else:
            line = grant_nr()
        if line:
            lines.append(line)

    return lines


def parse_gencode_text(full_text: str) -> dict:
    """
    Parses the body of a /gencode command (everything after the command line).

    Returns a dict:
        {
            "mode": "fix" | "random",
            "rewards": {
                "rorupees": int, "balls": {type: qty}, "stones": {canonical_name: qty},
                "random": {"stone"|"pokemon"|"legendary"|"nr"|"full": qty},
            },
            "limit": int | None,
            "custom_code": str | None,
            "error": str | None
        }

    Reward-type lines support a deferred-reward syntax where the content is
    NOT chosen here — only the type is recorded. The actual reward is rolled
    independently for each trainer at redemption time:
        Random              (full random: stone / pokemon / legendary / NR)
        Random Stone
        Random Pokemon
        Random Legendary
        Random NR
    Each of the above may optionally take a leading quantity, e.g.
    "3 Random NR" rolls three independent NR amounts. Note this "Random" is
    distinct from the mode line on line 1 (Fix/Random code-naming mode) —
    they can both appear in the same code body since the mode line is only
    ever lines[0].
    """
    result = {
        "mode": None,
        "rewards": {"rorupees": 0, "balls": {}, "stones": {}, "random": {}},
        "limit": None,
        "custom_code": None,
        "error": None,
    }

    lines = [ln.strip() for ln in full_text.strip().splitlines() if ln.strip()]
    if not lines:
        result["error"] = "❌ Empty command body."
        return result

    # First line is mode
    mode_line = lines[0].lower()
    if mode_line == "fix":
        result["mode"] = "fix"
    elif mode_line == "random":
        result["mode"] = "random"
    else:
        result["error"] = "❌ First line must be `Fix` or `Random`."
        return result

    for line in lines[1:]:
        line_lower = line.lower()

        # Limit line: "Limit 15"
        if line_lower.startswith("limit"):
            parts = line_lower.split()
            if len(parts) >= 2 and parts[1].isdigit():
                val = int(parts[1])
                if val <= 0:
                    result["error"] = "❌ Limit must be a positive number."
                    return result
                result["limit"] = val
            else:
                result["error"] = "❌ Invalid Limit format. Use: Limit <number>"
                return result
            continue

        # Custom code line: "code: STARTER"
        if line_lower.startswith("code:"):
            code_val = line.split(":", 1)[1].strip().upper()
            if not code_val or not code_val.isalnum():
                result["error"] = "❌ Invalid code format. Code must be alphanumeric."
                return result
            result["custom_code"] = code_val
            continue

        # Deferred-reward lines: "Random", "Random Stone", "Random Pokemon",
        # "Random Legendary", "Random NR" — optional leading quantity, default 1.
        # Must be checked before the generic "<qty> <item>" regex below since a
        # bare "Random Stone" line has no leading digit at all.
        import re
        m_random = re.match(
            r"^(?:(\d+)\s+)?random(?:\s+(stone|pok[eé]mon|legendary|nr|rorupees?))?$",
            line_lower,
        )
        if m_random:
            qty = int(m_random.group(1)) if m_random.group(1) else 1
            if qty <= 0:
                result["error"] = "❌ Invalid quantity for a Random reward. Must be positive."
                return result
            subtype_raw = m_random.group(2)
            if subtype_raw is None:
                subtype = "full"
            elif subtype_raw in ("pokemon", "pokémon"):
                subtype = "pokemon"
            elif subtype_raw in ("nr", "rorupee", "rorupees"):
                subtype = "nr"
            else:
                subtype = subtype_raw  # "stone" or "legendary"
            result["rewards"]["random"][subtype] = result["rewards"]["random"].get(subtype, 0) + qty
            continue

        # Reward lines: "<qty> <item>"
        import re
        m = re.match(r"^(\d+)\s+(.+)$", line_lower)
        if m:
            qty = int(m.group(1))
            item_raw = m.group(2).strip()

            if qty <= 0:
                result["error"] = f"❌ Invalid quantity for '{item_raw}'. Must be positive."
                return result

            # Check RoRupees
            if "rorupee" in item_raw:
                result["rewards"]["rorupees"] += qty
                continue

            # Normalize "master ball" / "master balls" to the ITEM_DB_COLS key "master"
            if item_raw in ("master ball", "master balls"):
                item_raw = "master"

            # Check if it's a ball type
            if item_raw in ITEM_DB_COLS:
                result["rewards"]["balls"][item_raw] = result["rewards"]["balls"].get(item_raw, 0) + qty
                continue

            # Check if it's a stone (supports multi-word, X/Y variants, plurals)
            normalized_stone = _normalize_stone_input(item_raw)
            canonical = STONE_NAME_MAP.get(normalized_stone)
            # Fallback: also try the raw value in case it was already canonical
            if not canonical:
                canonical = STONE_NAME_MAP.get(item_raw)
            if canonical:
                result["rewards"]["stones"][canonical] = result["rewards"]["stones"].get(canonical, 0) + qty
                continue

            # Unknown item — skip silently (flexible parser)
            logger.warning(f"gencode parser: unrecognized item '{item_raw}' — skipping")
            continue

    # Validation
    if not any([
        result["rewards"]["rorupees"],
        result["rewards"]["balls"],
        result["rewards"]["stones"],
        result["rewards"]["random"],
    ]):
        result["error"] = "❌ No valid rewards found. Add balls, stones, RoRupees, or a Random reward type."
        return result

    if result["mode"] == "fix" and not result["custom_code"]:
        result["error"] = "❌ Fix mode requires a `code: <CODE>` line."
        return result

    return result


def build_gencode_success_msg(code: str, rewards: dict, limit) -> str:
    """Builds the HTML success message after a code is created."""
    lines = [f"Redeem code created: <code>{code}</code>\n"]
    if rewards["rorupees"]:
        lines.append(f"RoRupees: <b>{rewards['rorupees']:,}</b>")
    for ball_type, qty in rewards["balls"].items():
        lines.append(f"Ball: <b>{qty}x {BALL_DISPLAY.get(ball_type, ball_type.capitalize())}</b>")
    for stone_name, qty in rewards["stones"].items():
        stone_str = stone_name + (f" x{qty}" if qty > 1 else "")
        lines.append(f"Stone: <b>{stone_str}</b>")
    _random_labels = {
        "stone": "Random Stone", "pokemon": "Random Pokemon",
        "legendary": "Random Legendary", "nr": "Random NR", "full": "Random",
    }
    for subtype, qty in rewards.get("random", {}).items():
        label = _random_labels.get(subtype, subtype.capitalize())
        qty_str = f" x{qty}" if qty > 1 else ""
        lines.append(f"Reward Type: <b>{label}{qty_str}</b> <i>(rolled per trainer at redemption)</i>")
    lines.append(f"Limit: <b>{limit if limit else 'Unlimited'}</b>")
    return "\n".join(lines)


def build_redeem_success_msg(code: str, rewards: dict, random_lines: list[str] | None = None) -> str:
    """Builds the reward delivery message shown to the trainer.

    random_lines: pre-formatted HTML lines describing any deferred 'Random ...'
    rewards already resolved for this specific trainer (see
    _gencode_resolve_random_rewards), appended after the fixed rewards.
    """
    lines = ["🎉 Redeem Successful!\n", f"Code: {code}\n"]
    if rewards["rorupees"]:
        lines.append(f"💰 +{rewards['rorupees']:,} RoRupees")
    for ball_type, qty in rewards["balls"].items():
        emoji = BALL_EMOJIS.get(ball_type, "🎯")
        lines.append(f"{emoji} +{qty} {BALL_DISPLAY.get(ball_type, ball_type.capitalize())}")
    for stone_name, qty in rewards["stones"].items():
        lines.append(f" +{qty} {stone_name}")
    if random_lines:
        lines.extend(random_lines)
    return "\n".join(lines)


async def gencode(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Head-admin-only command to create a redeem code."""
    user = update.effective_user

    if user.id not in HEAD_ADMIN_IDS:
        # Silent — don't reveal the command exists to non-head-admins
        return

    # The full message text includes "/gencode\n..." — strip the first line
    full_text = update.message.text or ""
    # Remove the command line itself
    body = "\n".join(full_text.splitlines()[1:]).strip()

    if not body:
        await update.message.reply_text(
            "Usage:\n/gencode\nFix or Random\n10 great\n5000 RoRupees\nLimit 10\ncode: MYCODE  ← (Fix only)"
        )
        return

    parsed = parse_gencode_text(body)

    if parsed["error"]:
        await update.message.reply_text(parsed["error"])
        return

    mode = parsed["mode"]
    rewards = parsed["rewards"]
    limit = parsed["limit"]

    # Determine the code
    overwrite_existing = False  # whether to UPDATE instead of INSERT
    if mode == "fix":
        code = parsed["custom_code"]
        # Allow reuse only if the existing code's limit is exhausted
        conn = sqlite3.connect("ZNX.db")
        cursor = conn.cursor()
        cursor.execute("SELECT usage_count, usage_limit FROM redeem_codes WHERE code = ?", (code,))
        existing = cursor.fetchone()
        conn.close()
        if existing:
            usage_count, usage_limit = existing
            if usage_limit is None or usage_count < usage_limit:
                await update.message.reply_text(
                    f"❌ Code <code>{code}</code> already exists and is still active. Choose a different code.",
                    parse_mode="HTML"
                )
                return
            overwrite_existing = True  # limit reached — safe to overwrite
    else:
        # Generate random code; reuse one whose limit is exhausted, otherwise find a fresh one
        conn = sqlite3.connect("ZNX.db")
        cursor = conn.cursor()
        code = None
        for _ in range(20):  # retry up to 20 times
            candidate = generate_random_code()
            cursor.execute("SELECT usage_count, usage_limit FROM redeem_codes WHERE code = ?", (candidate,))
            row = cursor.fetchone()
            if not row:
                code = candidate  # brand-new code
                break
            usage_count, usage_limit = row
            if usage_limit is not None and usage_count >= usage_limit:
                code = candidate  # limit exhausted — safe to reuse
                overwrite_existing = True
                break
            # Code exists and still active — try another candidate
        conn.close()
        if code is None:
            await update.message.reply_text("❌ Failed to generate a unique code. Please try again.")
            return

    # Save to DB
    rewards_json = json.dumps(rewards)
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    if overwrite_existing:
        cursor.execute(
            "UPDATE redeem_codes SET rewards = ?, usage_count = 0, usage_limit = ?, created_by = ?, created_at = ? WHERE code = ?",
            (rewards_json, limit, user.id, int(time.time()), code)
        )
    else:
        cursor.execute(
            "INSERT INTO redeem_codes (code, rewards, usage_count, usage_limit, created_by, created_at) VALUES (?, ?, 0, ?, ?, ?)",
            (code, rewards_json, limit, user.id, int(time.time()))
        )
    conn.commit()
    conn.close()

    msg = build_gencode_success_msg(code, rewards, limit)
    await update.message.reply_text(msg, parse_mode="HTML")


async def redeem_code(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Trainer command: /redeem <CODE>"""
    user = update.effective_user

    # Must be registered
    profile = get_user(user.id)
    if profile is None:
        await update.message.reply_text("You haven't registered yet! Type /start to begin your journey.")
        return

    if not context.args:
        await update.message.reply_text("Usage: /redeem <code>\nExample: /redeem STARTER")
        return

    code_input = context.args[0].strip().upper()

    # Validate format
    if not code_input.isalnum():
        await update.message.reply_text("❌ Invalid code format.")
        return

    conn = get_db("ZNX.db")
    cursor = conn.cursor()

    # Look up code
    cursor.execute(
        "SELECT rewards, usage_count, usage_limit FROM redeem_codes WHERE code = ?",
        (code_input,)
    )
    code_row = cursor.fetchone()

    if not code_row:
        await update.message.reply_text("❌ Invalid redeem code.")
        return

    rewards_json, usage_count, usage_limit = code_row
    rewards = json.loads(rewards_json)

    # Check usage limit
    if usage_limit is not None and usage_count >= usage_limit:
        await update.message.reply_text("❌ This redeem code has reached its usage limit.")
        return

    # Check duplicate claim
    cursor.execute(
        "SELECT 1 FROM redeem_claims WHERE user_id = ? AND code = ?",
        (user.id, code_input)
    )
    if cursor.fetchone():
        await update.message.reply_text("❌ You already redeemed this code.")
        return

    # ── Deliver rewards ──────────────────────────────────────────────────────

    # RoRupees + Balls: both live on `users`, so both go through the cache
    # via one atomic increment_user() call (rather than one UPDATE per item
    # like before) — still a single, non-yielding step.
    users_deltas = {}
    if rewards.get("rorupees", 0) > 0:
        users_deltas["nova_rupee"] = rewards["rorupees"]

    for ball_type, qty in rewards.get("balls", {}).items():
        db_col = ITEM_DB_COLS.get(ball_type)
        if db_col and qty > 0:
            users_deltas[db_col] = users_deltas.get(db_col, 0) + qty

    if users_deltas:
        increment_user(user.id, **users_deltas)

    # Stones
    for stone_name, qty in rewards.get("stones", {}).items():
        if qty > 0:
            cursor.execute(
                """
                INSERT INTO user_stones (user_id, stone_name, quantity)
                VALUES (?, ?, ?)
                ON CONFLICT(user_id, stone_name) DO UPDATE SET quantity = quantity + excluded.quantity
                """,
                (user.id, stone_name, qty)
            )

    # Random rewards — resolved fresh for THIS trainer right now, independently
    # of whatever any other trainer who redeemed the same code received.
    random_lines: list[str] = []
    random_spec = rewards.get("random")
    if random_spec:
        random_lines = await _gencode_resolve_random_rewards(random_spec, user.id, cursor)

    # Record claim and increment usage
    cursor.execute(
        "INSERT INTO redeem_claims (user_id, code) VALUES (?, ?)",
        (user.id, code_input)
    )
    cursor.execute(
        "UPDATE redeem_codes SET usage_count = usage_count + 1 WHERE code = ?",
        (code_input,)
    )

    conn.commit()

    msg = build_redeem_success_msg(code_input, rewards, random_lines)
    await update.message.reply_text(msg, parse_mode="HTML")


# ════════════════════════════════════ DAILY REWARDS SYSTEM ════════════════════════════════════
# Reset schedule is shared with Safari Zone: 05:30 IST / 00:00 UTC (_safari_reset_date()).
DAILY_REWARD_RORUPEES   = 300
DAILY_REWARD_REGULARBALLS = 10
DAILY_REWARD_GREATBALLS   = 5
DAILY_REWARD_ULTRABALLS   = 1


async def daily_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """/daily — Claim once-per-reset-cycle daily rewards.
    Uses the exact same reset schedule as Safari Zone (05:30 IST / 00:00 UTC)."""
    user = update.effective_user

    if not is_registered(user.id):
        await update.message.reply_text("You haven't registered yet! Type /start to begin your journey.")
        return

    today = _safari_reset_date()

    profile = get_user(user.id)

    # Cooldown — already claimed this reset cycle. Checking + claiming here
    # is one non-yielding block (no await between the check and the write
    # below), so this can't double-grant even if two /daily presses land
    # back-to-back for the same trainer.
    if (profile.get("last_daily_claim") or "") == today:
        await update.message.reply_text(
            "<b>You have already claimed today's Daily Reward.</b>\n\n"
            "<i>Come back after the next reset.</i>",
            parse_mode="HTML"
        )
        return

    # Grant rewards and record the claim atomically
    increment_user(
        user.id,
        nova_rupee=DAILY_REWARD_RORUPEES,
        pokeballs=DAILY_REWARD_REGULARBALLS,
        greatballs=DAILY_REWARD_GREATBALLS,
        ultraballs=DAILY_REWARD_ULTRABALLS,
    )
    update_user(user.id, last_daily_claim=today)

    await update.message.reply_text(
        "<b><u>Your Daily Rewards</u></b>\n\n"
        f"{DAILY_REWARD_RORUPEES} RoRupees\n"
        f"{DAILY_REWARD_REGULARBALLS} Regular Balls\n"
        f"{DAILY_REWARD_GREATBALLS} Great Balls\n"
        f"{DAILY_REWARD_ULTRABALLS} Ultra Ball\n\n"
        "<i>Your Next Reset: Midnight UTC</i>",
        parse_mode="HTML"
    )


async def list_codes(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Hidden head-admin-only command: /codes — lists all generated redeem codes."""
    user = update.effective_user

    # Silently ignore anyone who is not a head admin
    if user.id not in HEAD_ADMIN_IDS:
        return

    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        "SELECT code, usage_count, usage_limit, rewards, created_at FROM redeem_codes ORDER BY created_at DESC"
    )
    rows = cursor.fetchall()
    conn.close()

    if not rows:
        await update.message.reply_text("📋 No redeem codes found.")
        return

    lines = ["📋 <b>All Redeem Codes</b>\n"]
    for code, usage_count, usage_limit, rewards_json, created_at in rows:
        # Usage display
        if usage_limit is None:
            usage_str = f"{usage_count}/∞"
            status = "🟢 Active"
        elif usage_count >= usage_limit:
            usage_str = f"{usage_count}/{usage_limit}"
            status = "🔴 Exhausted"
        else:
            usage_str = f"{usage_count}/{usage_limit}"
            status = "🟢 Active"

        # Created date
        try:
            dt = datetime.fromtimestamp(created_at, tz=timezone.utc).strftime("%Y-%m-%d")
        except Exception:
            dt = "N/A"

        # Rewards summary
        try:
            rewards = json.loads(rewards_json)
            reward_parts = []
            if rewards.get("rorupees", 0):
                reward_parts.append(f"{rewards['rorupees']:,} NR")
            for ball_type, qty in rewards.get("balls", {}).items():
                reward_parts.append(f"{qty}x {BALL_DISPLAY.get(ball_type, ball_type)}")
            for stone_name, qty in rewards.get("stones", {}).items():
                reward_parts.append(f"{qty}x {stone_name}")
            _random_labels = {
                "stone": "Random Stone", "pokemon": "Random Pokemon",
                "legendary": "Random Legendary", "nr": "Random NR", "full": "Random",
            }
            for subtype, qty in rewards.get("random", {}).items():
                label = _random_labels.get(subtype, subtype.capitalize())
                reward_parts.append(f"{qty}x {label}" if qty > 1 else label)
            rewards_str = ", ".join(reward_parts) if reward_parts else "—"
        except Exception:
            rewards_str = "—"

        lines.append(
            f"<code>{code}</code> | {status}\n"
            f"  Used: {usage_str} | Date: {dt}\n"
            f"  Rewards: {rewards_str}"
        )

    # Telegram message limit guard: split into chunks if needed
    full_text = "\n\n".join(lines)
    CHUNK_SIZE = 4000
    for i in range(0, len(full_text), CHUNK_SIZE):
        await update.message.reply_text(full_text[i:i + CHUNK_SIZE], parse_mode="HTML")


async def rmcode(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Hidden head-admin-only command: /rmcode <CODE> — forcefully expires an active code."""
    user = update.effective_user

    # Silently ignore anyone who is not a head admin
    if user.id not in HEAD_ADMIN_IDS:
        return

    if not context.args:
        await update.message.reply_text("Usage: /rmcode <CODE>\nExample: /rmcode STARTER7")
        return

    code_input = context.args[0].strip().upper()

    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        "SELECT usage_count, usage_limit FROM redeem_codes WHERE code = ?",
        (code_input,)
    )
    row = cursor.fetchone()

    if not row:
        conn.close()
        await update.message.reply_text(f"❌ Code <code>{code_input}</code> does not exist.", parse_mode="HTML")
        return

    usage_count, usage_limit = row

    # Only allow expiring codes that are still active:
    #   - Infinite limit (usage_limit IS NULL), OR
    #   - Limit not yet reached (usage_count < usage_limit)
    if usage_limit is not None and usage_count >= usage_limit:
        conn.close()
        await update.message.reply_text(
            f"⚠️ Code <code>{code_input}</code> is already exhausted (used {usage_count}/{usage_limit}).\n"
            f"It cannot be expired again.",
            parse_mode="HTML"
        )
        return

    # Expire the code by setting usage_limit = usage_count
    # This makes usage_count >= usage_limit, so the code is immediately unusable
    # while preserving the claims history intact
    new_limit = usage_count if usage_count > 0 else 0
    cursor.execute(
        "UPDATE redeem_codes SET usage_limit = ? WHERE code = ?",
        (new_limit, code_input)
    )
    conn.commit()
    conn.close()

    limit_label = "∞ (infinite)" if usage_limit is None else str(usage_limit)
    await update.message.reply_text(
        f"✅ Code <code>{code_input}</code> has been expired.\n"
        f"Previous limit: <b>{limit_label}</b> | Times used: <b>{usage_count}</b>\n"
        f"The code can no longer be redeemed.",
        parse_mode="HTML"
    )


