async def ping_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """/ping — measure real Telegram round-trip latency.

    Times an actual Telegram API call (sending a message) rather than
    comparing two immediate perf_counter() calls or relying on message
    timestamps, since neither reflects real network/API latency.
    """
    start_time = time.perf_counter()
    sent_message = await update.message.reply_text("🏓 Pinging...")
    elapsed_time = time.perf_counter() - start_time
    latency_ms = round(elapsed_time * 1000, 2)
    try:
        await sent_message.edit_text(f"🏓 Pong! {latency_ms:.2f}ms")
    except Exception:
        pass


