# Eligible Mega Stones for the Starter Kit random reward.
# Sourced from MEGA_STONE_COMMANDS display names, excluding:
#   • Jade Orb (Rayquaza transformation — handled separately)
#   • Stones for legendary / mythical Pokémon (Mewtwo, Latias, Latios,
#     Diancie, Darkrai, Heatran, Zeraora, Zygarde)
#   • All SPECIAL_TRANSFORMATION_ITEMS (Orbs, Rusted items, Carrots, etc.)
_STARTERKIT_EXCLUDED_COMMAND_KEYS = {
    # Rayquaza transformation item (listed in MEGA_STONE_COMMANDS)
    "jade_orb",
    # Legendary stones
    "mewtwonite", "mewtwonite_x", "mewtwonite_y",  # Mewtwo
    "latiasite",                                     # Latias
    "latiosite",                                     # Latios
    "diancite",                                      # Diancie (mythical)
    "darkranite",                                    # Darkrai (mythical)
    "heatranite",                                    # Heatran (legendary)
    "zeraorite",                                     # Zeraora (mythical)
    "zygardite",                                     # Zygarde (legendary)
}


def _starterkit_eligible_stones() -> list[str]:
    """
    Return a sorted list of unique Mega Stone display names that are eligible
    as Starter Kit rewards (non-legendary, non-mythical, non-transformation).
    """
    seen: set[str] = set()
    result: list[str] = []
    for cmd_key, (display_name, _pokemon, _mega_name) in sorted(MEGA_STONE_COMMANDS.items()):
        if cmd_key in _STARTERKIT_EXCLUDED_COMMAND_KEYS:
            continue
        if display_name not in seen:
            seen.add(display_name)
            result.append(display_name)
    return result


async def starterkit_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """/starterkit — claim a one-time Welcome Starter Kit."""
    user = update.effective_user
    msg  = update.message
    if not msg:
        return

    # Must be registered
    if not is_registered(user.id):
        await msg.reply_text(
            "⚠️ Please send your trainer name first before using the bot."
        )
        return

    # ── Atomic claim: check-and-set as one non-yielding in-memory step ────────
    profile = get_user(user.id)
    if profile is None:
        await msg.reply_text("❌ Could not find your trainer data. Try /start first.")
        return

    already_claimed = profile.get("starterkit_claimed")
    if already_claimed:
        await msg.reply_text(
            "<b>You have already claimed your Starter Kit!</b>",
            parse_mode="HTML"
        )
        return

    # ── Pick random Mega Stone ────────────────────────────────────────────
    eligible = _starterkit_eligible_stones()
    if not eligible:
        await msg.reply_text("❌ No eligible Mega Stones available. Please contact an admin.")
        return
    chosen_stone = random.choice(eligible)

    # ── Grant all rewards atomically ──────────────────────────────────────
    # The `users` side (balls/currency/claimed-flag) is a single in-memory
    # dict mutation — it either fully applies or, if get_user() above had
    # returned None, never started; there's no partial state to roll back.
    # Only the user_stones INSERT is real SQL that can actually fail, so
    # that's what the try/except below guards.
    increment_user(
        user.id,
        pokeballs=50,
        greatballs=40,
        ultraballs=30,
        repeatballs=20,
        nestballs=10,
        master_ball=1,
        nova_rupee=5000,
    )
    update_user(user.id, starterkit_claimed=1)
    try:
        conn = get_db("ZNX.db")
        conn.execute(
            """INSERT INTO user_stones (user_id, stone_name, quantity)
               VALUES (?, ?, 1)
               ON CONFLICT(user_id, stone_name)
               DO UPDATE SET quantity = quantity + 1""",
            (user.id, chosen_stone)
        )
        conn.commit()
    except Exception as _e:
        logger.error(f"[starterkit] DB error for user {user.id}: {_e}")
        await msg.reply_text("❌ An error occurred. Please try again later.")
        return

    # ── Build and send the caption ────────────────────────────────────────────
    caption = (
        "✨ <b>Pokémon Ro — Welcome, Trainer!</b>\n\n"
        "🎉 <b>Your adventure begins today!</b>\n\n"
        "<i>Professor Orion has prepared a special Starter Kit just for you.</i>\n\n"
        "🎁 <b><i>Starter Rewards</i></b>\n\n"
        "<b>Regular Ball</b> × 50\n"
        "<b>Great Ball</b> × 40\n"
        "<b>Ultra Ball</b> × 30\n"
        "<b>Repeat Ball</b> × 20\n"
        "<b>Nest Ball</b> × 10\n"
        "<b>Master Ball</b> × 1\n\n"
        "💶 <b>RoRupéé</b> × 5,000\n"
        f"✨ <b>{chosen_stone}</b> × 1\n\n"
        "━━━━━━━━━━━━━━━━━━━━━━\n\n"
        "🌟 <b>Claim Complete!</b>\n\n"
        "<i>May your Pokédex grow, your battles be victorious, and your journey become legendary.</i>\n\n"
        "✨ <blockquote>Good luck, Trainer!</blockquote>"
    )

    image_url = "https://iili.io/CRpXFqJ.jpg"
    try:
        await msg.reply_photo(
            photo=image_url,
            caption=caption,
            parse_mode="HTML"
        )
    except Exception:
        # Fallback: send as text if photo fails
        try:
            await msg.reply_text(caption, parse_mode="HTML")
        except Exception as _e2:
            logger.error(f"[starterkit] Failed to send message to {user.id}: {_e2}")


