async def shutdown_flush_hook(application: Application) -> None:
    """post_shutdown callback: final USER_CACHE flush on any clean bot stop
    (Ctrl+C, SIGTERM/redeploy, admin /restart). See flush_user_cache_on_shutdown()
    and the cache_flush_loop() docstring above for the full data-loss-bound
    reasoning. Deliberately does not raise — a flush failure here shouldn't
    prevent the process from actually exiting."""
    try:
        await flush_user_cache_on_shutdown()
    except Exception as e:
        logger.error(f"[USER CACHE] shutdown_flush_hook failed: {e}")
    # Final Turso push so a redeploy/restart never loses writes.
    if _turso_sync is not None:
        try:
            _turso_sync.push_all_safe()
        except Exception:
            pass

# ════════════════════════════════════ QUERY / FEEDBACK SYSTEM ════════════════════════════════════

def _as_chat_id(raw, fallback=None):
    if raw is None or str(raw).strip() == "":
        return fallback
    s = str(raw).strip()
    if s.lstrip("-").isdigit():
        return int(s)
    return s  # @username; invite links can't be used directly


QUERY_ADMIN_GC = _as_chat_id(
    _env_chat("QUERY_ADMIN_GC"),
    (OWNER_IDS[0] if OWNER_IDS else None),
)


async def query_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """/query <text> — submit a bug report or feature request to the admin team."""
    user = update.effective_user
    if not user:
        return
    reg = is_registered(user.id)
    if not reg:
        await update.message.reply_text("❌ You are not registered yet. Use /start to begin.")
        return
    trainer_name = reg[0] or str(user.id)

    if not context.args:
        await update.message.reply_text("Usage: /query <your query or bug report>")
        return

    query_text = " ".join(context.args)

    conn = sqlite3.connect("ZNX.db")
    cur = conn.cursor()
    cur.execute("SELECT COUNT(*) FROM queries")
    count = (cur.fetchone()[0] or 0) + 1
    query_id = f"Q{count:04d}"
    uname = f"@{user.username}" if user.username else "N/A"
    cur.execute(
        "INSERT INTO queries (query_id, user_id, username, trainer_name, query_text, created_at) VALUES (?,?,?,?,?,?)",
        (query_id, user.id, uname, trainer_name, query_text, int(time.time()))
    )
    conn.commit()
    conn.close()

    await update.message.reply_text(
        f"Query <b>{query_id}</b> submitted!\n\nWe'll get back to you soon.",
        parse_mode="HTML"
    )

    try:
        await context.bot.send_message(
            chat_id=QUERY_ADMIN_GC,
            text=(
                f"?? New Query\n\n"
                f"ID: {query_id}\n\n"
                f"User:\n{trainer_name}\n\n"
                f"Username:\n{uname}\n\n"
                f"User ID:\n{user.id}\n\n"
                f"Query:\n{query_text}"
            )
        )
    except Exception as e:
        logger.warning(f"[query] Failed to notify admin GC: {e}")


# ── Safari session restore cache ──────────────────────────────────────────────
# Populated at bot startup from the database; entries are consumed lazily the
# first time a user sends any message/callback after a restart.  This is the
# PTB-safe way to restore per-user context.user_data without a post_init hook.
_SAFARI_RESTORE_CACHE: dict[int, dict] = {}

def _safari_populate_restore_cache() -> None:
    """Load all active Safari sessions from DB into the in-memory restore cache.
    Called once at startup (inside main() after init_db()).  Subsequent restores
    are lazy — _safari_maybe_restore() injects the data into context.user_data
    the first time an affected user triggers any handler."""
    sessions = _safari_session_load_all_active()
    for s in sessions:
        _SAFARI_RESTORE_CACHE[s["user_id"]] = {
            "region":     s["region"],
            "balls":      s["balls"],
            "hunt_count": s["hunt_count"],
        }
    if sessions:
        logger.info(
            f"[SAFARI RESTORE] Loaded {len(sessions)} active Safari session(s) from DB: "
            + ", ".join(str(s["user_id"]) for s in sessions)
        )

def _safari_maybe_restore(user_id: int, context) -> None:
    """Lazily restore a persisted Safari session into context.user_data.
    Called at the top of every Safari-aware handler.  Does nothing if the
    session is already active or if there is no stored session for this user."""
    if context.user_data.get("safari_active"):
        return   # already active — nothing to do
    session = _SAFARI_RESTORE_CACHE.pop(user_id, None)
    if session is None:
        # Cache miss — check DB directly (handles the case where the cache was
        # populated before this user's entry was inserted, e.g. edge cases)
        session = _safari_session_restore_for_user(user_id)
    if session is None:
        return
    # Restore session into context.user_data
    context.user_data["safari_active"]     = True
    context.user_data["safari_region"]     = session["region"]
    context.user_data["safari_balls"]      = session["balls"]
    context.user_data["safari_hunt_count"] = session["hunt_count"]
    context.user_data["safari_encounter"]  = None
    logger.info(
        f"[SAFARI RESTORE] Restored session for user {user_id}: "
        f"region={session['region']}, balls={session['balls']}, "
        f"hunts={session['hunt_count']}/{SAFARI_HUNT_LIMIT}"
    )


def _clear_safari_state(context, user_id: int | None = None) -> None:
    """Ends the active Safari session but preserves the daily-use stamp in the DB.
    The persistent DB record (safari_last_cycle / safari_daily_used) keeps the
    trainer locked out until 05:30 IST the next day regardless of bot restarts.
    Also clears the persistent session record so the session is not restored on restart.
    Call _clear_safari_state_full() only when you want to wipe the DB record too
    (e.g. a hard admin reset)."""
    for key in ['safari_active', 'safari_region', 'safari_balls', 'safari_hunt_count',
                'safari_encounter', 'safari_in_action_menu',
                'safari_current_encounter_id']:
        context.user_data.pop(key, None)
    # Clear the persistent session so it is not re-loaded on restart
    if user_id:
        _safari_session_clear_db(user_id)


def _clear_safari_state_full(user_id: int, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Wipes ALL Safari state including the persistent DB daily-use stamp (admin/debug use)."""
    for key in ['safari_active', 'safari_region', 'safari_balls', 'safari_hunt_count',
                'safari_encounter', 'safari_in_action_menu',
                'safari_current_encounter_id']:
        context.user_data.pop(key, None)
    # Clear both the daily-use record and the active session record
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        """UPDATE users
           SET safari_last_cycle = '', safari_daily_used = 0,
               safari_session_active = 0, safari_session_region = '',
               safari_session_balls = 0, safari_session_hunt_count = 0
           WHERE user_id = ?""",
        (user_id,)
    )
    conn.commit()
    conn.close()


def _safari_spawn_pokemon(region: str) -> tuple:
    """Returns (pokemon_id, rarity) for a Safari encounter.
    Legendary rate is ~8% — much higher than the normal 1.5%."""
    pool = SAFARI_POKEMON_POOL.get(region, SAFARI_POKEMON_POOL["Kanto"])
    if random.random() < 0.20:
        rarity = "legendary"
        pkmn_id = random.choice(pool["legendary"])
    else:
        rarity = "common"
        pkmn_id = random.choice(pool["common"])
    return pkmn_id, rarity


async def _check_safari_limits(user_id: int, context: ContextTypes.DEFAULT_TYPE, query) -> None:
    """Auto-exits Safari Zone when balls run out or hunt limit is reached."""
    safari_balls = context.user_data.get('safari_balls', 0)
    hunt_count   = context.user_data.get('safari_hunt_count', 0)
    region       = context.user_data.get('safari_region', 'Unknown')

    if safari_balls <= 0:
        _safari_db_mark_used(user_id)
        _clear_safari_state(context, user_id=user_id)
        try:
            await query.message.reply_text(
                "🎒 <b>Your Safari Expedition has ended!</b>\n\n"
                "<blockquote>You have used all of your Safari Balls.</blockquote>"
                "<i>Come back after the cooldown resets to explore again!</i>",
                parse_mode="HTML"
            )
        except Exception:
            pass
        return

    if hunt_count >= SAFARI_HUNT_LIMIT:
        _clear_safari_state(context, user_id=user_id)
        try:
            await query.message.reply_text(
                f"The Safari Game has finished and you were kicked out of the "
                f"<b>{region} Safari Zone</b>.",
                parse_mode="HTML"
            )
        except Exception:
            pass


async def safari_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """/safari — Enter the Safari Zone for the trainer's current region."""
    if update.effective_chat.type != "private":
        await update.message.reply_text(
            "❌ This command only works in private chat.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("Open Bot DM", url="https://t.me/PokieNova_bot?start=cmd_safari")]])
        )
        return

    user = update.effective_user
    # Restore any persisted Safari session from DB (survives restarts/crashes)
    _safari_maybe_restore(user.id, context)

    if not is_registered(user.id):
        await update.message.reply_text("You need to register first! Use /start.")
        return

    # Already inside Safari Zone
    if context.user_data.get('safari_active'):
        region = context.user_data.get('safari_region', 'Unknown')
        balls  = context.user_data.get('safari_balls', 0)
        hunts  = context.user_data.get('safari_hunt_count', 0)
        await update.message.reply_text(
            f"You are already inside the <b>{region} Safari Zone</b>!\n\n"
            f"Safari Balls: <b>{balls}</b>\n"
            f"Hunts: <b>{hunts}/{SAFARI_HUNT_LIMIT}</b>\n\n"
            "Use /hunt to find Pokémon, or /exit to leave.",
            parse_mode="HTML"
        )
        return

    profile = get_user(user.id)
    if profile is None:
        await update.message.reply_text("You need to register first! Use /start.")
        return

    region  = profile.get("current_region") or "Kanto"
    balance = profile.get("nova_rupee") or 0

    keyboard = [[InlineKeyboardButton("Yes, Enter", callback_data=f"safari_enter_{region}_{user.id}")]]

    await update.message.reply_text(
        f"Do you want to enter the <b>{region} Safari Zone</b>?\n\n"
        f"You will receive <b>30 Safari Balls</b>.\n"
        f"Hunt Limit: 200 Hunts\n"
        f"Only Safari Zone Pokémon will appear while hunting!\n"
        f"Use /exit to leave at any time.\n\n"
        f"<b>Entry Fee</b>: {SAFARI_ENTRY_FEE} RoRupees\n"
        f"Your Balance: {balance} 💴",
        parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(keyboard)
    )


async def safari_enter_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles the [Yes, Enter] button — deducts fee and activates Safari."""
    query = update.callback_query
    user  = query.from_user

    # ── Ownership guard: format is safari_enter_{region}_{owner_id} ──────────
    raw = query.data[len("safari_enter_"):]  # e.g. "Kanto_123456789"
    parts = raw.rsplit("_", 1)
    if len(parts) == 2:
        region = parts[0]
        try:
            owner_id = int(parts[1])
            if not await validate_owner(query, owner_id):
                return
        except ValueError:
            await query.answer("This menu belongs to another trainer.", show_alert=True)
            return
    else:
        # No owner_id embedded — deny
        await query.answer("This menu belongs to another trainer.", show_alert=True)
        return
    # ─────────────────────────────────────────────────────────────────────────

    # ── Daily Safari access check (persistent — survives bot restarts) ───────
    if _safari_db_check_used(user.id):
        from datetime import datetime as _dt
        now_ist = _dt.now(IST)
        # Calculate next reset time
        next_reset = now_ist.replace(hour=5, minute=30, second=0, microsecond=0)
        if now_ist >= next_reset:
            next_reset = next_reset + timedelta(days=1)
        time_left = next_reset - now_ist
        hours_left, rem = divmod(int(time_left.total_seconds()), 3600)
        mins_left = rem // 60
        await query.answer(
            f"You already visited the Safari Zone today!\nCome back after the daily reset.\nNext reset: {hours_left}h {mins_left}m",
            show_alert=True
        )
        return
    # ── end daily check ──────────────────────────────────────────────────────

    profile = get_user(user.id)

    if profile is None:
        await query.answer("Could not find your trainer data.", show_alert=True)
        return

    balance = profile.get("nova_rupee") or 0

    if balance < SAFARI_ENTRY_FEE:
        await query.answer(
            f"Not enough RoRupees! You need {SAFARI_ENTRY_FEE} 💴.",
            show_alert=True
        )
        return

    new_balance = balance - SAFARI_ENTRY_FEE
    update_user(user.id, nova_rupee=new_balance)

    context.user_data['safari_active']       = True
    context.user_data['safari_region']       = region
    context.user_data['safari_balls']        = SAFARI_BALL_COUNT
    context.user_data['safari_hunt_count']   = 0
    context.user_data['safari_encounter']    = None
    # Persistently mark today's Safari visit so it survives bot/VPS restarts
    _safari_db_mark_used(user.id)
    # Persistently save the active session so it is restored if the bot restarts
    _safari_session_save(user.id, context)

    await query.edit_message_text(
        f"You entered the <b>{region} Safari Zone</b>!\n\n"
        f"You received <b>30 Safari Balls</b>.\n"
        f"-{SAFARI_ENTRY_FEE} RoRupees\n"
        f"(Balance: {new_balance} 💴)\n\n"
        f"Use /hunt to find Pokémon.\n"
        f"Use /exit to leave.",
        parse_mode="HTML"
    )


async def exit_safari(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """/exit — Leave the Safari Zone."""
    if update.effective_chat.type != "private":
        return

    user = update.effective_user
    # Restore any persisted Safari session from DB (survives restarts/crashes)
    _safari_maybe_restore(user.id, context)

    if not context.user_data.get('safari_active'):
        await update.message.reply_text("You are not currently in a Safari Zone.")
        return

    region = context.user_data.get('safari_region', 'Unknown')
    user = update.effective_user
    _clear_safari_state(context, user_id=user.id)

    await update.message.reply_text(
        f"You left the <b>{region} Safari Zone</b>.\n"
        "Remaining Safari Balls have been discarded.",
        parse_mode="HTML"
    )


async def _safari_hunt_encounter(user_id: int, region: str,
                                  context: ContextTypes.DEFAULT_TYPE, message) -> None:
    """Spawns a Safari encounter when /hunt is used inside the Safari Zone."""
    safari_balls = context.user_data.get('safari_balls', 0)
    hunt_count   = context.user_data.get('safari_hunt_count', 0)

    pkmn_id, rarity = _safari_spawn_pokemon(region)
    level = random.randint(45, 70) if rarity == "legendary" else random.randint(15, 50)

    # Roll shiny at Safari spawn time (2% chance)
    is_shiny = roll_shiny()

    sprite_url   = None
    pokemon_name = "Unknown"
    poke_numeric_id = pkmn_id
    species_catch_rate = 45

    try:
        data = await _cached_pokeapi_get(f"https://pokeapi.co/api/v2/pokemon/{pkmn_id}")
        if data:
            raw_name     = data["name"]
            pokemon_name = raw_name.capitalize()
            poke_numeric_id = data["id"]
            if is_shiny:
                sprite_url = shiny_sprite_url(poke_numeric_id)
            else:
                sprite_url = data["sprites"]["other"]["official-artwork"]["front_default"]

            # Official species catch rate (PokéAPI "capture_rate"), same
            # cached lookup the regular battle system uses.
            s_data = await _cached_pokeapi_get(data["species"]["url"])
            if s_data:
                species_catch_rate = s_data.get("capture_rate", 45)
    except Exception as e:
        logger.error(f"Safari PokeAPI fetch failed: {e}")

    context.user_data['safari_encounter'] = {
        "id":         str(pkmn_id),
        "name":       pokemon_name,
        "level":      level,
        "rarity":     rarity,
        "sprite_url": sprite_url,
        "rocks":      3,
        "baits":      3,
        "catch_mod":  0.0,
        "flee_mod":   0.0,
        "shiny":      is_shiny,
        "catch_rate": species_catch_rate,
    }
    context.user_data['safari_hunt_count'] = hunt_count + 1
    # Persist updated hunt count immediately so restarts resume at correct position
    _safari_session_save(user_id, context)

    # Generate a unique encounter ID and store it as the trainer's active encounter
    encounter_id = uuid.uuid4().hex
    context.user_data['safari_current_encounter_id'] = encounter_id

    caught_indicator = " ☆" if has_caught_species(user_id, pokemon_name) else ""
    pretty_name = pokemon_name.replace('-', ' ').title()
    display = display_name_with_shiny(pretty_name, is_shiny)
    caption = (
        f"A wild <b>{display}</b> (Lv. {level}) has appeared!{caught_indicator}\n\n"
        f"/hunt limit: <b>{hunt_count + 1}/{SAFARI_HUNT_LIMIT}</b>\n"
        f"Safari Balls remaining: <b>{safari_balls}</b>"
    )

    keyboard = [[InlineKeyboardButton("Catch", callback_data=f"safari_catch_menu_{encounter_id}")]]

    if sprite_url:
        await context.bot.send_photo(
            chat_id=message.chat_id,
            photo=sprite_url,
            caption=caption,
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup(keyboard)
        )
    else:
        await message.reply_text(caption, parse_mode="HTML",
                                 reply_markup=InlineKeyboardMarkup(keyboard))

    # ── Anti-Bot CAPTCHA: count this successful hunt too ─────────────────────
    # Safari Zone encounters are spawned by the same /hunt command — just
    # routed through this branch instead of the normal wild-encounter path in
    # _hunt_inner — so they must feed the same per-trainer counter. Before this
    # fix, a trainer could run an entire Safari session (up to
    # SAFARI_HUNT_LIMIT successful hunts) with zero CAPTCHA risk, which is
    # exactly the kind of gap that makes the CAPTCHA feel inconsistent.
    await _captcha_register_hunt(user_id, context, message.chat_id)


async def safari_catch_menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Shows the Safari action menu (Rock / Bait / Catch / Run).
    Sets safari_in_action_menu so /hunt is blocked until the encounter ends."""
    query = update.callback_query

    if not context.user_data.get('safari_active'):
        await query.answer("This menu belongs to another trainer.", show_alert=True)
        return

    enc = context.user_data.get('safari_encounter')
    if not enc:
        await query.answer("Pokémon already fled!", show_alert=True)
        return

    # ── Encounter ID validation ──────────────────────────────────────────────
    # Callback data format: safari_catch_menu_{encounter_id}
    callback_data    = query.data  # e.g. "safari_catch_menu_abc123..."
    prefix           = "safari_catch_menu_"
    callback_enc_id  = callback_data[len(prefix):] if callback_data.startswith(prefix) else None
    active_enc_id    = context.user_data.get('safari_current_encounter_id')

    if not callback_enc_id or callback_enc_id != active_enc_id:
        await query.answer("Pokémon already fled!", show_alert=True)
        return
    # ── end validation ───────────────────────────────────────────────────────


    # Trainer has now entered the action menu — block /hunt until this ends
    context.user_data['safari_in_action_menu'] = True
    safari_balls = context.user_data.get('safari_balls', 0)
    rocks  = enc.get('rocks', 0)
    baits  = enc.get('baits', 0)

    keyboard = [
        [
            InlineKeyboardButton(f"Throw Rock ({rocks})",  callback_data="safari_rock"),
            InlineKeyboardButton(f"Throw Bait ({baits})",  callback_data="safari_bait"),
        ],
        [
            InlineKeyboardButton("Catch", callback_data="safari_throw_ball"),
            InlineKeyboardButton("Run",   callback_data="safari_run"),
        ],
    ]

    await query.edit_message_caption(
        caption=(
            f"Choose an action for <b>{enc['name']}</b>.\n\n"
            f"Safari Balls: <b>{safari_balls}</b>"
        ),
        parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(keyboard)
    )


async def safari_rock_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Throw Rock — raises catch chance AND flee rate; 30% instant flee."""
    query = update.callback_query

    enc = context.user_data.get('safari_encounter')
    if not enc:
        await query.answer("This menu belongs to another trainer.", show_alert=True)
        return

    if enc.get('rocks', 0) <= 0:
        await query.answer("No rocks left!", show_alert=True)
        return

    enc['rocks']     -= 1
    enc['catch_mod']  = enc.get('catch_mod', 0.0) + 0.20
    enc['flee_mod']   = enc.get('flee_mod',  0.0) + 0.30
    context.user_data['safari_encounter'] = enc

    safari_balls = context.user_data.get('safari_balls', 0)

    # 30% chance of immediate flee
    if random.random() < 0.30:
        context.user_data['safari_encounter'] = None
        context.user_data['safari_in_action_menu'] = False
        context.user_data.pop('safari_current_encounter_id', None)
        await query.edit_message_caption(
            caption=f"🪨 You threw a Rock!\n<b>{enc['name']}</b> got angry and fled!",
            parse_mode="HTML"
        )
        return

    rocks_left = enc['rocks']
    baits_left = enc.get('baits', 0)

    keyboard = [
        [
            InlineKeyboardButton(f"Throw Rock ({rocks_left})", callback_data="safari_rock"),
            InlineKeyboardButton(f"Throw Bait ({baits_left})", callback_data="safari_bait"),
        ],
        [
            InlineKeyboardButton("Catch", callback_data="safari_throw_ball"),
            InlineKeyboardButton("Run",   callback_data="safari_run"),
        ],
    ]

    await query.edit_message_caption(
        caption=(
            f"🪨 You threw a Rock!\n"
            f"<b>{enc['name']}</b> became angry!\n\n"
            f"Catch ↑ | Flee chance ↑\n\n"
            f"Choose an action for <b>{enc['name']}</b>.\n\n"
            f"Safari Balls: <b>{safari_balls}</b>"
        ),
        parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(keyboard)
    )


async def safari_bait_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Throw Bait — lowers catch chance AND flee rate."""
    query = update.callback_query

