# ════════════════════════════════════ TRADE SYSTEM ════════════════════════════════════

# In-memory trade session store  { trade_id -> session_dict }
TRADE_SESSIONS: dict = {}
# Maps user_id -> trade_id so we can detect duplicate ACTIVE trade attempts quickly
# Only populated when a trade moves past the request phase (after Accept)
USER_TRADE_MAP: dict = {}
# Maps user_id -> trade_id for PENDING requests only (before Accept)
# Does not block new requests — multiple pending requests are allowed
PENDING_TRADE_MAP: dict = {}
# Timeout for a trade session (seconds)
TRADE_TIMEOUT = 600  # 10 minutes


def _new_trade_id() -> str:
    """Generates a short unique trade identifier (12-char hex)."""
    return uuid.uuid4().hex[:12]


def _expire_old_trades() -> None:
    """Removes trade sessions that have exceeded the timeout."""
    now = time.time()
    expired = [tid for tid, s in list(TRADE_SESSIONS.items())
               if now - s["created_at"] > TRADE_TIMEOUT]
    for tid in expired:
        _cancel_trade(tid)


def _cancel_trade(trade_id: str) -> None:
    """Removes a trade session and unmaps both participants from all maps."""
    session = TRADE_SESSIONS.pop(trade_id, None)
    if session:
        initiator_id = session.get("initiator_id")
        target_id    = session.get("target_id")
        USER_TRADE_MAP.pop(initiator_id, None)
        USER_TRADE_MAP.pop(target_id, None)
        PENDING_TRADE_MAP.pop(initiator_id, None)
        PENDING_TRADE_MAP.pop(target_id, None)


def _get_pokemon_by_db_id(pk_db_id: int) -> dict | None:
    """Fetches a full user_pokemon row as a dict, or None if not found."""
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        """SELECT id, user_id, pokemon_id, pokemon_name, level, exp, nature,
                  iv_hp, iv_atk, iv_def, iv_spa, iv_spd, iv_spe,
                  ev_hp, ev_atk, ev_def, ev_spa, ev_spd, ev_spe,
                  moves, is_active, boosted_stats, caught_at, COALESCE(shiny, 0),
                  COALESCE(special_tag, '')
           FROM user_pokemon WHERE id = ?""",
        (pk_db_id,),
    )
    row = cursor.fetchone()
    conn.close()
    if not row:
        return None
    keys = [
        "id", "user_id", "pokemon_id", "pokemon_name", "level", "exp", "nature",
        "iv_hp", "iv_atk", "iv_def", "iv_spa", "iv_spd", "iv_spe",
        "ev_hp", "ev_atk", "ev_def", "ev_spa", "ev_spd", "ev_spe",
        "moves", "is_active", "boosted_stats", "caught_at", "shiny", "special_tag",
    ]
    return dict(zip(keys, row))


def _get_active_squad_ids(user_id: int) -> list:
    """Returns the list of pokemon DB ids in the user's active squad."""
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        "SELECT pokemon_ids FROM user_squads WHERE user_id = ? AND is_active = 1",
        (user_id,),
    )
    row = cursor.fetchone()
    conn.close()
    if row:
        try:
            return json.loads(row[0]) or []
        except Exception:
            return []
    return []


def _count_user_pokemon(user_id: int) -> int:
    """Returns the total number of pokemon owned by a user."""
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute("SELECT COUNT(*) FROM user_pokemon WHERE user_id = ?", (user_id,))
    count = cursor.fetchone()[0]
    conn.close()
    return count


# ── Trade Pokemon Selection UI ──────────────────────────────────────────────

def _format_trade_select_text(
    trainer_name: str,
    rows: list,
    settings: dict,
    page: int,
    total: int,
) -> str:
    """Formats the pokemon selection list for a trade participant."""
    display_mode = settings["display_mode"]
    sort_mode = settings["sort_mode"]
    sort_order = settings["sort_order"]
    total_pages = math.ceil(total / ROPOKE_PAGE_SIZE) if total > 0 else 1
    offset = (page - 1) * ROPOKE_PAGE_SIZE

    sort_label = SORT_MODE_LABELS.get(sort_mode, sort_mode.title())
    sort_arrow = "▼" if sort_order == "desc" else "▲"
    display_label = DISPLAY_MODE_LABELS.get(display_mode, display_mode.title())

    lines = [f"<b>{trainer_name}</b>, select the Pokémon you want to offer:\n"]
    for i, row in enumerate(rows):
        poke_name = row[2]
        val = get_display_value(row, display_mode)
        num = offset + i + 1
        # row[18] = shiny (get_user_pokemon_page schema)
        is_shiny    = bool(row[18]) if len(row) > 18 else False
        special_tag = row[21] if len(row) > 21 and row[21] else ""
        display = display_name_with_shiny(_camp_name(row[0], poke_name), is_shiny)
        display = append_special_tag(display, special_tag)
        entry = f"{num}. <b>{display}</b>"
        if val:
            entry += f" - {val}"
        lines.append(entry)

    lines.append(
        f"\n<b>Total:</b> {total} | <b>Page:</b> {page}/{total_pages}\n"
        f"<b>Sort:</b> {sort_label} {sort_arrow} | <b>Display:</b> {display_label}"
    )
    return "\n".join(lines)


def _build_trade_select_keyboard(
    trade_id: str,
    role: str,
    rows: list,
    page: int,
    total: int,
) -> InlineKeyboardMarkup:
    """
    Builds the keyboard for pokemon selection during a trade.
    Number buttons [1]..[N] for selecting a pokemon, plus pagination.
    role is 'i' (initiator) or 't' (target).
    """
    total_pages = math.ceil(total / ROPOKE_PAGE_SIZE) if total > 0 else 1
    page = max(1, min(page, total_pages))
    offset = (page - 1) * ROPOKE_PAGE_SIZE

    # Build numbered selection buttons
    sel_buttons = []
    for i, row in enumerate(rows):
        db_id = row[0]
        num = offset + i + 1
        sel_buttons.append(
            InlineKeyboardButton(
                str(num),
                callback_data=f"trd_sel:{trade_id}:{role}:{db_id}",
            )
        )

    kbd = []
    for i in range(0, len(sel_buttons), 5):
        kbd.append(sel_buttons[i : i + 5])

    # Pagination row
    pag_row = []
    if page > 1:
        pag_row.append(
            InlineKeyboardButton("Prev", callback_data=f"trd_page:{trade_id}:{role}:{page - 1}")
        )
    pag_row.append(InlineKeyboardButton(f"{page}/{total_pages}", callback_data="trd_noop"))
    if page < total_pages:
        pag_row.append(
            InlineKeyboardButton("Next", callback_data=f"trd_page:{trade_id}:{role}:{page + 1}")
        )
    kbd.append(pag_row)

    # Fast-forward row
    ff_row = []
    if total_pages > 5:
        if page > 5:
            ff_row.append(
                InlineKeyboardButton(
                    "⏪ 5", callback_data=f"trd_page:{trade_id}:{role}:{max(1, page - 5)}"
                )
            )
        if page + 5 <= total_pages:
            ff_row.append(
                InlineKeyboardButton(
                    "5 ⏩",
                    callback_data=f"trd_page:{trade_id}:{role}:{min(page + 5, total_pages)}",
                )
            )
    if total_pages > 10 and page + 10 <= total_pages:
        ff_row.append(
            InlineKeyboardButton(
                "10 ⏭️",
                callback_data=f"trd_page:{trade_id}:{role}:{min(page + 10, total_pages)}",
            )
        )
    if ff_row:
        kbd.append(ff_row)

    # Cancel button
    kbd.append([InlineKeyboardButton("Cancel Trade", callback_data=f"trd_cx:{trade_id}")])
    return InlineKeyboardMarkup(kbd)


def _build_trade_confirm_text(session: dict, pkmn1: dict, pkmn2: dict) -> str:
    """
    Builds the IV/EV comparison confirmation message.
    pkmn1 = initiator's offered pokemon, pkmn2 = target's offered pokemon.
    Uses HTML parse mode.
    """
    initiator_id   = session["initiator_id"]
    initiator_name = session["initiator_name"]
    target_id      = session["target_id"]
    target_name    = session["target_name"]

    def _pkmn_block(name: str, uid: int, p: dict) -> str:
        # Build stat table
        pkmn_display = display_name_with_shiny(p['pokemon_name'], bool(p.get('shiny', 0)))
        pkmn_display = append_special_tag(pkmn_display, p.get('special_tag', ''))
        lines = [
            f'• <a href="tg://user?id={uid}">{name}</a>',
            "",
            f"Pokémon: <b>{pkmn_display}</b>",
            f"Nature: {p['nature']}",
            "",
            "<pre>",
            "      IV   EV",
            f"HP   {p['iv_hp']:>4} {p['ev_hp']:>4}",
            f"Atk  {p['iv_atk']:>4} {p['ev_atk']:>4}",
            f"Def  {p['iv_def']:>4} {p['ev_def']:>4}",
            f"SpA  {p['iv_spa']:>4} {p['ev_spa']:>4}",
            f"SpD  {p['iv_spd']:>4} {p['ev_spd']:>4}",
            f"Spe  {p['iv_spe']:>4} {p['ev_spe']:>4}",
            "</pre>",
        ]
        return "\n".join(lines)

    sep = "\n━━━━━━━━━━━━━━━━━━\n"
    body = (
        _pkmn_block(initiator_name, initiator_id, pkmn1)
        + sep
        + _pkmn_block(target_name, target_id, pkmn2)
        + sep
        + "Both, please accept the trade!"
    )
    return body


def _build_confirm_keyboard(trade_id: str) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [
            InlineKeyboardButton("Accept", callback_data=f"trd_cf:{trade_id}"),
            InlineKeyboardButton("Decline", callback_data=f"trd_cx:{trade_id}"),
        ]
    ])


# ── Command Handler ─────────────────────────────────────────────────────────

async def trade_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """/trade command — must be used by replying to another trainer's message."""
    msg  = update.message
    user = update.effective_user

    _expire_old_trades()

    # Registration check
    if not is_registered(user.id):
        await msg.reply_text("❌ You need to register first. Use /start")
        return

    # Must reply to someone
    if not msg.reply_to_message:
        await msg.reply_text("❌ Reply to another trainer's message to trade with them.\nUsage: Reply to a message, then send /trade")
        return

    target = msg.reply_to_message.from_user
    if not target or target.is_bot:
        await msg.reply_text("❌ You can't trade with a bot.")
        return

    if target.id == user.id:
        await msg.reply_text("❌ You can't trade with yourself.")
        return

    # Target registration check
    if not is_registered(target.id):
        await msg.reply_text("❌ That trainer hasn't registered yet.")
        return

    # Block only if already in an ACTIVE trade (past the request phase)
    if user.id in USER_TRADE_MAP:
        await msg.reply_text("❌ You're already in an active trade session.")
        return
    if target.id in USER_TRADE_MAP:
        await msg.reply_text("❌ That trainer is already in an active trade session.")
        return

    # Fetch trainer names from DB
    initiator_row = is_registered(user.id)
    target_row    = is_registered(target.id)
    initiator_name = initiator_row[0] if initiator_row else (user.full_name or "Trainer")
    target_name    = target_row[0]    if target_row    else (target.full_name or "Trainer")

    # Create session in PENDING state — do NOT add to USER_TRADE_MAP yet
    trade_id = _new_trade_id()
    TRADE_SESSIONS[trade_id] = {
        "initiator_id":       user.id,
        "target_id":          target.id,
        "initiator_name":     initiator_name,
        "target_name":        target_name,
        "pokemon_1":          None,
        "pokemon_2":          None,
        "initiator_accepted": False,
        "target_accepted":    False,
        "created_at":         time.time(),
        "phase":              "request",
        "chat_id":            msg.chat_id,
        "message_id":         None,
    }
    # Track as pending only — not an active lock
    PENDING_TRADE_MAP[user.id]    = trade_id
    PENDING_TRADE_MAP[target.id]  = trade_id

    text = (
        f'[{initiator_name}](tg://user?id={user.id}) '
        f'requested a Pokémon trade with '
        f'[{target_name}](tg://user?id={target.id})'
    )
    keyboard = InlineKeyboardMarkup([
        [
            InlineKeyboardButton("Accept",  callback_data=f"trd_accept:{trade_id}"),
            InlineKeyboardButton("Decline", callback_data=f"trd_decline:{trade_id}"),
        ]
    ])
    sent = await msg.reply_text(text, parse_mode="Markdown", reply_markup=keyboard)
    TRADE_SESSIONS[trade_id]["message_id"] = sent.message_id

    # Schedule timeout cleanup
    asyncio.create_task(
        _trade_timeout_task(trade_id, sent.chat_id, sent.message_id, context.application)
    )


async def _trade_timeout_task(
    trade_id: str, chat_id: int, message_id: int, application
) -> None:
    """Cancels the trade after TRADE_TIMEOUT seconds if still pending."""
    await asyncio.sleep(TRADE_TIMEOUT)
    if trade_id in TRADE_SESSIONS:
        _cancel_trade(trade_id)
        try:
            await application.bot.edit_message_text(
                chat_id=chat_id,
                message_id=message_id,
                text="⏰ Trade request expired.",
            )
        except Exception:
            pass


# ── Callback Handlers ───────────────────────────────────────────────────────

async def trd_noop_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """No-op for page indicator buttons — only trade participants may interact."""
    query = update.callback_query
    user  = query.from_user

    # Even the page-indicator noop should only respond to trade participants
    # We extract trade_id from surrounding session via USER_TRADE_MAP
    trade_id = USER_TRADE_MAP.get(user.id)
    if not trade_id:
        # This user is not part of any active trade — silently deny
        await query.answer("This menu belongs to another trainer.", show_alert=True)
        return

    await query.answer()


async def trd_accept_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Target trainer accepts the trade request → show initiator's pokemon list."""
    query    = update.callback_query
    user     = query.from_user
    trade_id = query.data.split(":", 1)[1]

    _expire_old_trades()
    session = TRADE_SESSIONS.get(trade_id)
    if not session:
        await query.answer("❌ Trade session expired.", show_alert=True)
        return

    if user.id != session["target_id"]:
        await query.answer("This trade does not belong to you.", show_alert=True)
        return

    if session["phase"] != "request":
        await query.answer("❌ Trade is already in progress.", show_alert=True)
        return

    # Promote from pending to active — now lock both users
    initiator_id = session["initiator_id"]
    target_id_s  = session["target_id"]
    if initiator_id in USER_TRADE_MAP or target_id_s in USER_TRADE_MAP:
        await query.answer("❌ One of the trainers is already in an active trade.", show_alert=True)
        _cancel_trade(trade_id)
        return

    USER_TRADE_MAP[initiator_id] = trade_id
    USER_TRADE_MAP[target_id_s]  = trade_id
    PENDING_TRADE_MAP.pop(initiator_id, None)
    PENDING_TRADE_MAP.pop(target_id_s, None)

    session["phase"] = "initiator_select"
    await query.answer()

    # Show initiator's pokemon list
    initiator_id   = session["initiator_id"]
    initiator_name = session["initiator_name"]
    settings       = get_user_settings(initiator_id)
    rows, total, _fav = get_user_pokemon_page(initiator_id, 1, settings)

    if total == 0:
        _cancel_trade(trade_id)
        await query.edit_message_text("❌ The initiating trainer has no Pokémon to trade. Trade cancelled.")
        return

    text     = _format_trade_select_text(initiator_name, rows, settings, 1, total)
    keyboard = _build_trade_select_keyboard(trade_id, "i", rows, 1, total)
    await query.edit_message_text(text, parse_mode="HTML", reply_markup=keyboard)


async def trd_decline_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Either trainer declines — cancels the entire trade."""
    query    = update.callback_query
    user     = query.from_user
    trade_id = query.data.split(":", 1)[1]

    session = TRADE_SESSIONS.get(trade_id)
    if not session:
        await query.answer("Trade already cancelled.", show_alert=True)
        return

    if user.id not in (session["initiator_id"], session["target_id"]):
        await query.answer("This trade does not belong to you.", show_alert=True)
        return

    _cancel_trade(trade_id)
    await query.answer()
    await query.edit_message_text("Trade has been cancelled.")


async def trd_page_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles pokemon list pagination during trade selection."""
    query = update.callback_query
    user  = query.from_user
    # Format: trd_page:trade_id:role:page
    parts = query.data.split(":")
    if len(parts) != 4:
        await query.answer()
        return

    _, trade_id, role, page_str = parts
    try:
        page = int(page_str)
    except ValueError:
        await query.answer()
        return

    _expire_old_trades()
    session = TRADE_SESSIONS.get(trade_id)
    if not session:
        await query.answer("❌ Trade session expired.", show_alert=True)
        return

    # Validate that this is the correct user's turn
    if role == "i" and user.id != session["initiator_id"]:
        await query.answer("This trade does not belong to you.", show_alert=True)
        return
    if role == "t" and user.id != session["target_id"]:
        await query.answer("This trade does not belong to you.", show_alert=True)
        return

    selector_id   = session["initiator_id"] if role == "i" else session["target_id"]
    selector_name = session["initiator_name"] if role == "i" else session["target_name"]

    settings         = get_user_settings(selector_id)
    rows, total, _fav = get_user_pokemon_page(selector_id, page, settings)
    total_pages      = math.ceil(total / ROPOKE_PAGE_SIZE) if total > 0 else 1

    if page < 1 or page > total_pages:
        await query.answer("Invalid page.", show_alert=True)
        return

    text     = _format_trade_select_text(selector_name, rows, settings, page, total)
    keyboard = _build_trade_select_keyboard(trade_id, role, rows, page, total)
    try:
        await query.edit_message_text(text, parse_mode="HTML", reply_markup=keyboard)
    except Exception:
        pass
    await query.answer()


async def trd_sel_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles a trainer selecting a pokemon to offer in the trade."""
    query = update.callback_query
    user  = query.from_user
    # Format: trd_sel:trade_id:role:pokemon_db_id
    parts = query.data.split(":")
    if len(parts) != 4:
        await query.answer()
        return

    _, trade_id, role, pk_id_str = parts
    try:
        pk_db_id = int(pk_id_str)
    except ValueError:
        await query.answer()
        return

    _expire_old_trades()
    session = TRADE_SESSIONS.get(trade_id)
    if not session:
        await query.answer("❌ Trade session expired.", show_alert=True)
        return

    # Validate it's the right user's turn
    if role == "i":
        if user.id != session["initiator_id"]:
            await query.answer("This trade does not belong to you.", show_alert=True)
            return
        if session["phase"] != "initiator_select":
            await query.answer("❌ Unexpected selection.", show_alert=True)
            return
    else:
        if user.id != session["target_id"]:
            await query.answer("This trade does not belong to you.", show_alert=True)
            return
        if session["phase"] != "target_select":
            await query.answer("❌ Unexpected selection.", show_alert=True)
            return

    owner_id = session["initiator_id"] if role == "i" else session["target_id"]

    # Validate ownership
    pkmn = _get_pokemon_by_db_id(pk_db_id)
    if not pkmn or pkmn["user_id"] != owner_id:
        await query.answer("❌ Pokémon not found or ownership mismatch.", show_alert=True)
        return
    if is_pokemon_in_camp(pk_db_id):
        await query.answer("This Pokemon is in The Camp", show_alert=True)
        return

    # Cannot trade another session's pokemon
    if role == "i" and session.get("pokemon_1") == pk_db_id:
        await query.answer("Already selected.", show_alert=True)
        return

    # Cannot trade if it would leave the trainer with zero pokemon
    if _count_user_pokemon(owner_id) <= 1:
        await query.answer(
            "❌ You can't trade your last Pokémon.", show_alert=True
        )
        return

    # Cannot trade the active battle pokemon (is_active == 1) if only one usable pokemon left
    # (loose restriction: allow active pokemon trades as long as trainer has >1 total)

    await query.answer()

    if role == "i":
        # Initiator chose — now show target's list
        session["pokemon_1"] = pk_db_id
        session["phase"]     = "target_select"

        target_id   = session["target_id"]
        target_name = session["target_name"]
        settings    = get_user_settings(target_id)
        rows, total, _fav = get_user_pokemon_page(target_id, 1, settings)

        if total == 0:
            _cancel_trade(trade_id)
            await query.edit_message_text("❌ The other trainer has no Pokémon to trade. Trade cancelled.")
            return

        text     = _format_trade_select_text(target_name, rows, settings, 1, total)
        keyboard = _build_trade_select_keyboard(trade_id, "t", rows, 1, total)
        await query.edit_message_text(text, parse_mode="HTML", reply_markup=keyboard)

    else:
        # Target chose — show confirmation with IV/EV comparison
        session["pokemon_2"] = pk_db_id
        session["phase"]     = "confirm"

        pkmn1 = _get_pokemon_by_db_id(session["pokemon_1"])
        pkmn2 = _get_pokemon_by_db_id(session["pokemon_2"])

        if not pkmn1 or not pkmn2:
            _cancel_trade(trade_id)
            await query.edit_message_text("❌ A Pokémon no longer exists. Trade cancelled.")
            return

        text     = _build_trade_confirm_text(session, pkmn1, pkmn2)
        keyboard = _build_confirm_keyboard(trade_id)
        await query.edit_message_text(text, parse_mode="HTML", reply_markup=keyboard)


async def trd_cf_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles the Accept button on the trade confirmation screen."""
    query    = update.callback_query
    user     = query.from_user
    trade_id = query.data.split(":", 1)[1]

    _expire_old_trades()
    session = TRADE_SESSIONS.get(trade_id)
    if not session:
        await query.answer("❌ Trade session expired.", show_alert=True)
        return

    if user.id not in (session["initiator_id"], session["target_id"]):
        await query.answer("This trade does not belong to you.", show_alert=True)
        return

    if session["phase"] != "confirm":
        await query.answer("❌ Not in confirmation phase.", show_alert=True)
        return

    is_initiator = (user.id == session["initiator_id"])

    # Guard against double-clicking
    if is_initiator and session["initiator_accepted"]:
        await query.answer("You already accepted.", show_alert=True)
        return
    if not is_initiator and session["target_accepted"]:
        await query.answer("You already accepted.", show_alert=True)
        return

    if is_initiator:
        session["initiator_accepted"] = True
    else:
        session["target_accepted"] = True

    await query.answer()

    # ── Both accepted → execute trade ──────────────────────────────────────
    if session["initiator_accepted"] and session["target_accepted"]:
        pkmn1 = _get_pokemon_by_db_id(session["pokemon_1"])
        pkmn2 = _get_pokemon_by_db_id(session["pokemon_2"])

        # Final ownership re-validation before any DB write
        if not pkmn1 or pkmn1["user_id"] != session["initiator_id"]:
            _cancel_trade(trade_id)
            await query.edit_message_text(
                "❌ Trade failed: ownership of a Pokémon changed. Trade cancelled."
            )
            return
        if not pkmn2 or pkmn2["user_id"] != session["target_id"]:
            _cancel_trade(trade_id)
            await query.edit_message_text(
                "❌ Trade failed: ownership of a Pokémon changed. Trade cancelled."
            )
            return

        # Swap ownership — transfer ALL data (only user_id changes; all stats preserved)
        conn   = sqlite3.connect("ZNX.db")
        cursor = conn.cursor()
        # pkmn1 (initiator's) → target
        cursor.execute(
            "UPDATE user_pokemon SET user_id = ?, is_active = 0 WHERE id = ?",
            (session["target_id"], session["pokemon_1"]),
        )
        # pkmn2 (target's) → initiator
        cursor.execute(
            "UPDATE user_pokemon SET user_id = ?, is_active = 0 WHERE id = ?",
            (session["initiator_id"], session["pokemon_2"]),
        )
        conn.commit()
        conn.close()

        initiator_id   = session["initiator_id"]
        initiator_name = session["initiator_name"]
        target_id      = session["target_id"]
        target_name    = session["target_name"]
        name1 = display_name_with_shiny(pkmn1["pokemon_name"], bool(pkmn1.get("shiny", 0)))
        name2 = display_name_with_shiny(pkmn2["pokemon_name"], bool(pkmn2.get("shiny", 0)))

        success = (
            f"✅ <b>Trade Successful!</b>\n\n"
            f'<a href="tg://user?id={target_id}">{target_name}</a> received <b>{name1}</b>\n\n'
            f'<a href="tg://user?id={initiator_id}">{initiator_name}</a> received <b>{name2}</b>'
        )
        _cancel_trade(trade_id)
        await query.edit_message_text(success, parse_mode="HTML")

    # ── One accepted, waiting for the other ────────────────────────────────
    else:
        user_name  = session["initiator_name"] if is_initiator else session["target_name"]
        other_id   = session["target_id"]   if is_initiator else session["initiator_id"]
        other_name = session["target_name"] if is_initiator else session["initiator_name"]

        pkmn1 = _get_pokemon_by_db_id(session["pokemon_1"])
        pkmn2 = _get_pokemon_by_db_id(session["pokemon_2"])
        if not pkmn1 or not pkmn2:
            _cancel_trade(trade_id)
            await query.edit_message_text("❌ A Pokémon no longer exists. Trade cancelled.")
            return

        confirm_text = _build_trade_confirm_text(session, pkmn1, pkmn2)
        waiting_text = (
            confirm_text
            + f'\n\n✅ <a href="tg://user?id={user.id}">{user_name}</a> accepted.\n'
            f'⏳ Waiting for <a href="tg://user?id={other_id}">{other_name}</a>...'
        )
        keyboard = _build_confirm_keyboard(trade_id)
        try:
            await query.edit_message_text(waiting_text, parse_mode="HTML", reply_markup=keyboard)
        except Exception:
            pass


async def trd_cx_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Cancel trade during selection or confirmation phase."""
    query    = update.callback_query
    user     = query.from_user
    trade_id = query.data.split(":", 1)[1]

    session = TRADE_SESSIONS.get(trade_id)
    if not session:
        await query.answer("Trade already cancelled.", show_alert=True)
        return

    if user.id not in (session["initiator_id"], session["target_id"]):
        await query.answer("This trade does not belong to you.", show_alert=True)
        return

    _cancel_trade(trade_id)
    await query.answer()
    await query.edit_message_text("Trade has been cancelled.")


