def generate_event_ivs(min_iv: int = 10) -> dict:
    """IVs with guaranteed minimum per stat — used during high-IV events."""
    return {
        "hp":              random.randint(min_iv, 31),
        "attack":          random.randint(min_iv, 31),
        "defense":         random.randint(min_iv, 31),
        "special-attack":  random.randint(min_iv, 31),
        "special-defense": random.randint(min_iv, 31),
        "speed":           random.randint(min_iv, 31),
    }


def _leaderboard_excluded_ids() -> tuple:
    """Accounts hidden from public leaderboards.

    Historically this returned OWNER_IDS, which hid the bot owner — and when
    the owner is the only registered trainer every board rendered empty
    ("No trainers found yet!"). Owner/admin accounts now appear normally so
    leaderboards always show whoever is registered.
    """
    return ()


def _leaderboard_exclusion_sql(user_id_column: str = "user_id") -> tuple[str, tuple]:
    """Builds a SQL 'AND {column} NOT IN (?, ?, ...)' fragment plus its
    params tuple, for use in leaderboard WHERE clauses. Returns ("", ())
    if there happen to be no excluded IDs (never in practice, but safe).
    """
    excluded = _leaderboard_excluded_ids()
    if not excluded:
        return "", ()
    placeholders = ",".join("?" for _ in excluded)
    return f"AND {user_id_column} NOT IN ({placeholders})", excluded

