def _ap_lookup_user(query_str: str) -> dict | None:
    """Lookup a user by ID, username, or trainer name. Returns dict or None.

    Checks USER_CACHE before falling back to disk for the username/
    trainer_name searches — a trainer who just registered or renamed may
    exist only in-memory for up to cache_flush_loop's interval (45s), and a
    pure disk query would silently fail to find them during that window
    (the same staleness class of bug found and fixed in
    _process_referral_start's referral_code lookup)."""
    # Try numeric ID — served directly by the cache, which is itself
    # disk-backed on a miss, so this one always sees the freshest data.
    try:
        uid = int(query_str)
        profile = get_user(uid)
        if profile is not None:
            return {"user_id": uid, "username": profile.get("username"),
                    "trainer_name": profile.get("trainer_name"),
                    "region": profile.get("current_region"),
                    "balance": profile.get("nova_rupee") or 0}
    except ValueError:
        pass

    # Try username (strip @) — check cache first, then fall back to disk
    # for users who aren't currently cached at all.
    uname = query_str.lstrip("@").lower()
    for _uid, _profile in USER_CACHE.items():
        if (_profile.get("username") or "").lower() == uname:
            return {"user_id": _uid, "username": _profile.get("username"),
                    "trainer_name": _profile.get("trainer_name"),
                    "region": _profile.get("current_region"),
                    "balance": _profile.get("nova_rupee") or 0}

    conn = _ap_db()
    cur = conn.cursor()
    cur.execute(
        "SELECT user_id, username, trainer_name, current_region, nova_rupee FROM users WHERE LOWER(username) = ?",
        (uname,)
    )
    row = cur.fetchone()
    if row:
        return {"user_id": row[0], "username": row[1], "trainer_name": row[2],
                "region": row[3], "balance": row[4] or 0}

    # Try trainer name — same cache-first approach.
    tname = query_str.lower()
    for _uid, _profile in USER_CACHE.items():
        if (_profile.get("trainer_name") or "").lower() == tname:
            return {"user_id": _uid, "username": _profile.get("username"),
                    "trainer_name": _profile.get("trainer_name"),
                    "region": _profile.get("current_region"),
                    "balance": _profile.get("nova_rupee") or 0}

    cur.execute(
        "SELECT user_id, username, trainer_name, current_region, nova_rupee FROM users WHERE LOWER(trainer_name) = ?",
        (tname,)
    )
    row = cur.fetchone()
    if row:
        return {"user_id": row[0], "username": row[1], "trainer_name": row[2],
                "region": row[3], "balance": row[4] or 0}
    return None


def _ap_get_trainer_full(user_id: int) -> dict | None:
    conn = _ap_db()
    cur = conn.cursor()
    cur.execute(
        """SELECT u.user_id, u.username, u.trainer_name, u.current_region,
                  u.nova_rupee, u.candy, u.berry, u.vitamin, u.boost,
                  u.pokeballs, u.greatballs, u.ultraballs, u.master_ball,
                  u.repeatballs, u.nestballs, u.duskballs,
                  COUNT(p.id) as poke_count
           FROM users u
           LEFT JOIN user_pokemon p ON u.user_id = p.user_id
           WHERE u.user_id = ?
           GROUP BY u.user_id""",
        (user_id,)
    )
    row = cur.fetchone()
    conn.close()
    if not row:
        return None
    return {
        "user_id": row[0], "username": row[1], "trainer_name": row[2],
        "region": row[3], "balance": row[4] or 0,
        "candy": row[5] or 0, "berry": row[6] or 0,
        "vitamin": row[7] or 0, "boost": row[8] or 0,
        "pokeballs": row[9] or 0, "greatballs": row[10] or 0,
        "ultraballs": row[11] or 0, "master_ball": row[12] or 0,
        "repeatballs": row[13] or 0, "nestballs": row[14] or 0,
        "duskballs": row[15] or 0, "poke_count": row[16] or 0
    }


# ── Rank Management helpers ────────────────────────────────────────────────
# These deliberately reuse TRAINER_RANKS / get_trainer_rank / check_and_notify_rank_up
# (defined earlier, in the TRAINER RANK SYSTEM block) instead of duplicating any
# rank logic here.

def _ap_get_trainer_exp(user_id: int) -> tuple[str, int] | None:
    """Return (trainer_name, trainer_exp) for user_id, or None if the user
    doesn't exist."""
    profile = get_user(user_id)
    if profile is None:
        return None
    return (profile.get("trainer_name") or str(user_id)), (profile.get("trainer_exp") or 0)


def _ap_rank_name_lookup(raw: str) -> str | None:
    """Case-insensitive match of admin-supplied text against the canonical
    TRAINER_RANKS names. Returns the correctly-cased rank name, or None."""
    raw_norm = raw.strip().lower()
    for rank_name, _, _ in TRAINER_RANKS:
        if rank_name.lower() == raw_norm:
            return rank_name
    return None


def _ap_parse_id_amount(text: str) -> tuple[int, int] | None:
    """Parse a two-line 'User ID \\n Amount' admin reply into (user_id, amount).
    Returns None on any malformed input (wrong line count / non-numeric)."""
    lines = [ln.strip() for ln in text.strip().splitlines() if ln.strip()]
    if len(lines) != 2:
        return None
    try:
        target_id = int(lines[0])
        amount = int(lines[1].replace(",", ""))
    except ValueError:
        return None
    return target_id, amount


# ═══════════════════════════════════════════════════════════════════════════
# ═══════════════════════════ CENTRALIZED BAN SYSTEM ═════════════════════════
# ═══════════════════════════════════════════════════════════════════════════
# is_user_banned() is the single source of truth for whether a user is
# currently banned (permanent or an active temp ban). It hits the DB directly
# on every call — no caching — so an /rounban immediately restores access.
#
# ALL enforcement happens centrally via the global pre-check handlers
# (_global_ban_guard_message / _global_ban_guard_callback) registered in
# main() at group=-1, i.e. BEFORE every other handler (commands, callback
# buttons, conversation steps, background systems). Individual handlers no
# longer need — and must not add — their own duplicate ban checks.
#
# In GROUP chats, global_ban_guard_message additionally scopes itself to
# actual bot interactions via _is_bot_directed_message() below, so a banned
# user's ordinary conversation with other humans in the group doesn't get
# spammed with the ban notice. PRIVATE chats are unaffected — every message
# there is still checked, same as before this scoping was added.

BAN_MESSAGE_HTML = (
    "🚫 <b>You are banned from using PokeRo.</b>\n\n"
    "If you believe this is a mistake, please contact an administrator."
)
# Plain-text version for Telegram callback-query alerts, which do not support HTML.
BAN_MESSAGE_PLAIN = (
    "🚫 You are banned from using PokeRo.\n\n"
    "If you believe this is a mistake, please contact an administrator."
)


def is_user_banned(user_id: int) -> bool:
    """Centralized ban check. Returns True if user_id is currently banned
    (permanently, or under a temp ban that hasn't expired yet)."""
    conn = _ap_db()
    cur = conn.cursor()
    cur.execute("SELECT 1 FROM banned_users WHERE user_id = ? AND (expires_at IS NULL OR expires_at > ?)",
                (user_id, int(time.time())))
    row = cur.fetchone()
    conn.close()
    return bool(row)


def _ap_is_banned(user_id: int) -> bool:
    """Backwards-compatible alias — delegates to is_user_banned()."""
    return is_user_banned(user_id)


async def _check_user_banned(update: Update) -> bool:
    """Backwards-compatible alias — delegates to is_user_banned()."""
    user = update.effective_user
    if not user:
        return False
    return is_user_banned(user.id)


async def _is_bot_directed_message(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    """True if an incoming message in a GROUP chat is actually an interaction
    with the bot, as opposed to ordinary conversation between chat members.
    Used only to scope global_ban_guard_message — private chats always run
    the ban check regardless of this helper.

    Counts as a bot interaction:
      - Commands ("/hunt", "/admin", "/tm42@PokieNova_bot", etc.)
      - A reply to one of the bot's own messages (covers conversation
        replies to an active "Reply with ..." prompt, e.g. nickname entry)
      - Any other in-memory flow that is intentionally reachable from group
        chats and is currently awaiting a plain-text reply from this user
        (currently: the nickname-entry flow, PENDING_NICKNAME)
    """
    msg = update.effective_message
    if msg is None:
        return False

    text = msg.text or msg.caption or ""
    if text.startswith("/"):
        return True

    user = update.effective_user
    if user is not None and user.id in PENDING_NICKNAME:
        return True

    reply_to = msg.reply_to_message
    if reply_to is not None and reply_to.from_user is not None and reply_to.from_user.id == context.bot.id:
        return True

    return False


async def global_ban_guard_message(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Group=-1 catch-all MessageHandler — runs before every other message-based
    handler (commands, text replies, conversation states, photo/document
    uploads, everything). If the sender is banned, reply with the ban notice
    and hard-stop propagation so no other handler in any group executes.

    In GROUP chats, the ban check only runs when the message is actually an
    interaction with the bot (see _is_bot_directed_message) — otherwise a
    banned user's ordinary chatter with other humans would repeatedly trigger
    the ban notice and spam the group. PRIVATE chats are unaffected: every
    message there is still checked, exactly as before.
    """
    user = update.effective_user
    if user is None:
        return
    chat = update.effective_chat
    if chat is not None and chat.type != "private":
        if not await _is_bot_directed_message(update, context):
            return
    if is_user_banned(user.id):
        msg = update.effective_message
        if msg is not None:
            try:
                await msg.reply_text(BAN_MESSAGE_HTML, parse_mode="HTML")
            except Exception:
                pass
        raise ApplicationHandlerStop


async def global_ban_guard_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Group=-1 catch-all CallbackQueryHandler — runs before every other
    inline-button handler. If the presser is banned, answer the callback with
    a Telegram alert (instead of silently failing) and hard-stop propagation."""
    user = update.effective_user
    if user is None:
        return
    if is_user_banned(user.id):
        query = update.callback_query
        if query is not None:
            try:
                await query.answer(BAN_MESSAGE_PLAIN, show_alert=True)
            except Exception:
                pass
        raise ApplicationHandlerStop


def _ap_log(admin_id: int, admin_name: str, action: str, target_id: int | None, target_name: str | None):
    """Write a log entry for every admin action."""
    conn = _ap_db()
    cur = conn.cursor()
    now_str = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M")
    cur.execute(
        "INSERT INTO admin_logs (admin_id, admin_name, action, target_id, target_name, logged_at) VALUES (?,?,?,?,?,?)",
        (admin_id, admin_name, action, target_id, target_name, now_str)
    )
    conn.commit()
    conn.close()


def _ap_get_stats() -> dict:
    conn = _ap_db()
    cur = conn.cursor()
    cur.execute("SELECT COUNT(*) FROM users")
    trainers = cur.fetchone()[0]
    cur.execute("SELECT COUNT(*) FROM user_pokemon")
    pokemon_total = cur.fetchone()[0]
    cur.execute("SELECT SUM(usage_count) FROM redeem_codes")
    codes_r = cur.fetchone()[0] or 0
    # Count active camps
    now_ts = int(time.time())
    cur.execute("SELECT COUNT(*) FROM users WHERE camp_pokemon_id != 0 AND camp_end_time > ?", (now_ts,))
    camps = cur.fetchone()[0]
    # Safari: users who used safari today
    today = _safari_reset_date()
    cur.execute("SELECT COUNT(*) FROM users WHERE safari_last_cycle = ? AND safari_daily_used = 1", (today,))
    safari_visits = cur.fetchone()[0]

    # DAU/WAU/MAU via last_active timestamp
    midnight_today = int(time.time() // 86400 * 86400)  # start of today UTC
    import datetime as _dt
    now_utc = _dt.datetime.now(_dt.timezone.utc)
    # Weekly: reset Monday UTC
    week_start = now_utc - _dt.timedelta(days=now_utc.weekday())
    week_ts = int(_dt.datetime(week_start.year, week_start.month, week_start.day, tzinfo=_dt.timezone.utc).timestamp())
    # Monthly: reset first day of month
    month_ts = int(_dt.datetime(now_utc.year, now_utc.month, 1, tzinfo=_dt.timezone.utc).timestamp())
    cur.execute("SELECT COUNT(*) FROM users WHERE last_active > ?", (now_ts - 86400,))
    daily_active = cur.fetchone()[0]
    cur.execute("SELECT COUNT(*) FROM users WHERE last_active > ?", (week_ts,))
    weekly_active = cur.fetchone()[0]
    cur.execute("SELECT COUNT(*) FROM users WHERE last_active > ?", (month_ts,))
    monthly_active = cur.fetchone()[0]

    # Battles today via battle_events log — only /challenge and /randomclash (pvp), not wild hunts
    cur.execute("SELECT COUNT(*) FROM battle_events WHERE created_at > ? AND event_type = 'pvp'", (now_ts - 86400,))
    battles_today = cur.fetchone()[0]

    # Pokémon caught today
    cur.execute("SELECT COUNT(*) FROM user_pokemon WHERE caught_at > ?", (now_ts - 86400,))
    caught_today = cur.fetchone()[0]

    conn.close()
    return {
        "trainers": trainers, "pokemon_total": pokemon_total,
        "codes_redeemed": codes_r, "camps": camps, "safari_visits": safari_visits,
        "daily_active": daily_active, "weekly_active": weekly_active, "monthly_active": monthly_active,
        "battles_today": battles_today, "caught_today": caught_today,
    }


def _ap_get_active_battles() -> list:
    """List every (user_id, trainer_name) currently marked active_battle=1.

    Merges in USER_CACHE first: a battle lock set via update_user()
    moments ago (see _set_battle_lock) may not be flushed to disk yet, and
    an admin trying to see/manage stuck battles should see it immediately,
    not up to cache_flush_loop's interval later."""
    conn = _ap_db()
    cur = conn.cursor()
    cur.execute(
        """SELECT u.user_id, u.trainer_name FROM users u WHERE u.active_battle = 1"""
    )
    rows = cur.fetchall()
    seen_ids = {r[0] for r in rows}
    for _uid, _profile in USER_CACHE.items():
        if _profile.get("active_battle") and _uid not in seen_ids:
            rows.append((_uid, _profile.get("trainer_name")))
            seen_ids.add(_uid)
    return rows


def _ap_get_codes() -> list:
    conn = _ap_db()
    cur = conn.cursor()
    cur.execute(
        "SELECT code, rewards, usage_count, usage_limit, created_at FROM redeem_codes ORDER BY created_at DESC"
    )
    rows = cur.fetchall()
    conn.close()
    return rows


def _ap_get_maintenance_mode() -> bool:
    conn = _ap_db()
    cur = conn.cursor()
    try:
        cur.execute("SELECT value FROM bot_settings WHERE key = 'maintenance_mode'")
        row = cur.fetchone()
        conn.close()
        return bool(row and row[0] == '1')
    except Exception:
        conn.close()
        return False


def _ap_set_maintenance_mode(enabled: bool):
    conn = _ap_db()
    cur = conn.cursor()
    cur.execute(
        "INSERT INTO bot_settings (key, value) VALUES ('maintenance_mode', ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value",
        ('1' if enabled else '0',)
    )
    conn.commit()
    conn.close()


def _ap_ensure_tables():
    """Ensure admin panel specific tables exist."""
    conn = _ap_db()
    cur = conn.cursor()
    # Head admins
    cur.execute("""CREATE TABLE IF NOT EXISTS head_admins (
        user_id INTEGER PRIMARY KEY
    )""")
    # Admin details (for display)
    cur.execute("""CREATE TABLE IF NOT EXISTS admin_details (
        user_id INTEGER PRIMARY KEY,
        username TEXT,
        first_name TEXT
    )""")
    cur.execute("""CREATE TABLE IF NOT EXISTS head_admin_details (
        user_id INTEGER PRIMARY KEY,
        username TEXT,
        first_name TEXT
    )""")
    # Banned users
    cur.execute("""CREATE TABLE IF NOT EXISTS banned_users (
        user_id INTEGER PRIMARY KEY,
        ban_type TEXT DEFAULT 'permanent',
        reason TEXT,
        banned_by INTEGER,
        banned_at TEXT,
        expires_at INTEGER
    )""")
    # Muted users
    cur.execute("""CREATE TABLE IF NOT EXISTS muted_users (
        user_id INTEGER PRIMARY KEY,
        reason TEXT,
        muted_by INTEGER,
        muted_at TEXT,
        expires_at INTEGER
    )""")
    # Admin logs
    cur.execute("""CREATE TABLE IF NOT EXISTS admin_logs (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        admin_id INTEGER,
        admin_name TEXT,
        action TEXT,
        target_id INTEGER,
        target_name TEXT,
        logged_at TEXT
    )""")
    # Bot settings
    cur.execute("""CREATE TABLE IF NOT EXISTS bot_settings (
        key TEXT PRIMARY KEY,
        value TEXT
    )""")
    # Ensure owners are head admins
    for owner_id in OWNER_IDS:
        cur.execute("INSERT OR IGNORE INTO head_admins (user_id) VALUES (?)", (owner_id,))
        cur.execute(
            "INSERT OR IGNORE INTO head_admin_details (user_id, username, first_name) VALUES (?, 'FINAL_BOSS_01', '╭╯╷ SHADOW †')",
            (owner_id,)
        )
    conn.commit()
    conn.close()


