async def mysterygift_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """/mysterygift \u2014 open a free Mystery Gift once per day (05:30 IST reset)."""
    user = update.effective_user
    if not is_registered(user.id):
        await update.message.reply_text("\u274c Register first with /start.")
        return
    today = _safari_reset_date()
    profile = get_user(user.id)
    if (profile.get("last_daily_claim") or "") > today:
        pass  # daily/mysterygift tracked separately below
    conn = get_db("ZNX.db")
    try:
        conn.execute(
            "CREATE TABLE IF NOT EXISTS mystery_gifts (user_id INTEGER PRIMARY KEY, last_claim TEXT)")
        conn.commit()
    except Exception:
        pass
    row = conn.execute(
        "SELECT last_claim FROM mystery_gifts WHERE user_id=?", (user.id,)).fetchone()
    if row and row[0] == today:
        await update.message.reply_text(
            "\U0001f381 You already opened today's Mystery Gift!\n<i>Come back after the next reset.</i>",
            parse_mode="HTML")
        return
    deltas, desc = random.choice(_MYSTERY_GIFT_POOL)
    increment_user(user.id, **deltas)
    conn.execute(
        "INSERT INTO mystery_gifts (user_id, last_claim) VALUES (?, ?) "
        "ON CONFLICT(user_id) DO UPDATE SET last_claim=excluded.last_claim",
        (user.id, today))
    conn.commit()
    await update.message.reply_text(
        f"\U0001f381 <b><u>Mystery Gift!</u></b>\n\nYou received\n{desc}\n\n"
        f"<i>Open another gift tomorrow!</i>",
        parse_mode="HTML")


# ── /userid ───────────────────────────────────────────────────────────────────
async def userid_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """/userid — check anyone's Telegram ID.

    • Reply to a message with /userid        → target = that message's sender
    • /userid @username or /userid 123456    → resolve via get_chat()
    • /userid (no reply, no args)            → your own ID
    """
    msg = update.message
    target = None

    # 1) Replying to someone's message
    reply = msg.reply_to_message
    if reply is not None and reply.from_user is not None:
        target = reply.from_user
    elif context.args:
        # 2) Given a @username or a raw numeric ID
        arg = context.args[0]
        try:
            chat = await context.bot.get_chat(arg)
            target = chat
        except Exception:
            await msg.reply_text(
                f"❌ Couldn't find a user for <code>{arg}</code>.\n"
                "<i>Use a @username the bot can see, or reply to their message instead.</i>",
                parse_mode="HTML")
            return
    else:
        # 3) No reply, no args → yourself
        target = update.effective_user

    uname = f"@{target.username}" if getattr(target, "username", None) else "—"
    full_name = " ".join(p for p in (target.first_name, target.last_name) if p) or "Unknown"
    kind = "🤖 Bot" if target.is_bot else "👤 User"
    me = await context.bot.get_me()
    if target.id == me.id:
        kind = "🤖 This bot (PokeRo)"

    chat = msg.chat
    chat_line = ""
    if chat.type != "private":
        chat_line = f"\n💬 Chat ID: <code>{chat.id}</code>"
    await msg.reply_text(
        f"🆔 <b>ID:</b> <code>{target.id}</code>\n"
        f"{kind} · <b>{full_name}</b>\n"
        f"📎 {uname}{chat_line}",
        parse_mode="HTML")


