# ── Main callback router ───────────────────────────────────────────────────────

async def ap_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Master callback handler for all ap_ prefixed callbacks."""
    query = update.callback_query
    user = query.from_user
    data = query.data

    # Security: all admin panel callbacks require admin access
    if not _ap_is_admin(user.id):
        await query.answer("❌ Unauthorized.", show_alert=True)
        return

    await query.answer()

    # ── Main panel ─────────────────────────────────────────────────────────
    if data == "ap_main":
        try:
            await query.edit_message_text(_ap_main_text(), reply_markup=_ap_main_keyboard())
        except Exception:
            pass
        return

    # ── User Management ────────────────────────────────────────────────────
    if data == "ap_user_mgmt":
        kb = InlineKeyboardMarkup([
            [InlineKeyboardButton("Admin List", callback_data="ap_admin_list")],
            [InlineKeyboardButton("Head Admin List", callback_data="ap_hadmin_list")],
            [InlineKeyboardButton("Trainer Lookup", callback_data="ap_lookup_prompt")],
            _ap_back_btn(),
        ])
        await query.edit_message_text("👥 *User Management*", parse_mode="Markdown", reply_markup=kb)
        return

    # ── Admin List ─────────────────────────────────────────────────────────
    if data == "ap_admin_list":
        admins = _ap_get_admins()
        if admins:
            lines = ["Admins in PᴏᴋᴇRᴏ:\n"]
            for uid, uname, fname in admins:
                tag = f"@{uname}" if uname else f"ID:{uid}"
                lines.append(f"- {tag} [{fname or 'N/A'}]")
            text = "\n".join(lines)
        else:
            text = "No admins registered yet."
        kb = InlineKeyboardMarkup([
            [InlineKeyboardButton("Add Admin", callback_data="ap_add_admin_prompt"),
             InlineKeyboardButton("Remove Admin", callback_data="ap_remove_admin_list")],
            _ap_back_btn("ap_user_mgmt"),
        ])
        await query.edit_message_text(text, reply_markup=kb)
        return

    # ── Head Admin List ────────────────────────────────────────────────────
    if data == "ap_hadmin_list":
        hadmins = _ap_get_head_admins()
        if hadmins:
            lines = ["Head Admins in PᴏᴋᴇRᴏ:\n"]
            for uid, uname, fname in hadmins:
                tag = f"@{uname}" if uname else f"ID:{uid}"
                lines.append(f"- {tag} [{fname or 'N/A'}]")
            text = "\n".join(lines)
        else:
            text = "No head admins registered."
        kb_rows = []
        if _ap_is_owner(user.id):
            kb_rows.append([
                InlineKeyboardButton("Add Head Admin", callback_data="ap_add_hadmin_prompt"),
                InlineKeyboardButton("Remove Head Admin", callback_data="ap_remove_hadmin_list"),
            ])
        kb_rows.append(_ap_back_btn("ap_user_mgmt"))
        await query.edit_message_text(text, reply_markup=InlineKeyboardMarkup(kb_rows))
        return

    # ── Add Admin prompt ───────────────────────────────────────────────────
    if data == "ap_add_admin_prompt":
        ADMIN_PENDING[user.id] = {"action": "add_admin"}
        await query.edit_message_text(
            "Send the Telegram ID of the user you want to add as Admin.\n\nSend /cancel to abort.",
            reply_markup=InlineKeyboardMarkup([_ap_back_btn("ap_admin_list")])
        )
        return

    # ── Add Head Admin prompt (owner only) ────────────────────────────────
    if data == "ap_add_hadmin_prompt":
        if not _ap_is_owner(user.id):
            await query.answer("❌ Only bot owners can manage Head Admins.", show_alert=True)
            return
        ADMIN_PENDING[user.id] = {"action": "add_head_admin"}
        await query.edit_message_text(
            "Send the Telegram ID of the user you want to add as Head Admin.\n\nSend /cancel to abort.",
            reply_markup=InlineKeyboardMarkup([_ap_back_btn("ap_hadmin_list")])
        )
        return

    # ── Remove Admin list ──────────────────────────────────────────────────
    if data == "ap_remove_admin_list":
        admins = _ap_get_admins()
        if not admins:
            await query.edit_message_text(
                "No admins to remove.",
                reply_markup=InlineKeyboardMarkup([_ap_back_btn("ap_admin_list")])
            )
            return
        rows = [[InlineKeyboardButton(f"{fname or uname or str(uid)}", callback_data=f"ap_rm_admin_confirm:{uid}")]
                for uid, uname, fname in admins]
        rows.append(_ap_back_btn("ap_admin_list"))
        await query.edit_message_text("Select admin to remove:", reply_markup=InlineKeyboardMarkup(rows))
        return

    # ── Remove Admin confirmation ──────────────────────────────────────────
    if data.startswith("ap_rm_admin_confirm:"):
        target_id = int(data.split(":")[1])
        conn = _ap_db()
        cur = conn.cursor()
        cur.execute("SELECT first_name, username FROM admin_details WHERE user_id = ?", (target_id,))
        row = cur.fetchone()
        conn.close()
        name = (row[0] if row else None) or str(target_id)
        kb = InlineKeyboardMarkup([
            [InlineKeyboardButton("Yes", callback_data=f"ap_rm_admin_do:{target_id}"),
             InlineKeyboardButton("Back", callback_data="ap_remove_admin_list")],
        ])
        await query.edit_message_text(f"Remove admin {name}?", reply_markup=kb)
        return

    # ── Remove Admin execute ───────────────────────────────────────────────
    if data.startswith("ap_rm_admin_do:"):
        target_id = int(data.split(":")[1])
        if target_id in OWNER_IDS:
            await query.answer("Cannot remove an owner.", show_alert=True)
            return
        conn = _ap_db()
        cur = conn.cursor()
        cur.execute("SELECT first_name FROM admin_details WHERE user_id = ?", (target_id,))
        row = cur.fetchone()
        name = (row[0] if row else None) or str(target_id)
        cur.execute("DELETE FROM admins WHERE user_id = ?", (target_id,))
        cur.execute("DELETE FROM admin_details WHERE user_id = ?", (target_id,))
        conn.commit()
        conn.close()
        if target_id in ADMIN_IDS:
            ADMIN_IDS.remove(target_id)
        _ap_log(user.id, user.first_name or str(user.id), f"Removed admin: {name}", target_id, name)
        await query.edit_message_text(
            f"✅ {name} has been removed from admins.",
            reply_markup=InlineKeyboardMarkup([_ap_back_btn("ap_admin_list")])
        )
        return

    # ── Remove Head Admin list (owner only) ────────────────────────────────
    if data == "ap_remove_hadmin_list":
        if not _ap_is_owner(user.id):
            await query.answer("❌ Only bot owners can manage Head Admins.", show_alert=True)
            return
        hadmins = _ap_get_head_admins()
        removable = [(uid, uname, fname) for uid, uname, fname in hadmins if uid not in OWNER_IDS]
        if not removable:
            await query.edit_message_text(
                "No removable head admins.",
                reply_markup=InlineKeyboardMarkup([_ap_back_btn("ap_hadmin_list")])
            )
            return
        rows = [[InlineKeyboardButton(f"{fname or uname or str(uid)}", callback_data=f"ap_rm_hadmin_confirm:{uid}")]
                for uid, uname, fname in removable]
        rows.append(_ap_back_btn("ap_hadmin_list"))
        await query.edit_message_text("Select Head Admin to remove:", reply_markup=InlineKeyboardMarkup(rows))
        return

    # ── Remove Head Admin confirmation ─────────────────────────────────────
    if data.startswith("ap_rm_hadmin_confirm:"):
        if not _ap_is_owner(user.id):
            await query.answer("❌ Only owners can manage Head Admins.", show_alert=True)
            return
        target_id = int(data.split(":")[1])
        conn = _ap_db()
        cur = conn.cursor()
        cur.execute("SELECT first_name FROM head_admin_details WHERE user_id = ?", (target_id,))
        row = cur.fetchone()
        conn.close()
        name = (row[0] if row else None) or str(target_id)
        kb = InlineKeyboardMarkup([
            [InlineKeyboardButton("Yes", callback_data=f"ap_rm_hadmin_do:{target_id}"),
             InlineKeyboardButton("Back", callback_data="ap_remove_hadmin_list")],
        ])
        await query.edit_message_text(f"Remove Head Admin {name}?", reply_markup=kb)
        return

    # ── Remove Head Admin execute ──────────────────────────────────────────
