        cur.execute(
            "SELECT admin_name, action, target_name, logged_at FROM admin_logs ORDER BY id DESC LIMIT ? OFFSET ?",
            (per_page, offset)
        )
        rows = cur.fetchall()
        cur.execute("SELECT COUNT(*) FROM admin_logs")
        total = cur.fetchone()[0]
        conn.close()

        if not rows:
            await query.edit_message_text(
                "📜 No admin logs yet.",
                reply_markup=InlineKeyboardMarkup([_ap_back_btn()])
            )
            return

        total_pages = max(1, (total + per_page - 1) // per_page)
        lines = [f"📜 Admin Logs (Page {page}/{total_pages})\n"]
        for aname, action, tname, logged_at in rows:
            lines.append(f"• {logged_at}\n  Admin: {aname}\n  Action: {action}\n  Target: {tname or '—'}")

        nav = []
        if page > 1:
            nav.append(InlineKeyboardButton("Prev", callback_data=f"ap_logs:{page-1}"))
        if page < total_pages:
            nav.append(InlineKeyboardButton("Next", callback_data=f"ap_logs:{page+1}"))
        kb_rows = []
