async def _nc_is_restricted(pokemon_id) -> bool:
    """Returns True if the Pokémon is legendary/mythical/UB (restricted in 0L mode)."""
    try:
        pid = int(pokemon_id)
        if pid in _NC_RESTRICTED_DEX:
            return True
    except (ValueError, TypeError):
        pass
    # Fallback: ask PokeAPI species endpoint
    try:
        data = await _cached_pokeapi_get(f"https://pokeapi.co/api/v2/pokemon-species/{str(pokemon_id).lower()}")
        if data:
            return bool(data.get("is_legendary") or data.get("is_mythical"))
    except Exception:
        pass
    return False

# ══════════════════════════════════════════════════════════════════════════
# ═══════════════════════ DYNAMAX ELIGIBILITY SYSTEM ═════════════════════════
# ══════════════════════════════════════════════════════════════════════════
#
# Only regular (non-legendary, non-mythical) Pokémon may Dynamax. This applies
# everywhere Dynamax is offered: /hunt, /challenge, and /randomclash.
#
# The following are NEVER eligible to Dynamax:
#   - Legendary Pokémon (sub-legendaries, box legendaries, cover legendaries,
#     Tapus, Treasures of Ruin, the Loyal Three, etc.)
#   - Mythical Pokémon
#   - Ultra Beasts
#   - Paradox Pokémon
#   - Any Pokémon flagged is_legendary / is_mythical in the bot's data
#
# _DYNAMAX_INELIGIBLE_DEX is the single source of truth: a flattened union of
# every Legendary/Mythical dex ID in REGION_DEX (the bot's own Pokémon
# database) plus the Ultra Beast and Paradox ID sets already used elsewhere
# in this file (GENCODE_ULTRA_BEAST_IDS / GENCODE_PARADOX_IDS), plus a small
# set of IDs/species not yet reflected in those tables (Hisui legendaries
# beyond Arceus, Paldea's box legendaries / Treasures of Ruin / Loyal Three,
# Pecharunt, Meltan/Melmetal, Zeraora, Marshadow, Magearna, Volcanion,
# Diancie, Hoopa, Zygarde, Zarude, Necrozma family, Cosmog family, Solgaleo/
# Lunala, the full Ultra Beast roster, and the Gen 9 Paradox Pokémon
# including Walking Wake / Iron Leaves).
#
# Built once at import time — cheap, static, and synchronous so it can be
# used directly inside the (non-async) keyboard-building functions where
# Dynamax buttons are rendered.

def _dynamax_ineligible_dex_pool() -> set:
    """Union of every dex ID that must never be allowed to Dynamax, built
    from REGION_DEX (Legendary/Mythical) plus the Ultra Beast / Paradox
    pools already defined elsewhere in this file, plus IDs not yet covered
    by those tables."""
    ids: set = set()
    for region_data in REGION_DEX.values():
        ids.update(region_data.get("legendary", []))
        ids.update(region_data.get("mythical", []))
    ids.update(GENCODE_ULTRA_BEAST_IDS)
    ids.update(GENCODE_PARADOX_IDS)
    ids.update(_NC_RESTRICTED_DEX)

    # ── Explicit supplemental IDs (not fully covered by the tables above) ──
    ids.update({
        # Ultra Beasts not already listed above (Poipole line, Stakataka,
        # Blacephalon, Nihilego's neighbors).
        803, 804, 805, 806,
        # Melmetal/Meltan (mythical).
        808, 809,
        # Zarude (mythical).
        893,
        # Gen 9 Paradox Pokémon + box legendaries/Treasures of Ruin/Loyal
        # Three + late mythicals not yet reflected in REGION_DEX/GENCODE_*.
        984, 985, 986, 987, 988, 989, 990, 991, 992, 993, 994, 995,
        1001, 1002, 1003, 1004, 1005, 1006, 1007, 1008, 1009, 1010,
        1014, 1015, 1016, 1017,   # Wo-Chien, Chien-Pao, Ting-Lu, Chi-Yu
        1020, 1021, 1022, 1023,   # Walking Wake, Iron Leaves, Indigo Disk Paradox
        1024,                     # Pecharunt (mythical)
        1025,                     # Ogerpon (mythical)
    })
    return ids


_DYNAMAX_INELIGIBLE_DEX: set = _dynamax_ineligible_dex_pool()

