def _dynamax_species_stem(raw_name: str) -> str:
    """Strip shiny marker / bracket tags / form suffixes so a team entry's
    display name (e.g. 'Giratina-Origin', '✨ Zacian [Tag]') reduces to a
    bare species stem for the name-based Dynamax eligibility fallback."""
    name = _normalize_species_for_mega(raw_name)
    # Drop a trailing "-form" style suffix (origin/crowned/etc.) so
    # "giratina-origin" / "zacian-crowned" still match the base species.
    name = re.split(
        r"[-\s](origin|crowned|therian|incarnate|complete|10%|50%|ash|school|dawn|dusk|ultra|resolute|primal|mega)\b",
        name
    )[0]
    return name.strip()


def is_dynamax_eligible(pkmn: dict) -> bool:
    """
    The single source of truth for Dynamax eligibility, used by every
    Dynamax button/callback across /hunt, /challenge, and /randomclash.

    Only regular (non-legendary, non-mythical) Pokémon may Dynamax. Returns
    False for Legendary, Mythical, Ultra Beast, and Paradox Pokémon,
    regardless of how they're framed (cover legendary, sub-legendary, box
    legendary, Tapu, Treasure of Ruin, Loyal Three, etc. — these are all
    just Legendary/Mythical Pokémon under the hood).

    Checks, in order:
      1. Explicit is_legendary / is_mythical flags on the dict, if ever set.
      2. The Pokémon's dex_id / id against _DYNAMAX_INELIGIBLE_DEX.
      3. The Pokémon's name (species stem) against _DYNAMAX_INELIGIBLE_NAMES
         — needed for form-slug entries (e.g. RandomClash Origin/Crowned
         forms) that may not carry a resolvable numeric dex_id.

    Accepts either a battle-side Pokémon dict (with dex_id/id + name) or is
    otherwise permissive (defaults to eligible) if no identifying info is
    present, so a lookup failure never silently blocks a normal Pokémon.
    """
    if not isinstance(pkmn, dict):
        return True

    if pkmn.get("is_legendary") or pkmn.get("is_mythical"):
        return False

    dex_id = pkmn.get("dex_id")
    if dex_id is None:
        dex_id = pkmn.get("id")
    if dex_id is not None:
        try:
            if int(dex_id) in _DYNAMAX_INELIGIBLE_DEX:
                return False
        except (ValueError, TypeError):
            pass

    name = pkmn.get("name")
    if name:
        stem = _dynamax_species_stem(name)
        if stem in _DYNAMAX_INELIGIBLE_NAMES:
            return False

    return True

# ─── NC challenge UI builder ──────────────────────────────────────────────────

def _nc_challenge_text(data: dict) -> str:
    s   = data["settings"]
    p1  = data["p1_name"]
    p2  = data["p2_name"]
    bs  = data["battle_state"]
    p1r = "✅ ready" if bs.get("p1_ready") else "❌ not ready"
    p2r = "✅ ready" if bs.get("p2_ready") else "❌ not ready"
    sw  = "ON" if s.get("switch") else "OFF"
    se  = "ON" if s.get("status_effects", True) else "OFF"
    sz  = f"{s.get('size',6)}v{s.get('size',6)}"
    mode_disp = _NC_MODE_DISPLAY.get(s.get("mode", "Open"), s.get("mode", "Open"))
    return (
        f"⚔️ <b>{p1}</b> <b>has challenged</b> <b>{p2}</b> <b>to a battle!</b>\n\n"
        f"<b>{p1}</b> <b>is {p1r}</b>\n"
        f"<b>{p2}</b> <b>is {p2r}</b>\n\n"
        f"<b>Current Settings:</b>\n"
        f"<b>Mode:</b> <code>{mode_disp}</code>  <b>|  Size:</b> <code>{sz}</code>\n"
        f"<b>Switch:</b> <code>{sw}</code>  <b>|  Status:</b> <code>{se}</code>"
    )

def _nc_challenge_kbd(battle_id: str) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("Accept", callback_data=f"nc_accept:{battle_id}"),
         InlineKeyboardButton("Decline", callback_data=f"nc_decline:{battle_id}")],
        [InlineKeyboardButton("Settings", callback_data=f"nc_settings:{battle_id}")]
    ])

# Friendly display names for internal mode values (internal values kept as-is
# for backward-compatible battle-rule logic; only the label shown to the
# trainer changes).
_NC_MODE_DISPLAY = {"Open": "Open", "6L": "6v6", "0L": "0v0", "Mix": "Mix"}

def _nc_settings_text(data: dict) -> str:
    s  = data["settings"]
    sw = "ON" if s.get("switch") else "OFF"
    se = "ON" if s.get("status_effects", True) else "OFF"
    wt = "ON" if s.get("weather", True) else "OFF"
    dm = "ON" if s.get("dynamax", False) else "OFF"
    sz = s.get("size", 6)
    mode_disp = _NC_MODE_DISPLAY.get(s.get("mode", "Open"), s.get("mode", "Open"))
    return (
        "<b>Battle Settings</b>\n\n"
        f"<b>Mode:</b> <code>{mode_disp}</code>\n"
        f"<b>Team Size:</b> <code>{sz}v{sz}</code>\n"
        f"<b>Switch:</b> <code>{sw}</code>\n"
        f"<b>Status Effects:</b> <code>{se}</code>\n"
        f"<b>Weather:</b> <code>{wt}</code>\n"
        f"<b>Dynamax:</b> <code>{dm}</code>\n\n"
        "<b>Configure the battle rules before starting.</b>"
    )

def _nc_settings_kbd(battle_id: str, s: dict) -> InlineKeyboardMarkup:
    sw_label = "Switch: On" if s.get("switch") else "Switch: Off"
    se_label = "Status Effects: On" if s.get("status_effects", True) else "Status Effects: Off"
    wt_label = "Weather: On" if s.get("weather", True) else "Weather: Off"
    dm_label = "Dynamax: On" if s.get("dynamax", False) else "Dynamax: Off"

    return InlineKeyboardMarkup([
        [InlineKeyboardButton("Open", callback_data=f"nc_mode:{battle_id}:Open"),
         InlineKeyboardButton("6v6",  callback_data=f"nc_mode:{battle_id}:6L"),
         InlineKeyboardButton("0v0",  callback_data=f"nc_mode:{battle_id}:0L")],
        [InlineKeyboardButton("Mix", callback_data=f"nc_mode:{battle_id}:Mix")],
        [InlineKeyboardButton("1", callback_data=f"nc_sz:{battle_id}:1"),
         InlineKeyboardButton("2", callback_data=f"nc_sz:{battle_id}:2"),
         InlineKeyboardButton("3", callback_data=f"nc_sz:{battle_id}:3")],
        [InlineKeyboardButton("4", callback_data=f"nc_sz:{battle_id}:4"),
         InlineKeyboardButton("5", callback_data=f"nc_sz:{battle_id}:5"),
         InlineKeyboardButton("6", callback_data=f"nc_sz:{battle_id}:6")],
        [InlineKeyboardButton(sw_label, callback_data=f"nc_sw:{battle_id}")],
        [InlineKeyboardButton(se_label, callback_data=f"nc_se:{battle_id}")],
        [InlineKeyboardButton(wt_label, callback_data=f"nc_wt:{battle_id}")],
        [InlineKeyboardButton(dm_label, callback_data=f"nc_dm:{battle_id}")],
        [InlineKeyboardButton("Reset", callback_data=f"nc_reset:{battle_id}"),
         InlineKeyboardButton("Save",  callback_data=f"nc_save:{battle_id}"),
         InlineKeyboardButton("Back",  callback_data=f"nc_saveback:{battle_id}")],
    ])

# ─── Mega Evolution helpers ───────────────────────────────────────────────────

def _normalize_species_for_mega(raw_name: str) -> str:
    """
    Strip display-only decoration from a Pokémon name and return the bare
    lowercase species string that MEGA_STONES / MEGA_FORM_DATA are keyed on.

    Handles all three decoration patterns the codebase produces:
      "✨ Charizard"       → "charizard"
      "Charizard [Tidal]"  → "charizard"
      "✨ Mewtwo [Tag]"    → "mewtwo"

    Rules (applied in order):
      1. Strip the shiny marker (✨) and any surrounding whitespace.
      2. Strip a trailing [Tag] suffix (square-bracket content).
      3. Lowercase and strip residual whitespace.

    This must NOT strip hyphens or regional suffixes — "ninetales-alola" must
    stay "ninetales-alola" so it still resolves in MEGA_STONES if ever added.
    Only the shiny emoji and bracket tags are removed.
    """
    name = str(raw_name or "").strip()
    name = name.replace("✨", "")                  # remove shiny marker
    name = re.sub(r"\[[^\]]*\]", "", name)         # remove [Tag] suffix
    return name.strip().lower()


def _mega_check_inventory(user_id: int, species_lower: str) -> list[str]:
    """
    Return the list of Mega Stones in the trainer's inventory that match
    this species.  Returns [] when the trainer owns no Keystone, or no
    matching stone, or the species does not support Mega Evolution.
    """
    # 1. Does the species support Mega Evolution?
    possible_stones = MEGA_STONES.get(species_lower)
    if not possible_stones:
        return []

    # 2. Does the trainer own a Keystone?
    profile = get_user(user_id)
    if not profile or not profile.get("has_keystone"):
        return []
    conn = get_db("ZNX.db")
    cur  = conn.cursor()

    # 3. Which matching stones does the trainer own (qty ≥ 1)?
    owned = []
    for stone in possible_stones:
        cur.execute(
            "SELECT quantity FROM user_stones WHERE user_id=? AND LOWER(TRIM(stone_name))=?",
            (user_id, stone.lower().strip()),
        )
        srow = cur.fetchone()
        if srow and srow[0] and srow[0] >= 1:
            owned.append(stone)
    conn.close()
    return owned


def _special_form_check_inventory(user_id: int, species_lower: str) -> list[dict]:
    """
    Return a list of form-info dicts for each special transformation item the
    trainer owns that applies to this species (Dialga, Palkia, Giratina,
    Zacian, Zamazenta, Calyrex).

    Looks up SPECIAL_FORM_DATA by (species_lower, item_display_name_lower) and
    checks user_stones using the item display name (e.g. "Ice Root Carrot"),
    NOT an underscore slug, to avoid the comparison mismatch bug.

    Returns [] when the trainer owns no relevant item for this species.
    Each returned dict has keys:
        item_lower, display_name, sprite_slug, pokeapi_slug, button_label, types
    """
    results = []
    conn = sqlite3.connect("ZNX.db")
    cur  = conn.cursor()
    for (sp, item_lower), form_info in SPECIAL_FORM_DATA.items():
        if sp != species_lower:
            continue
        # Compare using item display name (lowercased) — NOT underscore slug.
        cur.execute(
            "SELECT quantity FROM user_stones "
            "WHERE user_id=? AND LOWER(TRIM(stone_name))=?",
            (user_id, item_lower),
        )
        srow = cur.fetchone()
        if srow and srow[0] and srow[0] >= 1:
            display_name, sprite_slug, pokeapi_slug, button_label, types = form_info
            results.append({
                "item_lower":   item_lower,
                "display_name": display_name,
                "sprite_slug":  sprite_slug,
                "pokeapi_slug": pokeapi_slug,
                "button_label": button_label,
                "types":        types,
            })
    conn.close()
    return results


def _special_form_trainer_key(data: dict, user_id: int) -> str:
    """Return the unified per-trainer transformation flag in battle_state.
    Both Mega Evolution and Special Form (Origin/Crowned/Rider) share this
    single flag — only ONE transformation is allowed per trainer per battle."""
    return "transform_used1" if user_id == data["p1_id"] else "transform_used2"


def _base_species_for_mega(species_lower: str) -> str:
    """
    Strip gender suffixes (-male, -female) so gendered forms resolve to the
    correct MEGA_FORM_DATA key.  E.g. "pyroar-male" → "pyroar".
    Only strips known gender suffixes — all other hyphens (regional forms,
    etc.) are left intact.
    """
    for suffix in ("-male", "-female"):
        if species_lower.endswith(suffix):
            return species_lower[: -len(suffix)]
    return species_lower


def _mega_resolve_form(species_lower: str, stone_name: str) -> dict | None:
    """
    Given a species name (lower) and the stone the trainer activated,
    return the Mega form metadata dict or None if not found.

    Strips gender suffixes (-male / -female) before lookup so that
    "pyroar-male" and "pyroar-female" both resolve to the "pyroar" entry
    in MEGA_FORM_DATA (which stores a single shared Mega form).

    Returns:
        {
            "display_name": "Mega Charizard X",
            "sprite_slug":  "charizard-megax",   # used in _nc_sprite_url
            "pokeapi_slug": "charizard-mega-x",  # used to fetch mega stats
            "types":        ["fire", "dragon"],
        }
    """
    cache_key = (species_lower, stone_name.lower())
    if cache_key in _MEGA_RESOLVE_CACHE:
        return _MEGA_RESOLVE_CACHE[cache_key]
    base = _base_species_for_mega(species_lower)
    stone_lower = stone_name.lower()
    # Try the exact (possibly gendered) key first, then the base species.
    entry = MEGA_FORM_DATA.get((species_lower, stone_lower)) or MEGA_FORM_DATA.get((base, stone_lower))
    if entry is None:
        _MEGA_RESOLVE_CACHE[cache_key] = None
        return None
    display, sprite_slug, pokeapi_slug, types = entry
    result = {
        "display_name": display,
        "sprite_slug":  sprite_slug,
        "pokeapi_slug": pokeapi_slug,
        "types":        types,
    }
    _MEGA_RESOLVE_CACHE[cache_key] = result
    return result


def _mega_trainer_key(data: dict, user_id: int) -> str:
    """Return the unified per-trainer transformation flag in battle_state.
    Mega Evolution and Special Form (Origin/Crowned/Rider) share this flag —
    only ONE transformation of any kind is allowed per trainer per battle."""
    return "transform_used1" if user_id == data["p1_id"] else "transform_used2"


def _mega_already_used(data: dict, user_id: int) -> bool:
    """Return True if this trainer already used their one Mega Evolution (or
    Special Form transformation — they share the transform_used1/2 flag) this
    battle, OR has already Dynamaxed this battle.

    Mega Evolution and Dynamax are mutually exclusive per trainer per battle:
    using either one locks out the other for the rest of the battle, so this
    also checks the Dynamax flag before allowing a Mega Evolution."""
    bs = data["battle_state"]
    return bool(bs.get(_mega_trainer_key(data, user_id))) or bool(bs.get(_dynamax_trainer_key(data, user_id)))


def _dynamax_trainer_key(data: dict, user_id: int) -> str:
    """Return the per-trainer Dynamax-used flag in battle_state. This is
    stored separately from _mega_trainer_key's transform_used1/2, but the two
    are cross-checked (see _mega_already_used / _dynamax_already_used) so
    that Mega Evolution and Dynamax remain mutually exclusive — only ONE
    major transformation per trainer per battle."""
    return "dynamax_used1" if user_id == data["p1_id"] else "dynamax_used2"


def _dynamax_already_used(data: dict, user_id: int) -> bool:
    """Return True if this trainer already used their one Dynamax this battle,
    OR has already used a Mega Evolution / Special Form transformation this
    battle.

    Mega Evolution and Dynamax are mutually exclusive per trainer per battle:
    using either one locks out the other for the rest of the battle, so this
    also checks the Mega/transform flag before allowing a Dynamax."""
    bs = data["battle_state"]
    return bool(bs.get(_dynamax_trainer_key(data, user_id))) or bool(bs.get(_mega_trainer_key(data, user_id)))


# Cache for raw Mega base stats (slug → {stat_name: base_stat}).
# Base stats are immutable game data — cache forever.
_MEGA_BASE_STATS_CACHE: dict[str, dict] = {}

async def _mega_fetch_stats(pokeapi_slug: str, level: int, ivs: dict, evs: dict, nature: str) -> dict | None:
    """
    Fetch base stats for a Mega form from PokéAPI and apply the standard
    stat formula.  Returns dict with keys: attack, defense, sp_atk, sp_def,
    speed  (HP is intentionally excluded — it never changes on Mega Evolution).
    Returns None on network/API failure.

    Base stats are cached permanently after the first fetch; only the final
    calc (which depends on the trainer's IVs/EVs/Nature/Level) is computed
    each time.
    """
    try:
        # ── Fetch (or load from cache) the raw base stats ─────────────────────
        if pokeapi_slug in _MEGA_BASE_STATS_CACHE:
            base = _MEGA_BASE_STATS_CACHE[pokeapi_slug]
        else:
            url  = f"https://pokeapi.co/api/v2/pokemon/{pokeapi_slug}"
            data = await _cached_pokeapi_get(url)
            if data is None:
                return None
            base = {s["stat"]["name"]: s["base_stat"] for s in data.get("stats", [])}
            _MEGA_BASE_STATS_CACHE[pokeapi_slug] = base

        def calc(stat_name, iv_key, ev_key):
            b  = base.get(stat_name, 50)
            iv = ivs.get(iv_key, 0)
            ev = evs.get(ev_key, 0)
            return math.floor((((2 * b + iv + ev / 4) * level) / 100 + 5)
                              * get_nature_modifier(nature, stat_name))

        return {
            "attack":  calc("attack",          "attack",          "attack"),
            "defense": calc("defense",         "defense",         "defense"),
            "sp_atk":  calc("special-attack",  "special-attack",  "special-attack"),
            "sp_def":  calc("special-defense", "special-defense", "special-defense"),
            "speed":   calc("speed",           "speed",           "speed"),
        }
    except Exception as e:
        logger.warning(f"[MEGA] Failed to fetch mega stats for {pokeapi_slug}: {e}")
        return None


# ─── End Mega Evolution helpers ────────────────────────────────────────────────


# ─── Battle UI builder ────────────────────────────────────────────────────────

def _nc_types_str(types: list) -> str:
    return "/".join(TYPE_EMOJIS.get(t, "") for t in types)

def _nc_battle_text(data: dict) -> str:
    bs      = data["battle_state"]
    p1_name = data["p1_name"]
    p2_name = data["p2_name"]
    t1      = bs.get("team1", [])
    t2      = bs.get("team2", [])
    idx1    = bs.get("active1", 0)
    idx2    = bs.get("active2", 0)
    log     = bs.get("log", "")
    turn_id = bs.get("turn")

    # ── Weather header ────────────────────────────────────────────────────────
    weather_key  = bs.get("weather")
    weather_left = bs.get("weather_turns_left", 0)
    weather_line = ""
    if weather_key and weather_left > 0:
        weather_line = f"🌦️ <b>{_nc_weather_label(weather_key)}</b> — {weather_left} turn{'s' if weather_left != 1 else ''} remaining"

    def slot(team, idx):
        if not team or idx >= len(team): return None
        return team[idx]

    p1_pkmn = slot(t1, idx1)
    p2_pkmn = slot(t2, idx2)

    # Dynamic positioning: waiting trainer FIRST, active trainer SECOND
    current_is_p1 = (turn_id == data["p1_id"])
    if current_is_p1:
        top_name,    top_pkmn    = p2_name, p2_pkmn   # waiting — shown first
        bottom_name, bottom_pkmn = p1_name, p1_pkmn   # active  — shown second
        move_pkmn = p1_pkmn
    else:
        top_name,    top_pkmn    = p1_name, p1_pkmn   # waiting — shown first
        bottom_name, bottom_pkmn = p2_name, p2_pkmn   # active  — shown second
        move_pkmn = p2_pkmn

    def _pkmn_display_name(pkmn):
        """Return the correct display name respecting Mega, Dynamax, shiny, nickname, and special_tag."""
        shiny_tag = "✨ " if pkmn.get("shiny") else ""
        if pkmn.get("is_mega") and pkmn.get("mega_display_name"):
            base_name = pkmn["mega_display_name"]
        else:
            base_name = pkmn['name']
        dynamax_tag = " ★" if pkmn.get("is_dynamaxed") else ""
        return f"{shiny_tag}{base_name}{dynamax_tag}"

    def render_side(trainer_name, pkmn):
        if not pkmn:
            return (
                f"Trainer: <b>{trainer_name}</b>\n"
                f"Pokemon: <b>(no Pokémon)</b>"
            )
        hp         = pkmn.get("hp", 0)
        maxhp      = pkmn.get("max_hp", 1)
        types      = _nc_types_str(pkmn.get("types", []))
        name       = _pkmn_display_name(pkmn)
        bar        = generate_hp_bar(hp, maxhp)
        status_tag = f" [{pkmn['status'].upper()}]" if pkmn.get("status") else ""
        return (
            f"Trainer: <b>{trainer_name}</b>\n"
            f"Pokemon: <b>{name} [{types}]{status_tag}</b>\n"
            f"Lv. {pkmn.get('level', 1)} • HP {hp} / {maxhp}\n"
            f"{bar}"
        )

    # ── Parse the battle log into structured parts ────────────────────────────
    # Log format (from the move handler):
    #   Line 0:  "<b>{atk_name}</b> used <b>{move_name}</b>"   ← always present after a move
    #   Line 1+: effectiveness / crit / damage / faint lines
    # Other logs (speed tie, switch, weather, etc.) don't follow this pattern.
    log_header   = ""   # e.g. "<b>Rapidash Galar</b> used <b>Megahorn</b>"
    log_effect   = []   # italic effectiveness / crit lines
    log_damage   = ""   # "Dealt <b>35</b> damage"
    log_misc     = []   # everything else (faint, weather lines, etc.)

    import re as _re_log
    if log:
        raw_lines = log.split("\n")
        # Detect "X used Y" pattern on the first non-empty line
        first = raw_lines[0].strip() if raw_lines else ""
        used_pattern = _re_log.match(r"^<b>.+?</b> used <b>.+?</b>$", first)
        if used_pattern:
            log_header = first
            effect_keywords = {
                "It's super effective!",
                "It's not very effective...",
                "It doesn't affect the opponent's Pokémon...",
                "A critical hit!",
                "But it missed!",
                "The weather powered up the attack!",
                "The weather weakened the attack.",
                "(Status move — no damage)",
            }
            for line in raw_lines[1:]:
                stripped = line.strip()
                if not stripped:
                    continue
                if stripped in effect_keywords:
                    log_effect.append(stripped)
                elif stripped.startswith("Dealt "):
                    log_damage = stripped
                else:
                    log_misc.append(stripped)
        else:
            # Non-move log (speed tie, switch, Mega, weather, faint, etc.)
            log_misc = [l.strip() for l in raw_lines if l.strip()]

    # ── Assemble output ───────────────────────────────────────────────────────
    lines = []

    if weather_line:
        lines.append(weather_line)
        lines.append("")

    # ── Move summary block (only after a move was used) ───────────────────────
    if log_header:
        lines.append(log_header)
        for eff in log_effect:
            lines.append(f"<i>{eff}</i>")
        if log_damage:
            lines.append(log_damage)
        if log_misc:
            for ml in log_misc:
                lines.append(ml)
        lines.append("")

    elif log_misc:
        # Non-move log (speed tie, switch, etc.)
        for ml in log_misc:
            lines.append(ml)
        lines.append("")

    # ── Previous attacker's side (waiting trainer) ────────────────────────────
    lines.append(render_side(top_name, top_pkmn))
    lines.append("")

    # ── Current turn divider ──────────────────────────────────────────────────
    lines.append("Current Turn:")

    # ── Active trainer's side ─────────────────────────────────────────────────
    lines.append(render_side(bottom_name, bottom_pkmn))
    lines.append("")

    # ── Active trainer's moves ────────────────────────────────────────────────
    if move_pkmn:
        for m in move_pkmn.get("moves", []):
            acc        = _display_accuracy(m.get("accuracy"))
            pw         = m.get("power") or "—"
            mtype      = m.get("type", "normal")
            type_emoji = TYPE_EMOJIS.get(mtype, "")
            move_label = m["name"].replace("-", " ").title()
            lines.append(
                f"• <b>{move_label} [{mtype.capitalize()}{type_emoji}]</b>\n"
                f"<b>Power:</b> {pw} | <b>Accuracy:</b> {acc}"
            )

    return "\n".join(lines).rstrip()

def _nc_battle_kbd(battle_id: str, data: dict) -> InlineKeyboardMarkup:
    bs = data["battle_state"]
    turn_id = bs.get("turn")
    current_is_p1 = (turn_id == data["p1_id"])
    current_pkmn_idx = bs.get("active1" if current_is_p1 else "active2", 0)
    team = bs.get("team1" if current_is_p1 else "team2", [])
    current_pkmn = team[current_pkmn_idx] if team and current_pkmn_idx < len(team) else None

    rows = []
    if current_pkmn:
        moves = current_pkmn.get("moves", [])
        move_btns = []
        for i, m in enumerate(moves):
            mtype = m.get("type", "normal")
            type_emoji = TYPE_EMOJIS.get(mtype, "")
            lbl = f"{m['name'].replace('-',' ').title()}"
            move_btns.append(InlineKeyboardButton(lbl, callback_data=f"nc_move:{battle_id}:{i}"))
        # Pair moves into rows of 2
        for j in range(0, len(move_btns), 2):
            rows.append(move_btns[j:j+2])

    # ── Mega Evolve button(s) ─────────────────────────────────────────────────
    # Show if: Pokémon supports Mega, trainer owns Keystone + matching stone,
    # hasn't already used any transformation this battle, and the Pokémon hasn't
    # already transformed (is_mega flag).
    #
    # Species with two Mega Forms (e.g. Charizard, Mewtwo) get a separate
    # button per stone the trainer actually owns — [Mega X] [Mega Y] — so the
    # trainer picks the form explicitly instead of one stone being silently
    # auto-selected for them.
    #
    # Unified flag: _mega_trainer_key == _special_form_trainer_key → both return
    # "transform_used1" / "transform_used2". Only ONE transformation per trainer.
    if current_pkmn and not _mega_already_used(data, turn_id):
        # Normalize before the MEGA_STONES lookup — strip shiny markers (✨)
        # and [Tag] suffixes so "✨ Charizard" and "Charizard [Tidal]" both
        # resolve to "charizard".  Do NOT use .lower() on the raw name directly.
        species_lower = _normalize_species_for_mega(current_pkmn.get("name", ""))
        eligible_stones = _mega_check_inventory(turn_id, species_lower)
        if eligible_stones and not current_pkmn.get("is_mega"):
            mega_btns = []
            for stone in eligible_stones:
                stone_lower = stone.lower()
                if stone_lower.endswith(" x"):
                    label = "⚡ Mega X"
                elif stone_lower.endswith(" y"):
                    label = "⚡ Mega Y"
                elif stone_lower.endswith(" z"):
                    label = "⚡ Mega Z"
                else:
                    label = "⚡ Mega Evolve"
                stone_token = stone.replace(" ", "_")
                mega_btns.append(
                    InlineKeyboardButton(label, callback_data=f"nc_mega:{battle_id}:{stone_token}")
                )
            rows.append(mega_btns)

    # ── Special Form buttons (Origin / Crowned / Rider) ────────────────────────
    # Used by Dialga, Palkia, Giratina, Zacian, Zamazenta, Calyrex.
    # No Keystone required — only the specific transformation item.
    # Lookup uses SPECIAL_FORM_DATA (not MEGA_STONES / MEGA_FORM_DATA).
    # Inventory check uses item display names ("Ice Root Carrot"), not slugs.
    # Unified flag: same "transform_used1/2" key as Mega — at most ONE
    # transformation of ANY kind per trainer per battle.
    if current_pkmn and not current_pkmn.get("is_mega") and not bs.get(_special_form_trainer_key(data, turn_id)):
        sf_species = _normalize_species_for_mega(current_pkmn.get("name", ""))
        special_forms = _special_form_check_inventory(turn_id, sf_species)
        if special_forms:
            sf_btns = []
            for sf in special_forms:
                item_token = sf["item_lower"].replace(" ", "_")
                sf_btns.append(
                    InlineKeyboardButton(
                        sf["button_label"],
                        callback_data=f"nc_special_form:{battle_id}:{item_token}"
                    )
                )
            rows.append(sf_btns)

    # ── Dynamax button ──────────────────────────────────────────────────────
    # Mutually exclusive with Mega Evolution (and Special Form) — a trainer
    # who has already used either one this battle will never see this button.
    # _dynamax_already_used() checks both the Dynamax flag and the
    # Mega/transform flag, so only ONE major transformation per trainer per
    # battle is ever possible.
    dynamax_enabled = data["settings"].get("dynamax", False)
    if (dynamax_enabled and current_pkmn and not current_pkmn.get("is_dynamaxed")
            and not _dynamax_already_used(data, turn_id)):
        band_key = "p1_has_dynamax_band" if turn_id == data["p1_id"] else "p2_has_dynamax_band"
        if bs.get(band_key) and is_dynamax_eligible(current_pkmn):
            rows.append([InlineKeyboardButton("Dynamax", callback_data=f"nc_dynamax:{battle_id}")])

    draw_label = "🤝 Draw"
    bs_draw_req = bs.get("draw_request")
    if bs_draw_req and bs_draw_req != turn_id:
        draw_label = "🤝 Accept Draw"
    action_row = [
        InlineKeyboardButton("Switch",  callback_data=f"nc_switch_menu:{battle_id}"),
        InlineKeyboardButton(draw_label,   callback_data=f"nc_draw:{battle_id}"),
        InlineKeyboardButton("Forfeit", callback_data=f"nc_forfeit:{battle_id}"),
    ]
    rows.append(action_row)
    return InlineKeyboardMarkup(rows)


def _battle_kbd(battle_id: str, data: dict) -> InlineKeyboardMarkup:
    """
    Unified keyboard dispatcher: returns _rc_battle_kbd for randomclash battles
    and _nc_battle_kbd for challenge (/roclash) battles.

    Use this everywhere a battle keyboard needs to be rebuilt so that the correct
    Mega Evolution check is applied:
      - randomclash  → no Keystone / Mega Stone required  (_rc_battle_kbd)
      - challenge    → Keystone + Mega Stone required      (_nc_battle_kbd)
    """
    if _is_rc_battle(battle_id):
        return _rc_battle_kbd(battle_id, data)
    return _nc_battle_kbd(battle_id, data)


def _nc_switch_kbd(battle_id: str, data: dict, for_player_id: int, forced: bool = False) -> InlineKeyboardMarkup:
    """Switch selection keyboard. forced=True means after a faint (no Back button)."""
    bs   = data["battle_state"]
    is_p1 = (for_player_id == data["p1_id"])
    team  = bs.get("team1" if is_p1 else "team2", [])
    active_idx = bs.get("active1" if is_p1 else "active2", 0)
    fainted = set(bs.get("fainted1" if is_p1 else "fainted2", []))

    rows = [[InlineKeyboardButton("View Team", callback_data=f"nc_viewteam:{battle_id}")]]
    btns = []
    for i, pkmn in enumerate(team):
        if i == active_idx and not forced:
            btns.append(InlineKeyboardButton(" ", callback_data="nc_noop"))
        elif i in fainted or is_pokemon_in_camp(pkmn.get("db_id", 0)):
            btns.append(InlineKeyboardButton(f"[{i+1}]", callback_data="nc_noop"))
        else:
            btns.append(InlineKeyboardButton(str(i+1), callback_data=f"nc_switch:{battle_id}:{i}"))
        if len(btns) == 2:
            rows.append(btns)
            btns = []
    if btns:
        rows.append(btns)
    if not forced:
        rows.append([InlineKeyboardButton("Back", callback_data=f"nc_switchback:{battle_id}")])
    return InlineKeyboardMarkup(rows)

# ─── Team selection helpers ───────────────────────────────────────────────────

def _nc_team_select_text(data: dict, player_id: int, selected: list) -> str:
    is_p1   = (player_id == data["p1_id"])
    name    = data["p1_name"] if is_p1 else data["p2_name"]
    size    = data["settings"].get("size", 6)
    return (
        f"⚔️ <b>{name}</b>, select your team!\n"
        f"Choose <b>{size}</b> Pokémon from your squad.\n"
        f"Selected: {len(selected)}/{size}\n\n"
        "Tap a Pokémon to toggle selection."
    )

def _nc_team_select_kbd(battle_id: str, squad_pids: list, selected: list, player_id: int, size: int) -> InlineKeyboardMarkup:
    """Keyboard for team selection from squad. squad_pids = list of (db_id, name, level, shiny)."""
    rows = []
    row  = []
    for db_id, name, level, shiny in squad_pids:
        in_camp = is_pokemon_in_camp(db_id)
        tag = "✨ " if shiny else ""
        if in_camp:
            label = f"🏕 {tag}{name}"
            btn   = InlineKeyboardButton(label, callback_data="nc_camp_block")
        elif db_id in selected:
            label = f"✅ {tag}{name} Lv.{level}"
            btn   = InlineKeyboardButton(label, callback_data=f"nc_seldesel:{battle_id}:{db_id}")
        else:
            label = f"{tag}{name} Lv.{level}"
            btn   = InlineKeyboardButton(label, callback_data=f"nc_seldesel:{battle_id}:{db_id}")
        row.append(btn)
        if len(row) == 2:
            rows.append(row)
            row = []
    if row:
        rows.append(row)
    if len(selected) == size:
        rows.append([InlineKeyboardButton("Confirm Team", callback_data=f"nc_confirmteam:{battle_id}")])
    return InlineKeyboardMarkup(rows)

# ─── Daily RoRupee earning cap helper ──────────────────────────────────────

DAILY_NR_CAP = 5000  # Maximum NR earnable per day from /hunt, /challenge, /randomclash

def _apply_nr_cap(user_id: int, requested_amount: int) -> int:
    """
    Apply the 5,000 NR daily earning cap for /hunt, /challenge, /randomclash.

    Returns the ACTUAL amount to award (0 if cap already reached, or a partial
    amount if the full reward would exceed the remaining allowance).

    The cap resets at 05:30 IST using the same _safari_reset_date() cycle as
    Safari Zone and /daily.

    EXCLUDED sources (do NOT call this function for):
      • /daily reward
      • Admin rewards / add_nova_rupee
      • Redeem codes
      • Gifts / transfers / events / compensation

    Reads + writes daily_nr_earned/daily_nr_cycle as one atomic, non-yielding
    step against USER_CACHE (no `await` anywhere in this function) — same
    reasoning as increment_user(), which is what keeps two hunts/battles
    landing back-to-back for the same trainer from racing each other on the
    cap check.
    """
    if requested_amount <= 0:
        return 0
    today = _safari_reset_date()
    profile = get_user(user_id)
    if profile is None:
        return requested_amount  # Unregistered user — no cap tracking yet

    earned = profile.get("daily_nr_earned") or 0
    cycle = profile.get("daily_nr_cycle") or ""

    # New cycle → reset counter
    if cycle != today:
        earned = 0
        profile["daily_nr_earned"] = 0
        profile["daily_nr_cycle"] = today
        _USER_CACHE_DIRTY.add(user_id)

    remaining = max(0, DAILY_NR_CAP - earned)
    actual = min(requested_amount, remaining)

    if actual > 0:
        profile["daily_nr_earned"] = earned + actual
        profile["daily_nr_cycle"] = today
        _USER_CACHE_DIRTY.add(user_id)

    return actual

# ─── Reward helpers ───────────────────────────────────────────────────────────

def _nc_award_rupees(user_id: int, amount: int) -> int:
    """
    Award NR from a battle (challenge / randomclash) respecting the daily cap.
    Returns the ACTUAL amount awarded (may be 0 or partial if cap is reached).
    """
    actual = _apply_nr_cap(user_id, amount)
    if actual <= 0:
        return 0
    increment_user(user_id, nova_rupee=actual)
    return actual

def _nc_deduct_rupees(user_id: int, amount: int) -> None:
    profile = get_user(user_id)
    if profile is None:
        return
    current = profile.get("nova_rupee") or 0
    profile["nova_rupee"] = max(0, current - amount)
    _USER_CACHE_DIRTY.add(user_id)

# ─── Daily NR limit notification helpers ─────────────────────────────────────

def _is_daily_nr_over_cap(user_id: int) -> bool:
    """Returns True if the user has already hit the 5,000 NR daily cap today."""
    today = _safari_reset_date()
    profile = get_user(user_id)
    if profile is None:
        return False
    earned = profile.get("daily_nr_earned") or 0
    cycle = profile.get("daily_nr_cycle") or ""
    return cycle == today and earned >= DAILY_NR_CAP


def _should_notify_daily_nr_limit(user_id: int) -> bool:
    """Returns True when the cap is reached AND the one-time notice hasn't been
    sent yet for today's reset cycle."""
    if not _is_daily_nr_over_cap(user_id):
        return False
    today = _safari_reset_date()
    profile = get_user(user_id)
    if profile is None:
        return False
    return (profile.get("daily_nr_limit_notified") or "") != today


def _mark_nr_limit_notified(user_id: int) -> None:
    """Mark the daily NR limit notification as sent for today's cycle."""
    today = _safari_reset_date()
    update_user(user_id, daily_nr_limit_notified=today)


# Message sent once when a trainer first hits the 5,000 NR daily cap.
DAILY_NR_LIMIT_NOTICE = (
    "⚠️ <b><u>Daily NR Limit Reached!</u></b>\n\n"
    "<i>You've reached today's maximum limit for earning</i> <b>💶 RoRupees</b>.\n\n"
    "You can still earn NR, but the rewards will be <b>Lower than usual</b>.\n\n"
    "<i>Come back after the daily reset to earn full rewards again!</i>"
)

