def _nc_normalize_sprite(name: str) -> str:
    """Normalize a Pokémon name to the PokemonShowdown sprite filename stem."""
    key = name.lower().strip()
    if key in _NC_SPRITE_FORM_MAP:
        return _NC_SPRITE_FORM_MAP[key]
    # Try partial prefix match for e.g. "Alcremie-RubyCream" style stored names
    for full_key, mapped in _NC_SPRITE_FORM_MAP.items():
        if key == full_key:
            return mapped
    # Generic: remove spaces, punctuation; lowercase
    normalized = key.replace(" ", "").replace(".", "").replace("'", "").replace("-", "")
    # Re-add hyphen for known regional/form patterns after stripping spaces
    # e.g. "ninetalesalola" -> "ninetales-alola"
    for suffix in [
        "alola", "galar", "hisui", "paldea",
        "blade", "origin", "altered", "sunny", "rainy", "snowy", "sunshine",
        "chill", "burn", "douse", "shock",
        "rubycream", "matchacream", "mintcream", "lemoncream", "saltedcream",
        "combat", "blaze", "aqua",
    ]:
        if normalized.endswith(suffix) and len(normalized) > len(suffix):
            base = normalized[: len(normalized) - len(suffix)]
            return f"{base}-{suffix}"
    return normalized

def _nc_sprite_url(dex_id: int, back: bool = False, shiny: bool = False) -> str | None:
    """Return PokeAPI sprite URL for a given numeric dex_id.
    Uses shiny sprite paths when shiny=True.
    Returns None if dex_id is falsy."""
    if not dex_id:
        return None
    if back:
        if shiny:
            return f"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/back/shiny/{dex_id}.png"
        else:
            return f"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/back/{dex_id}.png"
    else:
        if shiny:
            return f"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/shiny/{dex_id}.png"
        else:
            return f"https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/{dex_id}.png"

def _nc_build_battle_image_url(data: dict) -> tuple[str, str]:
    """
    Build the back-sprite URL and front-sprite URL based on whose turn it is.
    Returns (back_url, front_url) — back = current turn player (bottom-left),
    front = opponent (top-right).
    Respects Mega Evolution sprite IDs (new_api_id).

    Priority for Mega/transformed sprites:
      1. MEGA_BATTLE_SPRITE_IDS numeric ID (Megas, Mega X/Y, Primal
         Reversions, Origin/Crowned/Rider Forms, custom Megas — every
         transformation category)
      2. Showdown sprite slug fallback (only for slugs not yet catalogued
         in MEGA_BATTLE_SPRITE_IDS)
      3. Base dex_id
    """
    bs = data["battle_state"]
    turn_id = bs.get("turn")
    current_is_p1 = (turn_id == data["p1_id"])

    t1 = bs.get("team1", [])
    t2 = bs.get("team2", [])
    idx1 = bs.get("active1", 0)
    idx2 = bs.get("active2", 0)
    p1_pkmn = t1[idx1] if t1 and idx1 < len(t1) else None
    p2_pkmn = t2[idx2] if t2 and idx2 < len(t2) else None

    if current_is_p1:
        active_pkmn   = p1_pkmn   # bottom-left (back sprite)
        opponent_pkmn = p2_pkmn   # top-right (front sprite)
    else:
        active_pkmn   = p2_pkmn
        opponent_pkmn = p1_pkmn

    # Official artwork fallback for unknown Pokémon
    fallback = "https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/0.png"

    def _resolve_url(pkmn: dict | None, back: bool) -> str:
        if pkmn is None:
            return fallback
        is_shiny = bool(pkmn.get("shiny", False))

        # ── Gigantamax form sprite (Dynamax with Gmax form) ────────────────────
        if pkmn.get("is_dynamaxed"):
            raw_name = pkmn.get("name", "")
            gmax_slug = raw_name.lower().replace(" ", "-").replace("✨", "").strip("-") + "-gmax"
            if back:
                gmax_url = (
                    f"https://play.pokemonshowdown.com/sprites/dex-back-shiny/{gmax_slug}.png"
                    if is_shiny else
                    f"https://play.pokemonshowdown.com/sprites/dex-back/{gmax_slug}.png"
                )
            else:
                gmax_url = (
                    f"https://play.pokemonshowdown.com/sprites/dex-shiny/{gmax_slug}.png"
                    if is_shiny else
                    f"https://play.pokemonshowdown.com/sprites/dex/{gmax_slug}.png"
                )
            return gmax_url  # renderer falls back to base sprite if Gmax slug 404s

        # ── Mega Evolution / Special Form priority chain ───────────────────────
        if pkmn.get("is_mega") and pkmn.get("mega_sprite_slug"):
            slug = pkmn["mega_sprite_slug"]

            # 1. MEGA_BATTLE_SPRITE_IDS — single source of truth for every
            #    battle transformation (Megas, Mega X/Y, Primal Reversions,
            #    Origin/Crowned/Rider Forms, custom Megas). Resolved via the
            #    numeric PokeAPI sprite ID for the TRANSFORMED form — never a
            #    Pokémon-name lookup, never the base form.
            battle_id = MEGA_BATTLE_SPRITE_IDS.get(slug)
            if battle_id:
                url = _nc_sprite_url(battle_id, back=back, shiny=is_shiny)
                if url:
                    return url
                # Sprite URL construction succeeded; the composite renderer will
                # fall back to official artwork automatically if the fetch fails.
                return (
                    f"https://raw.githubusercontent.com/PokeAPI/sprites/master/"
                    f"sprites/pokemon/other/official-artwork/{battle_id}.png"
                )

            # 2. Not yet catalogued in MEGA_BATTLE_SPRITE_IDS — Showdown
            #    back/front sprite as a defensive fallback, then artwork.
            dex_id = pkmn.get("dex_id") or 0
            if not back:
                showdown_url = (
                    f"https://play.pokemonshowdown.com/sprites/dex-shiny/{slug}.png"
                    if is_shiny else
                    f"https://play.pokemonshowdown.com/sprites/dex/{slug}.png"
                )
                return showdown_url
            else:
                # Showdown back sprite — falls back to official artwork for back if missing
                showdown_back = (
                    f"https://play.pokemonshowdown.com/sprites/dex-back-shiny/{slug}.png"
                    if is_shiny else
                    f"https://play.pokemonshowdown.com/sprites/dex-back/{slug}.png"
                )
                # Return Showdown back first; if it's missing at render time the
                # composite builder's resolve_sprite will flip official artwork.
                return showdown_back

        # ── Base form ──────────────────────────────────────────────────────────
        dex_id = pkmn.get("dex_id")
        url = _nc_sprite_url(dex_id, back=back, shiny=is_shiny)
        return url if url else fallback

    back_url  = _resolve_url(active_pkmn,   back=True)
    front_url = _resolve_url(opponent_pkmn, back=False)
    return back_url, front_url

def _nc_draw_weather_overlay(
    canvas: "Image.Image",
    weather_key: str,
    rng: "random.Random",
    W: int,
    H: int,
    layer: str,          # "behind" = before sprites, "front" = after sprites
) -> None:
    """
    Draw weather visual effects onto *canvas* (RGBA, modified in-place).

    Layer strategy so sprites are never obscured:
      "behind" — heavy tints, bulk particles, rain/snow/dust fill
      "front"  — sparse accent particles only (≤15 % opacity), no solid fills
    """
    try:
        from PIL import Image, ImageDraw, ImageFilter
    except ImportError:
        return

    draw = ImageDraw.Draw(canvas, "RGBA")

    # ─── helpers ─────────────────────────────────────────────────────────────
    def tint(r, g, b, a):
        """Full-canvas colour tint."""
        overlay = Image.new("RGBA", (W, H), (r, g, b, a))
        canvas.alpha_composite(overlay)

    def scatter_circles(n, rad_lo, rad_hi, colour, alpha_lo, alpha_hi):
        """Random filled circles — used for particles, snow, dust."""
        for _ in range(n):
            x  = rng.randint(0, W)
            y  = rng.randint(0, H)
            r  = rng.randint(rad_lo, rad_hi)
            a  = rng.randint(alpha_lo, alpha_hi)
            draw.ellipse([(x - r, y - r), (x + r, y + r)], fill=(*colour, a))

    def rain_streaks(n, colour, alpha, length_lo, length_hi, width, slant=3):
        """Diagonal rain or snow streaks."""
        for _ in range(n):
            x1 = rng.randint(0, W)
            y1 = rng.randint(0, H)
            length = rng.randint(length_lo, length_hi)
            x2 = x1 + slant
            y2 = y1 + length
            draw.line([(x1, y1), (x2, y2)], fill=(*colour, alpha), width=width)

    def wind_streaks(n, colour, alpha):
        """Horizontal swept wind lines."""
        for _ in range(n):
            x1 = rng.randint(-W // 4, W)
            y  = rng.randint(0, H)
            length = rng.randint(W // 6, W // 2)
            x2 = x1 + length
            a  = rng.randint(alpha // 2, alpha)
            w  = rng.randint(1, 2)
            draw.line([(x1, y), (x2, y)], fill=(*colour, a), width=w)

    def sun_rays(num_rays, cx, cy, inner_r, outer_r, colour, alpha):
        """Fan of triangular sun rays from a point."""
        for i in range(num_rays):
            base_angle = (360 / num_rays) * i
            half_w = 8
            a1 = math.radians(base_angle - half_w)
            a2 = math.radians(base_angle + half_w)
            pts = [
                (cx + inner_r * math.cos(a1), cy + inner_r * math.sin(a1)),
                (cx + outer_r * math.cos((a1 + a2) / 2), cy + outer_r * math.sin((a1 + a2) / 2)),
                (cx + inner_r * math.cos(a2), cy + inner_r * math.sin(a2)),
            ]
            draw.polygon(pts, fill=(*colour, alpha))

    def lightning_bolt(x_top, colour, alpha):
        """Jagged lightning bolt from top towards mid-canvas."""
        import math
        pts = []
        x, y = x_top, 0
        for _ in range(6):
            x += rng.randint(-25, 25)
            y += rng.randint(20, 50)
            pts.append((x, y))
        for i in range(len(pts) - 1):
            draw.line([pts[i], pts[i + 1]], fill=(*colour, alpha), width=rng.randint(2, 4))

    def haze_bands(num, colour, alpha):
        """Horizontal misty bands for fog."""
        for _ in range(num):
            y  = rng.randint(0, H)
            ht = rng.randint(H // 12, H // 5)
            band = Image.new("RGBA", (W, ht), (0, 0, 0, 0))
            bd   = ImageDraw.Draw(band, "RGBA")
            bd.rectangle([(0, 0), (W, ht)], fill=(*colour, rng.randint(alpha // 2, alpha)))
            blurred = band.filter(ImageFilter.GaussianBlur(radius=18))
            canvas.alpha_composite(blurred, (0, max(0, y - ht // 2)))

    def nebula_patch(cx, cy, rx, ry, colour, alpha):
        """Soft elliptical nebula glow."""
        patch = Image.new("RGBA", (rx * 2, ry * 2), (0, 0, 0, 0))
        pd    = ImageDraw.Draw(patch, "RGBA")
        pd.ellipse([(0, 0), (rx * 2, ry * 2)], fill=(*colour, alpha))
        blurred = patch.filter(ImageFilter.GaussianBlur(radius=max(rx // 3, 6)))
        canvas.alpha_composite(blurred, (cx - rx, cy - ry))

    # ═══════════════════════════════════════════════════════════════════════
    # ☀️  SUNNY
    # ═══════════════════════════════════════════════════════════════════════
    if weather_key == "sunny":
        if layer == "behind":
            # Warm golden tint over whole canvas
            tint(255, 200, 80, 55)
            # Brightness boost — lighter wash
            tint(255, 240, 160, 30)
            # Sun disc (top-right corner)
            cx, cy = int(W * 0.88), int(H * 0.10)
            glow = Image.new("RGBA", (W, H), (0, 0, 0, 0))
            gd   = ImageDraw.Draw(glow, "RGBA")
            for radius, alpha in [(80, 18), (60, 30), (42, 50), (28, 90)]:
                gd.ellipse(
                    [(cx - radius, cy - radius), (cx + radius, cy + radius)],
                    fill=(255, 230, 80, alpha)
                )
            blurred_glow = glow.filter(ImageFilter.GaussianBlur(radius=14))
            canvas.alpha_composite(blurred_glow)
            # Hard sun core
            draw.ellipse([(cx - 20, cy - 20), (cx + 20, cy + 20)], fill=(255, 245, 150, 210))
            # Rays
            sun_rays(12, cx, cy, 24, 75, (255, 230, 100), 70)
        # front layer — nothing needed; tint already gives brightness

    # ═══════════════════════════════════════════════════════════════════════
    # 🌧️  RAIN
    # ═══════════════════════════════════════════════════════════════════════
    elif weather_key == "rain":
        if layer == "behind":
            # Cool dark blue tint
            tint(30, 50, 100, 55)
            # Many rain streaks across full canvas
            rain_streaks(180, (180, 210, 255), 130, 12, 28, 1, slant=4)
            # Splash dots at ground level
            for _ in range(40):
                sx = rng.randint(0, W)
                sy = rng.randint(int(H * 0.70), H)
                sr = rng.randint(1, 3)
                draw.ellipse([(sx - sr, sy - sr), (sx + sr, sy + sr)],
                             fill=(180, 220, 255, rng.randint(60, 110)))
        elif layer == "front":
            # Sparse foreground drops — very faint so sprites show through
            rain_streaks(30, (200, 225, 255), 35, 8, 18, 1, slant=3)

    # ═══════════════════════════════════════════════════════════════════════
    # ⛈️  THUNDERSTORM
    # ═══════════════════════════════════════════════════════════════════════
    elif weather_key == "thunderstorm":
        if layer == "behind":
            # Heavy dark storm tint
            tint(20, 20, 50, 80)
            # Very heavy rain
            rain_streaks(240, (160, 190, 240), 130, 14, 35, 1, slant=5)
            # Occasional wider streaks
            rain_streaks(40, (140, 170, 220), 100, 20, 55, 2, slant=6)
            # Lightning flash — bright white wash
            tint(200, 210, 255, rng.randint(10, 35))
            # 1–2 lightning bolts
            for _ in range(rng.randint(1, 2)):
                lightning_bolt(rng.randint(W // 5, W * 4 // 5), (220, 230, 255), 180)
        elif layer == "front":
            rain_streaks(35, (180, 210, 255), 30, 10, 22, 1, slant=4)

    # ═══════════════════════════════════════════════════════════════════════
    # ❄️  SNOWSTORM
    # ═══════════════════════════════════════════════════════════════════════
    elif weather_key == "snowstorm":
        if layer == "behind":
            # Cold pale-blue tint
            tint(180, 210, 255, 60)
            # Blizzard wind streaks
            wind_streaks(60, (210, 230, 255), 70)
            # Background snowflakes (larger, more opaque)
            scatter_circles(120, 2, 6, (240, 248, 255), 100, 190)
            # Tiny ice particles
            scatter_circles(80, 1, 3, (220, 240, 255), 60, 130)
        elif layer == "front":
            # Sparse foreground flakes
            scatter_circles(20, 2, 5, (255, 255, 255), 40, 90)

    # ═══════════════════════════════════════════════════════════════════════
    # 🌪️  WINDY
    # ═══════════════════════════════════════════════════════════════════════
    elif weather_key == "windy":
        if layer == "behind":
            # Pale grey-green tint
            tint(200, 220, 180, 40)
            # Dense wind streaks
            wind_streaks(80, (210, 220, 200), 90)
            wind_streaks(40, (190, 210, 170), 60)
            # Floating leaf-like ovals
            for _ in range(35):
                lx = rng.randint(0, W)
                ly = rng.randint(0, H)
                lw = rng.randint(4, 9)
                lh = rng.randint(2, 5)
                la = rng.randint(80, 160)
                col = rng.choice([(120, 180, 60), (160, 200, 80), (100, 160, 50)])
                draw.ellipse([(lx - lw, ly - lh), (lx + lw, ly + lh)], fill=(*col, la))
            # Swirl arcs — curved wind lines
            for _ in range(12):
                sx = rng.randint(W // 4, W * 3 // 4)
                sy = rng.randint(H // 4, H * 3 // 4)
                for step in range(30):
                    t  = step / 30
                    r  = 20 + 60 * t
                    angle = math.radians(rng.randint(0, 360) + step * 12)
                    ex = int(sx + r * math.cos(angle))
                    ey = int(sy + r * math.sin(angle) * 0.5)
                    draw.point((ex, ey), fill=(200, 215, 180, rng.randint(50, 100)))
        elif layer == "front":
            wind_streaks(12, (220, 230, 210), 20)

    # ═══════════════════════════════════════════════════════════════════════
    # 🌫️  FOG
    # ═══════════════════════════════════════════════════════════════════════
    elif weather_key == "fog":
        if layer == "behind":
            # Base dim tint
            tint(200, 205, 210, 50)
            # Multiple blurred haze bands
            haze_bands(6, (220, 225, 230), 80)
            # Second layer of softer bands
            haze_bands(4, (240, 242, 244), 55)
        elif layer == "front":
            # Light frontal mist — keeps sprites visible but adds depth
            haze_bands(2, (235, 238, 240), 28)

    # ═══════════════════════════════════════════════════════════════════════
    # 🏜️  SANDSTORM
    # ═══════════════════════════════════════════════════════════════════════
    elif weather_key == "sandstorm":
        if layer == "behind":
            # Semi-transparent sandy tan haze — RGBA(194, 178, 128, 45)
            tint(194, 178, 128, 45)
            # Horizontal wind streaks in sand tones
            wind_streaks(70, (210, 165, 80), 100)
            wind_streaks(35, (190, 140, 60), 80)
            # Drifting sand particle dots
            scatter_circles(200, 1, 4, (220, 170, 80), 80, 160)
            scatter_circles(100, 1, 2, (200, 150, 60), 60, 120)
            # Larger blurred dust cloud patches
            for _ in range(8):
                dcx = rng.randint(0, W)
                dcy = rng.randint(0, H)
                drx = rng.randint(50, 120)
                dry = rng.randint(20, 50)
                patch = Image.new("RGBA", (drx * 2, dry * 2), (0, 0, 0, 0))
                pd    = ImageDraw.Draw(patch, "RGBA")
                pd.ellipse([(0, 0), (drx * 2, dry * 2)],
                           fill=(210, 160, 70, rng.randint(40, 80)))
                blurred = patch.filter(ImageFilter.GaussianBlur(radius=10))
                canvas.alpha_composite(blurred, (max(0, dcx - drx), max(0, dcy - dry)))
        elif layer == "front":
            # Sparse foreground sand particles — FIXED: correct arg order (n, rad_lo, rad_hi, colour, alpha_lo, alpha_hi)
            tint(194, 178, 128, 18)
            scatter_circles(30, 1, 3, (220, 175, 85), 25, 55)
            wind_streaks(10, (215, 170, 80), 20)

    # ═══════════════════════════════════════════════════════════════════════
    # 🌙  MOONLIGHT
    # ═══════════════════════════════════════════════════════════════════════
    elif weather_key == "moonlight":
        if layer == "behind":
            # Deep blue-purple night tint
            tint(20, 20, 80, 70)
            # Moon glow — top-left
            mx, my = int(W * 0.12), int(H * 0.12)
            for radius, alpha in [(90, 12), (65, 22), (44, 40), (28, 70)]:
                patch = Image.new("RGBA", (W, H), (0, 0, 0, 0))
                pd    = ImageDraw.Draw(patch, "RGBA")
                pd.ellipse(
                    [(mx - radius, my - radius), (mx + radius, my + radius)],
                    fill=(200, 210, 255, alpha)
                )
                blurred = patch.filter(ImageFilter.GaussianBlur(radius=12))
                canvas.alpha_composite(blurred)
            # Moon disc
            draw.ellipse([(mx - 22, my - 22), (mx + 22, my + 22)], fill=(240, 245, 255, 220))
            # Star sparkles
            for _ in range(55):
                sx = rng.randint(0, W)
                sy = rng.randint(0, int(H * 0.65))
                sr = rng.choice([1, 1, 1, 2])
                sa = rng.randint(120, 220)
                draw.ellipse([(sx - sr, sy - sr), (sx + sr, sy + sr)], fill=(255, 255, 255, sa))
            # Fairy dust particles
            scatter_circles(40, 1, 3, (180, 160, 255), 60, 130)
        elif layer == "front":
            scatter_circles(10, 1, 2, (200, 180, 255), 20, 50)

    # ═══════════════════════════════════════════════════════════════════════
    # ☣️  TOXIC MIST
    # ═══════════════════════════════════════════════════════════════════════
    elif weather_key == "toxic_mist":
        if layer == "behind":
            # Sickly purple-green tint
            tint(80, 120, 40, 55)
            # Gas cloud patches
            for _ in range(10):
                gcx = rng.randint(0, W)
                gcy = rng.randint(0, H)
                grx = rng.randint(60, 140)
                gry = rng.randint(30, 70)
                col = rng.choice([(100, 180, 60), (120, 80, 160), (80, 160, 50)])
                patch = Image.new("RGBA", (grx * 2, gry * 2), (0, 0, 0, 0))
                pd    = ImageDraw.Draw(patch, "RGBA")
                pd.ellipse([(0, 0), (grx * 2, gry * 2)],
                           fill=(*col, rng.randint(35, 70)))
                blurred = patch.filter(ImageFilter.GaussianBlur(radius=14))
                canvas.alpha_composite(blurred, (max(0, gcx - grx), max(0, gcy - gry)))
            # Poison bubble particles
            scatter_circles(80, 2, 6, (140, 80, 180), 70, 150)
            scatter_circles(60, 1, 3, (80, 180, 60), 50, 110)
            # Rising bubble lines
            for _ in range(20):
                bx = rng.randint(0, W)
                for seg in range(rng.randint(3, 7)):
                    by1 = H - seg * rng.randint(15, 30)
                    by2 = by1 - rng.randint(8, 18)
                    draw.line([(bx, max(0, by1)), (bx + rng.randint(-3, 3), max(0, by2))],
                              fill=(120, 200, 80, rng.randint(40, 90)), width=1)
        elif layer == "front":
            scatter_circles(15, 2, 5, (160, 100, 200), 20, 45)

    # ═══════════════════════════════════════════════════════════════════════
    # 🌌  COSMIC WEATHER
    # ═══════════════════════════════════════════════════════════════════════
    elif weather_key == "cosmic":
        if layer == "behind":
            # Deep space tint — dark purple-blue
            tint(10, 5, 50, 85)
            # Nebula patches
            nebula_patch(int(W * 0.25), int(H * 0.35), 160, 90, (80, 20, 160), 45)
            nebula_patch(int(W * 0.70), int(H * 0.25), 130, 70, (20, 60, 180), 40)
            nebula_patch(int(W * 0.50), int(H * 0.60), 110, 60, (140, 0, 120), 35)
            # Extra faint nebula wisps
            nebula_patch(int(W * 0.80), int(H * 0.70), 90, 50, (60, 20, 140), 25)
            nebula_patch(int(W * 0.10), int(H * 0.55), 100, 55, (20, 80, 160), 28)
            # Dense star field
            for _ in range(120):
                sx = rng.randint(0, W)
                sy = rng.randint(0, H)
                sr = rng.choice([1, 1, 1, 1, 2])
                sa = rng.randint(140, 255)
                draw.ellipse([(sx - sr, sy - sr), (sx + sr, sy + sr)],
                             fill=(255, 255, 255, sa))
            # Bright featured stars with cross-flare
            for _ in range(8):
                bsx = rng.randint(0, W)
                bsy = rng.randint(0, int(H * 0.85))
                bsr = rng.randint(2, 4)
                draw.ellipse([(bsx - bsr, bsy - bsr), (bsx + bsr, bsy + bsr)],
                             fill=(255, 255, 255, 230))
                fl = rng.randint(6, 14)
                draw.line([(bsx - fl, bsy), (bsx + fl, bsy)], fill=(255, 255, 255, 100), width=1)
                draw.line([(bsx, bsy - fl), (bsx, bsy + fl)], fill=(255, 255, 255, 100), width=1)
            # Cosmic particle dust
            scatter_circles(60, 1, 3, (160, 100, 255), 60, 140)
            scatter_circles(40, 1, 2, (100, 180, 255), 50, 110)
            scatter_circles(30, 1, 2, (255, 100, 200), 40, 90)
        elif layer == "front":
            # Sparse foreground stars/particles
            scatter_circles(12, 1, 2, (200, 150, 255), 20, 50)
            for _ in range(4):
                sx = rng.randint(0, W)
                sy = rng.randint(0, H)
                draw.ellipse([(sx - 1, sy - 1), (sx + 1, sy + 1)], fill=(255, 255, 255, 80))


async def _nc_build_composite_image(data: dict) -> bytes | None:
    """
    Build a fresh battle image from scratch every call — no caching, no reuse.

    Layer order:
        1. Background image (resized to canvas)
        2. Weather overlay — BEHIND layer  (tints, bulk particles, rain fill)
        3. Pokémon sprites               (never obscured)
        4. Weather overlay — FRONT layer  (sparse accent particles, ≤15 % opacity)

    Canvas: 768 × 384 px

    Back sprite  (current-turn player — bottom-left):
        • Scale ≈ 2.6× raw Showdown sprite  (LANCZOS, aspect ratio preserved)
        • Left edge  : x = 5 % of canvas width
        • Bottom edge: y = 88 % of canvas height

    Front sprite (opponent — upper-right):
        • Scale ≈ 2.0× raw Showdown sprite
        • Left edge  : x = 65 % of canvas width
        • Top edge   : y = 15 % of canvas height
    """
    try:
        from PIL import Image
        import io as _io
    except ImportError:
        return None

    CANVAS_W, CANVAS_H = 768, 384
    BACK_SCALE_FACTOR  = 2.6
    FRONT_SCALE_FACTOR = 2.0
    # Official artwork (~475×475 px) is far larger than a Showdown sprite
    # (~80–96 px box). Shrink it to a comparable footprint first so the
    # existing scale factors above still produce a normally-sized battler
    # instead of artwork that overwhelms the canvas.
    ARTWORK_THUMBNAIL_PX = 96

    # ── Resolve which Pokémon to draw (respect faint state) ──────────────────
    bs            = data["battle_state"]
    turn_id       = bs.get("turn")
    current_is_p1 = (turn_id == data["p1_id"])

    t1       = bs.get("team1", [])
    t2       = bs.get("team2", [])
    idx1     = bs.get("active1", 0)
    idx2     = bs.get("active2", 0)
    fainted1 = set(bs.get("fainted1", []))
    fainted2 = set(bs.get("fainted2", []))

    p1_pkmn = t1[idx1] if t1 and idx1 < len(t1) else None
    p2_pkmn = t2[idx2] if t2 and idx2 < len(t2) else None

    if idx1 in fainted1:
        p1_pkmn = None
    if idx2 in fainted2:
        p2_pkmn = None

    if current_is_p1:
        back_pkmn  = p1_pkmn
        front_pkmn = p2_pkmn
    else:
        back_pkmn  = p2_pkmn
        front_pkmn = p1_pkmn

    fallback_url = "https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/0.png"

    # ── Fetch images ──────────────────────────────────────────────────────────
    bg_name = bs.get("battle_bg", random.choice(_NC_BACKGROUNDS))
    bg_url  = f"https://play.pokemonshowdown.com/sprites/gen6bgs/{bg_name}"

    async def fetch_img(url: str | None) -> "Image.Image | None":
        if url is None:
            return None
        try:
            raw = await _cached_sprite_bytes(url)
            if raw:
                return Image.open(_io.BytesIO(raw)).convert("RGBA")
        except Exception:
            pass
        return None

    async def resolve_sprite(pkmn: dict | None, is_back: bool) -> "Image.Image | None":
        """
        Resolve the battle sprite for one side, in priority order:

          1. PokeAPI sprite      — /back/shiny, /back, /shiny, or plain numeric ID
                                   uses Mega form's new_api_id when is_mega=True
          2. Official artwork     — same source /hunt uses (shiny artwork first
                                     if shiny, then normal artwork)
          3. Generic placeholder  — absolute last resort, never crash

        Fainted Pokémon arrive here as pkmn=None and render nothing — no
        fallback artwork is ever generated for a fainted Pokémon.

        Official artwork has no real back-view, so when it ends up being used
        for the BACK (current-turn) position it's mirrored horizontally to
        imitate one. Genuine PokeAPI back sprites are never mirrored.
        Fallback usage is logged for debugging only — never shown to users.
        """
        if pkmn is None:
            return None

        name     = pkmn.get("name", "Pokémon")
        is_shiny = bool(pkmn.get("shiny", False))

        # [SHINY CHECK] debug log
        logger.info(f"[SHINY CHECK] Pokemon: {name} | Shiny: {is_shiny} | Back: {is_back}")

        # ── Priority 1: PokeAPI sprite (numeric ID) via MEGA_BATTLE_SPRITE_IDS ──
        # MEGA_BATTLE_SPRITE_IDS is the single source of truth for battle
        # sprites and covers every transformation category: Mega Evolutions
        # (classic + Mega X/Y), Primal Reversions, Origin Forms, Crowned
        # Forms, Calyrex Rider Forms, and PokeRo custom Megas. It resolves
        # straight to the numeric PokeAPI sprite ID for the TRANSFORMED form
        # — never a Pokémon-name/Showdown-slug lookup — so a transformed
        # Pokémon NEVER falls back to its base-form sprite while its slug is
        # present in the mapping.
        sprite_id   = None
        mega_img    = None
        if pkmn.get("is_mega") and pkmn.get("mega_sprite_slug"):
            mega_slug = pkmn["mega_sprite_slug"]
            battle_id = MEGA_BATTLE_SPRITE_IDS.get(mega_slug)

            if battle_id:
                # 1a. Direct numeric-ID sprite for the transformed form.
                sprite_id  = battle_id
                sprite_url = _nc_sprite_url(battle_id, back=is_back, shiny=is_shiny)
                logger.info(f"[SPRITE URL] Battle transform (numeric) {'Back' if is_back else 'Front'}: {sprite_url}")
                mega_img = await fetch_img(sprite_url)

                if mega_img is None:
                    # 1b. Raw sprite file missing/unreachable — retry with the
                    # TRANSFORMED form's OWN official artwork at the SAME
                    # numeric ID (flipped/darkened below for back view).
                    # This still never shows the base species.
                    used_artwork_fallback = False
                    if is_shiny:
                        shiny_art = (
                            f"https://raw.githubusercontent.com/PokeAPI/sprites/master/"
                            f"sprites/pokemon/other/official-artwork/shiny/{battle_id}.png"
                        )
                        mega_img = await fetch_img(shiny_art)
                        if mega_img is not None:
                            used_artwork_fallback = True
                            logger.info(f"[SPRITE URL] Battle transform shiny artwork fallback: {shiny_art}")
                    if mega_img is None:
                        normal_art = (
                            f"https://raw.githubusercontent.com/PokeAPI/sprites/master/"
                            f"sprites/pokemon/other/official-artwork/{battle_id}.png"
                        )
                        logger.info(f"[SPRITE URL] Battle transform artwork fallback: {normal_art}")
                        mega_img = await fetch_img(normal_art)
                        used_artwork_fallback = mega_img is not None

                    if mega_img is not None and is_back and used_artwork_fallback:
                        # Official artwork has no genuine back view — flip +
                        # darken it so it reads as a rear sprite.
                        try:
                            from PIL import ImageEnhance
                            mega_img = mega_img.convert("RGBA")
                            mega_img = mega_img.transpose(Image.FLIP_LEFT_RIGHT)
                            mega_img = ImageEnhance.Brightness(mega_img).enhance(0.78)
                            r, g, b, a = mega_img.split()
                            a = a.point(lambda v: int(v * 0.82))
                            mega_img = Image.merge("RGBA", (r, g, b, a))
                        except Exception as _me:
                            logger.warning(f"[BATTLE] Battle transform back-sprite post-process failed: {_me}")
            else:
                # ── Defensive fallback only ─────────────────────────────────
                # MEGA_BATTLE_SPRITE_IDS covers every slug currently defined
                # in MEGA_FORM_DATA / SPECIAL_FORM_DATA, so this branch should
                # not trigger in practice. It exists solely so a future
                # transformation added before its numeric ID is catalogued
                # still shows the transformed form's Showdown/artwork sprite
                # instead of crashing or silently reverting to the base form.
                if is_back:
                    showdown_url = (
                        f"https://play.pokemonshowdown.com/sprites/dex-back-shiny/{mega_slug}.png"
                        if is_shiny else
                        f"https://play.pokemonshowdown.com/sprites/dex-back/{mega_slug}.png"
                    )
                else:
                    showdown_url = (
                        f"https://play.pokemonshowdown.com/sprites/dex-shiny/{mega_slug}.png"
                        if is_shiny else
                        f"https://play.pokemonshowdown.com/sprites/dex/{mega_slug}.png"
                    )
                logger.warning(
                    f"[BATTLE] {mega_slug!r} not found in MEGA_BATTLE_SPRITE_IDS — "
                    f"add its numeric sprite ID. Falling back to Showdown lookup: {showdown_url}"
                )
                mega_img = await fetch_img(showdown_url)
                if mega_img is None:
                    mega_art_url = f"https://play.pokemonshowdown.com/sprites/dex/{mega_slug}.png"
                    mega_img = await fetch_img(mega_art_url)
                    if mega_img is not None and is_back:
                        try:
                            from PIL import ImageEnhance
                            mega_img = mega_img.convert("RGBA")
                            mega_img = mega_img.transpose(Image.FLIP_LEFT_RIGHT)
                            mega_img = ImageEnhance.Brightness(mega_img).enhance(0.78)
                            r, g, b, a = mega_img.split()
                            a = a.point(lambda v: int(v * 0.82))
                            mega_img = Image.merge("RGBA", (r, g, b, a))
                        except Exception as _me:
                            logger.warning(f"[BATTLE] Uncatalogued transform back-sprite post-process failed: {_me}")

        if mega_img is not None:
            return mega_img

        # Fall through to base-form sprite when not Mega or mega sprite fetch failed
        if sprite_id is None:
            sprite_id = pkmn.get("dex_id")

        sprite_url = _nc_sprite_url(sprite_id, back=is_back, shiny=is_shiny)
        # [SPRITE URL] debug log
        logger.info(f"[SPRITE URL] {'Back' if is_back else 'Front'}: {sprite_url}")
        img = await fetch_img(sprite_url)
        used_artwork = False

        if img is None:
            logger.info(
                f"[BATTLE] Missing PokeAPI sprite for id={sprite_id} ({name})\n"
                f"Using artwork fallback."
            )

            # ── Priority 2: Official artwork (same source as /hunt) ─────────
            # artwork_url: for shiny Pokémon this was already set to the
            # shiny artwork URL when the team was loaded (_nc_load_team).
            # The (normal/shiny)_sprite_url fallback below only fires when
            # artwork_url is None (e.g. team loaded without artwork_url set).
            # NEVER derive shiny status from the Pokémon name — always read
            # is_shiny which was set from the database shiny flag.
            dex_id      = pkmn.get("dex_id")
            artwork_url = pkmn.get("artwork_url") or (
                shiny_sprite_url(dex_id) if (is_shiny and dex_id)
                else (normal_sprite_url(dex_id) if dex_id else None)
            )

            if is_shiny:
                img = await fetch_img(shiny_sprite_url(dex_id) if dex_id else None)
                if img is None:
                    logger.warning(
                        f"[SHINY FALLBACK] Shiny artwork unavailable for {name} (dex_id={dex_id}) — "
                        f"trying shiny artwork URL fallback"
                    )
                    img = await fetch_img(artwork_url)
                if img is None:
                    logger.warning(
                        f"[SHINY FALLBACK] All shiny artwork failed for {name} — "
                        f"using normal artwork as last resort"
                    )
                    img = await fetch_img(normal_sprite_url(dex_id) if dex_id else None)
            else:
                img = await fetch_img(artwork_url)

            used_artwork = img is not None
            if used_artwork:
                # Normalize artwork's resolution down to a sprite-like
                # footprint — see ARTWORK_THUMBNAIL_PX above. thumbnail()
                # only ever shrinks, preserves aspect ratio, and mutates
                # img in place.
                img.thumbnail((ARTWORK_THUMBNAIL_PX, ARTWORK_THUMBNAIL_PX), Image.LANCZOS)

            # ── Priority 3: generic placeholder — never leave the field empty ─
            if img is None:
                logger.warning(
                    f"[BATTLE] Artwork fallback unavailable for {name} — using generic placeholder."
                )
                img = await fetch_img(fallback_url)

        if used_artwork and is_back and img is not None:
            img = img.transpose(Image.FLIP_LEFT_RIGHT)
            # Slight darkening (brightness 0.78) and slight transparency
            # (alpha 0.82) make the artwork read as a convincing rear sprite
            # rather than a second front-facing Pokémon.
            try:
                from PIL import ImageEnhance
                img = img.convert("RGBA")
                img = ImageEnhance.Brightness(img).enhance(0.78)
                # Reduce overall alpha to ~82 % of its current value
                r, g, b, a = img.split()
                a = a.point(lambda v: int(v * 0.82))
                img = Image.merge("RGBA", (r, g, b, a))
            except Exception as _e:
                logger.warning(f"[BATTLE] Back-sprite artwork post-process failed: {_e}")

        return img

    bg_img    = await fetch_img(bg_url)
    back_img  = await resolve_sprite(back_pkmn,  is_back=True)
    front_img = await resolve_sprite(front_pkmn, is_back=False)

    if bg_img is None:
        return None

    # ── Determine active weather ──────────────────────────────────────────────
    weather_key   = bs.get("weather") or ""
    weather_turns = bs.get("weather_turns_left", 0)
    active_weather = weather_key if (weather_key and weather_turns > 0) else ""

    # Seeded RNG so every render of the same turn looks consistent
    # (seed = battle_id hash + turn_num so it changes each turn)
    _seed_str  = str(data.get("battle_id", "")) + str(bs.get("turn_num", 0))
    _seed_int  = int(hashlib.md5(_seed_str.encode()).hexdigest(), 16) % (2**31)

    # ── CPU-bound compositing (resize/paste/PNG-encode) runs in a worker
    # thread via asyncio.to_thread — this used to run inline on the event
    # loop and, since it happens on EVERY move/turn, would briefly freeze
    # the whole bot (all chats, all battles) for however long PIL took to
    # resize + paste + encode the frame. Network fetches above stay on the
    # event loop as before; only the pure-CPU part below is offloaded.
    def _compose() -> bytes:
        rng = random.Random(_seed_int)

        # ── 1. Fresh canvas ───────────────────────────────────────────────
        # Use the background's original dimensions — never crop, never zoom.
        # All subsequent percentage-based sprite positions automatically
        # scale to the real canvas size derived here.
        canvas_w, canvas_h = bg_img.size
        canvas = bg_img.convert("RGBA")

        # ── 2. Weather overlay — BEHIND sprites ────────────────────────────
        if active_weather:
            _nc_draw_weather_overlay(canvas, active_weather, rng, canvas_w, canvas_h, "behind")

        # ── 3. Sprite paste helpers ─────────────────────────────────────────
        def paste_back(sprite: "Image.Image") -> None:
            ow, oh = sprite.size
            nw = max(1, int(ow * BACK_SCALE_FACTOR))
            nh = max(1, int(oh * BACK_SCALE_FACTOR))
            sprite_r = sprite.resize((nw, nh), Image.LANCZOS)
            x = int(canvas_w * 0.05)
            y = int(canvas_h * 0.88) - nh + 25   # shifted 25 px down
            canvas.paste(sprite_r, (x, y), sprite_r)

        def paste_front(sprite: "Image.Image") -> None:
            ow, oh = sprite.size
            nw = max(1, int(ow * FRONT_SCALE_FACTOR))
            nh = max(1, int(oh * FRONT_SCALE_FACTOR))
            sprite_r = sprite.resize((nw, nh), Image.LANCZOS)
            x = int(canvas_w * 0.65)
            y = int(canvas_h * 0.15) - 25        # shifted 25 px up
            canvas.paste(sprite_r, (x, y), sprite_r)

        if back_img  is not None:
            paste_back(back_img)
        if front_img is not None:
            paste_front(front_img)

        # ── 4. Weather overlay — FRONT sprites (sparse, low opacity) ───────
        if active_weather:
            # Re-seed with a slight offset so front layer differs from behind layer
            rng2 = random.Random(_seed_int ^ 0xDEAD_BEEF)
            _nc_draw_weather_overlay(canvas, active_weather, rng2, canvas_w, canvas_h, "front")

        # ── 5. Export ───────────────────────────────────────────────────────
        buf = _io.BytesIO()
        canvas.save(buf, format="PNG")
        buf.seek(0)
        return buf.read()

    return await asyncio.to_thread(_compose)


async def _nc_update_battle_visual(bot, data: dict, caption: str, reply_markup=None) -> None:
    """
    Update the single persistent battle message in-place every turn.

    Strategy
    ────────
    • First call  (no message_id yet):
        → try send_photo  → stores message_id + battle_message_type="photo"
        → if photo fails  → send_message fallback, battle_message_type="text"

    • Subsequent calls (message_id exists):
        IF battle_message_type == "photo":
            → try edit_message_media  (new image via BytesIO — no BufferedInputFile)
            → if that fails: try edit_message_caption (only when msg is still a photo msg)
            → if both fail:  send a brand new battle message and switch to
                              editing THAT message from now on — the old
                              message is NEVER deleted (see note below)
        IF battle_message_type == "text":
            → use edit_message_text  (never call edit_message_caption on a text msg)
              → if that fails: send a brand new text message the same way

    Battle logic ALWAYS continues regardless of image/edit errors.
    All visual operations are wrapped in try/except — a failed image update
    must never freeze the battle.

    IMPORTANT — "message is not modified" is NOT a failure:
    Telegram raises this specific BadRequest when the caption/media/markup
    we're trying to set is byte-for-byte identical to what's already shown.
    The message already displays what we wanted, so this is a no-op success,
    not an error — it must never fall through to the "both edits failed"
    recovery path below. Treating it as a real failure is what used to send
    a brand new duplicate battle message every time two clicks (a rapid
    double-tap, or two concurrent handler runs) raced to render the exact
    same state: the second one would find nothing to change, get
    "not modified" back, and — before this fix — respond by spawning a
    fresh message instead of just leaving the existing one alone.

    IMPORTANT — never delete the battle message:
    On any GENUINE edit failure (message can't be edited, message deleted,
    invalid message, etc.) this function sends a replacement message BEFORE
    ever touching the old one, and the old message is never deleted.
    Deleting the old message first and only then attempting to send a
    replacement is what used to make the battle UI disappear completely
    whenever that replacement send failed. If the new message send also
    fails, `data["message_id"]` is simply left pointing at the old
    (still-existing) message, so the battle always has a real, visible
    message to keep editing on the next turn.

    PTB Compatibility
    ─────────────────
    BufferedInputFile is NOT available in all PTB versions. This function uses
    only io.BytesIO wrapped in InputFile, which works across PTB v13 and v20+.
    """
    import io as _io
    import traceback
    from telegram import InputMediaPhoto

    def _is_not_modified(exc: Exception) -> bool:
        """True only for Telegram's harmless 'message is not modified' error
        — see the docstring note above for why this must never be treated
        the same as a genuine edit failure."""
        return "not modified" in str(exc).lower()

    chat_id    = data.get("chat_id")
    message_id = data.get("message_id")
    # Retrieve tracked message type; default to "photo" for backwards compat
    msg_type   = data.get("battle_message_type", "photo")

    if not chat_id:
        logger.warning("[ROCLASH] _nc_update_battle_visual called with no chat_id — skipping")
        return

    # ── Always build a fresh composite image (errors here are non-fatal) ───────
    img_bytes = None
    try:
        img_bytes = await _nc_build_composite_image(data)
    except Exception as e:
        logger.error(f"[ROCLASH] _nc_build_composite_image failed: {e}\n{traceback.format_exc()}")
        # img_bytes stays None — we continue with text-only fallbacks below

    # ═══════════════════════════════════════════════════════════════════════════
    # CASE 1 — No existing message: send the battle message for the first time
    # ═══════════════════════════════════════════════════════════════════════════
    if not message_id:
        logger.info(f"[ROCLASH] chat_id={chat_id} | First send — no message_id yet")

        # ── Try send_photo ────────────────────────────────────────────────────
        photo_sent = False
        if img_bytes:
            try:
                sent = await bot.send_photo(
                    chat_id=chat_id,
                    photo=_io.BytesIO(img_bytes),
                    caption=caption,
                    parse_mode="HTML",
                    reply_markup=reply_markup,
                )
                data["battle_photo_id"]    = sent.photo[-1].file_id
                data["message_id"]         = sent.message_id
                data["battle_message_type"] = "photo"
                logger.info(
                    f"[ROCLASH] chat_id={chat_id} message_id={sent.message_id} "
                    f"message_type=photo | send_photo=success (composite image)"
                )
                photo_sent = True
            except Exception as e:
                logger.error(
                    f"[ROCLASH] chat_id={chat_id} | send_photo (composite) failed: {e}\n"
                    f"{traceback.format_exc()}"
                )

        # ── Try send_photo with BG URL fallback if composite image failed ─────
        if not photo_sent:
            try:
                bs     = data.get("battle_state", {})
                bg     = bs.get("battle_bg", _NC_BACKGROUNDS[0])
                bg_url = f"https://play.pokemonshowdown.com/sprites/gen6bgs/{bg}"
                sent   = await bot.send_photo(
                    chat_id=chat_id,
                    photo=bg_url,
                    caption=caption,
                    parse_mode="HTML",
                    reply_markup=reply_markup,
                )
                data["battle_photo_id"]    = sent.photo[-1].file_id
                data["message_id"]         = sent.message_id
                data["battle_message_type"] = "photo"
                logger.info(
                    f"[ROCLASH] chat_id={chat_id} message_id={sent.message_id} "
                    f"message_type=photo | send_photo=success (bg url fallback)"
                )
                photo_sent = True
            except Exception as e:
                logger.error(
                    f"[ROCLASH] chat_id={chat_id} | send_photo (bg url) failed: {e}\n"
                    f"{traceback.format_exc()}"
                )

        # ── Final fallback: text-only message ─────────────────────────────────
        if not photo_sent:
            try:
                sent = await bot.send_message(
                    chat_id=chat_id,
                    text=caption,
                    parse_mode="HTML",
                    reply_markup=reply_markup,
                )
                data["message_id"]         = sent.message_id
                data["battle_message_type"] = "text"
                logger.info(
                    f"[ROCLASH] chat_id={chat_id} message_id={sent.message_id} "
                    f"message_type=text | send_message=success (text fallback)"
                )
            except Exception as e:
                logger.error(
                    f"[ROCLASH] chat_id={chat_id} | send_message (text fallback) failed: {e}\n"
                    f"{traceback.format_exc()}"
                )
        return

    # ═══════════════════════════════════════════════════════════════════════════
    # CASE 2 — Message exists: edit it in-place based on tracked message type
    # ═══════════════════════════════════════════════════════════════════════════
    logger.info(
        f"[ROCLASH] chat_id={chat_id} message_id={message_id} "
        f"message_type={msg_type} | Attempting update"
    )

    # ── Branch A: message is a photo message ──────────────────────────────────
    if msg_type == "photo":

        # Step 1: try edit_message_media (update the image + caption + buttons)
        if img_bytes:
            try:
                media = InputMediaPhoto(
                    media=_io.BytesIO(img_bytes),
                    caption=caption,
                    parse_mode="HTML",
                )
                edited = await bot.edit_message_media(
                    chat_id=chat_id,
                    message_id=message_id,
                    media=media,
                    reply_markup=reply_markup,
                )
                if edited and hasattr(edited, "photo") and edited.photo:
                    data["battle_photo_id"] = edited.photo[-1].file_id
                logger.info(
                    f"[ROCLASH] chat_id={chat_id} message_id={message_id} "
                    f"message_type=photo | edit_media=success"
                )
                return
            except Exception as e:
                if _is_not_modified(e):
                    logger.info(
                        f"[ROCLASH] chat_id={chat_id} message_id={message_id} "
                        f"message_type=photo | edit_media=no-op (message already up to date)"
                    )
                    return
                logger.warning(
                    f"[ROCLASH] chat_id={chat_id} message_id={message_id} "
                    f"message_type=photo | edit_media=failed: {e}\n{traceback.format_exc()}"
                )

        # Step 2: edit_message_media failed (or no image) — try caption-only edit
        # This is ONLY valid on a photo message (not a text message).
        try:
            await bot.edit_message_caption(
                chat_id=chat_id,
                message_id=message_id,
                caption=caption,
                parse_mode="HTML",
                reply_markup=reply_markup,
            )
            logger.info(
                f"[ROCLASH] chat_id={chat_id} message_id={message_id} "
                f"message_type=photo | edit_caption=success (media edit fallback)"
            )
            return
        except Exception as e:
            if _is_not_modified(e):
                logger.info(
                    f"[ROCLASH] chat_id={chat_id} message_id={message_id} "
                    f"message_type=photo | edit_caption=no-op (message already up to date)"
                )
                return
            logger.warning(
                f"[ROCLASH] chat_id={chat_id} message_id={message_id} "
                f"message_type=photo | edit_caption=failed: {e}\n{traceback.format_exc()}"
            )

        # Step 3: Both edits failed (e.g. "message not modified", "message can't
        # be edited", "message deleted", "invalid message", etc.) — recover by
        # sending a brand new battle message. The old message is intentionally
        # NEVER deleted: deleting it first and then failing to send a
        # replacement is exactly what used to make the battle UI vanish
        # completely. Instead we just send the new message and, once that
        # succeeds, start editing THAT message for all future turns.
        logger.info(
            f"[ROCLASH] chat_id={chat_id} message_id={message_id} | "
            f"Both photo edits failed — sending replacement battle message "
            f"(old message left as-is, not deleted)"
        )

        # Send fresh photo
        recovery_sent = False
        if img_bytes:
            try:
                sent = await bot.send_photo(
                    chat_id=chat_id,
                    photo=_io.BytesIO(img_bytes),
                    caption=caption,
                    parse_mode="HTML",
                    reply_markup=reply_markup,
                )
                data["battle_photo_id"]    = sent.photo[-1].file_id
                data["message_id"]         = sent.message_id
                data["battle_message_type"] = "photo"
                logger.info(
                    f"[ROCLASH] chat_id={chat_id} message_id={sent.message_id} | "
                    f"Recovery send_photo=success message_type=photo"
                )
                recovery_sent = True
            except Exception as e:
                logger.error(
                    f"[ROCLASH] chat_id={chat_id} | Recovery send_photo failed: {e}\n"
                    f"{traceback.format_exc()}"
                )

        if not recovery_sent:
            try:
                sent = await bot.send_message(
                    chat_id=chat_id,
                    text=caption,
                    parse_mode="HTML",
                    reply_markup=reply_markup,
                )
                data["message_id"]         = sent.message_id
                data["battle_message_type"] = "text"
                logger.info(
                    f"[ROCLASH] chat_id={chat_id} message_id={sent.message_id} | "
                    f"Recovery send_message=success message_type=text"
                )
            except Exception as e:
                logger.error(
                    f"[ROCLASH] chat_id={chat_id} | Recovery send_message failed: {e}\n"
                    f"{traceback.format_exc()}"
                )
        return

    # ── Branch B: message is a text message — use edit_message_text only ──────
    # Never call edit_message_caption or edit_message_media on a text message.
    try:
        await bot.edit_message_text(
            chat_id=chat_id,
            message_id=message_id,
            text=caption,
            parse_mode="HTML",
            reply_markup=reply_markup,
        )
        logger.info(
            f"[ROCLASH] chat_id={chat_id} message_id={message_id} "
            f"message_type=text | edit_text=success"
        )
    except Exception as e:
        if _is_not_modified(e):
            logger.info(
                f"[ROCLASH] chat_id={chat_id} message_id={message_id} "
                f"message_type=text | edit_text=no-op (message already up to date)"
            )
            return
        logger.error(
            f"[ROCLASH] chat_id={chat_id} message_id={message_id} "
            f"message_type=text | edit_text=failed: {e}\n{traceback.format_exc()}"
        )
        # Recovery for text message: send a new text message
        try:
            sent = await bot.send_message(
                chat_id=chat_id,
                text=caption,
                parse_mode="HTML",
                reply_markup=reply_markup,
            )
            data["message_id"]         = sent.message_id
            data["battle_message_type"] = "text"
            logger.info(
                f"[ROCLASH] chat_id={chat_id} message_id={sent.message_id} | "
                f"Recovery text send_message=success message_type=text"
            )
        except Exception as e2:
            logger.error(
                f"[ROCLASH] chat_id={chat_id} | Recovery send_message (text) failed: {e2}\n"
                f"{traceback.format_exc()}"
            )

# ─── End RoClash Visual System ───────────────────────────────────────────────


async def _nc_timeout_worker(battle_id: str, app) -> None:
    await asyncio.sleep(NC_TIMEOUT_SEC)
    data = _nc_load(battle_id)
    if not data or data["status"] == "finished":
        return
    if data["status"] != "battle":
        return
    bs       = data["battle_state"]
    turn_id  = bs.get("turn")
    other_id = data["p2_id"] if turn_id == data["p1_id"] else data["p1_id"]
    other_nm = data["p2_name"] if turn_id == data["p1_id"] else data["p1_name"]
    lazy_nm  = data["p1_name"] if turn_id == data["p1_id"] else data["p2_name"]

    # ── Inactivity timeout is a forfeit — no Pokémon EXP, Trainer EXP,
    #    RoRupees, rank progress, or any other reward is awarded ────────────
    data["status"] = "finished"
    _nc_save(battle_id, data)
    _clear_battle_lock(turn_id)
    _clear_battle_lock(other_id)

    text = (
        f"🏳️ <b>Battle Forfeited!</b>\n\n"
        f"{lazy_nm} forfeited due to inactivity.\n\n"
        f"No rewards or experience were awarded."
    )
    await _nc_update_battle_visual(app.bot, data, text)
    _nc_save(battle_id, data)
    _nc_delete(battle_id)

def _nc_reset_timeout(battle_id: str, app) -> None:
    if battle_id in _nc_timeout_tasks:
        _nc_timeout_tasks[battle_id].cancel()
    task = asyncio.create_task(_nc_timeout_worker(battle_id, app))
    _nc_timeout_tasks[battle_id] = task

def _nc_cancel_timeout(battle_id: str) -> None:
    task = _nc_timeout_tasks.pop(battle_id, None)
    if task:
        task.cancel()

# ─── /topnr command ───────────────────────────────────────────────────────────

async def topnr_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Show leaderboard of trainers with the highest RoRupee balance.
    Rankings are recalculated fresh from the DB on every invocation — no caching.
    Shows @usernames when used in the bot's DM; hides them in group chats."""

    is_dm = update.effective_chat.type == "private"

    # Always query fresh — no caching
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    excl_sql, excl_params = _leaderboard_exclusion_sql("user_id")
    cursor.execute(
        f"""
        SELECT trainer_name, COALESCE(nova_rupee, 0) AS nr, username
        FROM users
        WHERE trainer_name IS NOT NULL AND trainer_name != ''
        {excl_sql}
        ORDER BY nr DESC
        LIMIT 10
        """,
        excl_params
    )
    rows = cursor.fetchall()
    conn.close()

    if not rows:
        await update.message.reply_text(
            "No trainers found yet!",
            parse_mode="HTML"
        )
        return

    # Medal emojis for top 3, numbered for the rest
    medals = ["🥇", "🥈", "🥉"]

    lines = ["🏆 <b><u>Top Trainers By RoRupees:</u></b>\n"]
    for i, (trainer_name, nr, username) in enumerate(rows):
        rank = medals[i] if i < 3 else f"{i + 1}."
        nr_fmt = f"{nr:,}"
        uname_part = f" (@{username})" if is_dm and username else ""
        # Pad trainer name and amount so the 💶 icon aligns consistently
        lines.append(f"{rank} <b>{trainer_name}</b>{uname_part}     {nr_fmt} 💶")

    await update.message.reply_text(
        "\n".join(lines),
        parse_mode="HTML"
    )


# ─── /topdex command ──────────────────────────────────────────────────────────

async def topdex_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Show leaderboard of trainers with the largest Pokémon collection.
    Rankings are recalculated fresh from the DB on every invocation — no caching.
    Shows @usernames when used in the bot's DM; hides them in group chats.

    Primary sort:   total Pokémon owned DESC
    Tiebreaker:     unique species count DESC
    Also shows:     [unique_species/1025] Pokédex progress
    """

    is_dm = update.effective_chat.type == "private"

    # Single efficient query — one pass over user_pokemon, grouped per trainer
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    excl_sql, excl_params = _leaderboard_exclusion_sql("u.user_id")
    cursor.execute(
        f"""
        SELECT
            u.trainer_name,
            COUNT(up.id)                    AS total_owned,
            COUNT(DISTINCT up.pokemon_id)   AS unique_species,
            u.username
        FROM users u
        JOIN user_pokemon up ON up.user_id = u.user_id
        WHERE u.trainer_name IS NOT NULL AND u.trainer_name != ''
        {excl_sql}
        GROUP BY u.user_id, u.trainer_name
        ORDER BY total_owned DESC, unique_species DESC
        LIMIT 10
        """,
        excl_params
    )
    rows = cursor.fetchall()
    conn.close()

    if not rows:
        await update.message.reply_text(
            "No trainers with Pokémon found yet!",
            parse_mode="HTML"
        )
        return

    TOTAL_SPECIES = 1025
    medals = ["🥇", "🥈", "🥉"]

    lines = ["🧬 <b><u>Top Pokémon Owners:</u></b>\n"]
    for i, (trainer_name, total_owned, unique_species, username) in enumerate(rows):
        rank = medals[i] if i < 3 else f"{i + 1}."
        total_fmt = f"{total_owned:,}"
        dex_tag = f"[{unique_species}/{TOTAL_SPECIES}]"
        uname_part = f" (@{username})" if is_dm and username else ""
        lines.append(f"{rank} <b>{trainer_name}</b>{uname_part}      ×{total_fmt} {dex_tag}")

    await update.message.reply_text(
        "\n".join(lines),
        parse_mode="HTML"
    )


# ─── /topbond command ─────────────────────────────────────────────────────────

async def topbond_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Show leaderboard of trainers whose single highest-bonded Pokémon has the
    largest RoBond value.
    Rankings are recalculated fresh from the DB on every invocation — no caching.
    Shows @usernames when used in the bot's DM; hides them in group chats.
    Supports shiny (✨) prefix and special_tag bold display.
    """

    is_dm = update.effective_chat.type == "private"

    # Single query: for every trainer, find the one Pokémon with the highest
    # pokemon_bond value (DESC), then keep only the top 10 trainers.
    # We use MAX() so that SQLite picks the bond value, then we join back to
    # retrieve the matching row's name / shiny / special_tag.
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    excl_sql, excl_params = _leaderboard_exclusion_sql("u.user_id")
    cursor.execute(
        f"""
        SELECT
            u.trainer_name,
            u.username,
            up.pokemon_name,
            up.pokemon_bond,
            COALESCE(up.shiny, 0)        AS is_shiny,
            COALESCE(up.special_tag, '') AS special_tag
        FROM users u
        JOIN user_pokemon up ON up.user_id = u.user_id
        WHERE
            u.trainer_name IS NOT NULL AND u.trainer_name != ''
            {excl_sql}
            AND up.pokemon_bond = (
                SELECT MAX(up2.pokemon_bond)
                FROM user_pokemon up2
                WHERE up2.user_id = u.user_id
            )
        GROUP BY u.user_id
        ORDER BY up.pokemon_bond DESC
        LIMIT 10
        """,
        excl_params
    )
    rows = cursor.fetchall()
    conn.close()

    if not rows:
        await update.message.reply_text(
            "No trainers with RoBond data found yet!",
            parse_mode="HTML"
        )
        return

    medals = ["🥇", "🥈", "🥉"]

    lines = ["🧬 <b><u>Top Pokémon RoBonds:</u></b>\n"]
    for i, (trainer_name, username, pokemon_name, bond, is_shiny_int, special_tag) in enumerate(rows):
        rank       = medals[i] if i < 3 else f"{i + 1}."
        uname_part = f" (@{username})" if is_dm and username else ""

        # Build the Pokémon display string (shiny prefix → name → special tag)
        poke_display = display_name_with_shiny(pokemon_name, bool(is_shiny_int))
        poke_display = append_special_tag(poke_display, special_tag)

        bond_tag = f"[{bond:,}/10,000]"
        lines.append(
            f"{rank} <b>{trainer_name}</b>{uname_part}      {poke_display} {bond_tag}"
        )

    await update.message.reply_text(
        "\n".join(lines),
        parse_mode="HTML"
    )


