# ════════════════════════════════════ /MYSTATS COMMAND ════════════════════════════════════
# ── Trainer Card (image) ─────────────────────────────────────────────────────────────────
# Renders the /mystats Trainer Card on top of the fixed PokeRo template
# (https://iili.io/CcOVmNa.jpg) using Pillow. The template's boxes/labels are
# never redrawn or redesigned — only the blank value area of each existing
# label box is filled in, the left character panel gets Ash's Showdown
# trainer sprite, and the six POKÉMON: boxes get the active squad's front/
# shiny sprites (or are left completely blank for empty slots).
#
# The template ships with 6 label boxes; each one now shows exactly what
# its label says (a real Trainer Card, not a stats dashboard) — the
# RandomClash-specific breakdown and User ID don't get a dedicated box, but
# both remain in the caption text sent alongside the image:
#   NAME:        Trainer Name
#   RANK:        Trainer Rank
#   PokéDex:     National Pokédex (owned/total)
#   REGION:      Current region (updated by /travel)
#   WIN RATE:    Overall Win Rate + Total Wins
#   Started On:  Registration date (D/M/YY), stamped once at /start
#
# All coordinates below were measured directly from the 1276x832 template
# image (label box bands, the character panel border, and the 3x2 POKÉMON
# grid lines).

_TC_TEMPLATE_URL   = "https://iili.io/CcOVmNa.jpg"
_TC_ASH_SPRITE_URL = "https://iili.io/Cc6e2yX.png"

_TC_CHAR_BOX = (38, 144, 410, 796)          # Ash sprite panel interior (x0,y0,x1,y1)

_TC_VALUE_X     = 600                        # value text always starts here...
_TC_VALUE_RIGHT = 858                        # ...and must never cross this x

_TC_LABEL_BOXES = {                          # label -> (box_top_y, box_bottom_y)
    "name":       (265, 316),
    "rank":       (334, 385),
    "pokedex":    (402, 454),
    "region":     (471, 522),
    "winrate":    (540, 591),
    "startedon":  (607, 660),
}

_TC_TEAM_COLS = [(903, 1068), (1083, 1250)]           # (x0, x1) for the 2 columns
_TC_TEAM_ROWS = [(299, 458), (469, 629), (640, 802)]  # (y0, y1) for the 3 rows


def _tc_species_slug(raw) -> str:
    """Lightweight species-slug cleanup for Trainer Card sprite lookups.

    Deliberately does NOT collapse Mega/Primal/Origin/Crowned/Gigantamax
    display-name prefixes back to the base species the way
    normalize_species_lookup_name() does for the Move Relearner — the
    Trainer Card must show the exact form a Pokémon is stored as (regional,
    Hisuian, Paldean, Galarian, Alolan, Rider forms, etc.), so any form
    suffix already present in the stored pokemon_id slug is preserved as-is.
    """
    if raw is None:
        return ""
    s = str(raw).strip()
    if not s:
        return ""
    try:
        int(s)
        return s  # numeric PokéAPI ids pass straight through
    except ValueError:
        pass
    s = s.replace("\u2728", "").strip()              # strip shiny star
    s = re.sub(r"\s*\[[^\]]*\]\s*$", "", s).strip()   # strip trailing [Tag]
    s = s.lower().replace(" ", "-")
    s = re.sub(r"-{2,}", "-", s).strip("-")
    return s


async def _tc_dex_id(pokemon_id_or_name) -> "int | None":
    """Resolves a stored pokemon_id (species slug/name/number) to the numeric
    PokéAPI id used to build front/shiny sprite URLs — going through the
    same shared, persistent _cached_pokeapi_get gateway every other PokéAPI
    lookup in the bot uses, so a species already fetched anywhere else in
    the bot never costs a second network round-trip."""
    slug = _tc_species_slug(pokemon_id_or_name)
    if not slug:
        return None
    try:
        return int(slug)
    except ValueError:
        pass
    data = await _cached_pokeapi_get(f"https://pokeapi.co/api/v2/pokemon/{slug}")
    if data and "id" in data:
        return data["id"]
    # Defensive fallback: if the raw stored slug itself isn't a valid PokéAPI
    # name for some reason, try the base-species form (strips Mega/Primal/
    # etc. prefixes) so the card can still show *something* rather than
    # leaving an otherwise-valid team slot blank.
    fallback = normalize_species_lookup_name(pokemon_id_or_name)
    if fallback and fallback != slug:
        data = await _cached_pokeapi_get(f"https://pokeapi.co/api/v2/pokemon/{fallback}")
        if data and "id" in data:
            return data["id"]
    return None


async def _tc_get_team_sprite(pokemon_id_or_name, is_shiny: bool):
    """Downloads (via the bot's existing in-memory sprite cache) and decodes
    the correct front battle sprite for one Trainer Card team slot. Returns a
    Pillow RGBA Image, or None if the species/sprite could not be resolved —
    callers must leave the slot blank in that case, never draw a placeholder."""
    dex_id = await _tc_dex_id(pokemon_id_or_name)
    if not dex_id:
        return None
    url = _nc_sprite_url(dex_id, back=False, shiny=is_shiny)
    if not url:
        return None
    raw = await _cached_sprite_bytes(url)
    if not raw and is_shiny:
        # A handful of forms have no dedicated shiny sprite file — fall back
        # to the normal sprite rather than dropping a shiny mon from the card.
        raw = await _cached_sprite_bytes(_nc_sprite_url(dex_id, back=False, shiny=False))
    if not raw:
        return None
    try:
        import io as _io
        from PIL import Image
        return Image.open(_io.BytesIO(raw)).convert("RGBA")
    except Exception as e:
        logger.warning(f"[TrainerCard] Sprite decode failed for dex id {dex_id}: {e}")
        return None


def _tc_load_font(size: int, bold: bool = True):
    """Loads a clean anti-aliased TrueType font, falling back gracefully
    across a handful of common Linux font paths and finally to Pillow's own
    bundled scalable default font so the card never fails to render text
    purely because of missing system fonts."""
    from PIL import ImageFont
    candidates = (
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
        "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf",
        "/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf",
    ) if bold else (
        "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
        "/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf",
    )
    for path in candidates:
        try:
            return ImageFont.truetype(path, size)
        except Exception:
            continue
    try:
        return ImageFont.load_default(size=size)
    except TypeError:
        return ImageFont.load_default()


def _tc_fit_text(draw, text: str, size: int, max_width: int, min_size: int = 11, bold: bool = True):
    """Shrinks the font size until *text* fits within max_width; if it's
    still too wide at min_size (pathologically long trainer names etc.) the
    text itself is truncated with an ellipsis as a last resort so a value
    can never spill outside its template box."""
    size = max(size, min_size)
    font = _tc_load_font(size, bold=bold)
    while size > min_size and draw.textlength(text, font=font) > max_width:
        size -= 1
        font = _tc_load_font(size, bold=bold)
    if draw.textlength(text, font=font) > max_width:
        while text and draw.textlength(text + "…", font=font) > max_width:
            text = text[:-1]
        if text:
            text = text + "…"
    return font, text


def _tc_draw_value(draw, text: str, x: int, box_top: int, box_bottom: int,
                    size: int, max_width: int, fill=(255, 255, 255, 255), bold: bool = True) -> None:
    """Draws *text* left-aligned at x, vertically centered within
    [box_top, box_bottom], auto-shrinking/truncating so it never overflows
    its template box."""
    font, text = _tc_fit_text(draw, text, size, max_width, bold=bold)
    bbox = draw.textbbox((0, 0), text, font=font)
    text_h = bbox[3] - bbox[1]
    y = box_top + (box_bottom - box_top - text_h) // 2 - bbox[1]
    draw.text((x, y), text, font=font, fill=fill)


def _tc_center_paste(canvas, sprite, box: tuple, pad: int = 10) -> None:
    """Auto-crops *sprite* to its actual opaque content first — stripping any
    transparent margin baked into the source PNG's canvas (Showdown trainer
    sprites and some Pokémon sprites ship with a lot of empty space around a
    much smaller subject, which otherwise renders tiny and off-center no
    matter how the box is padded) — then scales the cropped content
    proportionally (high-quality LANCZOS) to fill as much of *box* minus
    padding as possible, enlarging small sprites as well as shrinking large
    ones (Pillow's .thumbnail() only ever shrinks, which was the reason a
    small sprite used to stay small even inside a much bigger box), and
    alpha-composites it centered. Preserves transparency throughout."""
    from PIL import Image
    x0, y0, x1, y1 = box
    s = sprite if sprite.mode == "RGBA" else sprite.convert("RGBA")
    content_bbox = s.getchannel("A").getbbox()
    s = s.crop(content_bbox) if content_bbox else s.copy()
    max_w = max(1, (x1 - x0) - pad * 2)
    max_h = max(1, (y1 - y0) - pad * 2)
    scale = min(max_w / s.width, max_h / s.height)
    new_w = max(1, round(s.width * scale))
    new_h = max(1, round(s.height * scale))
    if (new_w, new_h) != s.size:
        s = s.resize((new_w, new_h), Image.LANCZOS)
    px = x0 + (x1 - x0 - s.width) // 2
    py = y0 + (y1 - y0 - s.height) // 2
    canvas.alpha_composite(s, (px, py))


async def _get_active_team_for_card(user_id: int) -> list:
    """Returns exactly 6 slots for the trainer's active squad:
    [{"pokemon_id": ..., "shiny": bool} or None, ...]. Missing/empty slots
    are None so the caller leaves that template box completely blank —
    never a placeholder, never a question mark."""
    squad = get_active_squad(user_id)
    slots = [None] * 6
    if not squad:
        return slots
    pokemon_ids = json.loads(squad[2] or "[]")
    if not pokemon_ids:
        return slots
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    for i, pid in enumerate(pokemon_ids[:6]):
        cursor.execute(
            "SELECT pokemon_id, COALESCE(shiny, 0) FROM user_pokemon WHERE id = ? AND user_id = ?",
            (pid, user_id)
        )
        row = cursor.fetchone()
        if row:
            slots[i] = {"pokemon_id": row[0], "shiny": bool(row[1])}
    conn.close()
    return slots


async def build_trainer_card_image(
    *,
    trainer_name: str,
    user_id: int,
    rank_name: str,
    owned_species: int,
    total_species: int,
    current_region: str,
    started_on: str,
    total_wins: int,
    overall_win_rate: int,
    team_slots: list,
) -> "bytes | None":
    """Builds the full Trainer Card JPEG for /mystats. Returns None on any
    failure (missing Pillow, template unreachable, undecodable image, etc.)
    so the caller can fall back to the plain-text stats message — /mystats
    must never break because the image couldn't be generated."""
    try:
        import io as _io
        from PIL import Image, ImageDraw
    except ImportError as e:
        logger.error(f"[TrainerCard] Pillow unavailable, cannot build card: {e}")
        return None

    # Template is fetched through the bot's existing sprite/image byte cache
    # (in-memory, keyed by URL) — downloaded once, reused for every future
    # /mystats call for any trainer, exactly like every other cached sprite.
    template_bytes = await _cached_sprite_bytes(_TC_TEMPLATE_URL)
    if not template_bytes:
        logger.warning("[TrainerCard] Could not download template image")
        return None

    try:
        canvas = Image.open(_io.BytesIO(template_bytes)).convert("RGBA")
    except Exception as e:
        logger.warning(f"[TrainerCard] Could not decode template image: {e}")
        return None

    draw = ImageDraw.Draw(canvas, "RGBA")
    WHITE = (255, 255, 255, 255)
    value_w = _TC_VALUE_RIGHT - _TC_VALUE_X

    # ── Label-box values (see mapping note above the constants) ─────────────
    top, bot = _TC_LABEL_BOXES["name"]
    _tc_draw_value(draw, str(trainer_name), _TC_VALUE_X, top, bot, 24, value_w, fill=WHITE)

    top, bot = _TC_LABEL_BOXES["rank"]
    _tc_draw_value(draw, str(rank_name), _TC_VALUE_X, top, bot, 24, value_w, fill=WHITE)

    top, bot = _TC_LABEL_BOXES["pokedex"]
    _tc_draw_value(draw, f"{owned_species:,}/{total_species:,}", _TC_VALUE_X, top, bot, 24, value_w, fill=WHITE)

    top, bot = _TC_LABEL_BOXES["region"]
    _tc_draw_value(draw, str(current_region), _TC_VALUE_X, top, bot, 24, value_w, fill=WHITE)

    top, bot = _TC_LABEL_BOXES["winrate"]
    _tc_draw_value(draw, f"{overall_win_rate}% ({total_wins:,} Wins)", _TC_VALUE_X, top, bot, 22, value_w, fill=WHITE)

    top, bot = _TC_LABEL_BOXES["startedon"]
    _tc_draw_value(draw, str(started_on), _TC_VALUE_X, top, bot, 24, value_w, fill=WHITE)

    # ── Ash sprite (character panel, left side) ─────────────────────────────
    ash_bytes = await _cached_sprite_bytes(_TC_ASH_SPRITE_URL)
    if ash_bytes:
        try:
            ash_img = Image.open(_io.BytesIO(ash_bytes)).convert("RGBA")
            _tc_center_paste(canvas, ash_img, _TC_CHAR_BOX, pad=4)
        except Exception as e:
            logger.warning(f"[TrainerCard] Could not decode Ash sprite: {e}")

    # ── Active team sprites (6 boxes, row-major: TL,TR / ML,MR / BL,BR) ─────
    cells = [(cx0, cy0, cx1, cy1) for (cy0, cy1) in _TC_TEAM_ROWS for (cx0, cx1) in _TC_TEAM_COLS]
    for i, cell in enumerate(cells):
        slot = team_slots[i] if i < len(team_slots) else None
        if not slot:
            continue  # empty slot -- leave the box completely blank
        sprite_img = await _tc_get_team_sprite(slot["pokemon_id"], slot["shiny"])
        if sprite_img is None:
            continue  # unresolvable sprite -- leave blank rather than guess
        _tc_center_paste(canvas, sprite_img, cell, pad=14)

    out = _io.BytesIO()
    canvas.convert("RGB").save(out, format="JPEG", quality=92)
    out.seek(0)
    return out.getvalue()


async def mystats_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Shows the stats of the trainer who executed the command.
    Works in both private chats and groups — always reports the sender's own stats,
    never another trainer's, regardless of chat type."""
    user = update.effective_user

    if not is_registered(user.id):
        await update.message.reply_text("You need to register first with /start.")
        return

    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        "SELECT trainer_name, COALESCE(trainer_exp, 0), "
        "COALESCE(challenge_wins, 0), COALESCE(challenge_battles, 0), "
        "COALESCE(randomclash_wins, 0), COALESCE(randomclash_battles, 0), "
        "COALESCE(current_region, 'Kanto'), COALESCE(joined_at, 0) "
        "FROM users WHERE user_id = ?",
        (user.id,)
    )
    row = cursor.fetchone()

    # National Pokédex: count only unique species owned, not duplicates
    cursor.execute(
        "SELECT COUNT(DISTINCT pokemon_id) FROM user_pokemon WHERE user_id = ?", (user.id,)
    )
    dex_row = cursor.fetchone()
    conn.close()

    if not row:
        await update.message.reply_text("You need to register first with /start.")
        return

    (trainer_name, trainer_exp, challenge_wins, challenge_battles,
     randomclash_wins, randomclash_battles, current_region, joined_at_ts) = row

    trainer_name  = trainer_name or user.first_name
    owned_species = dex_row[0] if dex_row else 0
    TOTAL_SPECIES = 1025

    rank_name, _, _ = get_trainer_rank(trainer_exp)

    # Division-by-zero safe: 0% when no battles of that type have been played
    randomclash_win_rate = (
        round((randomclash_wins / randomclash_battles) * 100) if randomclash_battles > 0 else 0
    )
    overall_win_rate = (
        round((challenge_wins / challenge_battles) * 100) if challenge_battles > 0 else 0
    )

    # "Started On:" -- registration date as D/M/YY (e.g. 7/7/26)
    if joined_at_ts:
        _joined_dt = datetime.fromtimestamp(joined_at_ts)
        started_on = f"{_joined_dt.day}/{_joined_dt.month}/{_joined_dt.strftime('%y')}"
    else:
        started_on = "Unknown"

    text = (
        "💠 <b><u>Trainer Status</u></b> :\n\n"
        f"✦ <b>Name</b> : {trainer_name}\n"
        f"✦ <b>Trainer Rank</b> : {rank_name}\n"
        f"✦ <b>National Pokédex</b> : {owned_species:,}/{TOTAL_SPECIES:,}\n"
        f"✦ <b>RandomClash Wins</b> : {randomclash_wins:,}\n"
        f"✦ <b>RandomClash Win Rate</b> : {randomclash_win_rate}%\n"
        f"✦ <b>Total Wins</b> : {challenge_wins:,}\n"
        f"✦ <b>Win Rate</b> : {overall_win_rate}%"
    )

    # ── Trainer Card image (best-effort — never blocks the text stats) ──────
    # Any failure anywhere in the pipeline (template/sprite download,
    # decoding, Pillow missing, etc.) falls back to the original plain-text
    # reply so /mystats keeps working exactly as before.
    image_bytes = None
    try:
        team_slots = await _get_active_team_for_card(user.id)
        image_bytes = await build_trainer_card_image(
            trainer_name=trainer_name,
            user_id=user.id,
            rank_name=rank_name,
            owned_species=owned_species,
            total_species=TOTAL_SPECIES,
            current_region=current_region,
            started_on=started_on,
            total_wins=challenge_wins,
            overall_win_rate=overall_win_rate,
            team_slots=team_slots,
        )
    except Exception as e:
        logger.error(f"[TrainerCard] Failed to build /mystats card image for user {user.id}: {e}")
        image_bytes = None

    if image_bytes:
        import io as _io
        await update.message.reply_photo(
            photo=_io.BytesIO(image_bytes),
            caption=text,
            parse_mode="HTML",
        )
    else:
        await update.message.reply_text(text, parse_mode="HTML")


# ════════════════════════════════════ REFERRAL SYSTEM ════════════════════════════════════

# Milestone definitions: (referral_count, reward_description, reward_fn)
# reward_fn(conn, cursor, referrer_id) applies the reward in-DB
REFERRAL_MILESTONES = [
    (1,  "💰 1,000 RoRupees",
         lambda uid: increment_user(uid, nova_rupee=1000)),
    (5,  "🎁 5,000 RoRupees + 50 Regular Balls",
         lambda uid: increment_user(uid, nova_rupee=5000, pokeballs=50)),
    (10, "✨ Random Rare Pokémon (granted by admin)",
         None),   # complex reward — handled separately with a notification
    (25, "💰 15,000 RoRupees + 30 Ultra Balls",
         lambda uid: increment_user(uid, nova_rupee=15000, ultraballs=30)),
    (50, "🌟 Referral Badge + 3 Master Balls + 20,000 RoRupees",
         lambda uid: (increment_user(uid, nova_rupee=20000, master_ball=3), update_user(uid, referral_badge=1))),
]

REFERRAL_VALID_RANK     = "Elite"     # referred user must reach this rank
REFERRAL_VALID_CATCHES  = 100         # referred user must catch this many Pokémon


def _gen_referral_code(user_id: int) -> str:
    """Generate a unique referral code for a trainer."""
    raw = f"RO{user_id}{int(time.time())}"
    h   = hashlib.md5(raw.encode()).hexdigest().upper()
    return f"RO{h[:6]}"


def _ensure_referral_code(user_id: int) -> str:
    """Get or create a referral code for the trainer."""
    profile = get_user(user_id)
    if profile is None:
        return ""
    code = profile.get("referral_code") or ""
    if not code:
        code = _gen_referral_code(user_id)
        update_user(user_id, referral_code=code)
    return code


def _get_valid_referral_count(user_id: int) -> int:
    """Return how many valid referrals this trainer has."""
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        "SELECT COUNT(*) FROM referrals WHERE referrer_id = ? AND is_valid = 1", (user_id,)
    )
    count = cursor.fetchone()[0]
    conn.close()
    return count


def _get_total_referral_count(user_id: int) -> int:
    """Return total referrals (including pending)."""
    conn = sqlite3.connect("ZNX.db")
    cursor = conn.cursor()
    cursor.execute(
        "SELECT COUNT(*) FROM referrals WHERE referrer_id = ?", (user_id,)
    )
    count = cursor.fetchone()[0]
    conn.close()
    return count


async def _check_referral_milestones(bot, referrer_id: int, valid_count: int) -> None:
    """Check and grant any newly unlocked referral milestones."""
    conn = get_db("ZNX.db")
    cursor = conn.cursor()

    for req_count, reward_desc, reward_fn in REFERRAL_MILESTONES:
        if valid_count < req_count:
            continue
        # Check if already claimed
        cursor.execute(
            "SELECT 1 FROM referral_milestones WHERE user_id = ? AND milestone = ?",
            (referrer_id, req_count)
        )
        if cursor.fetchone():
            continue
        # Grant reward — reward_fn now writes straight to USER_CACHE via
        # increment_user()/update_user() (see REFERRAL_MILESTONES above),
        # so it no longer needs the raw conn/cursor.
        if reward_fn:
            reward_fn(referrer_id)
        cursor.execute(
            "INSERT OR IGNORE INTO referral_milestones (user_id, milestone) VALUES (?, ?)",
            (referrer_id, req_count)
        )
        conn.commit()

        # Notify referrer
        notif = (
            "🎁 <b>Referral Reward Unlocked!</b>\n\n"
            f"Reward:\n{reward_desc}\n\n"
            "Added to your inventory."
        )
        try:
            await bot.send_message(chat_id=referrer_id, text=notif, parse_mode="HTML")
        except Exception:
            pass


async def referral_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Show the trainer's referral stats and unique invite link."""
    user = update.effective_user

    profile = get_user(user.id)
    if profile is None:
        await update.message.reply_text("You haven't registered yet! Type /start to begin your journey.")
        return

    code        = _ensure_referral_code(user.id)
    total_ref   = _get_total_referral_count(user.id)
    valid_ref   = _get_valid_referral_count(user.id)
    ref_link    = f"https://t.me/PokieNova_bot?start={code}"

    # Progress bar toward next milestone
    next_ms = None
    for req_count, _, _ in REFERRAL_MILESTONES:
        if valid_ref < req_count:
            next_ms = req_count
            break
    if next_ms is None:
        next_ms = REFERRAL_MILESTONES[-1][0]  # already at top

    bar_len    = 18
    bar_filled = int(valid_ref / next_ms * bar_len) if next_ms > 0 else bar_len
    bar_filled = min(bar_filled, bar_len)
    prog_bar   = "█" * bar_filled + "░" * (bar_len - bar_filled)

    reward_lines = ""
    for req_count, desc, _ in REFERRAL_MILESTONES:
        medal = {1: "🥇", 5: "🥈", 10: "🥉", 25: "🏆", 50: "👑"}.get(req_count, "🎁")
        reward_lines += f"\n{medal} {req_count} Referral{'s' if req_count > 1 else ''} ➜ {desc}\n"

    text = (
        f"👤 Your Referrals : {total_ref} Trainer{'s' if total_ref != 1 else ''}\n\n"
        f"🎟 Referral Link :\n\n{ref_link}\n\n"
        f"🎉 <b>Referral Rewards</b>\n"
        f"{reward_lines}\n"
        f"📊 <b>Referral Progress</b>\n\n"
        f"{prog_bar} {valid_ref} / {next_ms}\n\n"
        f"💡 Invite your friends using your unique referral link. Your friend must reach "
        f"<b>{REFERRAL_VALID_RANK}</b> rank and catch <b>{REFERRAL_VALID_CATCHES} Pokémon</b> "
        f"before the referral becomes valid.\n\n"
        f"⚠️ Each player can only be referred once."
    )

    keyboard = [[InlineKeyboardButton("Send to your friends", switch_inline_query=ref_link)]]
    await update.message.reply_text(
        text,
        parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(keyboard)
    )


async def _process_referral_start(bot, referred_id: int, code: str) -> None:
    """
    Called when a new trainer registers via a referral link.
    Stores the pending referral (not yet valid) and notifies the referrer.
    """
    # Find referrer by code — this is a lookup BY referral_code, not by
    # user_id, so USER_CACHE (keyed only by user_id) can't serve it via a
    # simple key lookup. BUT: a referral code generated moments ago via
    # _ensure_referral_code() may still be sitting only in USER_CACHE,
    # not yet flushed to disk (cache_flush_loop runs every 45s) — a pure
    # disk query would miss it and silently fail to link the referral for
    # up to that whole window. So check the in-memory cache for a match
    # first (cheap: this only runs once per new-user /start with a
    # referral code, not on a hot path), and fall back to disk for
    # referrers who aren't currently cached at all.
    conn = get_db("ZNX.db")
    cursor = conn.cursor()
    referrer_id = None
    referrer_name = None
    for _uid, _profile in USER_CACHE.items():
        if _profile.get("referral_code") == code:
            referrer_id = _uid
            referrer_name = _profile.get("trainer_name")
            break
    if referrer_id is None:
        cursor.execute("SELECT user_id, trainer_name FROM users WHERE referral_code = ?", (code,))
        referrer_row = cursor.fetchone()
        if not referrer_row:
            return
        referrer_id, referrer_name = referrer_row

    # Self-referral guard
    if referrer_id == referred_id:
        return

    # Already referred guard
    cursor.execute("SELECT 1 FROM referrals WHERE referred_id = ?", (referred_id,))
    if cursor.fetchone():
        return

    # Get referred trainer name
    referred_profile = get_user(referred_id)
    referred_name = (referred_profile.get("trainer_name") if referred_profile else None) or "Unknown"

    # Store referral (pending, not yet valid) — referrals table, stays raw SQL
    cursor.execute(
        "INSERT OR IGNORE INTO referrals (referrer_id, referred_id, is_valid, joined_at) VALUES (?, ?, 0, ?)",
        (referrer_id, referred_id, int(time.time()))
    )
    conn.commit()
    # Store back-reference on referred user — this IS a `users` column
    update_user(referred_id, referrer_id=referrer_id)

    # Notify referrer
    notif = (
        "🎉 <b>New Referral!</b>\n\n"
        f"Trainer:\n<b>{referred_name}</b>\n\n"
        "Joined using your referral link.\n\n"
        "Progress:\n0/100 Pokémon\nRank: Rookie"
    )
    try:
        await bot.send_message(chat_id=referrer_id, text=notif, parse_mode="HTML")
    except Exception:
        pass


async def _check_referral_completion(bot, referred_id: int) -> None:
    """
    Called whenever a referred trainer earns EXP or catches a Pokémon.
    Validates the referral if conditions are met (Elite rank + 100 catches).
    """
    conn   = get_db("ZNX.db")
    cursor = conn.cursor()

    # Is this user referred?
    cursor.execute(
        "SELECT id, referrer_id, is_valid FROM referrals WHERE referred_id = ?", (referred_id,)
    )
    ref_row = cursor.fetchone()
    if not ref_row or ref_row[2]:  # Not referred or already valid
        return

    ref_db_id, referrer_id, _ = ref_row

    # Check trainer exp (Elite = 40,000)
    referred_profile = get_user(referred_id)
    trainer_exp = (referred_profile.get("trainer_exp") or 0) if referred_profile else 0
    rank_name, _, _ = get_trainer_rank(trainer_exp)

    # Check Pokémon catches (distinct species)
    cursor.execute(
        "SELECT COUNT(*) FROM user_pokemon WHERE user_id = ?", (referred_id,)
    )
    catch_row   = cursor.fetchone()
    catch_count = catch_row[0] if catch_row else 0

    reached_elite  = (rank_name == REFERRAL_VALID_RANK or
                      trainer_exp >= 40_000)  # Elite threshold
    reached_catches = catch_count >= REFERRAL_VALID_CATCHES

    if not (reached_elite and reached_catches):
        return

    # Mark referral as valid
    cursor.execute(
        "UPDATE referrals SET is_valid = 1, validated_at = ? WHERE id = ?",
        (int(time.time()), ref_db_id)
    )
    conn.commit()

    # Get referred trainer name to notify referrer
    referred_name = (referred_profile.get("trainer_name") if referred_profile else None) or "A trainer"

    valid_count = 0
    cursor.execute(
        "SELECT COUNT(*) FROM referrals WHERE referrer_id = ? AND is_valid = 1",
        (referrer_id,)
    )
    valid_count_row = cursor.fetchone()
    valid_count = valid_count_row[0] if valid_count_row else 0

    # Notify referrer of completion
    notif = (
        "🎉 <b>Referral Completed!</b>\n\n"
        f"<b>{referred_name}</b> has reached {REFERRAL_VALID_RANK} Rank "
        f"and caught {REFERRAL_VALID_CATCHES} Pokémon.\n\n"
        "Referral count increased."
    )
    try:
        await bot.send_message(chat_id=referrer_id, text=notif, parse_mode="HTML")
    except Exception:
        pass

    # Check and grant milestones
    await _check_referral_milestones(bot, referrer_id, valid_count)


