# ─── /rofree command ────────────────────────────────────────────────────────


def _rofree_has_battle_state(target_id: int) -> bool:
    """True if the target trainer currently has any active/stuck battle state."""
    in_wild_battle   = _is_in_battle(target_id)
    in_roclash     = _nc_find_by_player(target_id) is not None
    return bool(
        in_wild_battle or
        in_roclash or
        battle_last_activity.get(target_id) or
        battle_callback_last.get(target_id)
    )


def _rofree_clear(context: ContextTypes.DEFAULT_TYPE, target_id: int) -> None:
    """Performs the actual battle-state clearing for /rofree."""
    # ── Clear wild-battle state from user_data ────────────────────────────────
    try:
        target_data = context.application.user_data.get(target_id)
        if target_data:
            target_data['battle_state']      = None
            target_data['active_hunt_msg_id'] = None
    except Exception:
        pass

    # ── Clear RoClash DB entry ──────────────────────────────────────────────
    nc_data = _nc_find_by_player(target_id)
    if nc_data:
        _nc_delete(nc_data["battle_id"])

    # ── Clear persistent battle lock + in-memory trackers ────────────────────
    _clear_battle_lock(target_id)           # clears DB flag + battle_last_activity + battle_callback_last


async def rofree(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Free a trainer (or another trainer, if Head Admin) from a stuck battle state.
    Completely free — executes immediately with no confirmation step."""
    user = update.effective_user
    msg  = update.message

    # ── Determine target ──────────────────────────────────────────────────────
    args = context.args
    target_id = user.id  # default: free yourself

    if args:
        # Only Head Admins may free another trainer
        if not _ap_is_head_admin(user.id):
            await msg.reply_text("❌ Only Head Admins can free other trainers.")
            return
        try:
            target_id = int(args[0])
        except ValueError:
            await msg.reply_text("❌ Invalid user ID. Usage: /rofree {user_id}")
            return

    # ── Check whether the target has any active battle state ─────────────────
    if not _rofree_has_battle_state(target_id):
        if target_id == user.id:
            await msg.reply_text("You are not currently stuck in a battle.")
        else:
            await msg.reply_text(f"Trainer {target_id} is not currently stuck in a battle.")
        return

    # ── Clear immediately — no cost, no confirmation ──────────────────────────
    _rofree_clear(context, target_id)

    # ── Reply ─────────────────────────────────────────────────────────────────
    if target_id == user.id:
        result_text = "✅ All battle locks have been cleared.\n\nYou may now battle again."
    else:
        result_text = f"✅ Successfully cleared battle locks for {target_id}."

    await msg.reply_text(result_text)

# ─── /roclash command ───────────────────────────────────────────────────────

async def roclash(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Challenge another trainer to a  PvP battle."""
    user = update.effective_user
    msg  = update.message

    if not is_registered(user.id):
        await msg.reply_text("You need to register first with /start.")
        return

    if _is_in_battle(user.id):
        await msg.reply_text("You are already in a battle.")
        return

    # Only block if in an ACTIVE battle session (battle/selecting) — not a pending challenge
    if _nc_find_by_player(user.id):
        await msg.reply_text("You are already in an active battle.")
        return

    if not msg.reply_to_message:
        await msg.reply_text("⚔️ Reply to another trainer's message to challenge them!\nUsage: /challenge (reply)")
        return

    opponent = msg.reply_to_message.from_user
    if opponent.id == user.id:
        await msg.reply_text("You can't challenge yourself!")
        return

    if not is_registered(opponent.id):
        await msg.reply_text("That trainer hasn't registered yet.")
        return

    if _is_in_battle(opponent.id):
        await msg.reply_text(f"{opponent.first_name} is already in a battle.")
        return

    # Only block opponent if they are in an active battle session
    if _nc_find_by_player(opponent.id):
        await msg.reply_text(f"{opponent.first_name} is already in an active battle.")
        return

    # Get trainer names
    p1_profile = get_user(user.id)
    p2_profile = get_user(opponent.id)
    p1_name = (p1_profile.get("trainer_name") if p1_profile else None) or user.first_name
    p2_name = (p2_profile.get("trainer_name") if p2_profile else None) or opponent.first_name

    battle_id = uuid.uuid4().hex[:12]
    _nc_create(battle_id, user.id, p1_name, opponent.id, p2_name, msg.chat_id, 0)

    data = _nc_load(battle_id)
    data["battle_state"]["p1_ready"] = True
    data["battle_state"]["p2_ready"] = False
    _nc_save(battle_id, data)

    text = _nc_challenge_text(data)
    kbd  = _nc_challenge_kbd(battle_id)
    sent = await msg.reply_text(text, parse_mode="HTML", reply_markup=kbd)

    data["message_id"] = sent.message_id
    data["chat_id"]    = sent.chat_id
    _nc_save(battle_id, data)

# ─── Challenge callbacks ───────────────────────────────────────────────────────

async def nc_accept_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query     = update.callback_query
    user      = query.from_user
    battle_id = query.data.split(":")[1]
    data      = _nc_load(battle_id)

    if not data:
        await query.answer("Challenge expired.", show_alert=True)
        return
    if user.id != data["p2_id"]:
        await query.answer("This challenge does not belong to you.", show_alert=True)
        return
    if data["status"] != "pending":
        await query.answer("This challenge is no longer active.", show_alert=True)
        return

    settings = data["settings"]
    mode     = settings.get("mode", "Open")
    size     = settings.get("size", 6)

    # ── Validate both squads before starting ─────────────────────────────────
    for pid, pname in ((data["p1_id"], data["p1_name"]), (data["p2_id"], data["p2_name"])):
        squad = get_active_squad(pid)
        if not squad:
            await query.answer(
                f"{pname} has no active squad. Set one up with /myteam first.",
                show_alert=True
            )
            return

        pids = json.loads(squad[2] or "[]")

        # Open mode: no squad size or legendary restrictions — just needs at least 1 Pokémon
        if mode == "Open":
            if len(pids) == 0:
                await query.answer(
                    f"{pname}'s squad is empty. Set one up with /myteam first.",
                    show_alert=True
                )
                return
            continue

        # Team size check (non-Open modes)
        if len(pids) < size:
            await query.answer(
                "⚠️ Your Team Doesn't Meet The Battle Rules.\n\n"
                "Do /myteam in DM and Set Team According To Rules.",
                show_alert=True
            )
            return

        # Camp & empty slot check
        valid_pids = []
        for db_id in pids[:size]:
            if is_pokemon_in_camp(db_id):
                await query.answer(
                    "⚠️ Your Team Doesn't Meet The Battle Rules.\n\n"
                    "Do /myteam in DM and Set Team According To Rules.",
                    show_alert=True
                )
                return
            valid_pids.append(db_id)

        if len(valid_pids) < size:
            await query.answer(
                "⚠️ Your Team Doesn't Meet The Battle Rules.\n\n"
                "Do /myteam in DM and Set Team According To Rules.",
                show_alert=True
            )
            return

        # Mode validation — each Pokémon's restricted-status check is
        # independent of the others, so run them concurrently instead of
        # awaiting one at a time.
        restricted_flags = await asyncio.gather(
            *[_nc_is_restricted_by_db(db_id) for db_id in valid_pids]
        )
        restricted_count = sum(1 for flag in restricted_flags if flag)
        normal_count = size - restricted_count

        if mode == "6L":
            if restricted_count < size:
                await query.answer(
                    "⚠️ Your Team Doesn't Meet The Battle Rules.\n\n"
                    "6L Mode Only Allows Legendary And Mythical Pokémon.\n\n"
                    "Do /myteam in DM and Set Team According To Rules.",
                    show_alert=True
                )
                return
        elif mode == "0L":
            if restricted_count > 0:
                await query.answer(
                    "⚠️ Your Team Doesn't Meet The Battle Rules.\n\n"
                    "0L Mode Does Not Allow Legendary Or Mythical Pokémon.\n\n"
                    "Do /myteam in DM and Set Team According To Rules.",
                    show_alert=True
                )
                return
        elif mode == "Mix":
            half = size // 2
            if restricted_count != half or normal_count != half:
                await query.answer(
                    "⚠️ Your Team Doesn't Meet The Battle Rules.\n\n"
                    f"Mix Mode Requires Exactly {half} Legendary/Mythical Pokémon "
                    f"And {half} Non-Legendary Pokémon.\n\n"
                    "Do /myteam in DM and Set Team According To Rules.",
                    show_alert=True
                )
                return

    # ── All checks passed — load squad ids and start battle ──────────────────
    def _get_squad_ids(player_id, team_size, open_mode=False):
        sq = get_active_squad(player_id)
        pids = json.loads(sq[2] or "[]")
        return pids if open_mode else pids[:team_size]

    open_mode = (mode == "Open")
    sel1 = _get_squad_ids(data["p1_id"], size, open_mode)
    sel2 = _get_squad_ids(data["p2_id"], size, open_mode)

    data["battle_state"]["sel1"] = sel1
    data["battle_state"]["sel2"] = sel2
    data["status"] = "selecting"
    _nc_save(battle_id, data)

    await query.answer("Challenge accepted! Starting battle...")
    await query.edit_message_text(
        f"⚔️ <b>{data['p1_name']}</b> vs <b>{data['p2_name']}</b>\n\nLoading teams...",
        parse_mode="HTML"
    )

    await _nc_start_battle(context, battle_id)

async def nc_decline_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    query     = update.callback_query
    user      = query.from_user
    battle_id = query.data.split(":")[1]
    data      = _nc_load(battle_id)

    if not data:
        await query.answer("Challenge expired.", show_alert=True)
        return
    if user.id != data["p2_id"]:
        await query.answer("This challenge does not belong to you.", show_alert=True)
        return

    _nc_delete(battle_id)
    await query.answer("Challenge declined.")
    await query.edit_message_text(
        f"❌ <b>{data['p2_name']}</b> declined the challenge.",
        parse_mode="HTML"
    )

