async def nc_save_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Permanently save current RoClash settings as the challenger's defaults.
    Does NOT return to the challenge screen — stays on the settings page."""
    query     = update.callback_query
    user      = query.from_user
    battle_id = query.data.split(":")[1]
    data      = _nc_load(battle_id)

    if not data or user.id != data["p1_id"]:
        await query.answer("Not allowed.", show_alert=True)
        return

    # Persist settings into user_settings table
    settings_json = json.dumps(data["settings"])
    conn = sqlite3.connect("ZNX.db")
    cur  = conn.cursor()
    cur.execute("INSERT OR IGNORE INTO user_settings (user_id) VALUES (?)", (user.id,))
    cur.execute(
        "UPDATE user_settings SET nc_default_settings = ? WHERE user_id = ?",
        (settings_json, user.id)
    )
    conn.commit()
    conn.close()

    await query.answer("Settings Saved", show_alert=True)
    # Stay on settings page (just refresh it in case text changed)
    try:
        await query.edit_message_text(
            _nc_settings_text(data), parse_mode="HTML",
            reply_markup=_nc_settings_kbd(battle_id, data["settings"])
        )
    except Exception:
        pass

