# ── Helpers ────────────────────────────────────────────────────────────────────

def _is_rc_battle(battle_id: str) -> bool:
    """Return True if the battle_id belongs to a randomclash."""
    return str(battle_id).startswith("rc_")


def _rc_ensure_columns() -> None:
    """Add battle_type and rc_default_settings columns if not present."""
    conn = _nc_db()
    cur  = conn.cursor()
    for ddl in [
        "ALTER TABLE roclash_battles ADD COLUMN battle_type TEXT DEFAULT 'ro'",
        "ALTER TABLE user_settings ADD COLUMN rc_default_settings TEXT",
    ]:
        try:
            cur.execute(ddl)
            conn.commit()
        except Exception:
            pass
    conn.close()


