# Minimum / maximum move power for RandomClash movesets
_RC_MOVE_MIN_POWER = 80
_RC_MOVE_MAX_POWER = 150


async def _rc_generate_moveset(session: aiohttp.ClientSession, species_slug: str, types: list) -> list:
    """
    Generate a RandomClash moveset for a given species — always exactly 4 moves.

    STAB rules:
      • Single-type Pokémon  → 1 STAB move  + 3 additional moves
      • Dual-type Pokémon    → 2 STAB moves (1 per type) + 2 additional moves

    Power rules (primary pool):
      • Only level-up moves are considered.
      • Damaging moves only (no status).
      • 80 ≤ power ≤ 150.

    If the primary pool cannot supply 4 moves the function falls through:
      Phase 2 — relax power filter: any level-up damaging move, highest power first.
      Phase 3 — universal fallback moves (Hyper Beam, Earthquake, Surf, …).
      Phase 4 — Tackle as absolute last resort.

    Accuracy=None is patched via _RC_ALWAYS_HIT_ACCURACY or defaulted to 100.
    Returns a list of exactly 4 move-info dicts (or fewer only on hard API failure).
    """
    try:
        api_url = f"https://pokeapi.co/api/v2/pokemon/{species_slug.lower()}"
        pdata = await _cached_pokeapi_get(api_url)
        if not pdata:
            raise ValueError(f"PokeAPI fetch failed for {species_slug}")

        # ── Collect all level-up moves learnable by Lv100 ──────────────────────
        candidates = []
        seen = set()
        for m in pdata.get("moves", []):
            mname = m["move"]["name"]
            if mname in seen:
                continue
            for vgd in m["version_group_details"]:
                if vgd["move_learn_method"]["name"] == "level-up" and vgd["level_learned_at"] <= 100:
                    candidates.append((vgd["level_learned_at"], m["move"]["url"], mname))
                    seen.add(mname)
                    break

        # Sort by level desc so highest-level (generally strongest) moves come first
        candidates.sort(key=lambda x: x[0], reverse=True)

        # ── Fetch move details and split into primary (80-150) / all-damaging ──
        primary_moves: list = []   # power 80-150, damaging, level-up
        all_levelup:   list = []   # any power,   damaging, level-up

        for _, url, mname in candidates:
            mi = await fetch_move_info(session, url)
            if not mi:
                continue
            if mi.get("damage_class") == "status":
                continue
            # Patch always-hit moves
            if mi.get("accuracy") is None:
                mi["accuracy"] = _RC_ALWAYS_HIT_ACCURACY.get(mname, 100)
            power = mi.get("power") or 0
            if power <= 0:
                # Skip 0-power / null-power moves (Splash, fixed-damage moves
                # with null power in PokeAPI, etc.) — only real damaging moves.
                continue
            all_levelup.append(mi)
            if _RC_MOVE_MIN_POWER <= power <= _RC_MOVE_MAX_POWER:
                primary_moves.append(mi)

        # Sort both pools by power descending
        primary_moves.sort(key=lambda x: x.get("power", 0), reverse=True)
        all_levelup.sort(key=lambda x: x.get("power", 0), reverse=True)

        # ── Helper ─────────────────────────────────────────────────────────────
        def _add(mi: dict, chosen: list) -> bool:
            if len(chosen) < 4 and mi not in chosen:
                chosen.append(mi)
                return True
            return False

        # ── Phase 1: primary pool (power 80-150 level-up moves) ────────────────
        # STAB first: one STAB move per Pokémon type, then fill remaining slots.
        chosen: list = []

        for ptype in types:                   # add best STAB per type
            for mi in primary_moves:
                if mi["type"] == ptype:
                    if _add(mi, chosen):
                        break

        for mi in primary_moves:              # fill remaining slots
            if len(chosen) >= 4:
                break
            _add(mi, chosen)

        # ── Phase 2: relax power — any level-up damaging move ──────────────────
        if len(chosen) < 4:
            for ptype in types:               # try to get STAB from full pool
                if len(chosen) >= 4:
                    break
                for mi in all_levelup:
                    if mi["type"] == ptype:
                        if _add(mi, chosen):
                            break
            for mi in all_levelup:            # fill remaining
                if len(chosen) >= 4:
                    break
                _add(mi, chosen)

        # ── Phase 3: universal fallback moves (guarantee 4 total) ──────────────
        if len(chosen) < 4:
            _FALLBACK_URLS = [
                "https://pokeapi.co/api/v2/move/63/",   # Hyper Beam  — 150 Normal
                "https://pokeapi.co/api/v2/move/89/",   # Earthquake  — 100 Ground
                "https://pokeapi.co/api/v2/move/56/",   # Surf        — 90  Water
                "https://pokeapi.co/api/v2/move/394/",  # Aura Sphere — 80  Fighting
                "https://pokeapi.co/api/v2/move/87/",   # Thunderbolt — 90  Electric
                "https://pokeapi.co/api/v2/move/58/",   # Ice Beam    — 90  Ice
                "https://pokeapi.co/api/v2/move/53/",   # Flamethrower— 90  Fire
                "https://pokeapi.co/api/v2/move/95/",   # Psychic     — 90  Psychic
            ]
            chosen_names = {m.get("name") for m in chosen}
            for url in _FALLBACK_URLS:
                if len(chosen) >= 4:
                    break
                fb = await fetch_move_info(session, url)
                if fb and fb.get("name") not in chosen_names:
                    if fb.get("accuracy") is None:
                        fb["accuracy"] = 100
                    chosen.append(fb)
                    chosen_names.add(fb.get("name"))

        # ── Phase 4: Tackle — absolute last resort ──────────────────────────────
        if len(chosen) < 4:
            tk = await fetch_move_info(session, "https://pokeapi.co/api/v2/move/33/")
            if tk:
                chosen_names = {m.get("name") for m in chosen}
                # Tackle has no accuracy=None issue, but patch defensively
                if tk.get("accuracy") is None:
                    tk["accuracy"] = 100
                while len(chosen) < 4 and tk.get("name") not in chosen_names:
                    chosen.append(tk)
                    chosen_names.add(tk.get("name"))

        return chosen[:4]

    except Exception as exc:
        logger.warning(f"[RANDOMCLASH] moveset gen failed for {species_slug}: {exc}")
        return []


async def _rc_check_fully_evolved(session: aiohttp.ClientSession, lookup) -> bool:
    """
    Authoritative "is this Pokémon fully evolved?" check for RandomClash,
    reusing the same PokeAPI evolution-chain traversal as get_evolution_stage()
    (defined near the top of this file). This is the final safety net behind
    the static _RC_UNEVOLVED_IDS pre-filter and the curated _RC_FORM_SLUGS
    list — those are hand-maintained and can drift out of sync with reality
    (this is exactly how the Nidorina/Nidoqueen draft bug happened), whereas
    this check looks the answer up live, so it self-corrects for ANY gap,
    including ones nobody has spotted yet.

    Works for alternate-form slugs too (e.g. "raichu-alola") because PokeAPI
    resolves any variety/form to its underlying *species* (e.g. "raichu")
    before walking the evolution chain — so a regional form that branches
    into a brand-new species (e.g. Galarian Meowth -> Perrserker) is still
    correctly detected as "not fully evolved", even though the slug itself
    doesn't say so.

    Fails OPEN (returns True) on any network/API problem so a transient
    PokeAPI hiccup can never make RandomClash drafting stall — the static
    pre-filter has already done most of the work by the time we get here.
    """
    try:
        url = f"https://pokeapi.co/api/v2/pokemon/{str(lookup).lower()}"
        pdata = await _cached_pokeapi_get(url)
        if not pdata:
            return True

        species = pdata.get("species") or {}
        species_name = species.get("name")
        species_url  = species.get("url")
        if not species_name or not species_url:
            return True

        stage = await get_evolution_stage(session, species_url, species_name)
        return stage in ("final", "single", "legendary", "mythical")
    except Exception as exc:
        logger.warning(f"[RANDOMCLASH] fully-evolved check failed for {lookup}: {exc}")
        return True


async def _rc_draft_random_team(size: int, mode: str, regions: list) -> list:
    """
    Draft `size` random Lv100 Pokémon.

    mode:
      "0L"  — only normal (non-restricted) Pokémon
      "6L"  — only restricted (legendary / mythical / UB / paradox)
      "Mix" — free mix of all tiers
    regions: list of region names; full list = National Pokédex.

    Returns battle-ready team dicts compatible with _nc_load_team output.
    """
    use_all = set(regions) == set(_ALL_REGIONS)

    common_entries:     list = []
    restricted_entries: list = []

    for region in (list(_RC_REGION_POOLS.keys()) if use_all else regions):
        if region not in _RC_REGION_POOLS:
            continue
        common, legendary, mythical = _RC_REGION_POOLS[region]
        for pid in common:
            common_entries.append((pid, None))
        for pid in legendary + mythical:
            restricted_entries.append((pid, None))
        if region == "Alola":
            for pid in GENCODE_ULTRA_BEAST_IDS:
                restricted_entries.append((pid, None))
        if region == "Paldea":
            for pid in _RC_PARADOX_IDS:
                restricted_entries.append((pid, None))

    # Forms
    for (display, slug, freg) in _RC_FORM_SLUGS:
        if not use_all and freg not in regions:
            continue
        is_restricted = any(kw in slug for kw in _RC_RESTRICTED_FORM_KEYWORDS)
        if is_restricted:
            restricted_entries.append((None, slug))
        else:
            common_entries.append((None, slug))

    # Deduplicate
    common_entries     = list(set(common_entries))
    restricted_entries = list(set(restricted_entries))

    # RandomClash rule: only fully evolved Pokémon in common pool.
    # Restricted (legendary/mythical/UB/paradox) are always allowed.
    # Form-slug entries (dex_id=None) are presumed fully evolved.
    common_entries = [
        (pid, slug) for (pid, slug) in common_entries
        if slug is not None or pid not in _RC_UNEVOLVED_IDS
    ]

    if mode == "0L":
        pool = [(pid, slug, False) for (pid, slug) in common_entries] or [(1, None, False)]
    elif mode == "6L":
        pool = [(pid, slug, True) for (pid, slug) in restricted_entries] or [(150, None, True)]
    else:
        pool = (
            [(pid, slug, False) for (pid, slug) in common_entries] +
            [(pid, slug, True) for (pid, slug) in restricted_entries]
        ) or [(1, None, False)]

    team = []
    # ── Retry loop: keep picking until we have exactly `size` Pokémon ──────────
    # Each individual slot is guarded by its own asyncio timeout so a slow or
    # hanging PokeAPI call can never stall the whole draft indefinitely.
    max_attempts      = size * 10        # generous ceiling; normally succeeds quickly
    attempts          = 0
    _PER_PICK_TIMEOUT = 20               # seconds per single Pokémon slot attempt

    # Reuse the module-level shared session (respects _TunedClientSession patch
    # and benefits from connection pooling) instead of opening a new one.
    _rc_session = _get_http_session()

    # ── Fallback move stubs (used when fetch_move_info returns None) ───────────
    _FALLBACK_MOVE_STUBS = [
        {"name": "hyper-beam",   "power": 150, "accuracy": 90,  "type": "normal",   "damage_class": "special"},
        {"name": "earthquake",   "power": 100, "accuracy": 100, "type": "ground",   "damage_class": "physical"},
        {"name": "surf",         "power": 90,  "accuracy": 100, "type": "water",    "damage_class": "special"},
        {"name": "thunderbolt",  "power": 90,  "accuracy": 100, "type": "electric", "damage_class": "special"},
        {"name": "ice-beam",     "power": 90,  "accuracy": 100, "type": "ice",      "damage_class": "special"},
        {"name": "flamethrower", "power": 90,  "accuracy": 100, "type": "fire",     "damage_class": "special"},
        {"name": "psychic",      "power": 90,  "accuracy": 100, "type": "psychic",  "damage_class": "special"},
        {"name": "shadow-ball",  "power": 80,  "accuracy": 100, "type": "ghost",    "damage_class": "special"},
    ]

    async def _draft_one_pokemon(dex_id, slug, is_restricted) -> "dict | None":
        """Draft a single Pokémon slot. Returns the team-entry dict or None."""
        lookup = slug if slug else dex_id
        try:
            info = await get_pokemon_battle_info(lookup, 100)
            if not info:
                return None

            # ── TEAM VALIDATION (1/4): fully evolved ───────────────────────
            # Legendaries/Mythicals/UBs/Paradoxes are exempt by design.
            # Everything else gets the live, authoritative PokeAPI check —
            # if it fails, this pick is discarded and a fresh one is
            # drafted on the next loop iteration ("regenerate that Pokémon").
            if not is_restricted:
                if not await _rc_check_fully_evolved(_rc_session, lookup):
                    return None

            if slug:
                display_name = slug.replace("-", " ").title()
            else:
                display_name = info.get("name", str(dex_id)).replace("-", " ").title()

            # Generate high-quality RC moveset (STAB + power 80-150)
            species_slug = str(lookup).lower() if slug else str(dex_id)
            rc_moves = await _rc_generate_moveset(_rc_session, species_slug, info["types"])
            if not rc_moves:
                rc_moves = list(info.get("moves") or [])  # fallback to battle-info moves

            # Ensure accuracy is never None / "—" in the RC team
            for mv in rc_moves:
                if mv.get("accuracy") is None:
                    mv["accuracy"] = _RC_ALWAYS_HIT_ACCURACY.get(mv.get("name", ""), 100)

            # ── TEAM VALIDATION (2/4): must have exactly 4 moves ───────────
            # Pad with fallback stubs if needed.  Uses a bounded counter to
            # guarantee termination even when fetch_move_info returns None.
            if len(rc_moves) < 4:
                existing_names = {m.get("name") for m in rc_moves}
                for stub in _FALLBACK_MOVE_STUBS:
                    if len(rc_moves) >= 4:
                        break
                    if stub["name"] not in existing_names:
                        # Try to fetch the real move data; use stub on failure
                        _stub_urls = {
                            "hyper-beam":   "https://pokeapi.co/api/v2/move/63/",
                            "earthquake":   "https://pokeapi.co/api/v2/move/89/",
                            "surf":         "https://pokeapi.co/api/v2/move/57/",
                            "thunderbolt":  "https://pokeapi.co/api/v2/move/85/",
                            "ice-beam":     "https://pokeapi.co/api/v2/move/58/",
                            "flamethrower": "https://pokeapi.co/api/v2/move/53/",
                            "psychic":      "https://pokeapi.co/api/v2/move/94/",
                            "shadow-ball":  "https://pokeapi.co/api/v2/move/247/",
                        }
                        url = _stub_urls.get(stub["name"])
                        fetched = None
                        if url:
                            try:
                                fetched = await fetch_move_info(_rc_session, url)
                            except Exception:
                                fetched = None
                        mv_entry = fetched if fetched else dict(stub)
                        if mv_entry.get("accuracy") is None:
                            mv_entry["accuracy"] = stub["accuracy"]
                        rc_moves.append(mv_entry)
                        existing_names.add(stub["name"])

            # ── TEAM VALIDATION (3/4): random nature ───────────────────────
            rc_nature = random.choice(list(NATURES.keys()))

            # ── TEAM VALIDATION (4/4): valid for region + mode ─────────────
            # Structurally guaranteed — `pool` was built only from the
            # caller's selected `regions` and only from the tier(s) the
            # selected `mode` permits, so any entry reaching this point is
            # already region/mode-correct by construction.

            return {
                "db_id":       None,
                "name":        display_name,
                "level":       100,
                "hp":          info["max_hp"],
                "max_hp":      info["max_hp"],
                "attack":      info["attack"],
                "defense":     info["defense"],
                "sp_atk":      info["sp_atk"],
                "sp_def":      info["sp_def"],
                "speed":       info["speed"],
                "types":       info["types"],
                "moves":       rc_moves,
                "nature":      rc_nature,
                "shiny":       False,
                "status":      None,
                "dex_id":      info.get("id", dex_id or 1),
                "artwork_url": info.get("sprite"),
            }
        except Exception as exc:
            logger.warning(f"[RANDOMCLASH] Draft failed for {lookup}: {exc}")
            return None

    async def _pick_one():
        (dex_id, slug, is_restricted) = random.choice(pool)
        try:
            return await asyncio.wait_for(
                _draft_one_pokemon(dex_id, slug, is_restricted),
                timeout=_PER_PICK_TIMEOUT,
            )
        except asyncio.TimeoutError:
            logger.warning(
                f"[RANDOMCLASH] per-pick timeout ({_PER_PICK_TIMEOUT}s) for "
                f"dex_id={dex_id} slug={slug} — skipping pick"
            )
            return None
        except Exception as exc:
            logger.warning(
                f"[RANDOMCLASH] per-pick error for dex_id={dex_id} slug={slug}: {exc}"
            )
            return None

    # ── Draft picks in concurrent batches instead of one at a time ─────────────
    # The old version awaited each of the `size` (usually 6) picks sequentially,
    # so a full team took roughly 6x a single pick's latency even though picks
    # are completely independent of each other. Firing a batch of picks
    # concurrently (still bounded by the module-level PokeAPI semaphore, so
    # this doesn't flood the API any harder) cuts total draft time roughly to
    # that of a single pick, plus a little for any re-drafts of failed slots.
    while len(team) < size and attempts < max_attempts:
        needed         = size - len(team)
        batch_size     = min(needed, max_attempts - attempts)
        attempts      += batch_size
        results        = await asyncio.gather(*[_pick_one() for _ in range(batch_size)])
        team.extend(entry for entry in results if entry is not None)

    return team


def _rc_create(battle_id, p1_id, p1_name, p2_id, p2_name, chat_id, msg_id) -> None:
    """Create a pending randomclash battle row using challenger's saved RC settings."""
    _rc_ensure_columns()

    conn_s = sqlite3.connect("ZNX.db")
    cur_s  = conn_s.cursor()
    try:
        cur_s.execute("SELECT rc_default_settings FROM user_settings WHERE user_id = ?", (p1_id,))
        row_s = cur_s.fetchone()
    except Exception:
        row_s = None
    conn_s.close()

    saved = {}
    if row_s and row_s[0]:
        try:
            saved = json.loads(row_s[0])
        except Exception:
            saved = {}

    settings = {
        "mode":           saved.get("mode",           "0L"),
        "size":           saved.get("size",           6),
        "switch":         saved.get("switch",         True),
        "status_effects": saved.get("status_effects", False),
        "weather":        saved.get("weather",        True),
        "mega":           saved.get("mega",           True),
        "dynamax":        saved.get("dynamax",         False),
        "visuals":        saved.get("visuals",        True),
        "regions":        saved.get("regions",        _ALL_REGIONS[:]),
    }
    conn = _nc_db()
    cur  = conn.cursor()
    try:
        cur.execute(
            """INSERT OR IGNORE INTO roclash_battles
               (battle_id, p1_id, p2_id, p1_name, p2_name, chat_id, message_id,
                status, settings, battle_state, created_at, battle_type)
               VALUES (?,?,?,?,?,?,?,?,?,?,?,?)""",
            (battle_id, p1_id, p2_id, p1_name, p2_name, chat_id, msg_id,
             "pending", json.dumps(settings), "{}", int(time.time()), "random")
        )
    except Exception:
        cur.execute(
            """INSERT OR IGNORE INTO roclash_battles
               (battle_id, p1_id, p2_id, p1_name, p2_name, chat_id, message_id,
                status, settings, battle_state, created_at)
               VALUES (?,?,?,?,?,?,?,?,?,?,?)""",
            (battle_id, p1_id, p2_id, p1_name, p2_name, chat_id, msg_id,
             "pending", json.dumps(settings), "{}", int(time.time()))
        )
    conn.commit()
    conn.close()


def _rc_save_user_settings(user_id: int, settings: dict) -> None:
    """Persist RC settings as the user's defaults."""
    _rc_ensure_columns()
    try:
        conn = sqlite3.connect("ZNX.db")
        cur  = conn.cursor()
        cur.execute("INSERT OR IGNORE INTO user_settings (user_id) VALUES (?)", (user_id,))
        cur.execute(
            "UPDATE user_settings SET rc_default_settings = ? WHERE user_id = ?",
            (json.dumps(settings), user_id)
        )
        conn.commit()
        conn.close()
    except Exception as exc:
        logger.error(f"[RANDOMCLASH] save settings failed: {exc}")


