_RC_MODE_DISPLAY = {"0L": "0l", "6L": "6l", "Mix": "Mix"}


def _rc_challenge_text(data: dict) -> str:
    s   = data["settings"]
    p1  = data["p1_name"]
    p2  = data["p2_name"]
    bs  = data["battle_state"]
    p1r = "✅ ready" if bs.get("p1_ready") else "❌ not ready"
    p2r = "✅ ready" if bs.get("p2_ready") else "❌ not ready"
    sw  = "ON" if s.get("switch", True) else "OFF"
    se  = "ON" if s.get("status_effects", False) else "OFF"
    sz  = f"{s.get('size', 6)}v{s.get('size', 6)}"
    md  = _RC_MODE_DISPLAY.get(s.get("mode", "0L"), s.get("mode", "0L"))
    return (
        f"⚔️ <b>{p1}</b> <b>has challenged</b> <b>{p2}</b> <b>to a Random Clash!</b>\n\n"
        f"<b>{p1}</b> <b>is {p1r}</b>\n"
        f"<b>{p2}</b> <b>is {p2r}</b>\n\n"
        f"<b>Current Settings:</b>\n"
        f"<b>Mode:</b> <code>{md}</code>  <b>|  Size:</b> <code>{sz}</code>\n"
        f"<b>Switch:</b> <code>{sw}</code>  <b>|  Status:</b> <code>{se}</code>"
    )


def _rc_challenge_kbd(battle_id: str) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("Accept",  callback_data=f"rc_accept:{battle_id}"),
         InlineKeyboardButton("Decline", callback_data=f"rc_decline:{battle_id}")],
        [InlineKeyboardButton("Settings",   callback_data=f"rc_settings:{battle_id}")]
    ])


def _rc_settings_text(data: dict) -> str:
    s  = data["settings"]
    sw = "ON" if s.get("switch", True)         else "OFF"
    se = "ON" if s.get("status_effects", False) else "OFF"
    wt = "ON" if s.get("weather", True)        else "OFF"
    mg = "ON" if s.get("mega", True)           else "OFF"
    dm = "ON" if s.get("dynamax", False)       else "OFF"
    vs = "ON" if s.get("visuals", True)        else "OFF"
    sz = s.get("size", 6)
    md = _RC_MODE_DISPLAY.get(s.get("mode", "0L"), s.get("mode", "0L"))
    regions = s.get("regions", _ALL_REGIONS)
    reg_display = "National Pokédex" if set(regions) == set(_ALL_REGIONS) else ", ".join(regions)
    return (
        "<b><u>Battle Settings</u></b>\n\n"
        f"<b>Mode:</b> {md}\n"
        f"<b>Team Size:</b> {sz}v{sz}\n"
        f"<b>Switch:</b> {sw}\n"
        f"<b>Status Effects:</b> {se}\n"
        f"<b>Weather:</b> {wt}\n"
        f"<b>Mega:</b> {mg}\n"
        f"<b>Dynamax:</b> {dm}\n"
        f"<b>Visuals:</b> {vs}\n"
        f"<b>Regions:</b> {reg_display}\n\n"
        "<b>Configure the battle rules before starting.</b>"
    )


