async def rc_reg_toggle_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Toggle a single region on/off in the region selector."""
    query     = update.callback_query
    user      = query.from_user
    parts     = query.data.split(":")
    battle_id = parts[1]
    region    = parts[2]
    data      = _nc_load(battle_id)

    if not data or user.id != data["p1_id"]:
        await query.answer("Not allowed.", show_alert=True); return

    selected = set(data["settings"].get("regions", _ALL_REGIONS))
    if region in selected:
        selected.discard(region)
        if not selected:
            selected.add(region)
            await query.answer("At least one region must be selected.", show_alert=True)
            return
    else:
        selected.add(region)

    data["settings"]["regions"] = sorted(
        selected, key=lambda r: _ALL_REGIONS.index(r) if r in _ALL_REGIONS else 99
    )
    _nc_save(battle_id, data)
    await query.answer(f"{region} toggled.")
    await query.edit_message_text(
        _rc_regions_text(data), parse_mode="HTML",
        reply_markup=_rc_regions_kbd(battle_id, data["settings"])
    )


