async def rc_reset_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Reset settings to user's saved RC defaults (or hard defaults)."""
    query     = update.callback_query
    user      = query.from_user
    battle_id = query.data.split(":")[1]
    data      = _nc_load(battle_id)

    if not data or user.id != data["p1_id"]:
        await query.answer("Not allowed.", show_alert=True); return
    if data["status"] != "pending":
        await query.answer("Settings can only be changed before the battle starts.", show_alert=True); return

    saved = {}
    try:
        conn = sqlite3.connect("ZNX.db")
        cur  = conn.cursor()
        cur.execute("SELECT rc_default_settings FROM user_settings WHERE user_id = ?", (user.id,))
        row = cur.fetchone()
        conn.close()
        if row and row[0]:
            saved = json.loads(row[0])
    except Exception:
        pass

    data["settings"] = {
        "mode":           saved.get("mode",           "0L"),
        "size":           saved.get("size",           6),
        "switch":         saved.get("switch",         True),
        "status_effects": saved.get("status_effects", False),
        "weather":        saved.get("weather",        True),
        "mega":           saved.get("mega",           True),
        "dynamax":        saved.get("dynamax",         False),
        "visuals":        saved.get("visuals",        True),
        "regions":        saved.get("regions",        _ALL_REGIONS[:]),
    }
    _nc_save(battle_id, data)
    await query.answer("Settings Reset")
    await query.edit_message_text(
        _rc_settings_text(data), parse_mode="HTML",
        reply_markup=_rc_settings_kbd(battle_id, data["settings"])
    )


# ── End-battle handler (RC variant: 150 NR, "Random Clash" branding) ──────────

async def _rc_end_battle(query, context, battle_id: str,
                          winner_id: int, forfeit: bool = False,
                          forfeiter_id: int | None = None) -> None:
    """Randomclash end-battle: 150 NR win reward, RC-branded result text."""
    data = _nc_load(battle_id)
    if not data:
        return

    loser_id  = data["p2_id"] if winner_id == data["p1_id"] else data["p1_id"]
    winner_nm = data["p1_name"] if winner_id == data["p1_id"] else data["p2_name"]
    loser_nm  = data["p2_name"] if winner_id == data["p1_id"] else data["p1_name"]
    bs        = data.get("battle_state", {})

    _nc_cancel_timeout(battle_id)

    # ── Forfeit: end immediately — no Pokémon EXP, Trainer EXP, RoRupees,
    #    rank progress, or any other reward is awarded ─────────────────────────
    if forfeit and forfeiter_id:
        data["status"] = "finished"
        _nc_save(battle_id, data)
        _clear_battle_lock(data["p1_id"])
        _clear_battle_lock(data["p2_id"])

        # Clear /rpreview sessions for both trainers
        _rc_preview_clear(battle_id)

        result_text = "🏳️ <b>Battle Forfeited!</b>\n\nNo rewards or experience were awarded."
        await _nc_update_battle_visual(context.bot, data, result_text)
        _nc_save(battle_id, data)
        _nc_delete(battle_id)
        return

    # /mystats tracking — genuine win only (forfeits already returned above)
    _mystats_log_battle_win(winner_id, "randomclash")

    # Cosmic Weather bonus (same as roclash)
    cosmic_bonus_text = ""
    if bs.get("weather_used") and bs.get("weather") == "cosmic" or bs.get("cosmic_weather_winner"):
        actual_rc_cosmic_nr = _nc_award_rupees(winner_id, 100)
        _rc_cosmic_profile = get_user(winner_id)
        _old = (_rc_cosmic_profile.get("trainer_exp") or 0) if _rc_cosmic_profile else 0
        increment_user(winner_id, trainer_exp=50)
        asyncio.create_task(check_and_notify_rank_up(context, winner_id, data.get("chat_id", winner_id), _old, _old + 50))
        rc_cosmic_nr_text = f"+{actual_rc_cosmic_nr} RoRupees\n" if actual_rc_cosmic_nr > 0 else ""
        cosmic_bonus_text = f"\n\n🌌 <b>Cosmic Energy Reward!</b>\n{rc_cosmic_nr_text}+50 Trainer EXP"

    actual_rc_win_nr = _nc_award_rupees(winner_id, RC_WIN_REWARD)
    nc_texp = random.randint(100, 300)
    _rc_win_profile = get_user(winner_id)
    _old = (_rc_win_profile.get("trainer_exp") or 0) if _rc_win_profile else 0
    increment_user(winner_id, trainer_exp=nc_texp)
    asyncio.create_task(check_and_notify_rank_up(context, winner_id, data.get("chat_id", winner_id), _old, _old + nc_texp))
    log = bs.get("log", "")
    if actual_rc_win_nr > 0:
        rc_nr_line = f"💶 {actual_rc_win_nr} RoRupees\n"
        rc_nr_limit_line = ""
    else:
        rc_nr_line = ""
        rc_nr_limit_line = "<i>You've reached the daily limit.</i>\n"
    result_text = (
        (f"{log}\n\n" if log else "") +
        f"🏆 <b>{winner_nm} won the Random Clash!</b>\n\n"
        f"<b>Rewards:</b>\n"
        f"{rc_nr_line}"
        f"{rc_nr_limit_line}"
        f"💫 {nc_texp} Trainer Exp"
        f"{cosmic_bonus_text}"
    )

    data["status"] = "finished"
    _nc_save(battle_id, data)
    _clear_battle_lock(data["p1_id"])
    _clear_battle_lock(data["p2_id"])

    # Clear /rpreview sessions for both trainers
    _rc_preview_clear(battle_id)

    await _nc_update_battle_visual(context.bot, data, result_text)
    _nc_save(battle_id, data)
    _nc_delete(battle_id)

    # ── One-time daily NR limit notification ──────────────────────────────────
    _rc_chat = data.get("chat_id") or winner_id
    if _should_notify_daily_nr_limit(winner_id):
        _mark_nr_limit_notified(winner_id)
        try:
            await context.bot.send_message(
                chat_id=_rc_chat,
                text=DAILY_NR_LIMIT_NOTICE,
                parse_mode="HTML"
            )
        except Exception:
            pass


# ════════════════════════════════════ /RPREVIEW SYSTEM ════════════════════════════════════
#
# /rpreview — show a trainer's current RandomClash team.
# Works while a RandomClash battle is active. Deletes session on battle end.
# In group chats: notifies user and sends full preview to DM.
# Privacy: a trainer can only view their own team, never the opponent's.
#

# In-memory map: user_id → battle_id  (populated when RC battle starts)
# Used by /rpreview to locate the active battle for the requesting trainer.
# Entries are removed in _rc_end_battle and on battle cancellation.
_RC_PREVIEW_SESSIONS: dict[int, str] = {}


def _rc_preview_register(battle_id: str, p1_id: int, p2_id: int) -> None:
    """Register both players in the preview session map."""
    _RC_PREVIEW_SESSIONS[p1_id] = battle_id
    _RC_PREVIEW_SESSIONS[p2_id] = battle_id


def _rc_preview_clear(battle_id: str) -> None:
    """Remove both players from the preview session map."""
    to_remove = [uid for uid, bid in _RC_PREVIEW_SESSIONS.items() if bid == battle_id]
    for uid in to_remove:
        _RC_PREVIEW_SESSIONS.pop(uid, None)


def _rpreview_team_text(team: list, active_idx: int, fainted_ids: list) -> str:
    """Build the DM overview message for a trainer's RC team."""
    lines = [
        "<b><u>Your RandomClash Team</u></b>\n",
        "<b>Which Pokémon's info would you like to see:</b>\n",
    ]
    for i, pkmn in enumerate(team, 1):
        name    = pkmn.get("name", "???")
        nature  = pkmn.get("nature", "Hardy")
        db_id   = pkmn.get("db_id")

        # Determine status tag
        is_active  = (i - 1 == active_idx)
        is_fainted = (db_id in fainted_ids) if db_id is not None else (pkmn.get("hp", 1) <= 0)

        if is_active:
            status_tag = " <b>[ Active ]</b>"
        elif is_fainted:
            status_tag = " <b>[Fainted]</b>"
        else:
            status_tag = ""

        lines.append(f"{i}. <b>{name}</b> — {nature}{status_tag}")
    return "\n".join(lines)


def _rpreview_pkmn_text(pkmn: dict) -> str:
    """Build the per-Pokémon detail page."""
    TYPE_EMOJI = {
        "fire": "🔥", "water": "💧", "grass": "🌿", "electric": "⚡",
        "psychic": "🔮", "ice": "❄️", "dragon": "🐉", "dark": "🌑",
        "fighting": "🥊", "poison": "☠️", "ground": "🌍", "flying": "🌪️",
        "bug": "🐛", "rock": "🪨", "ghost": "👻", "steel": "⚙️",
        "fairy": "✨", "normal": "🔘",
    }
    name   = pkmn.get("name", "???")
    nature = pkmn.get("nature", "Hardy")
    types  = pkmn.get("types", [])
    type_str = " / ".join(
        f"{t.capitalize()} ({TYPE_EMOJI.get(t, '❔')})" for t in types
    )

    lines = [
        f"✦ <b>{name}</b>\n",
        f"<b>Nature:</b> {nature}    <b>Type:</b> {type_str}\n",
    ]

    for mv in pkmn.get("moves", []):
        mv_name = mv.get("name", "???").replace("-", " ").title()
        mv_type = mv.get("type", "normal")
        mv_emoji = TYPE_EMOJI.get(mv_type, "❔")
        mv_power = mv.get("power") or "—"
        mv_acc   = mv.get("accuracy")
        if mv_acc is None:
            mv_acc = _RC_ALWAYS_HIT_ACCURACY.get(mv.get("name", ""), 100)
        mv_acc_display = _display_accuracy(mv_acc)
        mv_cat   = mv.get("damage_class", "physical").capitalize()

        lines += [
            f"<b>╭─「 {mv_name} 」</b>",
            f"<b>├─ Type:</b> {mv_type.capitalize()} ({mv_emoji})",
            f"<b>├─ Power:</b> {mv_power} | <b>Accuracy:</b> {mv_acc_display}",
            f"<b>└─ Category:</b> {mv_cat}\n",
        ]

    return "\n".join(lines)


async def rpreview_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """/rpreview — show the trainer's current RandomClash team."""
    user = update.effective_user
    msg  = update.message
    chat = update.effective_chat

    battle_id = _RC_PREVIEW_SESSIONS.get(user.id)
    if not battle_id:
        await msg.reply_text("<b>You are not in a random battle.</b>", parse_mode="HTML")
        return

    data = _nc_load(battle_id)
    if not data or data.get("status") not in ("battle", "selecting"):
        _RC_PREVIEW_SESSIONS.pop(user.id, None)
        await msg.reply_text("<b>You are not in a random battle.</b>", parse_mode="HTML")
        return

    is_p1      = (user.id == data["p1_id"])
    bs         = data.get("battle_state", {})
    team       = bs.get("team1" if is_p1 else "team2", [])
    active_idx = bs.get("active1" if is_p1 else "active2", 0)
    fainted    = bs.get("fainted1" if is_p1 else "fainted2", [])

    overview_text = _rpreview_team_text(team, active_idx, fainted)

    # Build 3-per-row number buttons
    size = len(team)
    num_rows = []
    row = []
    for i in range(1, size + 1):
        row.append(InlineKeyboardButton(str(i), callback_data=f"rp_pkmn:{battle_id}:{i-1}:{user.id}"))
        if len(row) == 3:
            num_rows.append(row)
            row = []
    if row:
        num_rows.append(row)
    kbd = InlineKeyboardMarkup(num_rows)

    # Group chat: redirect to DM
    if chat.type in ("group", "supergroup"):
        try:
            await context.bot.send_message(
                chat_id=user.id,
                text=overview_text,
                parse_mode="HTML",
                reply_markup=kbd
            )
        except Exception:
            # DM blocked — fallback
            await msg.reply_text(
                "<b>I've Sent Your Team Information To Your Dm!</b>\n\n"
                "<i>(Please start a DM with me first to receive it.)</i>",
                parse_mode="HTML"
            )
            return
        # In-group notification
        dm_url = f"https://t.me/{(await context.bot.get_me()).username}"
        notif_kbd = InlineKeyboardMarkup([[
            InlineKeyboardButton("Check Dm", url=dm_url)
        ]])
        await msg.reply_text(
            "<b>I've Sent Your Team Information To Your Dm!</b>",
            parse_mode="HTML",
            reply_markup=notif_kbd
        )
    else:
        await msg.reply_text(overview_text, parse_mode="HTML", reply_markup=kbd)


async def rp_pkmn_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Callback for /rpreview Pokémon number buttons."""
    query = update.callback_query
    user  = query.from_user

    parts = query.data.split(":")
    # rp_pkmn:{battle_id}:{pkmn_idx}:{owner_id}
    if len(parts) < 4:
        await query.answer("Invalid.", show_alert=True)
        return

    battle_id  = parts[1]
    pkmn_idx   = int(parts[2])
    owner_id   = int(parts[3])

    # Privacy guard — only the team owner can view
    if user.id != owner_id:
        await query.answer("This preview belongs to another trainer.", show_alert=True)
        return

    data = _nc_load(battle_id)
    if not data:
        await query.answer("Battle has ended.", show_alert=True)
        return

    is_p1 = (owner_id == data["p1_id"])
    bs    = data.get("battle_state", {})
    team  = bs.get("team1" if is_p1 else "team2", [])

    if pkmn_idx < 0 or pkmn_idx >= len(team):
        await query.answer("Invalid Pokémon.", show_alert=True)
        return

    pkmn      = team[pkmn_idx]
    detail_tx = _rpreview_pkmn_text(pkmn)
    back_kbd  = InlineKeyboardMarkup([[
        InlineKeyboardButton("Back", callback_data=f"rp_back:{battle_id}:{owner_id}")
    ]])

    await query.answer()
    await query.edit_message_text(detail_tx, parse_mode="HTML", reply_markup=back_kbd)


async def rp_back_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Back button on /rpreview detail page — return to team overview."""
    query = update.callback_query
    user  = query.from_user

    parts     = query.data.split(":")
    battle_id = parts[1]
    owner_id  = int(parts[2])

    if user.id != owner_id:
        await query.answer("Not your preview.", show_alert=True)
        return

    data = _nc_load(battle_id)
    if not data:
        await query.answer("Battle has ended.", show_alert=True)
        return

    is_p1      = (owner_id == data["p1_id"])
    bs         = data.get("battle_state", {})
    team       = bs.get("team1" if is_p1 else "team2", [])
    active_idx = bs.get("active1" if is_p1 else "active2", 0)
    fainted    = bs.get("fainted1" if is_p1 else "fainted2", [])

    overview_text = _rpreview_team_text(team, active_idx, fainted)
    size = len(team)
    num_rows = []
    row = []
    for i in range(1, size + 1):
        row.append(InlineKeyboardButton(str(i), callback_data=f"rp_pkmn:{battle_id}:{i-1}:{owner_id}"))
        if len(row) == 3:
            num_rows.append(row)
            row = []
    if row:
        num_rows.append(row)
    kbd = InlineKeyboardMarkup(num_rows)

    await query.answer()
    await query.edit_message_text(overview_text, parse_mode="HTML", reply_markup=kbd)


