# Menu banner — reused for both the initial send and the Back action so the
# message type is always a photo and edit_message_media works in both directions.
_PB_MENU_IMAGE   = "https://files.catbox.moe/q79ewb.jpg"
_PB_MENU_CAPTION = "Tap a ball button to see its image, catch bonus and conditions\\."

async def pokeballs_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Send the Pokéballs info main menu as a photo.
    Keeping it a photo ensures edit_message_media works on every Back press."""
    sent = await update.message.reply_photo(
        photo=_PB_MENU_IMAGE,
        caption=_PB_MENU_CAPTION,
        parse_mode="MarkdownV2",
        reply_markup=_pokeballs_main_keyboard(),
    )
    chat_id = update.effective_chat.id
    context.chat_data[f"pb_owner_{chat_id}_{sent.message_id}"] = update.effective_user.id

async def pokeballs_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handle Pokéballs menu button presses."""
    query = update.callback_query

    # Answer immediately — clears the spinner with zero delay.
    await query.answer()

    # ── Ownership guard ────────────────────────────────────────────────────────
    msg_id  = query.message.message_id
    chat_id = query.message.chat_id
    stored_owner = context.chat_data.get(f"pb_owner_{chat_id}_{msg_id}")

    if stored_owner and query.from_user.id != stored_owner:
        await query.answer("This menu belongs to another trainer.", show_alert=True)
        return

    data = query.data  # e.g. "pb_regular" or "pb_back"

    if data == "pb_back":
        # Message is always a photo — edit_message_media works every time.
        # Includes reply_markup in the same call so buttons never disappear.
        await query.edit_message_media(
            media=InputMediaPhoto(
                media=_PB_MENU_IMAGE,
                caption=_PB_MENU_CAPTION,
                parse_mode="MarkdownV2",
            ),
            reply_markup=_pokeballs_main_keyboard(),
        )
        return

    # Static dict lookup — no dynamic building per click.
    ball_key = data[3:]  # strip "pb_" prefix
    ball = POKEBALL_DATA.get(ball_key)
    if not ball:
        return

    # Single edit_message_media call with reply_markup — one round-trip,
    # buttons always present.
    await query.edit_message_media(
        media=InputMediaPhoto(
            media=ball["image"],
            caption=ball["caption"],
            parse_mode="MarkdownV2",
        ),
        reply_markup=_pokeballs_back_keyboard(),
    )



