# ── Key Item commands (separate from mega stones — stored in users table) ─────
KEY_ITEM_COMMANDS = {"keystone", "dynamax_band"}

async def keystone_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """/keystone — Show Keystone ownership and info."""
    user = update.effective_user
    msg  = update.message
    if not msg:
        return
    if not is_registered(user.id):
        await msg.reply_text("⚠️ Please send your trainer name first before using the bot.")
        return

    profile = get_user(user.id)
    owned = profile.get("has_keystone") if profile else False
    if owned:
        caption = (
            "Keystone\n\n"
            "Amount owned: <b>1</b>\n\n"
            "This <i>Key Item</i> allows Pokémon holding compatible Mega Stones to Mega Evolve during battle."
        )
        file_id = _get_stone_image_file_id("Keystone")
        if file_id:
            try:
                await msg.reply_photo(photo=file_id, caption=caption, parse_mode="HTML")
                return
            except Exception:
                pass
        await msg.reply_text(caption, parse_mode="HTML")
    else:
        await msg.reply_text("<b>You don't own this item.</b>", parse_mode="HTML")


