# Build a reverse map: command_text (with _x/_y normalised) -> entry
# This handles Telegram stripping underscores in command args.
def _normalise_stone_cmd(raw_cmd: str, args: list[str]) -> str:
    """
    Reconstruct the full stone command key from what Telegram delivers.

    Telegram sends /charizardite_x as:
        command = "charizardite"   (everything before the first _)
        message text = "/charizardite_x"   (full original text)

    We first try the full raw text, then fall back to cmd + first arg.
    """
    # Try the full text first (most reliable)
    raw_cmd = raw_cmd.lower()
    if args:
        suffix = args[0].lower()
        if suffix in ("x", "y", "z"):
            candidate = f"{raw_cmd}_{suffix}"
            if candidate in MEGA_STONE_COMMANDS:
                return candidate
    return raw_cmd


async def _mega_stone_cmd_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Universal handler for all /stonecommand hidden commands.

    Supports plain stones (/venusaurite) and X/Y variants
    (/charizardite_x, /charizardite_y, /mewtwonite_x, /mewtwonite_y).
    """
    user = update.effective_user
    msg  = update.message
    if not msg:
        return

    if not is_registered(user.id):
        await msg.reply_text("⚠️ Please send your trainer name first before using the bot.")
        return

    # ── Resolve the stone key ──────────────────────────────────────────────────
    raw_text = (msg.text or "").strip()
    full_cmd = raw_text.lstrip("/").split("@")[0].lower()   # e.g. "charizardite_x"

    # Strategy 2: if Telegram split it (command="charizardite", args=["x"])
    if full_cmd not in MEGA_STONE_COMMANDS and context.args:
        suffix = context.args[0].lower()
        if suffix in ("x", "y", "z"):
            full_cmd = f"{full_cmd}_{suffix}"

    entry = MEGA_STONE_COMMANDS.get(full_cmd)
    if not entry:
        # Last resort: DB lookup for any stone in inventory
        conn = sqlite3.connect("ZNX.db")
        cur = conn.cursor()
        cur.execute(
            "SELECT stone_name, quantity FROM user_stones "
            "WHERE user_id = ? AND LOWER(REPLACE(stone_name, ' ', '_')) = ?",
            (user.id, full_cmd)
        )
        db_row = cur.fetchone()
        conn.close()
        if db_row and db_row[1] > 0:
            stone_name = db_row[0]
            caption = (
                f"<b><u>{stone_name}</u></b>\n\n"
                f"Amount owned: <b>{db_row[1]}</b>\n\n"
                f"This <i>Key Item</i> allows your Pokémon to Mega Evolve during battle."
            )
            image_url = _get_stone_image(stone_name)
            if image_url:
                try:
                    await msg.reply_photo(photo=image_url, caption=caption, parse_mode="HTML")
                    return
                except Exception:
                    pass
            await msg.reply_text(caption, parse_mode="HTML")
        return

    stone_name, poke_name, mega_name = entry

    # ── Inventory lookup ───────────────────────────────────────────────────────
    conn = sqlite3.connect("ZNX.db")
    cur = conn.cursor()
    cur.execute(
        "SELECT quantity FROM user_stones WHERE user_id = ? AND stone_name = ?",
        (user.id, stone_name)
    )
    row = cur.fetchone()
    conn.close()

    amount = row[0] if row else 0
    if amount > 0:
        caption = (
            f"<b><u>{stone_name}</u></b>\n\n"
            f"Amount owned: <b>{amount}</b>\n\n"
            f"This <i>Key Item</i> can be used by <b>{poke_name}</b> to transform into "
            f"<b>{mega_name}</b> during a battle."
        )
    else:
        caption = "<b>You don't own this stone.</b>"

    # ── Try to send with image URL ─────────────────────────────────────────────
    image_url = _get_stone_image(stone_name)
    if image_url:
        try:
            await msg.reply_photo(photo=image_url, caption=caption, parse_mode="HTML")
            return
        except Exception:
            pass  # Fall through to text-only if image send fails

    await msg.reply_text(caption, parse_mode="HTML")


async def _special_item_cmd_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Hidden command handler for special transformation items:
    /jade_orb, /blue_orb, /red_orb, /adamant_crystal, /lustrous_globe,
    /griseous_core, /rusted_sword, /rusted_shield
    """
    user = update.effective_user
    msg  = update.message
    if not msg:
        return

    if not is_registered(user.id):
        await msg.reply_text("⚠️ Please send your trainer name first before using the bot.")
        return

    # Resolve command key from message text
    raw_text = (msg.text or "").strip()
    full_cmd = raw_text.lstrip("/").split("@")[0].lower()

    item_name = SPECIAL_ITEM_COMMANDS.get(full_cmd)
    if not item_name:
        return

    item_info = SPECIAL_TRANSFORMATION_ITEMS.get(item_name)
    if not item_info:
        return

    poke_name, mega_name, description = item_info

    # ── Inventory lookup — check user_stones ──────────────────────────────────
    conn = sqlite3.connect("ZNX.db")
    cur = conn.cursor()
    cur.execute(
        "SELECT quantity FROM user_stones WHERE user_id = ? AND stone_name = ?",
        (user.id, item_name)
    )
    row = cur.fetchone()
    conn.close()

    amount = row[0] if row else 0
    if amount > 0:
        caption = (
            f"<b><u>{item_name}</u></b>\n\n"
            f"Amount owned: <b>{amount}</b>\n\n"
            f"This <i>Key Item</i> can be used by <b>{poke_name}</b> to transform into "
            f"<b>{mega_name}</b> during a battle.\n\n"
            f"<i>{description}</i>"
        )
    else:
        caption = f"<b>You don't own this item.</b>"

    # ── Try to send with stored image URL ─────────────────────────────────────
    image_url = _get_stone_image(item_name)
    if image_url:
        try:
            await msg.reply_photo(photo=image_url, caption=caption, parse_mode="HTML")
            return
        except Exception:
            pass

    await msg.reply_text(caption, parse_mode="HTML")


# ══════════════════════════════════════════════════════════════════════════════
# ═══════════════ UNIFIED PRIVATE-CHAT MESSAGE DISPATCHERS ═══════════════════
# ══════════════════════════════════════════════════════════════════════════════
# PTB only calls ONE handler per update per group. If /add and /custom_poke_shadow
# each registered their own PHOTO/Document MessageHandler, only the first-
# registered would ever fire. These two functions collapse both into a single
# slot and dispatch internally so both workflows get a chance.

async def _unified_private_photo_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Single PHOTO/Document handler for private chat — dispatches to CPZ then /add.

    /add now uses URL-based flow (no image files). Photos are only handled by CPZ.
    """
    user = update.effective_user
    if not user:
        return

    # ── Priority 1: active /custom_poke_shadow session (head admin) ─────────────
    if user.id in CUSTOM_POKE_STATE and user.id in HEAD_ADMIN_IDS:
        await custom_poke_shadow_message_handler(update, context)
        return

    # ── Priority 2: active /add stone session — /add uses URLs now, not photos ─
    # If an admin sends a photo while in the /add flow, redirect them.
    if user.id in ADD_STONE_STATE and _ap_is_admin(user.id):
        await add_stone_message_handler(update, context)
        return

    # Not in any active session — silently ignore photo in private chat


async def _unified_private_text_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Single TEXT handler for private chat — dispatches to CPZ then /add.
    Falls through to ap_message_handler (group=1) for everything else."""
    user = update.effective_user
    if not user:
        return

    # Stamp last_active for DAU/WAU/MAU tracking
    _update_last_active(user.id)

    # ── Priority 1: active /custom_poke_shadow session (head admin) ─────────────
    if user.id in CUSTOM_POKE_STATE and user.id in HEAD_ADMIN_IDS:
        await custom_poke_shadow_message_handler(update, context)
        return

    # ── Priority 2: active /add stone session (any admin) ─────────────────────
    if user.id in ADD_STONE_STATE and _ap_is_admin(user.id):
        await add_stone_message_handler(update, context)
        return

    # Not in any active session — fall through to ap_message_handler in group=1


