async def _migrate_invalid_moves() -> None:
    """
    Startup migration: scan every Pokémon row whose stored moves column is
    non-empty and remove any moves that are in _KNOWN_INVALID_MOVE_SLUGS
    (status moves and known 0-power moves).

    If a Pokémon's entire moveset is wiped (all 4 slots were bad), the moves
    column is set to NULL so that compute_initial_moveset() will repopulate
    it lazily the next time the Pokémon enters battle or the Relearner.

    This is a fast offline pass — no PokeAPI calls are made.
    Pokémon whose stored moves survive (are not in the invalid set) are
    untouched.  A second, deeper API-based pass is done only for any Pokémon
    that ends up with fewer than 4 valid moves after this initial sweep.
    """
    try:
        conn = sqlite3.connect("ZNX.db")
        cur  = conn.cursor()
        cur.execute(
            "SELECT id, pokemon_id, pokemon_name, level, moves "
            "FROM user_pokemon WHERE moves IS NOT NULL AND moves != '[]' AND moves != 'null'"
        )
        rows = cur.fetchall()
        conn.close()
    except Exception as e:
        logger.error(f"[MIGRATE_MOVES] DB read error: {e}")
        return

    if not rows:
        logger.info("[MIGRATE_MOVES] No Pokémon rows to scan.")
        return

    migrated  = 0
    nullified = 0

    for pkmn_id, pokemon_api_id, pokemon_name, level, moves_json in rows:
        try:
            moves: list = json.loads(moves_json) if moves_json else []
            if not moves:
                continue

            # Fast offline filter — remove known-bad move slugs
            cleaned = [
                m for m in moves
                if str(m).strip().lower() not in _KNOWN_INVALID_MOVE_SLUGS
            ]

            if len(cleaned) == len(moves):
                continue  # nothing to fix for this Pokémon

            conn = sqlite3.connect("ZNX.db")
            cur  = conn.cursor()
            if cleaned:
                # Pokémon still has some valid moves — persist the cleaned list.
                cur.execute(
                    "UPDATE user_pokemon SET moves = ? WHERE id = ?",
                    (json.dumps(cleaned), pkmn_id)
                )
                migrated += 1
                logger.info(
                    f"[MIGRATE_MOVES] Cleaned moves for {pokemon_name} "
                    f"(id={pkmn_id}): {moves} → {cleaned}"
                )
            else:
                # All moves were invalid — null it so lazy backfill triggers.
                cur.execute(
                    "UPDATE user_pokemon SET moves = NULL WHERE id = ?",
                    (pkmn_id,)
                )
                nullified += 1
                logger.info(
                    f"[MIGRATE_MOVES] Nullified all moves for {pokemon_name} "
                    f"(id={pkmn_id}): {moves} → will recompute on next access"
                )
            conn.commit()
            conn.close()
        except Exception as e:
            logger.error(
                f"[MIGRATE_MOVES] Error processing pokemon id={pkmn_id} "
                f"({pokemon_name}): {e}"
            )

    if migrated or nullified:
        logger.info(
            f"[MIGRATE_MOVES] Done — cleaned {migrated} Pokémon, "
            f"nullified {nullified} Pokémon for lazy recompute."
        )
    else:
        logger.info("[MIGRATE_MOVES] All stored movesets are already valid.")



# ═══════════════════════════════════════════════════════════════════════════
# ═══════════════════════════════════════════════════════════════════════════
# ══════════════════ TM STORE & TM LEARNING SYSTEM (start) ══════════════════
# ═══════════════════════════════════════════════════════════════════════════
# Implements:
#   • The weekly, per-trainer deterministic TM Store (📀 TMs Store)
#   • TM inventory (user_tms) and weekly-offer purchase tracking
#   • Hidden /tm<N> commands (admin silent-grant + public TM Info UI)
#   • /add tm<N> admin grant shortcut (used by add_stone_cmd)
#   • TM-teaching flow: PokeAPI-driven learn-compatibility checking,
#     paginated Pokémon selection, and the <4-move / 4-move-replacement
#     learn UI
#
# Database tables owned by this section:
#   • user_tms              — already created earlier in init_db(); this
#                              section only ensures the move_name column
#                              exists and adds a performance index.
#   • weekly_tm_purchases   — created here. Tracks which of a trainer's 5
#                              deterministic weekly TM offers have already
#                              been bought, so each weekly offer can only be
#                              purchased once and the store never
#                              regenerates replacement TMs mid-week.
#
# Nothing here ever needs a background job: both the weekly store and the
# weekly purchase-tracking table key off the ISO week number of a
# Monday-05:30-IST-anchored clock, so everything "resets" automatically the
# instant a new week begins — no cleanup, no cron, no extra writes.
# ═══════════════════════════════════════════════════════════════════════════

DB_PATH = "ZNX.db"

