def _tm_rarity(price: int) -> str:
    """Derive rarity from price. Never randomly ignored — price IS rarity."""
    if price <= 5000:
        return "common"
    if price <= 7000:
        return "uncommon"
    return "rare"


# Pre-bucket TM numbers by rarity (sorted for deterministic sampling order).
_COMMON_TMS:   list[int] = sorted(n for n, d in TM_DATA.items() if _tm_rarity(d["price"]) == "common")
_UNCOMMON_TMS: list[int] = sorted(n for n, d in TM_DATA.items() if _tm_rarity(d["price"]) == "uncommon")
_RARE_TMS:     list[int] = sorted(n for n, d in TM_DATA.items() if _tm_rarity(d["price"]) == "rare")


def _move_slug(move_name: str) -> str:
    """Convert a TM's display move name to the slug PokeAPI expects."""
    return move_name.strip().lower().replace(" ", "-")


# ═══════════════════════════════════════════════════════════════════════════
# ═══════════════════════════ DATABASE / MIGRATION ══════════════════════════
# ═══════════════════════════════════════════════════════════════════════════

def init_tm_system_db() -> None:
    """Create / migrate every table this module needs.

    Safe to call every startup: every statement is either `IF NOT EXISTS`
    or wrapped in a try/except for the ALTER TABLE column-add pattern used
    throughout the rest of PokeRo.py. Never erases existing data.
    """
    conn = sqlite3.connect(DB_PATH)
    cur = conn.cursor()

    # user_tms is already created by PokeRo.py's main migration block, but
    # we guard here too in case this module is ever loaded standalone.
    cur.execute("""
        CREATE TABLE IF NOT EXISTS user_tms (
            user_id INTEGER NOT NULL,
            tm_number INTEGER NOT NULL,
            move_name TEXT NOT NULL,
            quantity INTEGER DEFAULT 1,
            PRIMARY KEY (user_id, tm_number)
        )
    """)
    # Old databases may have had a user_tms table created before move_name
    # existed — add it defensively.
    try:
        cur.execute("ALTER TABLE user_tms ADD COLUMN move_name TEXT DEFAULT ''")
    except sqlite3.OperationalError:
        pass

    # ── Weekly purchase tracking (point 21) ────────────────────────────────
    cur.execute("""
        CREATE TABLE IF NOT EXISTS weekly_tm_purchases (
            user_id INTEGER NOT NULL,
            week_number TEXT NOT NULL,
            tm_number INTEGER NOT NULL,
            PRIMARY KEY (user_id, week_number, tm_number)
        )
    """)

    # ── Indexes for thousands-of-concurrent-users performance ─────────────
    cur.execute("CREATE INDEX IF NOT EXISTS idx_user_tms_user ON user_tms(user_id)")
    cur.execute("CREATE INDEX IF NOT EXISTS idx_weekly_tm_purchases_lookup "
                "ON weekly_tm_purchases(user_id, week_number)")

    conn.commit()
    conn.close()


# ═══════════════════════════════════════════════════════════════════════════
# ═════════════════════ PERMANENT POKÉAPI CACHES (in-memory) ════════════════
# ═══════════════════════════════════════════════════════════════════════════
# Independent from PokeRo.py's caches by design (this module stays
# self-contained / dependency-free of PokeRo internals at import time).
# Never evicted — PokeAPI data for a given move/species never changes.

_TM_HTTP_SESSION: aiohttp.ClientSession | None = None

# move_slug -> elemental type string (e.g. "fire")
_MOVE_TYPE_CACHE: dict[str, str] = {}

# species_slug -> {"learnset": frozenset(move slugs learnable via TM),
#                   "types": [elemental type names]}
# A single /pokemon/{slug} fetch populates both, so the "Display: Types"
# selection mode and the learn-compatibility check never issue two separate
# requests for the same species.
_SPECIES_DATA_CACHE: dict[str, dict] = {}


def _tm_http_session() -> aiohttp.ClientSession:
    global _TM_HTTP_SESSION
    if _TM_HTTP_SESSION is None or _TM_HTTP_SESSION.closed:
        _TM_HTTP_SESSION = aiohttp.ClientSession()
    return _TM_HTTP_SESSION


async def get_move_elemental_type(move_name: str) -> str:
    """Return the elemental type (e.g. 'fire') for a move, fetched once from
    PokeAPI and cached permanently thereafter."""
    slug = _move_slug(move_name)
    if slug in _MOVE_TYPE_CACHE:
        return _MOVE_TYPE_CACHE[slug]
    try:
        url = f"https://pokeapi.co/api/v2/move/{slug}/"
        data = await _cached_pokeapi_get(url)
        if data:
            type_name = data.get("type", {}).get("name", "normal")
            _MOVE_TYPE_CACHE[slug] = type_name
            return type_name
    except Exception as e:
        logger.debug(f"[TM] move type fetch failed for {slug}: {e}")
    return "normal"


async def _get_species_data(species_slug: str) -> dict:
    """Fetch (once, cached permanently) a species' TM-learnset and elemental
    types from a single PokeAPI /pokemon/{slug} call. Never fetches the same
    species twice."""
    species_slug = (species_slug or "").strip().lower().replace(" ", "-")
    if species_slug in _SPECIES_DATA_CACHE:
        return _SPECIES_DATA_CACHE[species_slug]

    learnable: set = set()
    types: list = []
    try:
        url = f"https://pokeapi.co/api/v2/pokemon/{species_slug}/"
        data = await _cached_pokeapi_get(url)
        if data:
            for m in data.get("moves", []):
                for vgd in m.get("version_group_details", []):
                    if vgd.get("move_learn_method", {}).get("name") == "machine":
                        learnable.add(m["move"]["name"])
                        break
            types = [t["type"]["name"] for t in sorted(data.get("types", []), key=lambda t: t["slot"])]
    except Exception as e:
        logger.debug(f"[TM] species fetch failed for {species_slug}: {e}")

    result = {"learnset": frozenset(learnable), "types": types}
    # Cache even empty/failed results — a real "no data" answer is still
    # permanent, and avoids hammering PokeAPI on every retry.
    _SPECIES_DATA_CACHE[species_slug] = result
    return result


async def get_tm_learnset(species_slug: str) -> frozenset:
    """Return the set of move slugs `species_slug` can learn via a TM
    (PokeAPI move-learn method 'machine'). Cached permanently per species."""
    data = await _get_species_data(species_slug)
    return data["learnset"]


async def get_species_types(species_slug: str) -> list:
    """Return a species' elemental type(s), e.g. ['fire', 'flying']. Cached
    permanently alongside the TM learnset (same underlying API call)."""
    data = await _get_species_data(species_slug)
    return data["types"]


async def can_pokemon_learn_tm(species_slug: str, tm_number: int) -> bool:
    """Never hardcode compatibility — always resolved from the live (cached)
    PokeAPI learnset."""
    entry = TM_DATA.get(tm_number)
    if not entry:
        return False
    move_slug = _move_slug(entry["move"])
    learnset = await get_tm_learnset(species_slug)
    return move_slug in learnset


def _cached_species_types(species_slug: str) -> list:
    """Synchronous, cache-only lookup — used for UI rendering after
    eligibility filtering has already guaranteed the species is cached."""
    species_slug = (species_slug or "").strip().lower().replace(" ", "-")
    entry = _SPECIES_DATA_CACHE.get(species_slug)
    return entry["types"] if entry else []



# ═══════════════════════════════════════════════════════════════════════════
# ══════════════════════ WEEKLY STORE TIME / SEED LOGIC ═════════════════════
# ═══════════════════════════════════════════════════════════════════════════

_IST = timezone(timedelta(hours=5, minutes=30))
_RESET_HOUR, _RESET_MINUTE = 5, 30  # Monday 05:30 AM IST


def _ist_now() -> datetime:
    return datetime.now(timezone.utc).astimezone(_IST)


def current_store_week_key(now: datetime | None = None) -> str:
    """Return a label identifying the *current store week*, where a new week
    begins every Monday at 05:30 AM IST (not at the standard midnight ISO
    boundary). Shifting the clock back by the reset offset before computing
    isocalendar() makes the shifted-Monday-00:00 line up exactly with the
    real Monday-05:30 reset — so a plain isocalendar() call does the rest."""
    ist_now = now.astimezone(_IST) if now else _ist_now()
    shifted = ist_now - timedelta(hours=_RESET_HOUR, minutes=_RESET_MINUTE)
    iso_year, iso_week, _ = shifted.isocalendar()
    return f"{iso_year}-W{iso_week:02d}"


def time_until_next_reset() -> tuple[int, int]:
    """Return (days, hours) remaining until the next Monday 05:30 AM IST."""
    ist_now = _ist_now()
    days_ahead = (0 - ist_now.weekday()) % 7  # Monday == 0
    candidate = (ist_now + timedelta(days=days_ahead)).replace(
        hour=_RESET_HOUR, minute=_RESET_MINUTE, second=0, microsecond=0
    )
    if candidate <= ist_now:
        candidate += timedelta(days=7)
    delta = candidate - ist_now
    days = delta.days
    hours = delta.seconds // 3600
    return days, hours


def _seeded_rng(user_id: int, week_key: str) -> random.Random:
    """Deterministic seed = hash(user_id + week_number). Uses sha256 (not
    Python's randomized built-in hash()) so the seed is stable across
    process restarts and different bot instances."""
    raw = f"{user_id}:{week_key}".encode()
    seed_int = int(hashlib.sha256(raw).hexdigest(), 16) % (2**32)
    return random.Random(seed_int)


def generate_weekly_store(user_id: int, week_key: str | None = None) -> list[int]:
    """Deterministically generate this trainer's 5-TM weekly offer:
    2 Common + 2 Uncommon + 1 Rare. No database writes — pure function of
    (user_id, week_key). Never regenerates mid-week since week_key only
    changes once the real ISO week (Monday 05:30 IST) changes."""
    week_key = week_key or current_store_week_key()
    rng = _seeded_rng(user_id, week_key)
    common   = rng.sample(_COMMON_TMS,   2)
    uncommon = rng.sample(_UNCOMMON_TMS, 2)
    rare     = rng.sample(_RARE_TMS,     1)
    return common + uncommon + rare


def get_purchased_this_week(user_id: int, week_key: str | None = None) -> set:
    week_key = week_key or current_store_week_key()
    conn = sqlite3.connect(DB_PATH)
    cur = conn.cursor()
    cur.execute(
        "SELECT tm_number FROM weekly_tm_purchases WHERE user_id = ? AND week_number = ?",
        (user_id, week_key),
    )
    rows = cur.fetchall()
    conn.close()
    return {r[0] for r in rows}


def get_available_store(user_id: int) -> tuple[list[int], str]:
    """Return (remaining_tm_numbers, week_key) — the trainer's weekly offer
    minus whatever they've already purchased this week."""
    week_key = current_store_week_key()
    full_store = generate_weekly_store(user_id, week_key)
    purchased = get_purchased_this_week(user_id, week_key)
    remaining = [n for n in full_store if n not in purchased]
    return remaining, week_key


