def _get_nova_rupee(user_id: int) -> int | None:
    """Returns the trainer's RoRupee balance, or None if unregistered."""
    profile = get_user(user_id)
    if profile is None:
        return None
    return profile.get("nova_rupee") or 0


def _store_countdown_block() -> str:
    days, hours = time_until_next_reset()
    return (
        "<i>TMs Store refreshes every Monday at 5:30 AM IST.</i>\n\n"
        "Time Remaining:\n"
        f"{days} Days\n"
        f"{hours} Hours"
    )


def _tm_entry_block(tm_number: int) -> str:
    d = TM_DATA[tm_number]
    return (
        f"<b>TM{tm_number:03d}</b> — {d['move']}\n"
        f"Type: {d['category']}\n"
        f"Power: {d['power'] if d['power'] else '—'} | Accuracy: {d['accuracy']}\n"
        f"Price: {d['price']:,} 💶"
    )


def build_store_text_and_keyboard(user_id: int) -> tuple[str, InlineKeyboardMarkup]:
    rupees = _get_nova_rupee(user_id) or 0
    remaining, _week_key = get_available_store(user_id)

    if not remaining:
        text = (
            "📀 <b>Technical Machines</b>"
            f"<blockquote>Your RoRupees: {rupees:,} 💶</blockquote>\n"
            "✅ You have purchased every TM available this week.\n\n"
            "<i>New TMs will arrive next Monday at 5:30 AM IST.</i>\n\n"
            "Time Remaining:\n"
        )
        days, hours = time_until_next_reset()
        text += f"{days} Days\n{hours} Hours"
        keyboard = InlineKeyboardMarkup([
            [InlineKeyboardButton("Back", callback_data=f"ts_close_{user_id}")]
        ])
        return text, keyboard

    lines = ["📀 <b>Technical Machines</b>",
             f"<blockquote>Your RoRupees: {rupees:,} 💶</blockquote>"]
    for n in remaining:
        lines.append(_tm_entry_block(n))
    lines.append(_store_countdown_block())
    text = "\n\n".join(lines)

    rows = []
    btn_row = []
    for n in remaining:
        btn_row.append(InlineKeyboardButton(f"Buy TM{n:03d}", callback_data=f"ts_buy_{user_id}_{n}"))
        if len(btn_row) == 2:
            rows.append(btn_row)
            btn_row = []
    if btn_row:
        rows.append(btn_row)
    rows.append([InlineKeyboardButton("Refresh", callback_data=f"ts_open_{user_id}")])
    rows.append([InlineKeyboardButton("Back", callback_data=f"ts_close_{user_id}")])

    return text, InlineKeyboardMarkup(rows)


def romart_tm_button(user_id: int) -> InlineKeyboardMarkup:
    """The single button added below RoMart's existing shop UI."""
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("TMs Store", callback_data=f"ts_open_{user_id}")]
    ])


def _grant_tm(user_id: int, tm_number: int, qty: int = 1) -> None:
    """Increase a trainer's TM inventory (insert-or-increment)."""
    entry = TM_DATA[tm_number]
    conn = sqlite3.connect(DB_PATH)
    cur = conn.cursor()
    cur.execute(
        "INSERT INTO user_tms (user_id, tm_number, move_name, quantity) VALUES (?, ?, ?, ?) "
        "ON CONFLICT(user_id, tm_number) DO UPDATE SET quantity = quantity + excluded.quantity, "
        "move_name = excluded.move_name",
        (user_id, tm_number, entry["move"], qty),
    )
    conn.commit()
    conn.close()


def _consume_tm(user_id: int, tm_number: int) -> bool:
    """Decrement a trainer's TM inventory by 1, deleting the row at 0.
    Returns True on success, False if the trainer doesn't own one."""
    conn = sqlite3.connect(DB_PATH)
    cur = conn.cursor()
    cur.execute("SELECT quantity FROM user_tms WHERE user_id = ? AND tm_number = ?", (user_id, tm_number))
    row = cur.fetchone()
    if not row or row[0] <= 0:
        conn.close()
        return False
    new_qty = row[0] - 1
    if new_qty <= 0:
        cur.execute("DELETE FROM user_tms WHERE user_id = ? AND tm_number = ?", (user_id, tm_number))
    else:
        cur.execute(
            "UPDATE user_tms SET quantity = ? WHERE user_id = ? AND tm_number = ?",
            (new_qty, user_id, tm_number),
        )
    conn.commit()
    conn.close()
    return True


def _get_tm_quantity(user_id: int, tm_number: int) -> int:
    conn = sqlite3.connect(DB_PATH)
    cur = conn.cursor()
    cur.execute("SELECT quantity FROM user_tms WHERE user_id = ? AND tm_number = ?", (user_id, tm_number))
    row = cur.fetchone()
    conn.close()
    return row[0] if row else 0


async def build_tm_purchase_confirm_text(tm_number: int) -> str:
    """Confirmation screen text shown before a TM purchase is charged."""
    d = TM_DATA[tm_number]
    move_type  = await get_move_elemental_type(d["move"])
    type_emoji = TYPE_EMOJIS.get(move_type, "")
    pwr_display = d["power"] if d["power"] else "—"
    return (
        "<b><u>Confirm Purchase</u></b>\n\n"
        f"📀 <b>TM{tm_number:03d} — {d['move']}</b>\n\n"
        f"<b>Type:</b> {move_type.title()} {type_emoji} | <b>Category:</b> {d['category']}\n"
        f"<b>Power:</b> {pwr_display} | <b>Accuracy:</b> {d['accuracy']}\n\n"
        f"💶 <b>Price:</b> {d['price']:,} RoRupees\n\n"
        "<i>Are you sure you want to purchase this TM?</i>"
    )


def build_tm_purchase_confirm_keyboard(user_id: int, tm_number: int) -> InlineKeyboardMarkup:
    """Buy / Cancel buttons shown on the TM purchase confirmation screen."""
    return InlineKeyboardMarkup([[
        InlineKeyboardButton("Buy",    callback_data=f"ts_pbuy_{user_id}_{tm_number}"),
        InlineKeyboardButton("Cancel", callback_data=f"ts_pcancel_{user_id}_{tm_number}"),
    ]])


async def romart_store_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handles ts_open_/ts_buy_/ts_close_ callbacks from the TMs Store button
    on /romart and the in-store navigation buttons."""

    query = update.callback_query
    user = query.from_user
    parts = query.data.split("_")
    action = parts[1]
    owner_id = int(parts[2])

    if not await validate_owner(query, owner_id):
        return
    await query.answer()

    if not is_registered(user.id):
        await query.edit_message_caption(caption="You haven't registered yet! Type /start to begin your journey.")
        return
    if _is_in_battle(user.id) or context.user_data.get("safari_active"):
        await query.answer("❌ You cannot access the TMs Store while battling!", show_alert=True)
        return

    if action == "close":
        # Back button: always rebuild and show the RoMart HOME page (caption
        # + keyboard), never just swap the keyboard back — otherwise the
        # message keeps showing the TM Store's caption underneath the home
        # buttons. Centralized so every RoMart "Back" button behaves
        # identically and there's only one place that renders home.
        await render_romart_home(query, user.id)
        return

    if action == "open":
        text, keyboard = build_store_text_and_keyboard(user.id)
        try:
            await query.edit_message_caption(caption=text, reply_markup=keyboard, parse_mode="HTML")
        except Exception:
            pass
        return

    if action == "buy":
        tm_number = int(parts[3])
        week_key = current_store_week_key()
        full_store = generate_weekly_store(user.id, week_key)
        purchased = get_purchased_this_week(user.id, week_key)

        if tm_number not in full_store:
            await query.answer("❌ That TM is not part of your weekly store.", show_alert=True)
            return
        if tm_number in purchased:
            await query.answer("❌ You've already purchased this TM this week.", show_alert=True)
            return

        # ── Show purchase confirmation instead of buying immediately ─────────
        text = await build_tm_purchase_confirm_text(tm_number)
        keyboard = build_tm_purchase_confirm_keyboard(user.id, tm_number)
        try:
            await query.edit_message_caption(caption=text, reply_markup=keyboard, parse_mode="HTML")
        except Exception:
            pass
        return

    if action == "pbuy":
        tm_number = int(parts[3])
        week_key = current_store_week_key()
        full_store = generate_weekly_store(user.id, week_key)
        purchased = get_purchased_this_week(user.id, week_key)

        if tm_number not in full_store:
            await query.answer("❌ That TM is not part of your weekly store.", show_alert=True)
            return
        if tm_number in purchased:
            await query.answer("❌ You've already purchased this TM this week.", show_alert=True)
            return

        entry = TM_DATA[tm_number]
        price = entry["price"]
        rupees = _get_nova_rupee(user.id)
        if rupees is None:
            await query.edit_message_caption(caption="You haven't registered yet! Type /start to begin your journey.")
            return
        if rupees < price:
            await query.answer("❌ You don't have enough RoRupees.", show_alert=True)
            return

        # Re-check balance atomically and deduct — done as one non-yielding
        # block against the cached profile (no `await` between the check
        # and the deduct), same reasoning as increment_user()'s own
        # docstring: this is what actually prevents a double-spend if two
        # purchases for this trainer land back-to-back.
        profile = get_user(user.id)
        current_rupees = (profile.get("nova_rupee") or 0) if profile else 0
        if current_rupees < price:
            await query.answer("❌ You don't have enough RoRupees.", show_alert=True)
            return
        increment_user(user.id, nova_rupee=-price)

        conn = get_db(DB_PATH)
        cur = conn.cursor()
        try:
            cur.execute(
                "INSERT INTO weekly_tm_purchases (user_id, week_number, tm_number) VALUES (?, ?, ?)",
                (user.id, week_key, tm_number),
            )
        except sqlite3.IntegrityError:
            # Already purchased (race) — refund and bail. Refunding via
            # increment_user() (not a raw UPDATE) so the refund lands on
            # whatever the CURRENT cached balance is (which already
            # reflects the deduction above), rather than risking a stale
            # disk-read-based refund.
            increment_user(user.id, nova_rupee=price)
            await query.answer("❌ You've already purchased this TM this week.", show_alert=True)
            return
        cur.execute(
            "INSERT INTO user_tms (user_id, tm_number, move_name, quantity) VALUES (?, ?, ?, 1) "
            "ON CONFLICT(user_id, tm_number) DO UPDATE SET quantity = quantity + 1, move_name = excluded.move_name",
            (user.id, tm_number, entry["move"]),
        )
        conn.commit()

        text, keyboard = build_store_text_and_keyboard(user.id)
        try:
            await query.edit_message_caption(
                caption=f"✅ Bought <b>TM{tm_number:03d} — {entry['move']}</b> for {price:,} 💶!\n\n" + text,
                reply_markup=keyboard,
                parse_mode="HTML",
            )
        except Exception:
            pass
        return

    if action == "pcancel":
        # No RoRupees deducted, no TM added — just close the confirmation.
        text, keyboard = build_store_text_and_keyboard(user.id)
        try:
            await query.edit_message_caption(
                caption="<i>Purchase cancelled.</i>\n\n" + text,
                reply_markup=keyboard,
                parse_mode="HTML",
            )
        except Exception:
            pass
        return


