async def high_iv_hunt_cmd(update, context):
    """Toggle the High IV Hunt event (owner only)."""
    global HIGH_IV_HUNT_EVENT
    if update.effective_user.id not in OWNER_IDS:
        await update.message.reply_text("❌ Owner only.")
        return
    HIGH_IV_HUNT_EVENT = not HIGH_IV_HUNT_EVENT
    state = "🟢 ON" if HIGH_IV_HUNT_EVENT else "🔴 OFF"
    await update.message.reply_text(
        f"✅ High IV Hunt Event is now {state}\n"
        f"Every Pokémon caught in /hunt will have at least 10 IV in each stat."
        if HIGH_IV_HUNT_EVENT else
        f"✅ High IV Hunt Event is now {state}\n"
        f"Hunt IVs are back to normal."
    )


async def high_iv_safari_cmd(update, context):
    """Toggle the High IV Safari event (owner only)."""
    global HIGH_IV_SAFARI_EVENT
    if update.effective_user.id not in OWNER_IDS:
        await update.message.reply_text("❌ Owner only.")
        return
    HIGH_IV_SAFARI_EVENT = not HIGH_IV_SAFARI_EVENT
    state = "🟢 ON" if HIGH_IV_SAFARI_EVENT else "🔴 OFF"
    await update.message.reply_text(
        f"✅ High IV Safari Event is now {state}\n"
        f"Every Pokémon caught in /safari will have at least 10 IV in each stat."
        if HIGH_IV_SAFARI_EVENT else
        f"✅ High IV Safari Event is now {state}\n"
        f"Safari IVs are back to normal."
    )


def main() -> None:
    """Run the bot."""
    # Pull cloud data first if this machine has no local game DB yet
    # (fresh NexCloud clone), then push local → cloud so the backup is current.
    if _turso_sync is not None:
        try:
            _turso_sync.sync_on_startup()
        except Exception as e:
            print(f"[TURSO] startup sync error: {e}")
    init_db()
    # Load the persistent PokéAPI cache from disk into memory. Must happen
    # before any handler can run so /hunt, battles, etc. hit a warm cache
    # from the very first update instead of rebuilding it on demand.
    pokeapi_cache_init()
    # Restore active Safari sessions from DB into the startup cache.
    # Sessions are injected lazily into context.user_data per user.
    _safari_populate_restore_cache()
    # ── Startup migration: remove status/0-power moves from existing Pokémon ──
    asyncio.run(_migrate_invalid_moves())

    # concurrent_updates=True is required so a long-running handler (e.g. the
    # up-to-120s RandomClash draft) doesn't block every other update. By
    # default PTB processes updates ONE AT A TIME even though the code is
    # async — a slow RandomClash draft would freeze the whole bot (delayed
    # replies, "Query is too old" errors on other users' button presses)
    # until it finished. This lets independent updates run concurrently.
    #
    # post_shutdown=shutdown_flush_hook ensures USER_CACHE (see get_user/
    # update_user/increment_user above) is written to disk one last time
    # whenever the bot stops cleanly — Ctrl+C, SIGTERM from a host doing a
    # redeploy/restart, etc. PTB calls post_shutdown after run_polling()'s
    # own signal handling has stopped taking new updates, so this is the
    # correct hook rather than a raw signal/atexit handler racing PTB's own
    # shutdown sequence. This bounds data loss on an unclean crash (one the
    # process can't intercept at all, e.g. SIGKILL/power loss) to at most
    # one cache_flush_loop interval (45s) of writes — everything else is
    # covered by this hook.
    application = (
        Application.builder()
        .token(BOT_TOKEN)
        .concurrent_updates(True)
        .post_init(setup_commands)
        .post_shutdown(shutdown_flush_hook)
        .build()
    )

    # ── GLOBAL BAN GUARD ─────────────────────────────────────────────────────
    # Registered in group=-1 so it runs BEFORE every other handler in every
    # other group (commands, callback buttons, conversation states, background
    # systems — literally everything). If the user is banned, the guard
    # replies/answers with the ban notice and raises ApplicationHandlerStop,
    # which halts ALL further processing of this update across every group,
    # including the /start ConversationHandler below. This is the single
    # centralized enforcement point for bans; no other handler should
    # duplicate this check.
    application.add_handler(MessageHandler(filters.ALL, global_ban_guard_message), group=-1)
    application.add_handler(CallbackQueryHandler(global_ban_guard_callback), group=-1)

    conv_handler = ConversationHandler(
        entry_points=[CommandHandler("start", start)],
        states={
            ASK_NAME: [
                CallbackQueryHandler(intro_next_callback,     pattern="^intro_next$"),
                CallbackQueryHandler(intro_continue_callback, pattern="^intro_continue$"),
                MessageHandler(filters.TEXT & ~filters.COMMAND, receive_name),
                MessageHandler(filters.COMMAND,               name_reminder_cmd),
            ],
            CHOOSE_STARTER: [
                CallbackQueryHandler(choose_starter, pattern="^starter_"),
            ],
        },
        fallbacks=[CommandHandler("cancel", cancel)],
    )

    application.add_handler(conv_handler)
    application.add_handler(CommandHandler("Travel", travel))
    application.add_handler(CallbackQueryHandler(travel_callback, pattern="^region_"))
    application.add_handler(CommandHandler("hunt", hunt))

