    application.add_handler(CommandHandler("high_iv_safari", high_iv_safari_cmd))
    application.add_handler(CallbackQueryHandler(ap_callback, pattern="^ap_"))
    # Admin panel text message handler lives in group=1 so it is evaluated
    # independently of the CPZ handler (group=0).  PTB processes each group in
    # order; a return/pass in group=0 never silences group=1, which means
    # ap_message_handler always fires for head-admins who have ADMIN_PENDING
    # state set but no active CPZ session.
    application.add_handler(MessageHandler(
        filters.TEXT & ~filters.COMMAND & filters.ChatType.PRIVATE,
        ap_message_handler,
    ), group=1)

    # ── /roban & /rounban ──────────────────────────────────────────────────
    application.add_handler(CommandHandler("roban", roban_cmd))
    application.add_handler(CommandHandler("rounban", rounban_cmd))

    # ── Mega Stone hidden commands ─────────────────────────────────────────────
    # Telegram strips everything from the first underscore onward when it parses
    # a /command, so /charizardite_x arrives as command="charizardite" with no
    # args — CommandHandler("charizardite_x", …) will NEVER fire.
    #
    # Fix: one MessageHandler with a regex that matches the raw text of ANY
    # mega-stone command (including _x / _y variants) registered in group=3
    # so it fires AFTER all higher-priority handlers but before catch-alls.
    # NOTE: We use ONLY this single MessageHandler. Do NOT also register
    # CommandHandler(stone_name) for plain stones — that causes a double-fire
    # because PTB dispatches to both group=0 CommandHandlers AND group=3
    # MessageHandlers independently, resulting in two messages per command.
    import re as _re
    _stone_pattern = _re.compile(
        r"^/(" + "|".join(_re.escape(k) for k in MEGA_STONE_COMMANDS) + r")(@\w+)?(\s|$)",
        _re.IGNORECASE,
    )
    application.add_handler(
        MessageHandler(
            filters.Regex(_stone_pattern) & filters.COMMAND,
            _mega_stone_cmd_handler,
        ),
        group=3,
    )

    # ── Key Item hidden commands: /keystone and /dynamax_band ─────────────────
    # /keystone is plain and works as a CommandHandler.
    # /dynamax_band has an underscore so Telegram strips to /dynamax — use the
    # same MessageHandler + regex strategy as mega stones.
    application.add_handler(CommandHandler("keystone", keystone_cmd))
    _key_item_pattern = _re.compile(
        r"^/(dynamax_band)(@\w+)?(\s|$)",
        _re.IGNORECASE,
    )
    application.add_handler(
        MessageHandler(
            filters.Regex(_key_item_pattern) & filters.COMMAND,
            dynamax_band_cmd,
        ),
        group=3,
    )

    # ── Special transformation item hidden commands ────────────────────────────
    # /jade_orb, /blue_orb, /red_orb, /adamant_crystal, /lustrous_globe,
    # /griseous_core, /rusted_sword, /rusted_shield
    # All use underscores, so we use MessageHandler + regex (same reason as mega
    # stones — Telegram strips underscores in command parsing).
    _special_item_pattern = _re.compile(
        r"^/(" + "|".join(_re.escape(k) for k in SPECIAL_ITEM_COMMANDS) + r")(@\w+)?(\s|$)",
        _re.IGNORECASE,
    )
    application.add_handler(
        MessageHandler(
            filters.Regex(_special_item_pattern) & filters.COMMAND,
            _special_item_cmd_handler,
        ),
        group=3,
    )

    # ── Hidden /tm<N> commands (e.g. /tm68, /tm88, /tm154, /tm167) ─────────────
    # Same MessageHandler + regex strategy as Mega Stones above, registered in
    # group=3, so these work everywhere — DM, groups, and supergroups — instead
    # of only in private chat. filters.COMMAND already requires a leading "/",
    # and PTB's COMMAND filter/regex matching here is chat-type agnostic, so no
    # separate ChatType filter is needed (unlike the old per-DM-only behavior).
    # The regex is built from "tm" + digits (not a hardcoded number list), so
    # it stays in sync with TM_DATA automatically — adding a new TM there is
    # the only step needed. Matches with or without "@BotUsername", and is
    # case-insensitive (/TM68, /tm68, /Tm68, /tM68 all work). The handler
    # itself (tm_hidden_command_handler) re-parses the raw text and validates
    # the TM number against TM_DATA, so unknown /tm<N> numbers are ignored.
    _tm_hidden_pattern = _re.compile(r"^/tm(\d+)(@\w+)?(\s|$)", _re.IGNORECASE)
    application.add_handler(
        MessageHandler(
            filters.Regex(_tm_hidden_pattern) & filters.COMMAND,
            tm_hidden_command_handler,
        ),
        group=3,
    )

